function kh9Kinetic() { var m = pick([2, 4, 6, 8, 10]), v = rand(2, 6); var w = m * v * v / 2; return numMCQ6("Một vật khối lượng " + m + " kg chuyển động với tốc độ " + v + " m/s. Động năng của vật là bao nhiêu J?", "Wđ = ½mv²", w, "Wđ = ½ × " + m + " × " + (v * v) + " = " + w + " J.", 15); }
