  window.__ADV2BANKS24 = Object.assign(window.__ADV2BANKS24 || {}, {"gd9-b1":[{"f":"X1","p":"Em đặt ước mơ trở thành giáo viên ở vùng cao để giúp trẻ em khó khăn được học chữ. Một bạn chê nghề đó vất vả, lương không cao và khuyên em chọn nghề 'dễ giàu' hơn. Em nên giữ thái độ nào?","a":"Giữ mục tiêu mình chọn và lập kế hoạch học tập để thực hiện","w":["Bỏ ước mơ ngay vì bạn nói nghề đó không đáng phấn đấu","Đổi mục tiêu mỗi khi có người chê bai lựa chọn của mình","Giữ ước mơ trong lòng nhưng không cần học tập gì thêm"],"e":"Lí tưởng sống là mục đích cao đẹp do bản thân lựa chọn gắn với đóng góp cho cộng đồng; cần kiên định và biến lí tưởng thành kế hoạch hành động."},{"f":"X1","p":"Một bạn cùng lớp dành toàn bộ thời gian để làm video mạng xã hội mong nổi tiếng nhanh, bỏ bê việc học và nói 'học hành không quan trọng nữa'. Lời khuyên đúng nhất cho bạn là gì?","a":"Giữ học tập là nền tảng, cân bằng đam mê và nhiệm vụ","w":["Ủng hộ bạn bỏ học hẳn để tập trung làm video cho nổi tiếng","Khuyên bạn chỉ cần nổi tiếng là sẽ có mọi thứ, kể cả kiến thức","Chê bai đam mê của bạn và cấm bạn làm bất cứ video nào"],"e":"Đam mê cá nhân cần đi cùng học tập và lí tưởng sống lành mạnh; bỏ bê học tập vì hào nhoáng nhất thời dễ đánh mất tương lai."},{"f":"X1","p":"Em muốn vào đội tuyển học sinh giỏi của trường nhưng sợ thi không đạt sẽ bị bạn bè cười. Vì sợ, em định không đăng kí. Suy nghĩ nào thể hiện người sống có lí tưởng?","a":"Đăng kí, ôn luyện nghiêm túc để thử sức phấn đấu","w":["Không đăng kí cho an toàn, khỏi phải đối mặt thất bại","Đăng kí cho có tên nhưng không cần ôn luyện gì","Chờ bạn bè đăng kí hết rồi mới quyết định theo số đông"],"e":"Người có lí tưởng dám đặt mục tiêu và hành động, chấp nhận thử thách; chỉ mơ ước mà không hành động thì lí tưởng mãi là ảo tưởng."},{"f":"X1","p":"Quê em vừa bị thiệt hại do bão lũ. Em đang trong tuần ôn thi quan trọng nhưng rất muốn góp sức cùng đoàn thanh niên hỗ trợ bà con. Cách sắp xếp nào hợp lí nhất?","a":"Hỗ trợ trong khả năng, vẫn sắp xếp ôn thi hợp lí","w":["Bỏ hẳn ôn thi nhiều ngày để đi hỗ trợ dù sức mình còn hạn chế","Chỉ lo ôn thi, coi việc cứu trợ là của người lớn, không liên quan","Đăng ảnh kêu gọi trên mạng là đủ, không cần hành động thực tế"],"e":"Sống có lí tưởng là biết hướng về cộng đồng bằng hành động phù hợp lứa tuổi, đồng thời vẫn hoàn thành trách nhiệm học tập của bản thân."},{"f":"X1","p":"Mục tiêu của em là đỗ vào trường trung học phổ thông mình mong muốn. Nhưng lịch học của em chỉ gồm việc mơ về ngày đỗ, còn bài tập thường xuyên để dồn và bỏ qua phần khó. Điều em cần thay đổi trước tiên là gì?","a":"Lập kế hoạch ôn tập cụ thể, thực hiện đều mỗi ngày","w":["Mơ ước mạnh mẽ hơn nữa thì kết quả sẽ tự đến với mình","Chỉ học những phần dễ để thấy mình luôn làm đúng","Đợi sát ngày thi rồi học dồn một lần cho tập trung"],"e":"Lí tưởng, mục tiêu chỉ thành hiện thực bằng hành động cụ thể, bền bỉ; khoảng cách giữa mơ ước và lí tưởng chính là kế hoạch và nỗ lực."},{"f":"X1","p":"Một bạn cho rằng: 'Lí tưởng sống là chuyện của người lớn, học sinh cứ học xong đã rồi tính'. Em đồng tình với ý kiến nào sau đây?","a":"Không đồng tình, học sinh cần định hướng từ sớm","w":["Đồng tình hoàn toàn, học sinh không cần bất cứ định hướng nào","Đồng tình một phần, học sinh chỉ cần lí tưởng khi đã đi làm","Không quan tâm, lí tưởng của ai người đó tự lo lấy"],"e":"Thanh niên, học sinh cần sớm xác định lí tưởng, mục tiêu để học tập có hướng đi; định hướng từ sớm giúp không lãng phí tuổi trẻ."},{"f":"X1","p":"Em ngưỡng mộ một nhà khoa học trẻ Việt Nam nghiên cứu giải pháp xử lí rác thải nhựa. Ngưỡng mộ đó nên được em chuyển thành hành động nào?","a":"Học tốt môn liên quan, bắt đầu từ dự án nhỏ ở trường","w":["Chỉ cần chia sẻ bài viết về nhà khoa học là đã đủ thể hiện lí tưởng","Chờ đến khi học đại học mới cần làm bất cứ việc gì liên quan","Sao chép nguyên văn lí tưởng của nhà khoa học làm của mình"],"e":"Lí tưởng sống được nuôi dưỡng bằng học tập và hành động nhỏ, thiết thực ngay từ khi còn ngồi trên ghế nhà trường."},{"f":"X1","p":"Gia đình em gặp khó khăn về kinh tế, em lo ước mơ học lên cao của mình khó thực hiện và định buông xuôi. Thái độ đúng nhất trong hoàn cảnh này là gì?","a":"Tìm học bổng, điều chỉnh lộ trình, không bỏ mục tiêu","w":["Buông bỏ hẳn ước mơ vì hoàn cảnh khó khăn quyết định tất cả","Trách móc gia đình vì không lo được cho ước mơ của mình","Giấu khó khăn, vay mượn khắp nơi để theo đuổi bằng mọi giá"],"e":"Người có lí tưởng không dễ buông xuôi trước khó khăn; điều chỉnh lộ trình, tìm nguồn hỗ trợ là cách giữ vững mục tiêu lâu dài."},{"f":"X1","p":"Em chỉ thích một nghề vì thấy thu nhập cao, dù bản thân không có hứng thú cũng không có năng lực nổi trội ở lĩnh vực đó, và ngày càng chán nản khi tìm hiểu. Em nên cân nhắc điều gì?","a":"Cân nhắc sở thích, năng lực và đóng góp cho xã hội","w":["Cứ giữ lựa chọn đó vì thu nhập cao là tiêu chí duy nhất đúng","Bỏ mọi định hướng nghề nghiệp vì chọn nghề nào cũng chán","Chọn nghề theo bạn thân nhất để có người học cùng cho vui"],"e":"Lựa chọn lí tưởng, nghề nghiệp bền vững cần hài hoà lợi ích cá nhân với năng lực, sở thích và lợi ích cộng đồng, không chỉ chạy theo thu nhập."},{"f":"X1","p":"Lớp em tổ chức buổi nói chuyện với một cựu học sinh đã thành đạt và luôn tích cực làm việc thiện nguyện. Sau buổi nói chuyện, việc làm có ý nghĩa nhất của em là gì?","a":"Rút bài học, xác định bước phấn đấu cụ thể tiếp theo","w":["Xin chữ kí và chụp ảnh chung là đã học được đầy đủ bài học","Kể lại câu chuyện của anh chị cho thật hay để được khen là chính","Cho rằng thành công của anh chị là do may mắn, không cần học hỏi"],"e":"Tấm gương sống có lí tưởng chỉ có giá trị khi người học rút ra bài học và biến thành hành động phấn đấu của chính mình."},{"f":"X2","p":"Nhận định: 'Sống có lí tưởng là chỉ nghĩ đến những việc lớn lao, còn việc nhỏ hằng ngày như học tập, giúp đỡ gia đình thì không quan trọng.' Nhận định này đúng hay sai?","a":"Sai, lí tưởng bắt đầu từ việc nhỏ, trách nhiệm hằng ngày","w":["Đúng, việc nhỏ thì ai làm cũng được, không thể hiện lí tưởng","Đúng, người có lí tưởng không cần làm việc nhà hay học hành chăm","Sai, vì học sinh thì chưa cần quan tâm đến lí tưởng sống"],"e":"Lí tưởng sống cao đẹp luôn gắn với hành động cụ thể từ việc nhỏ nhất; tách lí tưởng khỏi đời sống hằng ngày sẽ biến nó thành khẩu hiệu rỗng."}],"gd9-b2":[{"f":"X1","p":"Trong trận đá bóng giao hữu, đồng đội của em chuyền hỏng một đường bóng quyết định khiến đội thua. Cả đội quay sang trách móc bạn ấy nặng lời. Em nên làm gì để thể hiện lòng khoan dung?","a":"Động viên bạn, cùng đội rút kinh nghiệm, không đổ lỗi","w":["Cùng mọi người trách bạn thật nhiều để bạn nhớ mà sửa","Từ nay không cho bạn tham gia đá bóng cùng đội nữa","Đổ thêm rằng bạn ấy lúc nào cũng làm hỏng việc của đội"],"e":"Khoan dung là biết thông cảm với sai sót vô ý, góp ý bằng sự động viên để người khác tiến bộ thay vì trừng phạt bằng lời nói."},{"f":"X1","p":"Em trai em vô tình làm rách một trang trong cuốn sách em rất quý. Em trai sợ hãi và khóc. Là anh/chị, em nên xử sự thế nào?","a":"An ủi em, nhắc cẩn thận, cùng dán lại cuốn sách","w":["Mắng em thật nặng và bắt em nhịn quà để đền cuốn sách mới","Giận em nhiều ngày, không nói chuyện với em nữa","Kể với bố mẹ theo hướng nặng thêm để em bị phạt thật đau"],"e":"Khoan dung trong gia đình thể hiện ở việc thông cảm với lỗi vô ý của người nhỏ tuổi, dạy bảo nhẹ nhàng thay vì trừng phạt nặng nề."},{"f":"X1","p":"Bạn mượn sách của em và trả muộn nhiều lần. Lần này bạn giải thích gia đình có việc đột xuất nên chưa đọc xong. Em nên ứng xử thế nào cho vừa khoan dung vừa rõ ràng?","a":"Thông cảm, cho thêm hạn cụ thể, nhắc lần sau đúng hẹn","w":["Cho mượn vô thời hạn, bạn trả lúc nào cũng được không cần hẹn","Không bao giờ cho bạn mượn bất cứ thứ gì nữa từ nay","Đòi bạn phải mua đền cuốn sách mới dù sách chưa hề bị hỏng"],"e":"Khoan dung không đồng nghĩa dễ dãi: thông cảm có lí do chính đáng nhưng vẫn cần giới hạn, hẹn rõ ràng để giữ nề nếp và tôn trọng lẫn nhau."},{"f":"X1","p":"Một người bạn cũ từng nói xấu em nay đã chân thành xin lỗi, chủ động sửa chữa bằng hành động cụ thể trong thời gian dài. Em nên có thái độ nào?","a":"Cho cơ hội sửa sai, đánh giá bằng hành động hiện tại","w":["Không bao giờ tha thứ dù bạn đã sửa sai thế nào đi nữa","Tha thứ ngay nhưng vẫn thường xuyên nhắc lại lỗi cũ để răn đe","Đồng ý làm lành với điều kiện bạn phải làm mọi việc em sai bảo"],"e":"Khoan dung là sẵn sàng tha thứ khi người có lỗi hối cải chân thành, đồng thời nhìn nhận họ bằng sự thay đổi thực tế."},{"f":"X1","p":"Trong giờ thảo luận, một bạn có niềm tin và phong tục khác với đa số lớp nên ý kiến của bạn bị vài bạn cười nhạo. Em thấy không thoải mái với cảnh đó. Em nên làm gì?","a":"Đề nghị cả lớp lắng nghe tôn trọng ý kiến khác biệt của bạn","w":["Cười theo số đông để không bị cho là khác người","Khuyên bạn từ nay giấu kín niềm tin của mình cho đỡ phiền","Bảo bạn phải thay đổi cho giống mọi người trong lớp"],"e":"Khoan dung gắn với tôn trọng sự khác biệt về quan điểm, tín ngưỡng; lắng nghe không đồng nghĩa phải đồng ý với mọi ý kiến."},{"f":"X1","p":"Mẹ nấu món ăn em không thích và em đã buột miệng cáu gắt. Sau bữa ăn, em nhận ra mẹ đã rất vất vả chuẩn bị. Việc làm đúng nhất của em là gì?","a":"Xin lỗi mẹ và góp ý nhẹ nhàng về khẩu vị cho lần sau","w":["Coi như không có chuyện gì, lần sau vẫn cáu nếu món không hợp ý","Đổ lỗi cho mẹ là không hiểu sở thích ăn uống của em","Bỏ hẳn bữa ăn gia đình từ nay để khỏi phải ăn món không thích"],"e":"Khoan dung bắt đầu trong gia đình: biết nhận lỗi, trân trọng công sức của người thân và góp ý bằng thái độ nhẹ nhàng."},{"f":"X1","p":"Bạn thân vô tình để lộ một bí mật nhỏ mà em từng dặn giữ kín. Bạn đã xin lỗi và giải thích đó là lỡ lời. Em nên xử lí thế nào?","a":"Nói rõ ranh giới riêng tư, tha thứ khi bạn nhận lỗi","w":["Chấm dứt tình bạn ngay lập tức, không nghe bất cứ giải thích nào","Để trả đũa, em cũng tiết lộ một bí mật của bạn cho người khác","Tha thứ ngoài mặt nhưng từ đó luôn nghi ngờ mọi lời bạn nói"],"e":"Khoan dung đi cùng thẳng thắn: nói rõ điều mình bị tổn thương và ranh giới, rồi tha thứ khi đối phương thực sự nhận lỗi, không trả đũa."},{"f":"X1","p":"Trong một cuộc thi ở trường, bạn đối thủ bị phát hiện gian lận và đến xin cả đội em bỏ qua, đừng báo thầy cô. Đội em nên làm gì cho đúng với tinh thần khoan dung?","a":"Không bao che, để thầy cô xử lí công bằng, không trả thù","w":["Bỏ qua gian lận lần này vì khoan dung là phải tha thứ mọi lỗi","Báo cáo nhưng yêu cầu thầy cô phạt bạn thật nặng cho bõ tức","Tung tin gian lận của bạn lên mạng để bạn không thi được nữa"],"e":"Khoan dung không phải bao che sai trái; hành vi gian lận cần xử lí công bằng, đồng thời người xử lí không lợi dụng để trả thù cá nhân."},{"f":"X1","p":"Em trượt khỏi đội tuyển sau kì thi chọn đội mà em đã ôn luyện rất lâu. Em tự trách mình nặng nề nhiều ngày và không muốn làm gì nữa. Thái độ khoan dung với bản thân đúng đắn là gì?","a":"Chấp nhận kết quả, rút kinh nghiệm, lập kế hoạch mới","w":["Tự kết luận mình kém cỏi và bỏ hẳn môn học đó từ nay","Đổ lỗi cho đề thi và thầy cô để bản thân khỏi phải tự trách","Ép mình học gấp đôi ngay lập tức để chuộc lỗi với bản thân"],"e":"Khoan dung với bản thân là nhìn nhận thiếu sót một cách bình tĩnh, rút kinh nghiệm và bước tiếp, không tự dằn vặt kéo dài hay đổ lỗi cho người khác."},{"f":"X1","p":"Nhà hàng xóm tổ chức tiệc gia đình và đã xin phép trước, nhưng tiếng ồn kéo dài hơn dự kiến một chút khiến em khó ngủ. Gia đình hàng xóm đã sang xin lỗi. Em và gia đình nên có thái độ nào?","a":"Thông cảm lần này, góp ý nhẹ về giờ giấc lần sau","w":["Không chấp nhận lời xin lỗi, đòi báo công an ngay trong đêm đó","Sang cãi nhau lớn tiếng để hàng xóm phải dừng tiệc ngay","Từ đó không giao tiếp gì với gia đình hàng xóm nữa"],"e":"Trong đời sống cộng đồng, sự cố nhỏ đã được xin lỗi trước và xin lỗi sau cần được thông cảm; góp ý nhẹ nhàng giúp quan hệ xóm giềng tốt đẹp."},{"f":"X2","p":"Nhận định: 'Khoan dung nghĩa là lúc nào cũng bỏ qua mọi lỗi lầm, không cần góp ý hay nhắc nhở người mắc lỗi.' Nhận định này đúng hay sai?","a":"Sai, khoan dung vẫn cần góp ý để người có lỗi sửa","w":["Đúng, đã khoan dung thì tuyệt đối không được nhắc lại lỗi của ai","Đúng, vì góp ý sẽ làm người khác tự ái và mất tình cảm","Sai, vì khoan dung là không bao giờ tha thứ cho bất cứ ai"],"e":"Khoan dung là tha thứ với tấm lòng rộng lượng nhưng không dung túng cái sai; góp ý chân thành giúp người mắc lỗi nhận ra và sửa mình."}],"gd9-b3":[{"f":"X1","p":"Thư viện khu phố nơi em ở thiếu người trực vào hai buổi chiều cuối tuần trong dịp hè. Em có thời gian rảnh và thích đọc sách. Việc làm phù hợp nhất là gì?","a":"Đăng kí trực thư viện theo lịch phù hợp việc học","w":["Nhận trực tất cả các buổi trong tuần dù phải bỏ học thêm","Chỉ đến chụp ảnh hoạt động một buổi để đăng lên mạng xã hội","Từ chối vì việc thư viện là của người lớn được trả lương"],"e":"Tham gia hoạt động cộng đồng cần phù hợp lứa tuổi, sức lực và không ảnh hưởng việc học; hỗ trợ thư viện khu phố là đóng góp thiết thực."},{"f":"X1","p":"Trong xóm em có vài em nhỏ học lớp 1, lớp 2 đọc còn chậm và gia đình các em bận đi làm. Nhóm bạn của em định tổ chức kèm đọc sách cho các em vào cuối tuần tại nhà văn hoá. Em nên tham gia thế nào?","a":"Tham gia theo nhóm, báo người lớn phụ trách biết","w":["Tự ý đón các em về nhà mình dạy mà không báo người lớn nào","Nhận kèm tất cả các em một mình để được nhiều người khen","Chỉ tham gia buổi đầu cho vui rồi bỏ ngang không báo lại"],"e":"Hoạt động vì cộng đồng cần tổ chức, có sự giám sát của người lớn và cam kết đều đặn mới thực sự giúp được người cần hỗ trợ."},{"f":"X1","p":"Sau trận mưa lớn, đoạn mương trước khu dân cư bị rác ùn tắc, nước bẩn tràn ra đường. Đoàn phường kêu gọi thanh thiếu niên hỗ trợ dọn dẹp vào sáng Chủ nhật. Em nên tham gia thế nào cho an toàn, hiệu quả?","a":"Tham gia có bảo hộ, làm việc phù hợp sức của mình","w":["Lội xuống giữa dòng mương sâu để vớt rác cho nhanh xong việc","Chỉ đứng trên bờ quay clip hoạt động của mọi người để đăng mạng","Ở nhà vì dọn mương là việc nặng, học sinh không liên quan"],"e":"Tham gia hoạt động cộng đồng phải đặt an toàn lên hàng đầu: có bảo hộ, làm việc vừa sức và dưới sự hướng dẫn của người phụ trách."},{"f":"X1","p":"Một cụ già trong khu phố bị ốm, con cháu ở xa, việc đi chợ hằng ngày gặp khó khăn. Nhóm thanh niên trong khu lập đội hỗ trợ mua đồ giúp cụ theo danh sách. Em có thể tham gia bằng cách nào phù hợp?","a":"Nhận việc nhẹ, rõ ràng như đi chợ theo danh sách","w":["Nhận quản lí toàn bộ tiền bạc của cụ cho tiện mua sắm lâu dài","Hứa giúp cụ mọi việc bất cứ lúc nào kể cả giờ học của em","Chụp ảnh cụ đăng mạng kêu gọi ủng hộ mà không hỏi ý cụ"],"e":"Giúp đỡ cộng đồng cần thiết thực, minh bạch và tôn trọng người được giúp; học sinh nên nhận phần việc vừa sức, rõ ràng."},{"f":"X1","p":"Trường em phát động tặng đồ dùng học tập còn tốt cho các bạn có hoàn cảnh khó khăn ngay trong trường. Một bạn đề nghị quay clip trao quà thật cảm động để đăng lên trang của lớp. Em nên góp ý thế nào?","a":"Tặng tế nhị, tôn trọng bạn nhận, không quay clip","w":["Đồng ý quay clip cận mặt bạn nhận quà cho thật xúc động","Chỉ tặng đồ đắt tiền nhất để clip trông thật hoành tráng","Không tặng nữa vì sợ bạn nhận quà sẽ ngại ngùng với lớp"],"e":"Hoạt động cộng đồng hướng tới người nhận; cách trao tặng tế nhị, tôn trọng nhân phẩm người nhận quan trọng không kém giá trị món quà."},{"f":"X1","p":"Địa phương tổ chức ngày hiến máu nhân đạo. Em rất muốn tham gia hiến máu nhưng năm nay em mới học lớp 9. Việc làm phù hợp nhất của em là gì?","a":"Hỗ trợ hậu cần, vận động người đủ điều kiện tham gia","w":["Khai tăng tuổi để được hiến máu như người trưởng thành","Ở nhà vì chưa đủ tuổi hiến máu thì không giúp được gì","Vận động bạn cùng lớp khai tuổi cùng mình cho có nhóm đi hiến"],"e":"Mỗi hoạt động cộng đồng có điều kiện riêng; chưa đủ điều kiện hiến máu vẫn có thể đóng góp bằng hỗ trợ, tuyên truyền đúng khả năng và quy định."},{"f":"X1","p":"Trạm y tế phường tổ chức buổi tiêm chủng, người dân đến đông và cần người hướng dẫn xếp hàng, ghi phiếu. Cán bộ y tế nhờ học sinh lớn hỗ trợ việc đơn giản. Em nên làm gì?","a":"Hỗ trợ xếp hàng theo hướng dẫn của cán bộ y tế","w":["Tự ý ghi thông tin sức khoẻ của người dân vào phiếu cho nhanh","Nhận việc tiêm thay vì thấy cán bộ đang quá bận rộn","Chỉ hỗ trợ người quen trong xóm được vào trước hàng"],"e":"Tham gia hỗ trợ y tế cộng đồng chỉ trong phạm vi việc đơn giản được phân công, tuyệt đối không làm thay việc chuyên môn và phải công bằng với mọi người."},{"f":"X1","p":"Một bạn trong nhóm tình nguyện của lớp chỉ tham gia hoạt động cộng đồng khi có cộng điểm thi đua. Bạn đến chụp vài tấm ảnh đầu buổi rồi xin về sớm. Em nên khuyên bạn điều gì?","a":"Tham gia thực chất, có trách nhiệm đến cuối việc","w":["Khuyên bạn chụp ảnh xong về sớm là khôn ngoan, đỡ mất công","Khuyên bạn bỏ hẳn hoạt động cộng đồng vì làm vậy mất thời gian","Im lặng vì động cơ tham gia của bạn không liên quan đến em"],"e":"Giá trị của hoạt động cộng đồng nằm ở đóng góp thực tế cho cộng đồng; tham gia hình thức, vì điểm số làm mất ý nghĩa của hoạt động."},{"f":"X1","p":"Vào mùa vụ, gia đình em rất bận việc đồng áng và việc nhà. Cùng lúc, khu phố có hoạt động cộng đồng kéo dài cả ngày cuối tuần mà em đã đăng kí. Cách sắp xếp hợp lí nhất là gì?","a":"Trao đổi với gia đình, ban tổ chức để dự phần phù hợp","w":["Bỏ việc nhà đi tham gia cả ngày mà không nói gì với gia đình","Bỏ hẳn hoạt động đã đăng kí mà không báo cho ban tổ chức biết","Nhờ em nhỏ trong nhà làm thay hết việc của mình để đi cả ngày"],"e":"Trách nhiệm với cộng đồng và gia đình cần được cân bằng; chủ động trao đổi, báo trước là cách ứng xử có trách nhiệm của người tham gia."},{"f":"X1","p":"Nhóm em lập một trang mạng kêu gọi nhận nuôi chó mèo bị bỏ rơi trong khu vực, nhưng số lượng vật nuôi gửi đến ngày càng nhiều, vượt quá khả năng chăm sóc của nhóm. Nhóm nên làm gì?","a":"Phối hợp trung tâm cứu hộ, chỉ nhận trong khả năng","w":["Tiếp tục nhận tất cả vì đã kêu gọi thì không được từ chối con nào","Bỏ mặc số vật nuôi vượt khả năng, chỉ chăm những con khoẻ mạnh","Đăng bài trách móc người dân gửi vật nuôi đến quá nhiều"],"e":"Hoạt động cộng đồng bền vững cần đánh giá đúng khả năng và phối hợp với tổ chức chuyên môn; làm vượt sức sẽ gây hại cho chính đối tượng cần giúp."},{"f":"X2","p":"Nhận định: 'Tham gia hoạt động cộng đồng thì phải làm những việc thật lớn lao, còn việc nhỏ trong xóm, trong trường thì không đáng gọi là hoạt động cộng đồng.' Nhận định này đúng hay sai?","a":"Sai, cộng đồng bắt đầu từ việc nhỏ thiết thực quanh mình","w":["Đúng, việc nhỏ thì ai cũng làm được nên không có ý nghĩa gì","Đúng, vì cộng đồng chỉ ghi nhận những hoạt động quy mô lớn","Sai, vì học sinh thì không nên tham gia bất cứ hoạt động cộng đồng nào"],"e":"Hoạt động cộng đồng là mọi hoạt động mang lại lợi ích cho cộng đồng, từ việc nhỏ gần gũi đến chương trình lớn; giá trị nằm ở ích lợi thực tế, không ở quy mô."}],"gd9-b4":[{"f":"X1","p":"Lớp bầu tổ trưởng mới. Bạn thân của em vận động mọi người bỏ phiếu cho mình dù một bạn khác làm việc trách nhiệm và công bằng hơn hẳn trong học kì qua. Em nên bỏ phiếu theo tiêu chí nào?","a":"Bỏ phiếu theo năng lực và phẩm chất thực tế của từng bạn","w":["Bỏ phiếu cho bạn thân vì tình bạn quan trọng hơn năng lực","Không bỏ phiếu cho ai để khỏi mất lòng cả hai bên","Bỏ phiếu theo bạn nào được số đông lớp đang ủng hộ nhất"],"e":"Khách quan, công bằng là đánh giá con người theo tiêu chí chung và biểu hiện thực tế, không theo tình cảm riêng hay áp lực số đông."},{"f":"X1","p":"Thầy giáo nhờ em nhận xét sản phẩm học tập của chính nhóm mình trước lớp. Sản phẩm của nhóm em làm chưa tốt ở một phần quan trọng. Em nên nhận xét thế nào?","a":"Nhận xét đúng thực tế, rõ phần tốt và phần chưa tốt","w":["Chê ít đi một chút để nhóm mình không bị điểm thấp hơn nhóm khác","Chỉ nói phần tốt, giấu hẳn phần chưa tốt của nhóm mình","Nhận xét khắt khe quá mức để tỏ ra mình rất khách quan"],"e":"Khách quan là đánh giá đúng sự thật kể cả khi đánh giá chính mình; giấu lỗi hay tự hạ quá mức đều là thiếu khách quan."},{"f":"X1","p":"Em nghe một bạn kể rằng bạn T đã gian lận trong kì kiểm tra vừa rồi, nhưng người kể không đưa ra được căn cứ nào và chỉ nghe lại từ người khác. Em nên có thái độ nào?","a":"Chưa kết luận vội, tìm thông tin nhiều phía có căn cứ","w":["Tin ngay vì người kể là bạn thân của mình, không thể nói sai","Kể lại cho nhiều bạn khác để mọi người cùng cảnh giác với T","Kết luận T gian lận nhưng chỉ nói nhỏ trong nhóm bạn thân"],"e":"Người khách quan không vội kết luận từ thông tin một chiều, thiếu chứng cứ; kết luận vội dễ gây oan và bất công cho người khác."},{"f":"X1","p":"Khi phân công việc trong nhóm học tập, bạn nhóm trưởng giao toàn việc khó cho một bạn ít nói vì 'bạn ấy không phản đối', còn việc nhẹ thì chia cho các bạn thân. Việc phân công này sai ở điểm nào?","a":"Thiếu công bằng, phân việc theo cảm tính, không đồng đều","w":["Không sai vì bạn ít nói đã không phản đối nghĩa là đồng ý","Sai vì mọi công việc trong nhóm đều phải giống hệt nhau mới công bằng","Sai vì nhóm trưởng không có quyền phân công việc cho ai cả"],"e":"Công bằng trong phân công là dựa trên năng lực, khối lượng tương xứng và có sự trao đổi, không lợi dụng tính cách của người khác để dồn việc."},{"f":"X1","p":"Trong giải chạy của trường, trọng tài phụ trách một nội dung lại là anh họ của một vận động viên thi đấu nội dung đó. Để bảo đảm công bằng, nhà trường nên làm gì?","a":"Đổi trọng tài hoặc giám sát chéo nội dung đó","w":["Giữ nguyên vì là người nhà thì càng hiểu rõ vận động viên hơn","Cho vận động viên đó nghỉ thi để khỏi phải đổi trọng tài","Để trọng tài tự hứa sẽ công bằng là đủ, không cần thay đổi gì"],"e":"Công bằng cần cơ chế tránh xung đột lợi ích; người có quan hệ thân thiết với thí sinh không nên trực tiếp cầm cân nảy mực phần thi đó."},{"f":"X1","p":"Trong lớp em, ý kiến của bạn học giỏi nhất thường được cả lớp mặc định là đúng mà không cần xét lập luận. Một lần, bạn đưa ra ý kiến chưa có căn cứ rõ ràng. Thái độ khách quan là gì?","a":"Xét ý kiến theo lập luận và căn cứ, dù người nói là ai","w":["Vẫn mặc định đúng vì bạn học giỏi thì hiếm khi nói sai","Phủ định ngay vì lần này chắc chắn bạn ấy nói sai để gây chú ý","Không cần nghe ý kiến của bất cứ bạn nào trong thảo luận nữa"],"e":"Khách quan là đánh giá nội dung theo chứng cứ, không đánh giá theo danh tiếng hay thành tích của người nói."},{"f":"X1","p":"Sau khi nhận bài kiểm tra, em phát hiện thầy giáo cộng nhầm điểm theo hướng có lợi cho em, khiến em cao hơn mức đúng hai điểm. Em nên làm gì?","a":"Báo thầy để sửa điểm đúng với bài làm thật","w":["Im lặng giữ điểm cao vì đó là lỗi của thầy, không phải của em","Chỉ nói với bạn bè trong lớp chứ không nói với thầy giáo","Xin thầy giữ nguyên điểm này và cộng bù trừ vào bài lần sau"],"e":"Công bằng phải áp dụng cả khi mình là người được lợi; trung thực về điểm số là biểu hiện khách quan với chính bản thân."},{"f":"X1","p":"Trên mạng xã hội lan truyền một bức ảnh cắt ghép cho thấy bạn cùng trường có hành vi xấu, kèm nhiều bình luận chỉ trích. Nhiều bạn đã kết luận bạn đó 'hư hỏng'. Em nên có thái độ nào?","a":"Không vội kết luận, chờ thông tin đầy đủ, tin cậy","w":["Kết luận theo số đông vì nhiều người bình luận thì chắc là thật","Chia sẻ bức ảnh kèm câu hỏi để mọi người tự phán xét thêm","Tin bức ảnh là thật vì ảnh chụp thì không thể làm giả được"],"e":"Ảnh cắt ghép, thông tin thiếu ngữ cảnh rất dễ gây hiểu lầm; thái độ khách quan là kiểm chứng nguồn và bối cảnh trước khi đánh giá một con người."},{"f":"X1","p":"Một câu lạc bộ của trường tuyển thành viên mới nhưng các anh chị phụ trách chỉ ưu tiên nhận người quen, dù tiêu chí tuyển đã được công bố công khai. Việc làm này vi phạm điều gì?","a":"Vi phạm nguyên tắc công bằng và minh bạch trong tuyển chọn","w":["Không vi phạm gì vì câu lạc bộ có quyền thích ai thì nhận người đó","Vi phạm vì câu lạc bộ thì không được phép tuyển thành viên mới","Chỉ vi phạm nếu người bị từ chối lên tiếng khiếu nại chính thức"],"e":"Khi đã có tiêu chí công khai, việc tuyển chọn phải theo đúng tiêu chí đó với mọi ứng viên; ưu tiên người quen là thiếu công bằng, thiếu khách quan."},{"f":"X1","p":"Lớp em thống nhất từ đầu năm học tiêu chí khen thưởng cuối kì dựa trên cả học tập và tham gia hoạt động lớp. Đến cuối kì, một bạn học tốt nhưng hầu như không tham gia hoạt động nào thắc mắc vì không được khen. Cách giải quyết công bằng nhất là gì?","a":"Áp dụng đúng tiêu chí đã thống nhất cho mọi bạn","w":["Thay đổi tiêu chí ngay để bạn học tốt nhất được khen cho êm chuyện","Khen thưởng thêm cho bạn đó ngoài tiêu chí để tránh thắc mắc","Bỏ hẳn việc khen thưởng của cả lớp để không ai phải thắc mắc"],"e":"Công bằng là áp dụng nhất quán tiêu chí đã công khai, thống nhất từ trước; thay đổi tiêu chí giữa chừng vì một cá nhân là thiếu công bằng với tập thể."},{"f":"X2","p":"Nhận định: 'Khách quan nghĩa là không có chính kiến riêng, ai nói gì cũng nên nghe theo.' Nhận định này đúng hay sai?","a":"Sai, khách quan là xét theo sự thật, chứng cứ","w":["Đúng, có chính kiến riêng thì sẽ không còn khách quan nữa","Đúng, vì nghe theo số đông bao giờ cũng là khách quan nhất","Sai, vì khách quan nghĩa là chỉ tin vào cảm giác của bản thân"],"e":"Người khách quan vẫn có quan điểm, nhưng quan điểm đó được hình thành từ sự thật và chứng cứ, không phải từ định kiến hay áp lực số đông."}],"gd9-b5":[{"f":"X1","p":"Khi chơi trò chơi điện tử có nội dung chiến tranh, một bạn trong nhóm hào hứng cổ vũ bạo lực ngoài đời và dùng lời lẽ kì thị người dân của nước đối thủ trong trò chơi. Em nên ứng xử thế nào?","a":"Nhắc bạn phân biệt game với đời thực, không kì thị","w":["Hùa theo bạn cho vui vì trong trò chơi thì nói gì cũng được","Rủ bạn tìm cách gây sự với người nước đó ngoài đời thực","Im lặng rời nhóm nhưng trong lòng đồng tình với bạn ấy"],"e":"Yêu chuộng hoà bình thể hiện ngay trong nhận thức và lời nói hằng ngày: giải trí không được biến thành cổ vũ bạo lực hay thù hận với con người thật."},{"f":"X1","p":"Sau một trận bóng đá quốc tế, đội tuyển mà bạn của em yêu thích thua trận. Bạn định lên mạng gây gổ, dùng lời lẽ xúc phạm cổ động viên đội bạn. Em nên khuyên bạn điều gì?","a":"Cổ vũ văn minh, tôn trọng đối thủ và người hâm mộ đội bạn","w":["Khuyên bạn dùng tài khoản phụ để xúc phạm cho đỡ bị phát hiện","Ủng hộ bạn vì thua trận thì có quyền bức xúc bằng mọi cách","Khuyên bạn bỏ hẳn bóng đá vì cổ vũ đội tuyển là vô ích"],"e":"Tinh thần thể thao và hoà bình là tôn trọng đối thủ; tranh cãi bằng xúc phạm, bạo lực lời nói đi ngược giá trị hoà bình, hữu nghị giữa các dân tộc."},{"f":"X1","p":"Lớp em đón một đoàn học sinh trao đổi đến từ một nước mà trong lịch sử từng có xung đột với Việt Nam. Một bạn nói không muốn tiếp đón đoàn này. Em nên giải thích thế nào cho đúng?","a":"Phân biệt quá khứ với con người hiện tại, ứng xử hữu nghị","w":["Đồng ý không tiếp đón vì phải ghi nhớ mối thù trong lịch sử","Tiếp đón nhưng giữ thái độ lạnh nhạt, xa cách cho rõ ràng","Chỉ tiếp đón nếu đoàn đó xin lỗi về mọi việc trong quá khứ"],"e":"Yêu nước và ghi nhớ lịch sử đi đôi với chính sách hoà bình, hữu nghị: khép lại quá khứ, hướng tới tương lai trong quan hệ giữa các dân tộc."},{"f":"X1","p":"Giờ ra chơi, em thấy một nhóm bạn lớn hơn đang trêu chọc, xô đẩy một em lớp dưới và coi đó là trò vui. Em nên làm gì để góp phần giữ môi trường học đường hoà bình?","a":"Can ngăn an toàn, báo thầy cô nếu sự việc tiếp diễn","w":["Đứng xem vì đó là chuyện của nhóm bạn lớn, không liên quan mình","Quay video đăng lên mạng để mọi người biết mặt nhóm bạn đó","Tham gia trêu cùng cho hoà đồng với nhóm bạn lớn hơn"],"e":"Hoà bình bắt đầu từ môi trường gần nhất là nhà trường; ngăn chặn bạo lực học đường bằng cách an toàn và báo người có trách nhiệm là hành động bảo vệ hoà bình thiết thực."},{"f":"X1","p":"Một video cũ từ nhiều năm trước bị cắt ghép, gắn chú thích sai lệch và lan truyền như thể là hình ảnh một xung đột vừa xảy ra, khiến nhiều người hoang mang, bình luận kích động. Em nên làm gì khi thấy video này?","a":"Kiểm chứng nguồn gốc video, không chia sẻ tin chưa rõ","w":["Chia sẻ ngay để mọi người kịp thời nắm tình hình xung đột","Bình luận kêu gọi đáp trả mạnh tay theo cảm xúc của mình","Tải video về và gửi cho càng nhiều nhóm càng tốt"],"e":"Tin giả về xung đột dễ kích động thù hận và bạo lực; kiểm chứng thông tin và không lan truyền tin sai là góp phần bảo vệ hoà bình trong thời đại số."},{"f":"X1","p":"Trường em phát động cuộc thi vẽ tranh với chủ đề hoà bình cho học sinh toàn trường. Để bức tranh của mình có ý nghĩa đúng với chủ đề, em nên chọn hướng thể hiện nào?","a":"Thể hiện hữu nghị, đoàn kết và khát vọng yên bình","w":["Vẽ cảnh chiến thắng bằng vũ khí thật hoành tráng cho ấn tượng","Chỉ vẽ phong cảnh quê mình, không cần thông điệp gì về hoà bình","Sao chép một bức tranh nổi tiếng trên mạng và ghi tên mình vào"],"e":"Truyền thông về hoà bình hướng tới hữu nghị, hợp tác và cuộc sống yên bình của con người; vinh quang vũ lực không phải thông điệp của hoà bình."},{"f":"X1","p":"Hai bạn trong lớp cãi nhau gay gắt vì một hiểu lầm nhỏ và bắt đầu hẹn nhau 'giải quyết' sau giờ học bằng đánh nhau. Em là bạn chung của cả hai, em nên làm gì?","a":"Hoà giải, giúp hai bạn lắng nghe nhau, nhờ thầy cô","w":["Đứng ngoài vì chuyện của hai bạn thì hai bạn tự giải quyết","Cổ vũ hai bạn đánh nhau một trận cho dứt điểm hiểu lầm","Đi rủ thêm bạn bè đến xem trận 'giải quyết' cho đông vui"],"e":"Đối thoại, hoà giải là phương thức giải quyết mâu thuẫn phù hợp với tinh thần hoà bình; bạo lực chỉ làm mâu thuẫn nhỏ thành hậu quả lớn."},{"f":"X1","p":"Nghe một cựu chiến binh kể về những mất mát của người dân thường trong chiến tranh, một bạn nói: 'Chiến tranh cũng thú vị, giá được sống thử một lần'. Em nên chia sẻ suy nghĩ nào với bạn?","a":"Chiến tranh gây đau thương, phải trân trọng hoà bình","w":["Đồng ý với bạn vì chiến tranh trong phim trông rất hấp dẫn","Cho rằng chuyện chiến tranh xưa không còn liên quan đến học sinh nay","Khuyên bạn tìm trò chơi chiến tranh thật giống ngoài đời để trải nghiệm"],"e":"Hiểu đúng hậu quả của chiến tranh giúp thế hệ trẻ biết quý trọng hoà bình và có trách nhiệm giữ gìn cuộc sống yên bình hôm nay."},{"f":"X1","p":"Một tổ chức quốc tế uy tín phát động quyên góp hỗ trợ trẻ em ở vùng đang có xung đột thông qua kênh chính thức của nhà trường. Em có một khoản tiền tiết kiệm nhỏ. Việc làm phù hợp nhất là gì?","a":"Ủng hộ trong khả năng qua kênh chính thức của trường","w":["Chuyển tiền cho một tài khoản cá nhân tự xưng làm từ thiện trên mạng","Không tham gia vì trẻ em ở nước khác không liên quan đến mình","Quyên góp toàn bộ tiền ăn sáng cả tháng để ủng hộ cho nhiều"],"e":"Chia sẻ với nạn nhân chiến tranh qua kênh uy tín thể hiện lòng nhân ái và tinh thần hoà bình; mức ủng hộ cần vừa với khả năng của học sinh."},{"f":"X1","p":"Bạn em cho rằng bảo vệ hoà bình chỉ là nhiệm vụ của quân đội và các nhà lãnh đạo, học sinh không làm được gì. Em đồng tình với ý kiến nào sau đây?","a":"Không đồng tình, học sinh giữ hoà bình từ hành động nhỏ","w":["Đồng tình hoàn toàn, học sinh chưa có vai trò gì với hoà bình","Đồng tình một phần, học sinh chỉ cần học thuộc định nghĩa hoà bình","Không cần quan tâm vì hoà bình hay chiến tranh là việc quá xa vời"],"e":"Hoà bình được giữ gìn bởi toàn xã hội; lối sống nhân ái, tôn trọng, giải quyết mâu thuẫn bằng đối thoại của mỗi học sinh chính là nền tảng của hoà bình."},{"f":"X2","p":"Nhận định: 'Bảo vệ hoà bình là biểu hiện của sự yếu đuối, hễ bị khiêu khích là phải đáp trả bằng bạo lực mới giữ được hoà bình.' Nhận định này đúng hay sai?","a":"Sai, giữ hoà bình bằng đối thoại, hợp tác chính nghĩa","w":["Đúng, đáp trả bạo lực ngay mới khiến đối phương không dám tái phạm","Đúng, vì đối thoại hoà bình chưa bao giờ giải quyết được mâu thuẫn","Sai, vì khi bị khiêu khích thì nên im lặng chịu đựng mọi thiệt thòi"],"e":"Quan điểm đúng về hoà bình là giải quyết bất đồng bằng đối thoại, thương lượng trên cơ sở tôn trọng lẫn nhau, đồng thời kiên quyết bảo vệ lợi ích chính đáng, không phải đáp trả bạo lực mù quáng hay chịu đựng thụ động."}],"gd9-b6":[{"f":"X1","p":"Tuần này em có ba môn kiểm tra quan trọng, đồng thời bạn thân rủ đi dự sinh nhật đúng vào tối trước ngày kiểm tra đầu tiên. Em nên sắp xếp thế nào?","a":"Ưu tiên ôn tập, hẹn gặp bạn vào dịp khác phù hợp","w":["Đi dự sinh nhật cả buổi tối, sáng hôm sau dậy sớm ôn bù cũng kịp","Bỏ luôn việc ôn tập vì sinh nhật bạn thân mỗi năm chỉ có một lần","Giả ốm để không phải đi sinh nhật và cũng không phải giải thích gì"],"e":"Quản lí thời gian là biết ưu tiên việc quan trọng, khẩn cấp; ứng xử khéo léo giúp giữ tình bạn mà không đánh đổi kết quả học tập."},{"f":"X1","p":"Mỗi khi ngồi vào bàn học, điện thoại của em liên tục báo tin nhắn từ các nhóm trò chuyện khiến em mất tập trung và học rất chậm. Giải pháp quản lí thời gian phù hợp nhất là gì?","a":"Tắt thông báo, để điện thoại xa chỗ học đã định","w":["Vừa học vừa trả lời tin nhắn ngay để khỏi bị bạn bè trách","Bỏ học mỗi khi có tin nhắn và học bù vào lúc nửa đêm","Nhờ bạn cùng lớp học hộ phần của mình trong lúc mình bận trò chuyện"],"e":"Loại bỏ yếu tố gây xao nhãng trong giờ học là kĩ năng quản lí thời gian cơ bản, hiệu quả hơn nhiều so với học bù vào ban đêm."},{"f":"X1","p":"Thầy giáo giao một dự án học tập thời hạn hai tuần. Em biết mình hay để việc đến cuối mới làm. Cách bắt đầu đúng nhất cho dự án này là gì?","a":"Chia dự án thành phần nhỏ với mốc cho từng phần","w":["Để đến ba ngày cuối mới làm dồn một lần cho tập trung","Làm phần dễ nhất trước rồi tính tiếp, phần khó để sau cùng mới nghĩ","Nhờ một bạn trong nhóm làm phần lớn, mình chỉ làm phần trình bày"],"e":"Chia nhỏ công việc dài hạn kèm mốc thời gian cụ thể là cách chống trì hoãn và bảo đảm tiến độ đã được chứng minh hiệu quả."},{"f":"X1","p":"Hôm nay em trực nhật về muộn, tối còn bài tập của hai môn và sáng mai có buổi sinh hoạt câu lạc bộ sớm. Em nên sắp xếp buổi tối thế nào?","a":"Làm việc quan trọng trước, bảo đảm thời gian ngủ","w":["Làm hết mọi việc kể cả việc chưa gấp, thức đến khuya cho xong tất cả","Bỏ bài tập của cả hai môn vì trực nhật về muộn là lí do chính đáng","Chỉ chuẩn bị cho câu lạc bộ vì đó là hoạt động em thích nhất"],"e":"Kế hoạch thời gian hợp lí phải cân bằng học tập, trách nhiệm và nghỉ ngơi; thiếu ngủ kéo dài làm giảm hiệu quả của mọi hoạt động hôm sau."},{"f":"X1","p":"Em đặt mục tiêu dậy sớm ôn bài nhưng đêm nào cũng lướt điện thoại đến khuya nên sáng không dậy nổi. Vấn đề cốt lõi em cần sửa là gì?","a":"Điều chỉnh giờ ngủ, giới hạn điện thoại buổi tối","w":["Đặt thêm nhiều đồng hồ báo thức thật to vào buổi sáng là đủ","Bỏ hẳn mục tiêu ôn bài buổi sáng vì mình không hợp dậy sớm","Uống thật nhiều cà phê vào buổi tối để sáng vẫn tỉnh táo ôn bài"],"e":"Quản lí thời gian phải xử lí nguyên nhân gốc rễ: giấc ngủ bị đánh cắp bởi thói quen buổi tối, không phải chỉ cố gắng dậy sớm bằng ý chí."},{"f":"X1","p":"Em ghi danh sách việc cần làm nhưng không ghi thời hạn cho từng việc. Kết quả là việc dễ được làm trước, việc gấp lại bị bỏ sót đến phút cuối. Em cần bổ sung điều gì?","a":"Ghi thời hạn và sắp xếp việc theo mức quan trọng, khẩn cấp","w":["Ghi danh sách dài hơn nữa để không bỏ sót bất cứ việc gì","Chỉ làm việc mình thích trước cho có hứng thú làm việc","Xoá bỏ danh sách vì ghi ra cũng không giúp được gì nhiều"],"e":"Danh sách công việc chỉ hiệu quả khi kèm thời hạn rõ ràng và thứ tự ưu tiên, nếu không việc dễ, việc thích sẽ luôn lấn việc quan trọng."},{"f":"X1","p":"Đang trong tuần ôn thi, một người bạn nhờ em giúp gấp một việc riêng của bạn mà việc đó sẽ làm em mất trọn buổi tối ôn tập đã lên kế hoạch. Em nên ứng xử thế nào?","a":"Từ chối lịch sự hoặc đề xuất giúp vào lúc khác","w":["Nhận lời giúp ngay vì từ chối bạn bè là ích kỉ trong lúc ôn thi","Nhận lời nhưng làm qua loa cho xong để còn quay lại ôn tập","Im lặng không trả lời tin nhắn của bạn cho đến khi thi xong"],"e":"Biết nói 'không' một cách lịch sự với việc không khẩn cấp của người khác là kĩ năng bảo vệ kế hoạch thời gian của chính mình."},{"f":"X1","p":"Cuối ngày, em nhìn lại và thấy còn ba việc trong kế hoạch chưa làm xong, trong đó chỉ một việc thực sự gấp cho ngày mai. Cách xử lí hợp lí nhất là gì?","a":"Làm việc gấp trước, chuyển việc chưa gấp sang mai","w":["Cố làm cả ba việc đến khuya dù ngày mai phải dậy sớm đi học","Bỏ cả ba việc và lập kế hoạch ngày mai hoàn toàn mới không nhắc lại","Chọn việc dễ nhất trong ba việc để làm cho đỡ cảm giác tội lỗi"],"e":"Nhìn lại kế hoạch cuối ngày giúp điều chuyển công việc một cách chủ động, có ưu tiên, thay vì hoặc ôm đồm quá sức hoặc buông xuôi."},{"f":"X1","p":"Hằng ngày em phải chờ xe buýt khoảng hai mươi phút vào buổi sáng. Khoảng thời gian này thường trôi qua lãng phí. Cách tận dụng hợp lí nhất là gì?","a":"Ôn thẻ từ vựng hoặc đọc sách mang theo trong lúc chờ xe","w":["Ngủ gật trên ghế chờ để bù cho việc thức khuya hôm trước","Chơi trò chơi điện tử thật tập trung để quên thời gian chờ đợi","Đứng sát mép đường ngóng xe liên tục cho đỡ sốt ruột"],"e":"Những khoảng thời gian chờ ngắn, đều đặn mỗi ngày cộng lại rất lớn; tận dụng cho việc học nhẹ, an toàn là biểu hiện quản lí thời gian hiệu quả."},{"f":"X1","p":"Lịch học thêm của em bị chồng chéo nhiều buổi trong tuần khiến em hầu như không còn thời gian nghỉ ngơi, tự học và ở bên gia đình. Em nên làm gì?","a":"Trao đổi với bố mẹ, sắp xếp lại lịch học hợp lí","w":["Cố chịu đựng lịch hiện tại vì càng học nhiều buổi càng tiến bộ nhanh","Tự ý bỏ bớt các buổi học thêm mà không nói gì với bố mẹ","Bỏ luôn việc tự học và nghỉ ngơi vì hai việc đó không quan trọng"],"e":"Thời gian biểu hiệu quả phải cân bằng giữa học tập, nghỉ ngơi và gia đình; lịch học quá tải kéo dài gây kiệt sức và giảm chất lượng học tập."},{"f":"X2","p":"Nhận định: 'Quản lí thời gian tốt nghĩa là lấp kín mọi phút trong ngày bằng công việc, không để một khoảng trống nào cho nghỉ ngơi.' Nhận định này đúng hay sai?","a":"Sai, kế hoạch tốt phải có nghỉ ngơi, phục hồi","w":["Đúng, nghỉ ngơi là biểu hiện của lãng phí thời gian quý giá","Đúng, vì người thành công không bao giờ để thời gian trống","Sai, vì quản lí thời gian tốt là làm càng ít việc càng tốt"],"e":"Nghỉ ngơi là một phần của kế hoạch thời gian khoa học, giúp duy trì sức khoẻ và hiệu quả lâu dài; lấp kín lịch trình dẫn đến quá tải và trì hoãn."}],"gd9-b7":[{"f":"X1","p":"Trường của em chuyển một số tiết học sang hình thức trực tuyến trong hai tuần vì sửa chữa phòng học. Một số bạn coi đây là dịp nghỉ ngơi. Thái độ thích ứng đúng của em là gì?","a":"Chuẩn bị thiết bị, giữ kỉ luật tự học như trực tiếp","w":["Coi hai tuần học trực tuyến là nghỉ học, không cần vào lớp đúng giờ","Chỉ điểm danh đầu giờ rồi làm việc riêng trong suốt tiết học","Chờ nhà trường quay lại học trực tiếp mới bắt đầu học lại nghiêm túc"],"e":"Thay đổi hình thức học đòi hỏi thích ứng bằng cách giữ nề nếp và tự giác; coi nhẹ học trực tuyến sẽ tạo lỗ hổng kiến thức cho chính mình."},{"f":"X1","p":"Bố em đổi ca làm việc nên giờ đưa đón đi học thay đổi, em phải làm quen với việc tự đi xe buýt đến trường trong thời gian tới. Cách thích ứng an toàn, hợp lí nhất là gì?","a":"Tìm hiểu tuyến xe, đi thử cùng người lớn trước khi tự đi hẳn","w":["Tự đi ngay chuyến đầu tiên một mình vào sáng sớm cho quen dần","Xin nghỉ học một thời gian đến khi bố quay lại ca làm cũ","Đi nhờ xe của bất cứ người lạ nào cho tiện và nhanh hơn xe buýt"],"e":"Trước thay đổi trong sinh hoạt, chuẩn bị từng bước có hỗ trợ giúp em tự lập an toàn, thay vì liều lĩnh hoặc né tránh thay đổi."},{"f":"X1","p":"Lên lớp 9, em bắt đầu học thêm nội dung lập trình trong môn Tin học và thấy khó hơn hẳn những gì mình quen làm trước đây. Cách thích ứng tích cực nhất là gì?","a":"Chia nhỏ để luyện tập, hỏi thầy cô, bạn khi chưa hiểu","w":["Kết luận mình không có năng khiếu và bỏ hẳn phần lập trình","Chỉ học thuộc lý thuyết, không cần thực hành trên máy tính","Chờ đến gần kì thi mới bắt đầu tìm hiểu lập trình một thể"],"e":"Gặp nội dung mới, khó là thay đổi bình thường trong học tập; thích ứng là điều chỉnh phương pháp, luyện tập từng bước và tìm hỗ trợ kịp thời."},{"f":"X1","p":"Đội bóng của lớp có huấn luyện viên mới, thầy thay đổi gần như toàn bộ chiến thuật mà đội đã quen. Một số bạn tỏ thái độ chống đối, muốn đội chơi theo cách cũ. Thái độ đúng là gì?","a":"Lắng nghe, tập theo chiến thuật mới, góp ý đúng lúc","w":["Cố tình chơi theo cách cũ trên sân để chứng minh chiến thuật mới sai","Bỏ tập cùng đội cho đến khi đội quay lại huấn luyện viên trước","Góp ý bằng cách cãi nhau gay gắt với thầy ngay trong buổi tập đầu"],"e":"Thích ứng với thay đổi là sẵn sàng thử phương pháp mới một cách nghiêm túc, phản hồi có căn cứ thay vì bảo thủ hoặc chống đối cảm tính."},{"f":"X1","p":"Bạn thân nhất của em dạo này có thêm nhóm bạn mới và ít dành thời gian cho em như trước. Em cảm thấy hụt hẫng. Cách ứng xử trưởng thành, thích ứng tốt là gì?","a":"Tôn trọng quan hệ mới của bạn, mở rộng quan hệ của mình","w":["Giận bạn và cắt đứt tình bạn vì cho rằng bạn đã thay lòng đổi dạ","Tìm cách nói xấu nhóm bạn mới để bạn quay lại chơi riêng với mình","Đòi bạn phải chọn một trong hai: hoặc nhóm mới, hoặc tình bạn với mình"],"e":"Quan hệ bạn bè thay đổi theo thời gian là điều tự nhiên; thích ứng là tôn trọng sự thay đổi, không níu kéo độc chiếm hay phá hoại quan hệ của người khác."},{"f":"X1","p":"Gia đình em vừa nhận nuôi một chú chó nhỏ. Việc chăm sóc thú cưng làm thay đổi giờ giấc sinh hoạt buổi sáng và buổi tối của cả nhà, em thấy khá xáo trộn. Em nên làm gì để thích ứng?","a":"Phân công chăm sóc rõ ràng, điều chỉnh lịch sinh hoạt","w":["Đề nghị mang chó đi cho người khác vì sinh hoạt bị xáo trộn quá nhiều","Để một mình mẹ chăm chó, em giữ nguyên mọi thói quen của mình","Bỏ bớt giờ học bài buổi tối để chơi với chó cho bù lại thời gian"],"e":"Thay đổi trong gia đình cần sự chia sẻ trách nhiệm và sắp xếp lại lịch sinh hoạt chung, thay vì đổ việc cho một người hay né tránh thay đổi."},{"f":"X1","p":"Kết quả học kì vừa rồi của em giảm rõ rệt sau khi chương trình lớp 9 nặng hơn hẳn so với lớp 8. Em nhận ra cách học cũ không còn phù hợp. Việc làm đúng nhất là gì?","a":"Phân tích nguyên nhân, đổi phương pháp, nhờ thầy tư vấn","w":["Cho rằng mình đã hết khả năng tiến bộ và chấp nhận kết quả thấp","Học nhiều giờ hơn theo đúng cách cũ dù cách đó đã không hiệu quả","Đổ lỗi hoàn toàn cho chương trình khó nên không cần thay đổi gì"],"e":"Thích ứng là nhận diện đúng nguyên nhân khi hoàn cảnh thay đổi và chủ động thay đổi phương pháp của bản thân, thay vì buông xuôi hay chỉ tăng thời lượng máy móc."},{"f":"X1","p":"Do nắng nóng kéo dài, trường em chuyển các hoạt động thể dục ngoài trời sang khung giờ sáng sớm trong nhiều tuần. Một số bạn kêu ca và xin nghỉ hết các tiết này. Thái độ đúng của em là gì?","a":"Chấp nhận lịch mới, chuẩn bị phù hợp bảo vệ sức khoẻ","w":["Xin nghỉ mọi tiết thể dục cho đến khi trường quay lại lịch cũ","Vận động cả lớp viết đơn đòi giữ nguyên lịch học giữa trưa nắng","Đến lớp theo lịch mới nhưng không tham gia vận động chút nào"],"e":"Điều chỉnh lịch vì sức khoẻ của học sinh là thay đổi hợp lí; thích ứng tích cực là phối hợp thực hiện thay vì chống đối hay bỏ mặc."},{"f":"X1","p":"Em bị chấn thương nhẹ ở chân khi chơi thể thao và được bác sĩ dặn nghỉ vận động mạnh trong một tháng. Em rất buồn vì phải rời xa môn thể thao yêu thích. Cách thích ứng đúng là gì?","a":"Tuân thủ điều trị, chọn hoạt động nhẹ khi hồi phục","w":["Vẫn cố chơi thể thao như cũ để chứng tỏ mình không yếu đuối","Bỏ hẳn mọi vận động và sinh hoạt đội nhóm trong suốt một năm sau đó","Tự ý tập nặng hơn để chân nhanh khỏi theo ý hiểu của mình"],"e":"Trước thay đổi bất ngờ về sức khoẻ, thích ứng là chấp nhận giới hạn tạm thời, tuân thủ chuyên môn y tế và duy trì tinh thần tích cực bằng hoạt động phù hợp."},{"f":"X1","p":"Một công cụ học tập số mới xuất hiện giúp tra cứu rất nhanh, nhưng thông tin nó đưa ra đôi lúc không chính xác. Nhiều bạn dùng công cụ này làm bài mà không kiểm tra lại. Cách sử dụng thể hiện thích ứng tốt với công nghệ là gì?","a":"Dùng để hỗ trợ, luôn kiểm chứng bằng nguồn tin cậy","w":["Tin tuyệt đối mọi thông tin công cụ đưa ra vì công nghệ luôn đúng","Cấm bản thân dùng mọi công cụ mới vì sợ thông tin không chính xác","Sao chép nguyên kết quả của công cụ vào bài làm cho nhanh và tiện"],"e":"Thích ứng với công nghệ mới là khai thác lợi ích của nó một cách có kiểm chứng và đúng quy định, không phụ thuộc mù quáng cũng không tẩy chay cực đoan."},{"f":"X2","p":"Nhận định: 'Thích ứng với thay đổi nghĩa là phải chấp nhận mọi thay đổi xung quanh, kể cả những thay đổi xấu, trái với đạo đức và pháp luật.' Nhận định này đúng hay sai?","a":"Sai, thích ứng không gồm chấp nhận điều sai trái","w":["Đúng, đã gọi là thích ứng thì thay đổi nào cũng phải theo hết","Đúng, vì chống lại thay đổi xấu cũng bị coi là không biết thích ứng","Sai, vì con người không cần thích ứng với bất cứ thay đổi nào cả"],"e":"Thích ứng đúng đắn là linh hoạt điều chỉnh bản thân trước hoàn cảnh mới trên cơ sở giữ vững nguyên tắc đạo đức, pháp luật; điều sai trái cần được nhận diện và không tiếp tay."}],"gd9-b8":[{"f":"X1","p":"Trong một buổi phát trực tiếp bán hàng, người bán giới thiệu đôi giày 'hàng hiệu giá chỉ bằng một phần mười giá hãng' nhưng không nói rõ nguồn gốc xuất xứ. Bạn em rủ mua ngay kẻo hết hàng. Quyết định của người tiêu dùng thông minh là gì?","a":"Không vội mua, kiểm tra uy tín và nguồn gốc hàng","w":["Mua ngay hai đôi vì giá rẻ như vậy chắc chắn là cơ hội hiếm có","Mua một đôi về dùng thử, giả hay thật thì lúc đó mới tính","Chia sẻ buổi bán hàng cho nhiều bạn cùng mua chung cho vui"],"e":"Giá rẻ bất thường kèm nguồn gốc mập mờ là dấu hiệu hàng giả, hàng nhái; tiêu dùng thông minh là kiểm chứng trước khi chi tiền, không mua theo thúc giục."},{"f":"X1","p":"Ở chợ, một quầy bán rau không có bảng nguồn gốc, rau trông héo nhưng người bán nói chắc nịch là 'rau nhà trồng, sạch tuyệt đối'. Bên cạnh có quầy rau có nguồn gốc rõ ràng, giá cao hơn một chút. Lựa chọn an toàn hơn là gì?","a":"Ưu tiên quầy rõ nguồn gốc, biết chọn rau tươi sạch","w":["Mua quầy rẻ hơn vì người bán đã cam kết bằng lời nói là đủ tin","Mua thật nhiều ở quầy không rõ nguồn gốc vì rau héo mới là rau sạch","Không mua rau ở chợ nữa vì chợ thì không bao giờ bảo đảm an toàn"],"e":"An toàn thực phẩm cần căn cứ vào nguồn gốc, điều kiện bảo quản và dấu hiệu thực tế, không chỉ dựa vào lời quảng cáo miệng của người bán."},{"f":"X1","p":"Em đặt đồ ăn qua ứng dụng, giá món ăn hiển thị rất rẻ nhưng đến bước thanh toán, tổng tiền tăng cao vì nhiều khoản phí cộng thêm không được báo rõ từ đầu. Em nên làm gì?","a":"Xem tổng tiền cuối, huỷ đơn nếu phí không minh bạch","w":["Cứ thanh toán vì đã mất công chọn món, phí thêm cũng không đáng kể","Đánh giá một sao cho quán ăn dù khoản phí do ứng dụng quy định","Mượn tài khoản của bạn để đặt lại với hi vọng phí sẽ thấp hơn"],"e":"Người tiêu dùng thông minh luôn kiểm tra tổng chi phí thực trả trước khi xác nhận giao dịch và có quyền không mua khi thông tin giá không minh bạch."},{"f":"X1","p":"Trước cổng trường, một người bán rong chào bán nước ngọt đóng chai không nhãn mác với giá rất rẻ. Nhiều bạn đã mua uống. Em nên ứng xử thế nào?","a":"Không mua, nhắc bạn cẩn trọng, báo nhà trường biết","w":["Mua uống thử một chai vì nhiều bạn uống rồi vẫn chưa sao","Mua mang về nhà cho em nhỏ uống vì giá rẻ, tiết kiệm tiền","Chỉ mua khi người bán hứa đây là hàng mới làm trong ngày"],"e":"Thực phẩm, đồ uống không nhãn mác, không rõ nguồn gốc tiềm ẩn nguy cơ mất an toàn; học sinh cần tránh xa và bảo vệ bạn bè, người thân khỏi sản phẩm như vậy."},{"f":"X1","p":"Điện thoại của em bị phồng pin. Một cửa hàng khuyên em bỏ máy cũ, mua máy mới đắt tiền của cửa hàng, trong khi một nơi sửa chữa uy tín cho biết chỉ cần thay pin chính hãng là dùng an toàn. Quyết định tiêu dùng hợp lí là gì?","a":"So sánh tại nơi uy tín, chọn cách an toàn, vừa tiền","w":["Nghe cửa hàng đầu tiên, mua ngay máy mới đắt tiền cho yên tâm","Tiếp tục dùng máy pin phồng vì thay pin hay mua mới đều tốn tiền","Tự tháo pin tại nhà theo video trên mạng để tiết kiệm chi phí sửa"],"e":"Tiêu dùng thông minh là tìm hiểu nhiều phương án, ưu tiên an toàn và nhu cầu thật; pin phồng là nguy cơ cháy nổ, tuyệt đối không tiếp tục sử dụng hay tự sửa."},{"f":"X1","p":"Về nhà, em phát hiện hộp sữa vừa mua có phần in hạn sử dụng bị mờ, không đọc được ngày tháng. Em còn giữ hoá đơn mua hàng. Việc làm đúng của người tiêu dùng là gì?","a":"Mang hoá đơn đến nơi bán, đổi hộp rõ hạn dùng","w":["Vẫn uống vì sữa trông và ngửi vẫn bình thường, không sao đâu","Vứt hộp sữa đi và im lặng coi như bài học cho riêng mình","Mang hộp sữa sang đổi ở một cửa hàng khác không phải nơi đã mua"],"e":"Không dùng thực phẩm không rõ hạn sử dụng; người tiêu dùng có quyền yêu cầu đổi trả tại đúng nơi bán khi có chứng từ hợp lệ."},{"f":"X1","p":"Trên mạng, một sản phẩm được quảng cáo là 'thực phẩm chức năng chữa được bách bệnh', nhiều bình luận khen ngợi. Ông bà em muốn dành tiền mua sản phẩm này thay cho thuốc điều trị đang dùng. Em nên khuyên ông bà điều gì?","a":"Không tin quảng cáo quá mức, hỏi bác sĩ trước khi dùng","w":["Ủng hộ ông bà mua vì nhiều người bình luận khen thì chắc chắn tốt","Khuyên ông bà mua thật nhiều để dùng dần cho được giá ưu đãi","Khuyên ông bà ngừng thuốc điều trị ngay để chuyển sang sản phẩm này"],"e":"Quảng cáo thổi phồng công dụng là vi phạm và gây hại; thực phẩm chức năng không thay thế thuốc chữa bệnh, mọi thay đổi điều trị phải theo chỉ định y tế."},{"f":"X1","p":"Em mua áo qua mạng, khi nhận hàng thấy chất liệu và kích cỡ khác xa mô tả, nhưng người bán từ chối đổi trả dù trang bán hàng có ghi chính sách đổi trả rõ ràng. Em nên làm gì?","a":"Lưu bằng chứng, khiếu nại sàn và nơi bán theo chính sách","w":["Chấp nhận mất tiền vì mua qua mạng thì phải chịu rủi ro như vậy","Đăng bài chửi bới, bịa thêm lỗi khác của người bán cho bõ tức","Mang áo đi bán lại cho bạn khác với giá gốc mà không nói rõ lỗi"],"e":"Người tiêu dùng có quyền khiếu nại khi hàng hoá không đúng mô tả; dùng bằng chứng và kênh khiếu nại chính thức là cách bảo vệ quyền lợi đúng đắn, văn minh."},{"f":"X1","p":"Đi siêu thị không mang danh sách, em bị thu hút bởi hàng loạt sản phẩm 'mua một tặng một' và chất đầy giỏ những món gia đình không thực sự cần, trong đó có món gần hết hạn. Bài học tiêu dùng đúng nhất là gì?","a":"Lập danh sách, kiểm tra hạn, chỉ mua theo nhu cầu","w":["Khuyến mãi mua một tặng một thì mua càng nhiều càng có lợi","Chỉ cần tránh món gần hết hạn, còn mua thừa món khác thì không sao","Từ nay không đi siêu thị nữa vì ở đó toàn chiêu trò khuyến mãi"],"e":"Khuyến mãi chỉ có lợi khi món hàng thực sự cần và còn hạn dùng tốt; mua sắm theo danh sách giúp tránh lãng phí tiền và thực phẩm."},{"f":"X1","p":"Khi mua hàng qua mạng, người bán yêu cầu em chuyển tiền vào một tài khoản cá nhân lạ ở ngoài ứng dụng mua sắm để 'được giảm thêm phí'. Em nên ứng xử thế nào?","a":"Từ chối giao dịch ngoài ứng dụng, dùng kênh chính thức","w":["Chuyển ngay vì giảm được phí thì chuyển ở đâu cũng là trả tiền mua hàng","Chuyển một nửa trước để giữ hàng, nửa còn lại trả khi nhận được đồ","Nhờ bạn chuyển hộ bằng tài khoản của bạn cho đỡ liên quan đến mình"],"e":"Giao dịch ngoài kênh chính thức làm mất cơ chế bảo vệ của sàn thương mại; yêu cầu chuyển khoản lạ là dấu hiệu lừa đảo phổ biến cần tránh xa."},{"f":"X2","p":"Nhận định: 'Hàng hoá càng đắt tiền thì chất lượng càng tốt, còn hàng giá rẻ thì chắc chắn là hàng kém chất lượng.' Nhận định này đúng hay sai?","a":"Sai, chất lượng xét theo nguồn gốc, tiêu chuẩn, nhu cầu","w":["Đúng, giá tiền bao giờ cũng phản ánh chính xác chất lượng hàng hoá","Đúng, vì vậy người thông minh chỉ nên mua hàng đắt nhất có thể","Sai, vì hàng giá rẻ bao giờ cũng tốt hơn hàng đắt tiền"],"e":"Giá cả chỉ là một yếu tố; người tiêu dùng thông minh đánh giá hàng hoá qua nguồn gốc, nhãn mác, tiêu chuẩn chất lượng và mức phù hợp với nhu cầu, không suy đoán một chiều từ giá."}],"gd9-b9":[{"f":"X1","p":"Em mượn xe đạp của bạn để đi học thêm. Do bất cẩn, em làm xe bị cong vành và hỏng phanh. Bạn rất buồn vì xe là phương tiện đi học hằng ngày. Trách nhiệm phù hợp nhất của em là gì?","a":"Nhận lỗi, thoả thuận sửa chữa, bồi thường thiệt hại cho bạn","w":["Trả lại xe lặng lẽ và nói xe tự hỏng khi đang đi trên đường","Cho rằng mượn xe thì hỏng hóc là rủi ro bạn phải tự chịu","Bỏ mặc vì giữa bạn bè với nhau không cần nói đến bồi thường"],"e":"Gây thiệt hại cho tài sản của người khác do lỗi của mình là vi phạm dân sự; người gây thiệt hại phải bồi thường, khắc phục hậu quả theo thoả thuận hoặc quy định pháp luật."},{"f":"X1","p":"Trong giờ kiểm tra do nhà trường tổ chức, một bạn bị phát hiện sử dụng tài liệu và điện thoại để gian lận. Ngoài việc xử lí bài kiểm tra, bạn đó còn phải chịu hình thức trách nhiệm nào trong nhà trường?","a":"Trách nhiệm kỉ luật theo nội quy, quy chế của nhà trường","w":["Trách nhiệm hình sự vì gian lận thi cử là tội phạm nghiêm trọng","Trách nhiệm dân sự vì đã gây thiệt hại vật chất cho nhà trường","Không phải chịu trách nhiệm gì thêm ngoài điểm không bài kiểm tra"],"e":"Vi phạm quy chế thi, nội quy trường học thuộc nhóm vi phạm kỉ luật; học sinh chịu hình thức kỉ luật của nhà trường tương ứng mức độ vi phạm."},{"f":"X1","p":"Một người bán hàng rong bày hàng lấn chiếm gần hết vỉa hè, đẩy người đi bộ xuống lòng đường, cản trở giao thông và bị lực lượng chức năng lập biên bản xử phạt tiền. Đây là loại vi phạm và trách nhiệm nào?","a":"Vi phạm hành chính, chịu trách nhiệm hành chính","w":["Vi phạm hình sự vì lấn chiếm lòng đường là hành vi nguy hiểm nhất","Vi phạm dân sự vì đã tranh chấp phần đường với người đi bộ","Vi phạm kỉ luật vì người bán hàng thuộc quản lí của tổ dân phố"],"e":"Hành vi xâm phạm trật tự quản lí nhà nước như lấn chiếm vỉa hè bị xử phạt hành chính; đây là điểm khác biệt với vi phạm hình sự, dân sự hay kỉ luật."},{"f":"X1","p":"Một bạn trong khu dân cư rủ em tham gia nhóm đi 'trả thù' một nhóm khác bằng hung khí vào tối cuối tuần vì mâu thuẫn trên mạng. Em nhận ra việc này rất nguy hiểm. Em nên làm gì?","a":"Từ chối, khuyên dừng lại, báo người lớn khi cần","w":["Đi cùng nhóm nhưng chỉ đứng xem, không trực tiếp ra tay là được","Giúp nhóm chuẩn bị đồ đạc nhưng không đi theo vào tối hôm đó","Im lặng không tham gia và cũng không cần báo cho ai biết"],"e":"Hành vi dùng hung khí đánh người có thể dẫn tới trách nhiệm hình sự về tội cố ý gây thương tích; ngăn chặn từ giai đoạn chuẩn bị là cách bảo vệ cả bạn và bản thân"},{"f":"X1","p":"Gia đình em thuê một căn phòng trọ có thoả thuận miệng và giấy biên nhận về giá thuê trong một năm. Chưa đầy nửa năm, chủ trọ tự ý tăng giá cao và doạ đuổi nếu không đồng ý. Tranh chấp này thuộc lĩnh vực pháp luật nào là chủ yếu?","a":"Tranh chấp dân sự về hợp đồng đã thoả thuận","w":["Vi phạm hình sự vì chủ trọ đã có hành vi đe doạ người thuê nhà","Vi phạm hành chính vì giá thuê nhà do cơ quan nhà nước ấn định sẵn","Vi phạm kỉ luật vì chủ trọ và người thuê cùng thuộc một khu phố"],"e":"Quan hệ thuê nhà là quan hệ dân sự dựa trên thoả thuận; khi một bên không tôn trọng cam kết, các bên giải quyết bằng thương lượng hoặc khởi kiện dân sự theo quy định."},{"f":"X1","p":"Trên đường về nhà, em nhặt được một chiếc ví có tiền và nhiều giấy tờ tuỳ thân quan trọng của người đánh rơi. Một bạn đi cùng bảo cứ giữ tiền lại, giấy tờ thì vứt đi. Em nên làm gì cho đúng pháp luật và đạo lí?","a":"Nộp ví cho công an để trả lại chủ sở hữu","w":["Giữ lại tiền trong ví, chỉ trả lại giấy tờ cho người đánh rơi","Vứt ví ở chỗ khác để khỏi liên quan đến chuyện tiền bạc của người lạ","Mang ví về nhà cất kĩ, chờ vài tháng không ai hỏi thì dùng tiền"],"e":"Chiếm giữ tài sản của người khác làm của riêng là hành vi trái pháp luật; nhặt được của rơi cần tìm cách trả lại qua cơ quan có thẩm quyền."},{"f":"X1","p":"Một chiếc xe tải chở hàng quá tải trọng, chạy quá tốc độ quy định trên đoạn đường đông dân cư và bị cảnh sát giao thông dừng xe, xử phạt và tạm giữ giấy phép lái xe. Người lái xe phải chịu loại trách nhiệm nào?","a":"Trách nhiệm hành chính về an toàn giao thông","w":["Trách nhiệm hình sự trong mọi trường hợp chở quá tải, quá tốc độ","Trách nhiệm dân sự vì đã làm đường giao thông bị hư hỏng nặng","Trách nhiệm kỉ luật do công ty vận tải tự xử lí nội bộ là chính"],"e":"Vi phạm quy tắc giao thông chưa gây hậu quả nghiêm trọng thuộc xử lí hành chính; chỉ khi gây hậu quả nghiêm trọng theo quy định mới xem xét trách nhiệm hình sự."},{"f":"X1","p":"Một nhân viên trong cơ quan thường xuyên đi muộn, bỏ vị trí làm việc không lí do và đã được nhắc nhở nhiều lần nên bị cơ quan áp dụng hình thức khiển trách. Hình thức khiển trách này thuộc loại trách nhiệm nào?","a":"Trách nhiệm kỉ luật trong cơ quan, tổ chức","w":["Trách nhiệm hành chính do cơ quan nhà nước cấp trên ban hành","Trách nhiệm dân sự vì đã gây thiệt hại uy tín cho cơ quan","Trách nhiệm hình sự ở mức nhẹ nhất dành cho người lao động"],"e":"Vi phạm nội quy, quy chế của cơ quan, tổ chức nơi mình công tác, học tập thuộc vi phạm kỉ luật và bị xử lí kỉ luật trong phạm vi nội bộ đó."},{"f":"X1","p":"Một tài khoản mạng xã hội đăng thông tin bịa đặt, xúc phạm danh dự một giáo viên trong trường khiến thầy cô rất bức xúc và uy tín bị ảnh hưởng. Người bị hại có thể bảo vệ mình bằng cách nào phù hợp?","a":"Lưu bằng chứng, yêu cầu gỡ bỏ, báo cơ quan thẩm quyền","w":["Tự ý đăng lại thông tin bịa đặt khác về chủ tài khoản để trả đũa","Im lặng chịu đựng vì chuyện trên mạng xã hội không ai xử lí được","Nhờ học sinh trong trường vào tài khoản đó bình luận chửi bới lại"],"e":"Xúc phạm danh dự, nhân phẩm người khác có thể phải chịu trách nhiệm dân sự như xin lỗi, bồi thường và tuỳ mức độ còn bị xử lí hành chính hoặc hình sự; nạn nhân cần dùng bằng chứng và kênh pháp luật."},{"f":"X1","p":"Em chứng kiến một bạn trong lớp nhiều lần lấy đồ dùng học tập của bạn khác giấu đi để trêu đùa, khiến bạn bị mất đồ rất lo lắng. Dù chưa có thiệt hại lớn, em nên nhìn nhận hành vi này thế nào?","a":"Hành vi sai, cần ngăn sớm, báo thầy cô xử lí phù hợp","w":["Chỉ là trò đùa vô hại của học sinh, không liên quan gì đến pháp luật","Đã là hành vi trộm cắp nghiêm trọng phải đưa ngay ra cơ quan công an","Việc của hai bạn với nhau, người ngoài không nên can thiệp điều gì"],"e":"Hành vi xâm phạm tài sản, quyền lợi của người khác dù bắt đầu từ 'trêu đùa' cũng là sai trái; ngăn chặn, giáo dục sớm giúp tránh leo thang thành vi phạm pháp luật thực sự."},{"f":"X2","p":"Nhận định: 'Mọi hành vi vi phạm pháp luật đều phải chịu trách nhiệm hình sự.' Nhận định này đúng hay sai?","a":"Sai, còn có trách nhiệm hành chính, dân sự, kỉ luật","w":["Đúng, vi phạm pháp luật thì hình thức xử lí cao nhất luôn được áp dụng","Đúng, vì trách nhiệm hình sự bao gồm tất cả các loại trách nhiệm khác","Sai, vì vi phạm pháp luật của học sinh thì không phải chịu trách nhiệm nào"],"e":"Pháp luật phân loại vi phạm thành hình sự, hành chính, dân sự và kỉ luật, tương ứng là các loại trách nhiệm khác nhau tuỳ tính chất, mức độ nguy hiểm của hành vi."}],"gd9-b10":[{"f":"X1","p":"Anh trai em muốn mở một tiệm sửa chữa xe máy nhỏ tại nhà sau khi học nghề xong. Để bắt đầu kinh doanh hợp pháp, anh cần quan tâm đến những việc nào trước tiên?","a":"Đăng kí kinh doanh, bảo đảm an toàn, kê khai thuế","w":["Cứ mở tiệm hoạt động trước, khi nào đông khách mới cần đăng kí gì","Chỉ cần vay đủ vốn và thuê mặt bằng, thủ tục pháp lí không quan trọng","Nhờ người khác đứng tên tiệm để mình khỏi phải kê khai, nộp thuế"],"e":"Quyền tự do kinh doanh được pháp luật bảo hộ khi công dân kinh doanh đúng ngành nghề cho phép, làm thủ tục đăng kí và thực hiện nghĩa vụ thuế, an toàn theo quy định."},{"f":"X1","p":"Chị họ em bán hàng trực tuyến tại nhà với doanh thu ngày càng ổn định. Chị cho rằng bán tại nhà, quy mô nhỏ thì không cần quan tâm đến kê khai hay hoá đơn gì cả. Lời khuyên đúng nhất cho chị là gì?","a":"Tìm hiểu kê khai, hoá đơn, nộp thuế đúng hoạt động","w":["Đồng ý với chị vì bán hàng tại nhà thì pháp luật không quản lí tới","Khuyên chị chia nhỏ doanh thu ra nhiều tài khoản để khỏi phải kê khai","Khuyên chị ngừng bán hàng trực tuyến vì thủ tục thuế quá phức tạp"],"e":"Kinh doanh dưới mọi hình thức đều phải tuân thủ pháp luật về thuế và hoá đơn ở mức tương ứng; tìm hiểu qua cơ quan thuế giúp tránh vi phạm và bị xử phạt."},{"f":"X1","p":"Một cửa hàng tạp hoá gần nhà em bị phát hiện bán nhiều mặt hàng thực phẩm đã hết hạn sử dụng nhưng được dán lại nhãn ngày tháng mới. Hành vi này bị đánh giá thế nào?","a":"Kinh doanh gian dối, vi phạm luật, hại người tiêu dùng","w":["Là cách làm khôn ngoan để tránh lãng phí hàng hoá tồn kho của cửa hàng","Chỉ là lỗi nhỏ về nhãn mác, không ảnh hưởng gì đến người tiêu dùng","Là việc bình thường vì khách hàng mua thì phải tự kiểm tra hạn dùng"],"e":"Người kinh doanh phải bảo đảm chất lượng, an toàn hàng hoá; gian lận hạn sử dụng là vi phạm pháp luật về kinh doanh và an toàn thực phẩm, bị xử lí và bồi thường thiệt hại."},{"f":"X1","p":"Em thấy một người bán hàng rong chào bán thuốc lá cho các em nhỏ tuổi vị thành niên trước cổng trường. Em nên có thái độ và hành động nào phù hợp?","a":"Không mua, nhắc các em, báo trường và cơ quan chức năng","w":["Coi đó là tự do kinh doanh, ai có nhu cầu mua thì người bán cứ bán","Giúp người bán chào mời thêm vì thấy việc buôn bán đang thuận lợi","Mua hộ các em nhỏ vì các em không trực tiếp mua sẽ không sao"],"e":"Pháp luật cấm bán thuốc lá cho người dưới 18 tuổi; bảo vệ trẻ em trước mặt hàng có hại là trách nhiệm chung, không thể lấy tự do kinh doanh để biện minh."},{"f":"X1","p":"Cuối năm, chủ một cơ sở kinh doanh quen với gia đình em than doanh thu cao, thuế phải nộp nhiều, và định khai giảm doanh thu xuống thấp hơn thực tế. Em nghe được câu chuyện này. Nhận định đúng về ý định đó là gì?","a":"Đó là trốn thuế, vi phạm nghĩa vụ kinh doanh","w":["Đó là cách tiết kiệm hợp lí mà cơ sở kinh doanh nào cũng làm","Chỉ khi bị cơ quan thuế phát hiện thì việc khai giảm mới là sai","Khai giảm một phần nhỏ doanh thu thì không bị coi là trốn thuế"],"e":"Kê khai trung thực và nộp thuế đúng, đủ là nghĩa vụ bắt buộc; cố ý khai gian để giảm số thuế phải nộp là trốn thuế và sẽ bị truy thu, xử phạt."},{"f":"X1","p":"Trường học mới của xóm em được xây khang trang bằng nguồn ngân sách nhà nước, trong đó có tiền thu từ thuế của người dân và doanh nghiệp. Sự việc này giúp em hiểu điều gì về ý nghĩa của thuế?","a":"Thuế là nguồn thu xây công trình phục vụ nhân dân","w":["Tiền thuế chỉ dùng để trả lương cho cán bộ, không liên quan công trình công cộng","Trường học được xây là do nhà trường tự kinh doanh mà có ngân sách","Nộp thuế hay không thì công trình công cộng vẫn được xây như nhau"],"e":"Thuế tạo nguồn tài chính cho Nhà nước đầu tư vào giáo dục, y tế, giao thông và các dịch vụ công, vì vậy nộp thuế vừa là nghĩa vụ vừa là đóng góp cho cộng đồng."},{"f":"X1","p":"Hộ kinh doanh của gia đình bạn em bị thiệt hại nặng sau đợt lũ, được cơ quan thuế hướng dẫn làm thủ tục để xem xét miễn, giảm thuế theo chính sách hỗ trợ. Gia đình bạn nên làm gì?","a":"Làm thủ tục theo hướng dẫn để được xem xét hỗ trợ","w":["Tự ý ngừng nộp thuế từ nay mà không cần làm bất cứ thủ tục gì","Khai thiệt hại cao hơn thực tế nhiều lần để được miễn giảm thật nhiều","Bỏ hẳn việc kinh doanh vì sau lũ thì không còn ai quan tâm đến thuế nữa"],"e":"Chính sách miễn, giảm thuế khi thiên tai là sự hỗ trợ chính đáng, nhưng phải thực hiện đúng thủ tục, trung thực; tự ý ngừng nộp hoặc khai gian đều là vi phạm."},{"f":"X1","p":"Em tình cờ biết một cửa hàng sử dụng hai hệ thống sổ sách: một sổ thật và một sổ ghi doanh thu thấp hơn để trình cơ quan thuế. Em nên có thái độ nào cho đúng?","a":"Không tiếp tay, có thể phản ánh tới cơ quan thuế","w":["Coi đó là bí quyết kinh doanh khôn ngoan nên học hỏi cho sau này","Giúp cửa hàng giữ bí mật vì đó là chuyện nội bộ của người ta","Đe doạ cửa hàng phải chia một phần lợi ích nếu không sẽ đi tố cáo"],"e":"Lập sổ sách gian lận để trốn thuế là vi phạm pháp luật; công dân có quyền và trách nhiệm phản ánh vi phạm qua kênh chính thức, không tiếp tay hay lợi dụng để vụ lợi."},{"f":"X1","p":"Gia đình em dự định sản xuất và bán một loại thực phẩm chế biến sẵn ra thị trường. Đây là mặt hàng liên quan trực tiếp đến sức khoẻ người dùng. Trước khi bán, gia đình cần làm gì cho đúng quy định?","a":"Đáp ứng điều kiện an toàn thực phẩm, đăng kí đúng","w":["Cứ bán thử trước, nếu khách ăn không sao thì không cần thủ tục gì","Chỉ cần bao bì đẹp và quảng cáo hay là đủ điều kiện bán hàng","Nhờ một cơ sở khác đã có giấy phép đứng tên hộ mãi mãi cho tiện"],"e":"Một số ngành nghề là kinh doanh có điều kiện; với thực phẩm, điều kiện an toàn vệ sinh phải được đáp ứng và kiểm tra trước khi đưa sản phẩm ra thị trường."},{"f":"X1","p":"Quán ăn của gia đình em bị một đối thủ tung tin sai sự thật trên mạng rằng quán dùng nguyên liệu kém chất lượng, khiến khách hàng hoang mang. Gia đình em nên ứng xử thế nào?","a":"Lưu bằng chứng, báo thẩm quyền, cạnh tranh bằng chất lượng","w":["Tung lại tin sai sự thật về quán đối thủ để trả đũa cho công bằng","Đóng cửa quán một thời gian dài chờ tin đồn tự lắng xuống hẳn","Nhờ người quen vào trang của đối thủ chửi bới, đe doạ liên tục"],"e":"Cạnh tranh phải lành mạnh, đúng pháp luật; bị tung tin giả gây hại, người kinh doanh bảo vệ uy tín bằng bằng chứng và cơ quan có thẩm quyền, không trả đũa bằng cách làm sai tương tự."},{"f":"X2","p":"Nhận định: 'Công dân có quyền tự do kinh doanh nghĩa là được bán bất cứ mặt hàng nào mang lại lợi nhuận, kể cả hàng cấm.' Nhận định này đúng hay sai?","a":"Sai, tự do kinh doanh phải trong khuôn khổ pháp luật","w":["Đúng, đã là quyền tự do thì pháp luật không được giới hạn mặt hàng nào","Đúng, miễn hàng hoá có người mua thì việc bán là hợp lí và hợp pháp","Sai, vì công dân hoàn toàn không có quyền tự do kinh doanh ở nước ta"],"e":"Quyền tự do kinh doanh là quyền kinh doanh các ngành nghề pháp luật không cấm và đáp ứng điều kiện kinh doanh; hàng cấm, hàng giả, hàng gây hại bị nghiêm cấm và xử lí nghiêm."}],"kh9-mo":[{"f":"K2","p":"Một nhóm nêu dự đoán 'nước ấm hoà tan đường nhanh hơn nước lạnh'. Bước tiếp theo đúng trình tự nghiên cứu là gì?","a":"Thiết kế thí nghiệm có đối chứng để kiểm tra dự đoán","w":["Viết ngay kết luận rằng dự đoán đúng hoàn toàn","Bỏ qua thí nghiệm, tìm câu trả lời trong trí nhớ","Trình bày kết quả trước lớp khi chưa làm thí nghiệm"],"e":"Trình tự: đặt vấn đề → dự đoán → thí nghiệm kiểm chứng → kết luận dựa trên số liệu."},{"f":"K2","p":"Để kiểm tra dự đoán trên, hai cốc thí nghiệm cần khác nhau ở điểm nào duy nhất?","a":"Nhiệt độ nước; đường, nước, cách khuấy đều giống nhau","w":["Cốc nước ấm nhiều đường hơn cốc nước lạnh","Cốc nước ấm khuấy mạnh, cốc lạnh không khuấy","Hai cốc dùng hai loại đường khác nhau để so"],"e":"Chỉ nhiệt độ thay đổi; mọi yếu tố khác giống nhau mới kết luận được về nhiệt độ."},{"f":"K2","p":"Khi thuyết trình kết quả nghiên cứu, cách trình bày số liệu nào thuyết phục nhất?","a":"Bảng số liệu và biểu đồ kèm nhận xét dựa trên số liệu đó","w":["Chỉ nói kết luận bằng lời, không đưa số liệu nào","Đưa số liệu của lần đo đẹp nhất, bỏ lần khác biệt","Sao chép biểu đồ của nhóm khác cho đẹp hơn"],"e":"Số liệu đầy đủ, trình bày rõ và nhận xét bám số liệu là cách thuyết trình khoa học."},{"f":"K2","p":"Muốn kiểm tra độ chính xác của một chiếc cân điện tử trong phòng thí nghiệm, cách làm đúng là gì?","a":"Cân các quả cân chuẩn đã biết khối lượng, lặp lại vài lần","w":["Cân một vật bất kì rồi tin ngay số hiển thị","Đoán khối lượng bằng tay rồi so với cân một lần","Chỉ cần cân hoạt động được là chắc chắn chính xác"],"e":"Quả cân chuẩn cho giá trị thật để đối chiếu; lặp lại giúp phát hiện sai lệch hệ thống."},{"f":"K2","p":"Trong báo cáo thí nghiệm, vì sao phải ghi cả những lần đo không như dự đoán?","a":"Để báo cáo trung thực, từ đó phân tích nguyên nhân sai lệch","w":["Để bài báo cáo dài hơn và trông chăm chỉ hơn","Không cần ghi, chỉ ghi lần đúng là đủ yêu cầu","Ghi lại để đổ lỗi cho dụng cụ thí nghiệm"],"e":"Trung thực với mọi số liệu là nguyên tắc nghiên cứu; số liệu lệch giúp tìm lỗi và cải tiến."},{"f":"K3","p":"Thời gian hoà tan đường: nước 20°C: 95 s, 85 s, 90 s; nước 50°C: 32 s, 28 s, 30 s. Kết luận đúng là gì?","a":"Nước ấm hoà tan nhanh hơn khoảng 3 lần nước lạnh","w":["Nước lạnh hoà tan nhanh hơn nước ấm rõ rệt","Nhiệt độ không ảnh hưởng thời gian hoà tan","Một lần đo 95 s chứng tỏ nước lạnh luôn cần 95 s"],"e":"Trung bình: lạnh 90 s, ấm 30 s → ấm nhanh gấp khoảng 3 lần; kết luận dựa trên trung bình nhiều lần đo."},{"f":"K3","p":"Bảng số lần nảy mầm trong 30 hạt mỗi khay: khay ẩm: 27 hạt, khay khô: 3 hạt, khay ngập nước: 9 hạt. Kết luận đúng là gì?","a":"Độ ẩm vừa phải thuận lợi nhất cho nảy mầm trong thử này","w":["Khay khô nảy mầm tốt nhất theo số liệu trên","Ngập nước là điều kiện nảy mầm tốt nhất","Cả ba khay nảy mầm như nhau hoàn toàn"],"e":"27 > 9 > 3: khay ẩm vừa nảy mầm nhiều nhất; khô quá hay ngập úng đều kém hơn."},{"f":"K3","p":"Đo khối lượng một mẫu đá 3 lần: 152 g, 151 g, 153 g. Giá trị nên báo cáo là gì?","a":"Khoảng 152 g (trung bình ba lần đo)","w":["Đúng tuyệt đối 153 g vì là số đo cuối cùng","Cộng ba lần thành 456 g để báo cáo","Bỏ hết vì ba số không giống hệt nhau"],"e":"Trung bình (152+151+153)/3 = 152 g; các lần đo gần nhau cho thấy phép đo ổn định."},{"f":"K3","p":"Một thí nghiệm chỉ làm 1 lần cho kết quả ủng hộ dự đoán. Nhận xét đúng về độ tin cậy là gì?","a":"Chưa đủ tin cậy, cần lặp lại thí nghiệm nhiều lần","w":["Một lần đúng là đủ chứng minh dự đoán luôn đúng","Kết quả đó áp dụng được cho mọi điều kiện khác","Không cần số liệu vì đã khớp với dự đoán rồi"],"e":"Một lần đo có thể tình cờ hoặc sai sót; lặp lại mới khẳng định được quy luật."},{"f":"K3","p":"Biểu đồ cột số cây sống sót: nhóm tưới đều 18/20, nhóm không tưới 5/20, nhóm tưới quá nhiều 9/20. Kết luận KHÔNG suy rộng quá mức là gì?","a":"Trong thử này, tưới đều cho tỉ lệ sống cao nhất","w":["Mọi loài cây đều cần đúng lượng nước như cây này","Không tưới thì không cây nào trên Trái Đất sống được","Tưới càng nhiều thì cây luôn càng sống tốt"],"e":"Chỉ kết luận trong phạm vi thử nghiệm; tưới quá nhiều cho kết quả kém hơn tưới đều (9 < 18)."}],"kh9-p1":[{"f":"K2","p":"Muốn kiểm tra động năng phụ thuộc vào tốc độ, thí nghiệm công bằng cần giữ gì không đổi?","a":"Khối lượng vật, chỉ thay đổi tốc độ của vật","w":["Thay cả khối lượng và tốc độ cùng lúc mỗi lần","Chỉ đo một tốc độ rồi suy ra mọi tốc độ khác","Dùng vật khác nhau hoàn toàn ở mỗi lần đo"],"e":"Động năng phụ thuộc cả khối lượng và tốc độ; muốn xét tốc độ phải giữ khối lượng không đổi."},{"f":"K2","p":"Để kiểm tra thế năng của vật phụ thuộc độ cao, cách đo nào đúng?","a":"Thả cùng một vật từ nhiều độ cao, so tác dụng lên vật đỡ","w":["Thả các vật nặng khác nhau từ cùng một độ cao","Thả vật từ một độ cao duy nhất rồi kết luận","Đổi cả vật và độ cao mỗi lần thả cho đa dạng"],"e":"Cùng một vật (khối lượng không đổi), chỉ độ cao thay đổi mới kết luận được về độ cao."},{"f":"K2","p":"Muốn so công suất của hai bạn khi kéo nước từ giếng, phép đo công bằng cần ghi gì?","a":"Công thực hiện và thời gian thực hiện của mỗi bạn","w":["Chỉ ghi ai kéo được nhiều nước hơn là đủ","Chỉ ghi thời gian, không cần biết công làm được","Đo sức khoẻ của hai bạn thay cho công và thời gian"],"e":"Công suất = công/thời gian nên phải đo cả hai đại lượng trong cùng công việc."},{"f":"K2","p":"Kiểm tra dự đoán 'vật rơi từ cao hơn chạm đất mạnh hơn', dấu hiệu quan sát hợp lí là gì?","a":"Độ lún của vật trên nền cát mềm ở mỗi độ cao thả","w":["Màu sắc của vật sau khi chạm đất mềm","Âm thanh nghe to hay nhỏ theo cảm tính cá nhân","Thời gian rơi đo bằng cách đếm nhẩm trong đầu"],"e":"Độ lún đo được và so sánh được giữa các lần thả, khách quan hơn cảm tính âm thanh."},{"f":"K2","p":"Khi đo công kéo vật lên dốc, vì sao phải đo cả quãng đường kéo và lực kéo?","a":"Vì công bằng lực nhân quãng đường theo hướng lực","w":["Vì chỉ đo lực kéo là tự tính được công ngay","Vì quãng đường không ảnh hưởng gì tới công kéo","Đo hai đại lượng chỉ để bảng số liệu đầy đủ"],"e":"A = F × s: thiếu một trong hai đại lượng thì không tính được công thực hiện."},{"f":"K3","p":"Vật 2 kg chuyển động với tốc độ 3 m/s. Động năng của vật là bao nhiêu?","a":"9 J","w":["6 J","18 J","3 J"],"e":"Wđ = ½mv² = ½ × 2 × 3² = 9 J."},{"f":"K3","p":"Quả nặng 2 kg ở độ cao 5 m so với mặt đất (g = 10 m/s²). Thế năng của nó là bao nhiêu?","a":"100 J","w":["10 J","20 J","50 J"],"e":"Wt = mgh = 2 × 10 × 5 = 100 J."},{"f":"K3","p":"Bảng động năng của vật 1 kg: v = 1 m/s: 0,5 J; 2 m/s: 2 J; 3 m/s: 4,5 J. Kết luận đúng là gì?","a":"Tốc độ gấp đôi thì động năng gấp bốn lần","w":["Động năng tăng tỉ lệ thuận đơn giản với tốc độ","Tốc độ gấp ba thì động năng gấp ba lần","Động năng không đổi khi tốc độ thay đổi"],"e":"0,5 → 2 J là gấp 4 khi v gấp 2: động năng tỉ lệ với bình phương tốc độ."},{"f":"K3","p":"Một người kéo lực 50 N trên quãng đường 10 m trong 5 s. Công suất của người đó là bao nhiêu?","a":"100 W","w":["500 W","25 W","10 W"],"e":"A = 50 × 10 = 500 J; P = 500/5 = 100 W."},{"f":"K3","p":"Vật rơi từ độ cao h, bỏ qua sức cản: thế năng ban đầu 200 J. Động năng ngay trước khi chạm đất là bao nhiêu?","a":"200 J","w":["0 J","100 J","400 J"],"e":"Cơ năng bảo toàn: thế năng chuyển hết thành động năng nên động năng chạm đất = 200 J."}],"kh9-p2":[{"f":"K2","p":"Muốn kiểm tra góc khúc xạ thay đổi theo góc tới, cách làm đúng là gì?","a":"Chiếu qua cùng bản thuỷ tinh với nhiều góc tới, ghi từng cặp","w":["Mỗi góc tới dùng một chất khác nhau để so sánh","Chỉ chiếu một góc tới rồi suy ra mọi góc còn lại","Đo góc khúc xạ bằng mắt ước lượng, không cần thước đo góc"],"e":"Cùng một môi trường, thay đổi có hệ thống góc tới và ghi cặp số liệu mới rút ra quy luật."},{"f":"K2","p":"Để kiểm tra kính lúp phóng đại vật, phép so công bằng là gì?","a":"Nhìn cùng vật qua kính và bằng mắt thường, cùng khoảng cách","w":["Nhìn vật to qua kính và vật nhỏ bằng mắt thường rồi so","Đưa kính thật xa vật cho hình ảnh to nhất có thể","Chỉ nhìn qua kính một lần rồi kết luận độ phóng đại"],"e":"Cùng vật, cùng khoảng cách quan sát thì sự khác biệt mới do kính lúp gây ra."},{"f":"K2","p":"Muốn tìm tiêu cự của thấu kính hội tụ bằng ánh sáng mặt trời, cách làm và ghi kết quả đúng là gì?","a":"Dịch màn đến vệt sáng nhỏ nhất, đo khoảng cách tới thấu kính","w":["Đặt màn ở vị trí bất kì rồi đo một lần duy nhất","Nhìn trực tiếp qua thấu kính vào mặt trời để ước lượng","Đo khoảng cách từ thấu kính tới mặt trời làm tiêu cự"],"e":"Vệt sáng nhỏ nhất trên màn ứng với ảnh của nguồn xa, khoảng cách đó xấp xỉ tiêu cự; lặp lại để chắc chắn."},{"f":"K2","p":"Kiểm tra hiện tượng phản xạ toàn phần, vì sao phải tăng góc tới từ từ và ghi góc bắt đầu mất tia khúc xạ?","a":"Để xác định góc tới hạn của cặp môi trường đó","w":["Để tia sáng biến mất càng sớm càng tốt trong thí nghiệm","Để không phải đo góc khúc xạ ở các lần chiếu","Góc giới hạn không cần số liệu vẫn kết luận được"],"e":"Góc tới hạn là giá trị cụ thể; chỉ tìm được bằng cách tăng dần góc tới và ghi mốc thay đổi."},{"f":"K2","p":"Khi vẽ đường truyền tia sáng qua lăng kính, ghi chép nào giúp kiểm tra kết quả đáng tin?","a":"Đánh dấu tia bằng ghim, đo góc lệch, lặp với góc tới khác","w":["Vẽ tự do bằng tay không cần ghim đánh dấu tia","Chỉ làm một lần và tô đẹp hình vẽ là đủ","Bỏ qua góc lệch, chỉ ghi màu sắc quầng sáng"],"e":"Đánh dấu thực tế và lặp lại với góc tới khác cho thấy hiện tượng nhất quán, không phải vẽ đoán."},{"f":"K3","p":"Chùm sáng qua lăng kính tách thành dải màu theo thứ tự đỏ, cam, vàng, lục, lam, chàm, tím. Kết luận đúng là gì?","a":"Ánh sáng trắng là hỗn hợp nhiều ánh sáng màu","w":["Lăng kính tự tạo ra màu cho ánh sáng trắng","Ánh sáng trắng chỉ gồm đúng hai màu đỏ và tím","Dải màu chứng tỏ ánh sáng trắng là đơn sắc"],"e":"Lăng kính chỉ tán sắc (tách) các thành phần đã có sẵn trong ánh sáng trắng."},{"f":"K3","p":"Thấu kính có tiêu cự 10 cm. Vật đặt cách thấu kính 30 cm cho ảnh rõ trên màn cách thấu kính 15 cm, ảnh cao bằng nửa vật. Kết luận đúng là gì?","a":"Ảnh thật, ngược chiều và nhỏ hơn vật","w":["Ảnh ảo, cùng chiều và lớn hơn vật","Không tạo được ảnh trên màn trong trường hợp này","Ảnh luôn bằng vật với mọi thấu kính hội tụ"],"e":"Ảnh hứng được trên màn là ảnh thật; cao nửa vật nên nhỏ hơn vật và ngược chiều."},{"f":"K3","p":"Bảng góc tới và góc khúc xạ (không khí → nước): 0°→0°, 20°→15°, 40°→29°, 60°→41°. Kết luận đúng là gì?","a":"Góc khúc xạ luôn nhỏ hơn góc tới khi vào nước","w":["Góc khúc xạ luôn lớn hơn góc tới tương ứng","Góc tới tăng thì góc khúc xạ giảm dần xuống","Ở góc tới 60° tia sáng không khúc xạ nữa"],"e":"Mọi cặp số đều có r < i: vào môi trường chiết quang hơn, tia gãy lại gần pháp tuyến."},{"f":"K3","p":"Kính lúp có tiêu cự 5 cm. Số bội giác tính theo công thức G = 25/f (cm) là bao nhiêu?","a":"5","w":["25","0,2","125"],"e":"G = 25/5 = 5: vật nhìn qua kính lớn gấp khoảng 5 lần khi ngắm chừng chuẩn."},{"f":"K3","p":"Tia sáng từ nước ra không khí: góc tới 30° cho tia khúc xạ 41°; góc tới 50° không còn tia khúc xạ. Kết luận đúng là gì?","a":"Ở 50° đã xảy ra phản xạ toàn phần","w":["Ở 50° tia sáng bị nước hấp thụ hết hoàn toàn","Góc khúc xạ ở 50° chắc chắn bằng 90° chính xác","Phản xạ toàn phần không thể xảy ra với nước"],"e":"Mất tia khúc xạ khi góc tới đủ lớn là dấu hiệu phản xạ toàn phần; góc tới hạn nằm giữa 30° và 50°."}],"kh9-p3":[{"f":"K2","p":"Muốn kiểm tra định luật Ohm trên một điện trở, thí nghiệm đúng cần làm gì?","a":"Thay đổi U, đo I tương ứng trên cùng điện trở nhiều lần","w":["Giữ nguyên một mức điện áp và đo đúng một lần","Đổi điện trở khác nhau ở mỗi mức điện áp đo","Đo hiệu điện thế mà không cần mắc ampe kế"],"e":"Nhiều cặp (U, I) trên cùng một điện trở mới kiểm tra được quan hệ tỉ lệ của định luật Ohm."},{"f":"K2","p":"Để so điện trở của hai dây dẫn khác vật liệu, điều kiện công bằng là gì?","a":"Hai dây cùng chiều dài và cùng tiết diện, đo trong cùng mạch","w":["Dây nào cũng được, dài ngắn tuỳ ý khi so sánh","Dây vật liệu tốt dùng ngắn, dây kia dùng thật dài","Chỉ cần biết tên vật liệu là kết luận được ngay"],"e":"Điện trở còn phụ thuộc chiều dài và tiết diện; giữ hai yếu tố đó giống nhau mới so được vật liệu."},{"f":"K2","p":"Muốn kiểm tra mạch song song có tổng điện trở nhỏ hơn mỗi điện trở thành phần, cách đo đúng là gì?","a":"Đo điện trở từng nhánh, rồi đo điện trở toàn mạch song song","w":["Chỉ đo toàn mạch rồi đoán điện trở từng nhánh","Mắc thêm nhánh đến khi mạch cháy mới kết luận","Đo bằng cách nhìn độ sáng đèn mà không đo điện"],"e":"So sánh số đo thực tế của từng nhánh với toàn mạch mới kiểm chứng được nhận định."},{"f":"K2","p":"Kiểm tra công suất tiêu thụ ghi trên bóng đèn, phép đo hợp lí là gì?","a":"Mắc đèn đúng U định mức, đo U và I, tính P = U·I","w":["Mắc đèn vào điện áp tuỳ ý rồi tin số ghi trên đèn","Đo công suất bằng cách sờ xem đèn nóng nhiều hay ít","Chỉ đo cường độ dòng điện là biết ngay công suất"],"e":"Công suất định mức ứng với hiệu điện thế định mức; đo U và I lúc đó rồi nhân lại để kiểm tra."},{"f":"K2","p":"Khi đo điện trở bằng vôn kế và ampe kế, vì sao phải đọc nhanh và ngắt mạch ngay sau khi đo?","a":"Để dây điện trở không nóng lên làm thay đổi điện trở của nó","w":["Để tiết kiệm điện cho phòng thí nghiệm nói chung","Để kim đồng hồ không bị mỏi khi chỉ số đo","Đọc nhanh hay chậm không ảnh hưởng gì kết quả"],"e":"Dòng điện làm nóng dây, điện trở thay đổi theo nhiệt độ nên đo lâu sẽ sai lệch dần."},{"f":"K3","p":"Điện trở 4 Ω mắc vào hiệu điện thế 12 V. Cường độ dòng điện qua nó là bao nhiêu?","a":"3 A","w":["48 A","0,33 A","8 A"],"e":"I = U/R = 12/4 = 3 A."},{"f":"K3","p":"Hai điện trở 3 Ω và 6 Ω mắc nối tiếp vào nguồn 9 V. Cường độ dòng điện trong mạch là bao nhiêu?","a":"1 A","w":["3 A","0,5 A","2 A"],"e":"R tổng = 3 + 6 = 9 Ω; I = 9/9 = 1 A."},{"f":"K3","p":"Hai điện trở 6 Ω và 3 Ω mắc song song. Điện trở tương đương của đoạn mạch là bao nhiêu?","a":"2 Ω","w":["9 Ω","4,5 Ω","18 Ω"],"e":"1/R = 1/6 + 1/3 = 1/2 → R = 2 Ω, nhỏ hơn cả hai điện trở thành phần."},{"f":"K3","p":"Bóng đèn 220 V – 100 W hoạt động đúng định mức trong 5 giờ. Điện năng tiêu thụ là bao nhiêu?","a":"0,5 kW·h","w":["500 kW·h","100 kW·h","5 kW·h"],"e":"A = P × t = 0,1 kW × 5 h = 0,5 kW·h (0,5 số điện)."},{"f":"K3","p":"Bảng đo trên một điện trở: U = 2 V → I = 0,5 A; 4 V → 1 A; 6 V → 1,5 A. Điện trở đó có giá trị bao nhiêu?","a":"4 Ω","w":["2 Ω","6 Ω","0,25 Ω"],"e":"R = U/I = 2/0,5 = 4 Ω, và không đổi ở cả ba lần đo: đúng định luật Ohm."}],"kh9-p4":[{"f":"K2","p":"Muốn kiểm tra điều kiện xuất hiện dòng điện cảm ứng, thí nghiệm nào có đối chứng rõ ràng?","a":"Một vòng để yên, một vòng cho nam châm chuyển động qua","w":["Cả hai vòng đều để yên rồi so sánh kim điện kế","Một vòng nối điện kế, vòng kia không nối gì cả","Chỉ làm trường hợp có dòng rồi kết luận mọi trường hợp"],"e":"Trường hợp đứng yên (không có dòng) cho thấy chính sự chuyển động tương đối mới tạo dòng cảm ứng."},{"f":"K2","p":"Để kiểm tra tốc độ quay của khung dây ảnh hưởng tới dòng xoay chiều, cần giữ gì không đổi?","a":"Nam châm, số vòng dây và điện kế; chỉ thay đổi tốc độ quay","w":["Thay nam châm mạnh hơn mỗi khi quay nhanh hơn","Đổi số vòng dây cùng lúc với tốc độ quay mỗi lần","Chỉ quay một tốc độ duy nhất rồi suy ra các tốc độ khác"],"e":"Chỉ tốc độ quay thay đổi mới quy được sự thay đổi của dòng cho yếu tố đó."},{"f":"K2","p":"Muốn so tác dụng nhiệt của dòng xoay chiều và dòng một chiều, phép so công bằng là gì?","a":"Cho hai dòng cùng I hiệu dụng qua cùng điện trở, đo nhiệt","w":["Dòng xoay chiều cho qua điện trở to, dòng một chiều qua điện trở nhỏ","Chỉ thử dòng xoay chiều rồi suy ra dòng một chiều","Đo nhiệt độ bằng tay sờ vào điện trở đang nóng"],"e":"Cùng điện trở và cường độ hiệu dụng như nhau mới so công bằng tác dụng nhiệt của hai loại dòng."},{"f":"K2","p":"Kiểm tra dự đoán 'nhiều vòng dây hơn cho dòng cảm ứng mạnh hơn', cách bố trí đúng là gì?","a":"Hai cuộn khác số vòng, cùng nam châm chuyển động như nhau","w":["Cuộn nhiều vòng dùng nam châm mạnh, cuộn ít vòng nam châm yếu","Di chuyển nam châm nhanh cho cuộn nhiều vòng hơn","Chỉ thử cuộn nhiều vòng rồi kết luận cho cuộn ít vòng"],"e":"Nam châm và tốc độ chuyển động phải giống nhau, chỉ số vòng khác nhau thì mới kết luận được."},{"f":"K2","p":"Khi trình bày kết quả thí nghiệm cảm ứng điện từ, ghi chép nào đầy đủ nhất?","a":"Ghi cả trường hợp có dòng và không có dòng cảm ứng","w":["Chỉ ghi những lần kim điện kế lệch mạnh nhất","Ghi kết luận 'luôn có dòng' cho ngắn gọn báo cáo","Bỏ qua lần nam châm đứng yên vì không có hiện tượng"],"e":"Trường hợp không có dòng cũng là dữ kiện quan trọng để rút ra điều kiện xuất hiện dòng cảm ứng."},{"f":"K3","p":"Quay khung dây đều: bảng số vòng quay mỗi giây và độ lệch kim điện kế: 1 vòng/s: nhỏ, 3 vòng/s: vừa, 5 vòng/s: lớn. Kết luận đúng là gì?","a":"Quay càng nhanh, dòng cảm ứng càng mạnh","w":["Quay nhanh hay chậm dòng cảm ứng đều như nhau","Quay chậm cho dòng cảm ứng mạnh nhất","Tốc độ quay không liên quan đến dòng cảm ứng"],"e":"Độ lệch tăng theo tốc độ quay: từ thông biến thiên càng nhanh, dòng cảm ứng càng mạnh."},{"f":"K3","p":"Máy phát điện xoay chiều quay 50 vòng mỗi giây. Tần số dòng điện tạo ra (một cặp cực) là bao nhiêu?","a":"50 Hz","w":["25 Hz","100 Hz","50 vòng/phút"],"e":"Mỗi vòng quay cho một chu kì dòng điện nên f = 50 Hz, đúng tần số điện lưới dân dụng."},{"f":"K3","p":"Đưa nam châm lại gần cuộn dây: kim lệch phải. Rút nam châm ra: kim lệch trái. Đưa vào nhanh hơn: kim lệch nhiều hơn. Kết luận đúng là gì?","a":"Dòng đổi chiều theo chuyển động, mạnh hơn khi chuyển nhanh","w":["Dòng cảm ứng luôn cùng một chiều trong mọi trường hợp","Tốc độ chuyển động không ảnh hưởng độ lệch kim","Khi rút nam châm ra thì không có dòng cảm ứng"],"e":"Đổi chiều chuyển động làm đổi chiều biến thiên từ thông nên dòng đổi chiều; nhanh hơn thì dòng mạnh hơn."},{"f":"K3","p":"Bóng đèn nối với máy phát tay quay: quay chậm đèn mờ nhấp nháy rõ, quay nhanh đều tay đèn sáng đều hơn. Giải thích đúng là gì?","a":"Quay nhanh cho dòng điện ổn định và mạnh hơn","w":["Đèn tự sáng hơn sau một lúc không do máy phát","Quay chậm cho dòng điện mạnh hơn quay nhanh","Máy phát tay chỉ tạo dòng một chiều cố định"],"e":"Tốc độ quay quyết định độ mạnh và tính liên tục của dòng cảm ứng phát ra."},{"f":"K3","p":"Một thiết bị dùng dòng xoay chiều 220 V, cường độ hiệu dụng 2 A. Công suất tiêu thụ xấp xỉ là bao nhiêu?","a":"440 W","w":["110 W","222 W","4400 W"],"e":"P ≈ U × I = 220 × 2 = 440 W với các thiết bị điện trở thông thường."}],"kh9-p5":[{"f":"K2","p":"Muốn kiểm tra tấm pin mặt trời ở hướng nào cho điện nhiều nhất, bố trí công bằng là gì?","a":"Cùng một pin, đặt lần lượt các hướng, đo lúc nắng như nhau","w":["Mỗi hướng dùng một tấm pin khác nhau để so sánh","Hướng nghiêng về mặt trời đo buổi trưa, hướng khác đo buổi chiều","Chỉ đo hướng thấy sáng nhất rồi kết luận luôn"],"e":"Cùng pin và điều kiện nắng tương đương, chỉ hướng đặt thay đổi mới so được lượng điện theo hướng."},{"f":"K2","p":"Để so hiệu quả giữ nhiệt của hai loại vật liệu cách nhiệt cho hộp nước nóng, cần giữ gì giống nhau?","a":"Lượng nước, nhiệt độ ban đầu và thời gian theo dõi như nhau","w":["Hộp vật liệu tốt chứa nhiều nước nóng hơn hộp kia","Đo hộp này sau 1 giờ, hộp kia sau 10 phút rồi so","Mở nắp hộp này và đậy kín hộp kia khi theo dõi"],"e":"Chỉ vật liệu cách nhiệt khác nhau; nước, nhiệt độ đầu và thời gian giống nhau mới công bằng."},{"f":"K2","p":"Muốn đánh giá một nguồn năng lượng là tái tạo hay không, tiêu chí kiểm tra đúng là gì?","a":"Xem nguồn có tự bổ sung nhanh theo thang đời người không","w":["Xem nguồn đó có tạo ra nhiều điện hay không","Xem nguồn đó có rẻ hơn các nguồn khác không","Xem nguồn đó đã được dùng lâu đời hay chưa"],"e":"Tính tái tạo nằm ở khả năng tự bổ sung nhanh (mặt trời, gió, nước) chứ không ở giá hay sản lượng."},{"f":"K2","p":"Kiểm tra dự đoán 'gió mạnh hơn làm tua-bin quay phát điện nhiều hơn', phép đo hợp lí là gì?","a":"Đo điện áp phát ra ở nhiều tốc độ gió, lặp lại mỗi mức","w":["Chỉ đo ở một cơn gió mạnh rồi suy ra mọi tốc độ gió","Đổi tua-bin lớn hơn khi gió mạnh để điện nhiều hơn","Đo tốc độ gió mà không cần đo lượng điện phát ra"],"e":"Phải đo cặp (tốc độ gió – lượng điện) nhiều mức mới thấy được quan hệ giữa hai đại lượng."},{"f":"K2","p":"Khi so lượng CO₂ thải ra của hai nhà máy, vì sao phải tính trên cùng một lượng điện sản xuất?","a":"Để so công bằng mức thải cho cùng một đơn vị sản phẩm","w":["Để hai nhà máy có con số thải bằng nhau cho đẹp","Vì lượng điện không liên quan gì tới lượng thải","Tính trên lượng điện khác nhau mới chính xác hơn"],"e":"Nhà máy lớn thải nhiều hơn là đương nhiên; chia cho cùng lượng điện mới thấy công nghệ nào sạch hơn."},{"f":"K3","p":"Bảng điện năng một hộ dùng trong tháng: than tổ ong (ước tính thải 90 kg CO₂), nếu chuyển sang bếp điện từ điện mặt trời mái nhà phần thải gần 0 cho phần điện đó. Kết luận đúng là gì?","a":"Dùng năng lượng tái tạo giúp giảm phát thải CO₂ rõ rệt","w":["Điện mặt trời thải CO₂ nhiều hơn than tổ ong","Thay đổi nguồn năng lượng không ảnh hưởng phát thải","CO₂ chỉ sinh ra từ xe cộ, không từ đun nấu"],"e":"Số liệu đối chiếu cho thấy nguồn tái tạo gần như không thải CO₂ khi vận hành, khác hẳn nhiên liệu hoá thạch."},{"f":"K3","p":"Một tấm pin mặt trời cho công suất 400 W lúc nắng tốt trong 5 giờ. Điện năng thu được là bao nhiêu?","a":"2 kW·h","w":["400 kW·h","80 kW·h","0,4 kW·h"],"e":"A = 0,4 kW × 5 h = 2 kW·h."},{"f":"K3","p":"Bảng sản lượng điện: thuỷ điện 30%, nhiệt điện than 45%, điện gió 10%, điện mặt trời 15%. Tỉ lệ năng lượng tái tạo là bao nhiêu?","a":"55%","w":["45%","25%","100%"],"e":"Tái tạo = thuỷ điện + gió + mặt trời = 30 + 10 + 15 = 55%."},{"f":"K3","p":"Đốt 1 kg than thải khoảng 2,5 kg CO₂; một nhà máy đốt 1000 kg than mỗi ngày. Lượng CO₂ thải mỗi ngày là bao nhiêu?","a":"2 500 kg","w":["250 kg","1 000 kg","25 000 kg"],"e":"1 000 × 2,5 = 2 500 kg CO₂ mỗi ngày."},{"f":"K3","p":"Một chuỗi năng lượng được đo như sau: cây xanh quang hợp cố định 10 000 kJ năng lượng từ Mặt Trời; động vật ăn cỏ nhận 1 000 kJ từ cây; động vật ăn thịt nhận 100 kJ từ động vật ăn cỏ. Kết luận nào đúng từ các số liệu này?","a":"Năng lượng qua các bậc giảm dần, gốc từ Mặt Trời","w":["Năng lượng tăng dần qua mỗi bậc dinh dưỡng","Động vật ăn thịt nhận nhiều năng lượng nhất","Năng lượng không bắt nguồn từ Mặt Trời chút nào"],"e":"10 000 → 1 000 → 100 kJ: mỗi bậc chỉ nhận khoảng 1/10 của bậc trước; toàn bộ bắt đầu từ năng lượng Mặt Trời do cây quang hợp cố định."}],"kh9-h1":[{"f":"K2","p":"Muốn kiểm tra kẽm có đẩy được đồng khỏi dung dịch CuSO₄ không, dấu hiệu và đối chứng đúng là gì?","a":"So Zn trong CuSO₄ với Zn trong nước cất, xem đồng bám","w":["Chỉ nhìn màu dung dịch CuSO₄ ban đầu rồi kết luận","Đun sôi dung dịch trước khi thả kẽm vào thử","Dùng thanh đồng thả vào CuSO₄ làm thí nghiệm chính"],"e":"Đối chứng trong nước cất cho thấy thay đổi (nếu có) là do CuSO₄, không phải do nước."},{"f":"K2","p":"Để xếp hạng hoạt động hoá học của ba kim loại bằng phản ứng với HCl, phép so công bằng cần gì?","a":"Các mẫu cùng dạng, cùng lượng, HCl cùng nồng độ, thể tích","w":["Kim loại nào thích thì dùng dạng bột cho phản ứng mạnh","Cho nồng độ acid khác nhau tuỳ từng kim loại thử","Mỗi kim loại thử ở một nhiệt độ dung dịch khác nhau"],"e":"Tốc độ sủi bọt chỉ so được khi mọi điều kiện khác giống hệt nhau giữa các kim loại."},{"f":"K2","p":"Muốn kiểm tra sắt rỉ nhanh hơn trong nước muối hay nước thường, bố trí đúng là gì?","a":"Hai đinh giống nhau, hai cốc khác nước, cùng thời gian","w":["Một đinh để trong nước muối, đinh kia để khô ngoài không khí","Đinh trong nước muối to hơn đinh trong nước thường","Chỉ quan sát nước muối rồi suy ra nước thường"],"e":"Chỉ loại nước khác nhau; đinh, thời gian và cách quan sát phải giống nhau."},{"f":"K2","p":"Kiểm tra nhôm có phản ứng với dung dịch CuSO₄ chậm do lớp oxide bảo vệ, thí nghiệm gợi ý đúng là gì?","a":"So nhôm đã chà sạch bề mặt với mẫu chưa chà, cùng dung dịch","w":["Đun nóng mẫu chưa chà còn mẫu chà để nguội rồi so","Dùng hai dung dịch CuSO₄ khác nồng độ cho hai mẫu","Không cần so sánh, lớp oxide không ảnh hưởng phản ứng"],"e":"Hai mẫu chỉ khác ở lớp bề mặt bị chà hay không mới kiểm tra được vai trò của lớp oxide."},{"f":"K2","p":"Khi tách kim loại bằng phương pháp nhiệt luyện, vì sao phải làm thí nghiệm mẫu nhỏ và ghi tỉ lệ chất khử?","a":"Để tìm điều kiện đủ khử mà không lãng phí và mất an toàn","w":["Để phản ứng xảy ra càng mạnh càng tốt không cần kiểm soát","Ghi tỉ lệ chỉ là thủ tục, không ảnh hưởng kết quả tách","Làm mẫu lớn ngay từ đầu cho kết quả đáng tin nhất"],"e":"Thử nhỏ, ghi tỉ lệ giúp xác định lượng chất khử vừa đủ trước khi làm lớn, an toàn và tiết kiệm."},{"f":"K3","p":"Cho các kim loại vào HCl loãng, tốc độ sủi bọt: Mg rất nhanh, Zn vừa, Fe chậm, Cu không sủi bọt. Thứ tự hoạt động giảm dần đúng là gì?","a":"Mg > Zn > Fe > Cu","w":["Cu > Fe > Zn > Mg","Fe > Mg > Zn > Cu","Mg > Cu > Zn > Fe"],"e":"Sủi bọt càng nhanh kim loại càng hoạt động mạnh; Cu không phản ứng nên yếu nhất trong nhóm này."},{"f":"K3","p":"Ngâm thanh Zn vào dung dịch CuSO₄ một thời gian, khối lượng dung dịch muối đồng giảm màu dần và có lớp đỏ bám. Kết luận đúng là gì?","a":"Zn đã đẩy Cu ra khỏi dung dịch muối của nó","w":["Cu đã đẩy Zn ra khỏi dung dịch muối kẽm","Không có phản ứng, lớp đỏ là gỉ của kẽm","Màu nhạt đi chỉ do dung dịch bị pha loãng"],"e":"Zn hoạt động mạnh hơn Cu nên Zn + CuSO₄ → ZnSO₄ + Cu (lớp đỏ là đồng kim loại)."},{"f":"K3","p":"Dãy hoạt động: K > Na > Ca > Mg > Al > Zn > Fe > Cu > Ag > Au. Kim loại nào đẩy được Fe khỏi dung dịch FeSO₄?","a":"Zn","w":["Cu","Ag","Au"],"e":"Chỉ kim loại đứng trước Fe trong dãy mới đẩy được Fe: Zn đứng trước, Cu, Ag, Au đứng sau."},{"f":"K3","p":"Cho 6,5 g Zn (Zn = 65) tác dụng hết với HCl dư. Số mol khí H₂ sinh ra là bao nhiêu?","a":"0,1 mol","w":["0,65 mol","1 mol","0,05 mol"],"e":"nZn = 6,5/65 = 0,1 mol; Zn + 2HCl → ZnCl₂ + H₂ nên nH₂ = 0,1 mol."},{"f":"K3","p":"Một hợp kim có 90% Fe và 10% C, Si... 10 kg hợp kim này chứa bao nhiêu sắt?","a":"9 kg","w":["1 kg","10 kg","90 kg"],"e":"Khối lượng Fe = 90% × 10 = 9 kg."}],"kh9-h2":[{"f":"K2","p":"Muốn kiểm tra khí ethylene làm mất màu nước brom, mẫu đối chứng đúng là gì?","a":"Ống nước brom cho khí methane qua, quan sát màu không đổi","w":["Ống nước brom để ngoài ánh sáng một mình","Ống chứa nước cất cho ethylene qua để so màu","Không cần đối chứng, cứ mất màu là do ethylene"],"e":"Methane (alkane) không làm mất màu brom; đối chứng này chứng tỏ tác dụng riêng của alkene có liên kết đôi."},{"f":"K2","p":"Để so khả năng cháy của methane và khí trong bật lửa (butane), phép thử công bằng cần gì?","a":"Đốt cùng thể tích khí, cùng điều kiện, quan sát như nhau","w":["Đốt lượng khí tuỳ ý, quan sát bằng cảm tính mỗi lần","Chỉ đốt một loại khí rồi suy ra loại còn lại","Trộn hai khí lại đốt chung rồi kết luận từng loại"],"e":"Cùng lượng khí và điều kiện đốt mới so được hiện tượng cháy của hai hydrocarbon."},{"f":"K2","p":"Muốn phân biệt bình khí methane và bình khí ethylene bị mất nhãn, thí nghiệm an toàn và đúng là gì?","a":"Dẫn khí qua brom: ethylene mất màu, methane thì không","w":["Đốt cả hai bình lớn để xem ngọn lửa nào to hơn","Ngửi trực tiếp hai bình khí để phân biệt mùi","Mở van hai bình ra phòng rồi quan sát màu khí"],"e":"Alkene có liên kết đôi làm mất màu brom, alkane thì không: đó là phản ứng nhận biết chuẩn."},{"f":"K2","p":"Kiểm tra dự đoán 'alkane có công thức chung CnH2n+2', cách kiểm chứng đúng là gì?","a":"Viết nhiều alkane cụ thể, kiểm tra tỉ lệ H theo n","w":["Chỉ kiểm tra một chất duy nhất là methane rồi kết luận","Đoán công thức chung từ tên gọi của dãy đồng đẳng","Bỏ qua các alkane mạch dài vì khó kiểm tra"],"e":"Kiểm tra trên CH₄, C₂H₆, C₃H₈... đều khớp CnH2n+2 mới tin được công thức chung."},{"f":"K2","p":"Khi thu khí methane bằng cách đẩy nước, vì sao cách này phù hợp để đo thể tích khí sinh ra?","a":"Vì methane rất ít tan trong nước nên ít bị hao hụt","w":["Vì methane tan hoàn toàn trong nước khi thu khí","Vì nước làm methane nặng thêm nên dễ đo hơn","Cách đẩy nước dùng được cho mọi khí tan tốt"],"e":"Khí ít tan mới thu bằng đẩy nước được mà không mất khí vào nước; khí tan tốt sẽ hao hụt nhiều."},{"f":"K3","p":"Công thức phân tử: C₂H₆, C₃H₆, C₄H₁₀, C₅H₁₀. Chất thuộc dãy alkane là những chất nào?","a":"C₂H₆ và C₄H₁₀","w":["C₃H₆ và C₅H₁₀","Chỉ C₃H₆","Cả bốn chất đều là alkane"],"e":"Alkane có dạng CnH2n+2: C₂H₆ (n=2) và C₄H₁₀ (n=4) khớp; hai chất còn lại dạng CnH2n là alkene."},{"f":"K3","p":"Đốt cháy hoàn toàn 1 mol CH₄ tạo 1 mol CO₂ và 2 mol H₂O, cần bao nhiêu mol O₂?","a":"2 mol","w":["1 mol","3 mol","0,5 mol"],"e":"CH₄ + 2O₂ → CO₂ + 2H₂O: cân bằng oxy cho thấy cần 2 mol O₂."},{"f":"K3","p":"Bảng tỉ lệ khối lượng: chất A gồm 75% C, 25% H (theo khối lượng nguyên tử C=12, H=1, tỉ lệ mol C:H = 1:4). Chất A là gì?","a":"Methane CH₄","w":["Ethylene C₂H₄","Butane C₄H₁₀","Acetylene C₂H₂"],"e":"x:y = (75/12) : (25/1) = 6,25 : 25 = 1 : 4 → CH₄."},{"f":"K3","p":"Dẫn hỗn hợp khí qua nước brom, khối lượng bình brom tăng 2,8 g do giữ lại ethylene (M = 28). Số mol ethylene bị giữ là bao nhiêu?","a":"0,1 mol","w":["2,8 mol","1 mol","0,28 mol"],"e":"n = 2,8/28 = 0,1 mol ethylene đã cộng hợp với brom nên bị giữ lại trong bình."},{"f":"K3","p":"Bảng nguồn và thành phần: xăng — hydrocarbon C5–C12, chưng cất từ dầu mỏ; diesel — hydrocarbon C10–C21, chưng cất từ dầu mỏ; LPG — propane và butane, tách từ khí thiên nhiên và dầu mỏ; methane — thành phần chính của khí thiên nhiên từ mỏ khí. Kết luận nào đúng từ bảng này?","a":"Các nhiên liệu đều khai thác từ mỏ dầu khí hoá thạch","w":["Tất cả đều là năng lượng tái tạo vô tận","Chỉ methane mới có nguồn gốc hoá thạch","Các nhiên liệu này không chứa carbon nào"],"e":"Bốn nhiên liệu đều là hydrocarbon hoặc hỗn hợp hydrocarbon lấy từ dầu mỏ, khí thiên nhiên — nhiên liệu hoá thạch, dùng hết không tái tạo kịp."}],"kh9-h3":[{"f":"K2","p":"Muốn kiểm tra ethylic alcohol có hoà tan được dầu ăn tốt hơn nước không, bố trí đúng là gì?","a":"Hai ống cùng lượng dầu, thêm nước/rượu như nhau, lắc đều","w":["Ống rượu cho nhiều dầu hơn để thấy rõ sự hoà tan","Chỉ thử với rượu rồi kết luận nước không hoà tan được","Đun nóng ống nước còn ống rượu để nguội rồi so"],"e":"Cùng lượng dầu và dung môi, lắc như nhau: chỉ dung môi khác nhau mới so được khả năng hoà tan."},{"f":"K2","p":"Để kiểm tra acetic acid làm quỳ đổi màu và tác dụng với đá vôi, vì sao cần thử riêng từng thí nghiệm?","a":"Vì mỗi thí nghiệm kiểm tra một tính chất khác nhau của acid","w":["Vì trộn chung đá vôi và quỳ sẽ đẹp hơn khi quan sát","Thử riêng chỉ để kéo dài thời gian làm thí nghiệm","Một thí nghiệm là đủ chứng minh mọi tính chất"],"e":"Tính chất với chỉ thị màu và phản ứng sinh khí CO₂ với đá vôi là hai bằng chứng độc lập, phải thử riêng."},{"f":"K2","p":"Muốn so độ chua của giấm ăn và nước chanh bằng giấy pH, phép đo công bằng cần gì?","a":"Giấy pH mới cho mỗi mẫu, đọc màu ngay và so cùng thang chuẩn","w":["Dùng lại một tờ giấy pH cho cả hai mẫu liên tiếp","Pha loãng giấm trước khi đo còn chanh để nguyên","Đọc màu sau một giờ để màu ổn định hoàn toàn"],"e":"Giấy mới tránh nhiễm chéo; đọc đúng lúc và cùng thang chuẩn mới so được pH hai mẫu."},{"f":"K2","p":"Kiểm tra rượu etylic cháy cho ngọn lửa thế nào, biện pháp an toàn bắt buộc là gì?","a":"Đốt lượng nhỏ ở đĩa sứ, xa vật dễ cháy, có giáo viên","w":["Đốt trực tiếp trong chai rượu còn đầy để lửa to","Để bạn đứng sát bên quan sát ngọn lửa cháy","Đốt gần giấy và hoá chất khác cho tiện lấy đồ"],"e":"Rượu dễ cháy: chỉ đốt lượng nhỏ, xa nguồn bắt lửa và vật dễ cháy, đúng quy tắc an toàn phòng thí nghiệm."},{"f":"K2","p":"Khi lên men giấm từ rượu loãng, vì sao phải để miệng lọ thoáng khí và ghi nhiệt độ hằng ngày?","a":"Để kiểm tra vai trò không khí và theo dõi điều kiện lên men","w":["Để rượu bay hơi hết càng nhanh càng tốt cho giấm","Ghi nhiệt độ chỉ để báo cáo dài hơn, không cần thiết","Đậy kín tuyệt đối mới lên men giấm được tốt"],"e":"Lên men giấm cần oxy không khí; ghi nhiệt độ giúp biết điều kiện nào giấm hình thành tốt."},{"f":"K3","p":"Một chai rượu 500 mL có độ rượu 40°. Thể tích ethylic alcohol nguyên chất trong chai là bao nhiêu?","a":"200 mL","w":["40 mL","500 mL","125 mL"],"e":"Độ rượu 40° nghĩa là 40 mL rượu nguyên chất trong 100 mL dung dịch → 500 × 40% = 200 mL."},{"f":"K3","p":"Cho giấm (chứa acetic acid) vào vỏ trứng (chủ yếu CaCO₃), thấy sủi bọt khí. Khí sinh ra là khí gì?","a":"Khí CO₂","w":["Khí H₂","Khí O₂","Không có khí, bọt là do giấm sôi"],"e":"Acid tác dụng với muối cacbonat sinh CO₂: bọt khí là cacbonic làm đục nước vôi trong."},{"f":"K3","p":"Bảng pH: giấm ăn 3, nước mưa 6, nước cất 7, dung dịch xà phòng 10. Dung dịch nào có tính acid mạnh nhất?","a":"Giấm ăn","w":["Nước cất","Dung dịch xà phòng","Nước mưa"],"e":"pH càng nhỏ tính acid càng mạnh; giấm pH = 3 nhỏ nhất nên acid mạnh nhất trong bảng."},{"f":"K3","p":"Hoà tan 25 g acetic acid vào nước được 500 g dung dịch giấm. Nồng độ phần trăm là bao nhiêu?","a":"5%","w":["25%","0,5%","10%"],"e":"C% = 25/500 × 100% = 5%, đúng nồng độ giấm ăn thông thường."},{"f":"K3","p":"Đốt cháy hoàn toàn 1 mol C₂H₅OH cần 3 mol O₂, tạo 2 mol CO₂ và 3 mol H₂O. Nếu đốt 0,5 mol rượu, số mol CO₂ tạo ra là bao nhiêu?","a":"1 mol","w":["2 mol","0,5 mol","3 mol"],"e":"Tỉ lệ 1 mol rượu → 2 mol CO₂ nên 0,5 mol rượu → 1 mol CO₂."}],"kh9-h4":[{"f":"K2","p":"Muốn kiểm tra tinh bột có trong gạo bằng thuốc thử iốt, mẫu đối chứng đúng là gì?","a":"Ống glucose không tinh bột, nhỏ iốt: không xanh tím","w":["Ống chứa tinh bột nhưng không nhỏ iốt vào thử","Ống chứa nước cất có màu sẵn để so sánh màu","Không cần đối chứng vì màu xanh tím là hiển nhiên"],"e":"Đối chứng âm tính cho thấy màu xanh tím chỉ xuất hiện khi thật sự có tinh bột, tránh nhầm màu của thuốc thử."},{"f":"K2","p":"Để kiểm tra nhiệt độ làm protein trong lòng trắng trứng đông tụ, bố trí nào đúng?","a":"Hai mẫu như nhau: một nguội, một đun nóng, xem độ đông","w":["Mẫu đun nóng cho thêm acid, mẫu nguội không cho gì","Chỉ đun một mẫu rồi kết luận nhiệt độ có tác dụng","Đun mẫu đến cháy khét mới quan sát sự thay đổi"],"e":"Chỉ nhiệt độ khác nhau, các yếu tố khác giống nhau mới quy sự đông tụ cho nhiệt độ được."},{"f":"K2","p":"Muốn kiểm tra chất béo có phản ứng tạo xà phòng hay không, vì sao phải thử riêng với nước và với dung dịch kiềm nóng?","a":"Để thấy xà phòng hoá chỉ xảy ra trong kiềm nóng","w":["Để chất béo tan trong nước lạnh giống như trong kiềm","Thử hai môi trường chỉ để thí nghiệm trông đầy đủ","Cả hai môi trường đều cho kết quả giống hệt nhau"],"e":"Đun chất béo với kiềm tạo xà phòng và glycerol; với nước thường chất béo không tan và không phản ứng."},{"f":"K2","p":"Kiểm tra dự đoán 'cellulose không tan trong nước như tinh bột', cách làm đúng là gì?","a":"Cho cùng lượng hai bột vào hai cốc nước như nhau, khuấy","w":["Cho cellulose vào nước nóng, tinh bột vào nước lạnh rồi so","Chỉ cho cellulose vào nước rồi kết luận về tinh bột","Nghiền cellulose thật mịn còn tinh bột để nguyên hạt"],"e":"Điều kiện nước và cách khuấy giống nhau, chỉ loại chất khác nhau thì phép so mới đúng."},{"f":"K2","p":"Khi thử tính chất của chất dẻo (polymer) chịu nhiệt, biện pháp an toàn và ghi chép đúng là gì?","a":"Hơ mẫu nhỏ bằng kẹp, ghi hiện tượng, làm nơi thoáng khí","w":["Đốt cả sản phẩm nhựa lớn trong lớp học để thử","Ngửi sát khói nhựa cháy để nhận biết loại polymer","Đốt nhựa không cần ghi chép, chỉ quan sát cho biết"],"e":"Đốt nhựa sinh khói độc: mẫu nhỏ, dùng kẹp, nơi thoáng và ghi hiện tượng là cách làm đúng, an toàn."},{"f":"K3","p":"Nhỏ iốt vào ba mẫu: cơm nguội → xanh tím; đường kính → không đổi màu; dầu ăn → không đổi màu. Kết luận đúng là gì?","a":"Chỉ cơm chứa tinh bột trong ba mẫu đã thử","w":["Cả ba mẫu đều chứa tinh bột như nhau","Đường kính chứa nhiều tinh bột nhất trong ba mẫu","Iốt đổi màu với mọi chất hữu cơ bất kì"],"e":"Màu xanh tím đặc trưng cho tinh bột: chỉ mẫu cơm cho phản ứng này."},{"f":"K3","p":"Một khẩu phần có 10 g chất béo, biết 1 g chất béo cung cấp khoảng 9 kcal. Năng lượng từ chất béo là bao nhiêu?","a":"90 kcal","w":["10 kcal","9 kcal","900 kcal"],"e":"10 × 9 = 90 kcal từ phần chất béo của khẩu phần."},{"f":"K3","p":"Thuỷ phân hoàn toàn saccharose (đường mía) thu được những chất nào?","a":"Glucose và fructose","w":["Chỉ một loại glucose duy nhất","Tinh bột và cellulose","Glucose và chất béo"],"e":"Saccharose là đường đôi: thuỷ phân cho 1 glucose + 1 fructose."},{"f":"K3","p":"Bảng độ tan trong nước ở nhiệt độ phòng: glucose tan tốt, tinh bột gần như không tan (tạo hồ khi đun), cellulose không tan. Kết luận đúng là gì?","a":"Ba carbohydrate này khác nhau rõ về độ tan trong nước","w":["Cả ba đều tan tốt trong nước như nhau hoàn toàn","Cellulose tan tốt nhất trong ba chất đã nêu","Độ tan không phân biệt được các carbohydrate"],"e":"Số liệu cho thấy độ tan giảm dần glucose > tinh bột > cellulose (không tan), dùng để phân biệt chúng."},{"f":"K3","p":"Đốt một mẫu nhựa cháy có khói đen dày và mùi khét, mẫu vải cotton cháy mùi giấy và tro mềm. Kết luận thận trọng đúng là gì?","a":"Hai vật liệu cháy khác nhau, cần thêm thử mới xác định nhựa","w":["Chỉ dựa vào mùi khói là khẳng định chắc chắn được loại nhựa","Nhựa và cotton cháy giống hệt nhau theo mô tả","Khói đen chứng tỏ mẫu đó chắc chắn là cotton"],"e":"Hiện tượng cháy chỉ gợi ý khác biệt vật liệu; nhận biết polymer cần nhiều thử nghiệm bổ sung, không kết luận vội từ một dấu hiệu."}],"kh9-h5":[{"f":"K2","p":"Muốn kiểm tra đá vôi có chứa CaCO₃ bằng acid, dấu hiệu và kiểm chứng khí nào đầy đủ nhất?","a":"Sủi bọt và dẫn khí qua nước vôi trong thấy đục","w":["Chỉ nghe tiếng xèo xèo là khẳng định đá vôi ngay","Ngửi mùi khí sinh ra để nhận biết đó là CO₂","Nhìn đá mòn đi là đủ chứng minh có CaCO₃"],"e":"Bọt khí cộng với nước vôi đục mới khẳng định khí là CO₂, từ đó suy ra đá có gốc cacbonat."},{"f":"K2","p":"Để so hàm lượng CaCO₃ trong hai mẫu đá vôi, phép đo công bằng cần gì?","a":"Cùng lượng đá bột, cùng acid dư, đo thể tích CO₂ sinh ra","w":["Mẫu đá nào cũng được, to nhỏ tuỳ ý khi so sánh","Mẫu nghi nhiều CaCO₃ thì cho thêm acid đậm đặc hơn","Chỉ đo mẫu thứ nhất rồi suy ra mẫu thứ hai"],"e":"Thể tích CO₂ tỉ lệ với lượng CaCO₃; điều kiện phản ứng giống hệt nhau mới so được hai mẫu."},{"f":"K2","p":"Muốn kiểm tra thuỷ tinh (silicate) có bền với acid thông thường không, cách thử an toàn đúng là gì?","a":"Nhỏ acid loãng lên mảnh nhỏ, so với mảnh đối chứng","w":["Ngâm cả chiếc cốc thuỷ tinh vào acid đặc nóng để thử nhanh","Dùng acid mạnh nhất có sẵn với lượng lớn để thử","Đập vỡ thuỷ tinh rồi kết luận về độ bền hoá học"],"e":"Thử trên mẫu nhỏ, có đối chứng và dùng acid loãng là cách kiểm tra an toàn, có cơ sở so sánh."},{"f":"K2","p":"Kiểm tra dự đoán 'đốt nhiên liệu hoá thạch làm tăng CO₂', cách thu thập bằng chứng hợp lí là gì?","a":"Đo CO₂ trước và sau đốt nhiên liệu trong hệ kín an toàn","w":["Chỉ nhìn ngọn lửa cháy rồi kết luận lượng CO₂ tăng","Đo CO₂ ngoài đường phố một lần rồi quy cho nhiên liệu","Không cần đo vì cháy luôn tạo CO₂ theo lí thuyết"],"e":"Đo trước–sau trong cùng hệ mới có số liệu chứng minh sự tăng CO₂ do đốt nhiên liệu."},{"f":"K2","p":"Khi nghiên cứu chu trình carbon qua sơ đồ và số liệu, bước nào giúp tránh kết luận sai?","a":"Đối chiếu CO₂ hấp thụ và thải ra trong cùng giai đoạn","w":["Chỉ xét lượng CO₂ thải ra, bỏ qua lượng được hấp thụ","Kết luận Trái Đất hết CO₂ vì cây hấp thụ liên tục","Chỉ dùng số liệu của một ngày để nói về toàn cầu"],"e":"Chu trình là cân bằng hai chiều; xét cả hấp thụ và thải trong cùng khoảng thời gian mới đúng."},{"f":"K3","p":"Nung 100 g đá vôi nguyên chất (CaCO₃) thu 56 g CaO. Khối lượng CO₂ thoát ra là bao nhiêu?","a":"44 g","w":["56 g","100 g","156 g"],"e":"Bảo toàn khối lượng: CO₂ = 100 − 56 = 44 g, đúng phương trình CaCO₃ → CaO + CO₂."},{"f":"K3","p":"Bảng thành phần vỏ Trái Đất (gần đúng): O 46%, Si 28%, Al 8%, Fe 5%. Hai nguyên tố chiếm phần lớn nhất là gì?","a":"Oxygen và silic","w":["Al và Fe cộng lại lớn hơn O và Si","Sắt chiếm phần lớn nhất vỏ Trái Đất","Oxygen chỉ chiếm tỉ lệ rất nhỏ trong vỏ"],"e":"46% + 28% = 74%: O và Si chiếm gần ba phần tư khối lượng vỏ Trái Đất."},{"f":"K3","p":"Một lò nung vôi dùng 200 kg đá vôi chứa 90% CaCO₃. Khối lượng CaCO₃ thực tế tham gia là bao nhiêu?","a":"180 kg","w":["200 kg","90 kg","220 kg"],"e":"CaCO₃ = 90% × 200 = 180 kg; phần còn lại là tạp chất không tham gia phản ứng."},{"f":"K3","p":"Số liệu CO₂ khí quyển tăng từ khoảng 280 ppm (trước công nghiệp) lên khoảng 420 ppm (hiện nay). Kết luận đúng là gì?","a":"Nồng độ CO₂ đã tăng khoảng 50% so với trước công nghiệp","w":["Nồng độ CO₂ gần như không thay đổi theo số liệu","CO₂ đã giảm mạnh nhờ hoạt động công nghiệp","420 ppm nghĩa là CO₂ chiếm 42% không khí"],"e":"(420−280)/280 = 50%; lưu ý 420 ppm chỉ là 0,042% không khí, không phải 42%."},{"f":"K3","p":"Chu trình carbon một năm của một khu rừng (ước tính): quang hợp hấp thụ 12 tấn CO₂/ha, hô hấp và phân huỷ thải 10 tấn CO₂/ha. Kết luận đúng là gì?","a":"Rừng này tích luỹ ròng khoảng 2 tấn CO₂/ha mỗi năm","w":["Rừng thải ròng 2 tấn CO₂/ha mỗi năm ra khí quyển","Rừng không tham gia gì vào chu trình carbon","Lượng hấp thụ và thải ra luôn bằng nhau tuyệt đối"],"e":"12 − 10 = 2 tấn CO₂/ha được giữ lại ròng trong sinh khối và đất rừng mỗi năm."}],"kh9-s1":[{"f":"K2","p":"Muốn kiểm chứng quy luật phân li của Mendel trên cây đậu, cách làm nào đúng khoa học?","a":"Lai cây thuần chủng khác tính trạng, đếm F₂ với mẫu lớn","w":["Chỉ trồng vài cây F₂ rồi kết luận tỉ lệ phân li ngay","Chọn những cây F₂ đúng dự đoán để đếm, bỏ cây khác","Quan sát F₁ thấy đồng tính là đủ chứng minh quy luật"],"e":"Tỉ lệ phân li chỉ tin cậy khi đếm số lượng lớn cá thể F₂ một cách khách quan, không chọn lọc."},{"f":"K2","p":"Để kiểm tra một cây hoa đỏ F₂ là thuần chủng hay không, phép lai kiểm chứng đúng là gì?","a":"Lai với cây hoa trắng lặn (lai phân tích), xem đời con","w":["Tự thụ phấn một lần rồi nhìn vài cây con kết luận","Lai với cây hoa đỏ khác bất kì trong vườn","Quan sát màu hoa của chính cây đó thật kĩ"],"e":"Lai phân tích với kiểu gene lặn: đời con phân tính thì cây đem lai là dị hợp, đồng tính đỏ thì thuần chủng."},{"f":"K2","p":"Muốn quan sát quá trình phiên mã–dịch mã qua mô hình, ghi chép nào giúp kiểm tra hiểu đúng trình tự?","a":"Ghi thứ tự: DNA → mRNA → chuỗi amino acid theo từng bước","w":["Ghi protein tạo ra trước, mRNA tạo ra sau cùng","Bỏ qua mRNA vì protein được làm thẳng từ DNA","Chỉ ghi tên các giai đoạn mà không ghi sản phẩm"],"e":"Trình tự thông tin DNA → mRNA → protein là mạch kiểm tra; ghi sản phẩm từng bước mới thấy sai ở đâu."},{"f":"K2","p":"Kiểm tra dự đoán 'đột biến gene là thay đổi trong cấu trúc gene', cách tiếp cận đúng là gì?","a":"So trình tự nucleotide của gene thường và gene đột biến","w":["Chỉ nhìn kiểu hình khác lạ rồi khẳng định đã đột biến gene","Đếm số lượng gene trong tế bào để tìm đột biến","Quan sát kích thước cơ thể sinh vật bằng mắt thường"],"e":"Đột biến gene là biến đổi trình tự nucleotide nên phải so sánh ở mức phân tử mới khẳng định được."},{"f":"K2","p":"Khi lập sơ đồ lai, vì sao phải viết đủ các loại giao tử của bố mẹ trước khi kết hợp?","a":"Để đời con được xét đủ mọi tổ hợp, không bỏ sót kiểu gene","w":["Để sơ đồ trông dài và đầy đủ hình thức trình bày","Để số giao tử của bố và mẹ luôn khác hẳn nhau","Viết giao tử chỉ cần thiết khi lai hai tính trạng"],"e":"Thiếu một loại giao tử sẽ làm tỉ lệ kiểu gene, kiểu hình ở đời con bị sai lệch ngay từ đầu."},{"f":"K3","p":"Lai Aa × Aa, đời con theo tỉ lệ kiểu gene nào đúng?","a":"1 AA : 2 Aa : 1 aa","w":["3 Aa : 1 aa","1 AA : 1 aa","4 Aa (toàn dị hợp)"],"e":"Mỗi bên cho giao tử A, a tỉ lệ bằng nhau; tổ hợp cho 1/4 AA, 1/2 Aa, 1/4 aa."},{"f":"K3","p":"Một gene có tỉ lệ nucleotide: A = 30%. Theo nguyên tắc bổ sung, tỉ lệ G là bao nhiêu?","a":"20%","w":["30%","60%","10%"],"e":"A = T = 30% → còn 40% cho G = C, mỗi loại 20%."},{"f":"K3","p":"Đếm F₂ của một phép lai một tính trạng: 602 cây hoa đỏ, 198 cây hoa trắng. Tỉ lệ này gần đúng với tỉ lệ nào?","a":"3 đỏ : 1 trắng","w":["1 đỏ : 1 trắng","1 đỏ : 3 trắng","Toàn hoa đỏ, không có phân li"],"e":"602 : 198 ≈ 3 : 1, phù hợp quy luật phân li khi đỏ là trội hoàn toàn."},{"f":"K3","p":"Một đoạn mRNA có trình tự bổ sung với mạch khuôn DNA (trừ T thay bằng U). Nếu mạch khuôn có A ở một vị trí, nucleotide tương ứng trên mRNA là gì?","a":"U","w":["T","G","C"],"e":"Trong phiên mã, A trên mạch khuôn bắt cặp với U trên mRNA (RNA dùng U thay cho T)."},{"f":"K3","p":"Lai hai cây dị hợp hai cặp gene độc lập AaBb × AaBb. Tỉ lệ kiểu hình lặn cả hai tính trạng (aabb) ở đời con là bao nhiêu?","a":"1/16","w":["1/4","9/16","3/16"],"e":"aabb cần aa (1/4) đồng thời bb (1/4) → 1/4 × 1/4 = 1/16."}],"kh9-s2":[{"f":"K2","p":"Muốn đếm số nhiễm sắc thể trong tế bào một loài, thời điểm quan sát nào cho số đếm tin cậy nhất?","a":"Kì giữa nguyên phân, khi NST co xoắn rõ, xếp ở xích đạo","w":["Bất kì lúc nào trong chu kì tế bào cũng đếm dễ như nhau","Khi tế bào vừa chết và NST đã tan rã hoàn toàn","Chỉ cần đếm số gene là suy ra số nhiễm sắc thể"],"e":"Ở kì giữa, NST rõ nhất và chưa phân li nên đếm chính xác số NST của loài."},{"f":"K2","p":"Để kiểm tra giảm phân tạo giao tử có bộ NST đơn bội, cách so sánh đúng là gì?","a":"So số NST tế bào mẹ (2n) với giao tử (n) cùng loài","w":["So số NST của hai loài khác nhau hoàn toàn","Đếm số tế bào con mà không cần đếm NST bên trong","Chỉ quan sát kích thước giao tử bằng mắt thường"],"e":"Cùng một loài, tế bào mẹ lưỡng bội cho giao tử đơn bội: phép so đó mới kiểm chứng được giảm phân."},{"f":"K2","p":"Muốn theo dõi di truyền liên kết gene, thiết kế phép lai kiểm chứng hợp lí là gì?","a":"Lai phân tích cá thể dị hợp 2 gene cùng NST, đếm đời con","w":["Lai hai cá thể thuần chủng rồi dừng ở F₁ đồng tính","Chỉ quan sát một tính trạng duy nhất ở đời con","Đếm số NST mà không ghi kiểu hình đời con"],"e":"Nếu hai gene liên kết, đời lai phân tích cho tỉ lệ lệch khỏi 1:1:1:1, thiên về kiểu hình bố mẹ."},{"f":"K2","p":"Kiểm tra một trường hợp nghi đột biến số lượng NST, bằng chứng cần thu thập là gì?","a":"Bộ NST (karyotype) cho thấy thừa hoặc thiếu một NST cụ thể","w":["Chỉ dựa vào chiều cao cơ thể khác thường là đủ khẳng định","Dựa vào nhóm máu của người đó để kết luận NST","Hỏi tiền sử ăn uống của gia đình người đó"],"e":"Đột biến số lượng NST chỉ khẳng định được khi nhìn trực tiếp bộ NST và đếm từng chiếc."},{"f":"K2","p":"Khi quan sát tiêu bản nguyên phân, vì sao phải quan sát nhiều tế bào ở các kì khác nhau?","a":"Để dựng trình tự các kì, tránh nhầm một lúc là toàn bộ","w":["Để chọn tế bào đẹp nhất chụp ảnh là đủ kết luận","Nhiều tế bào chỉ làm rối thêm quá trình quan sát","Một tế bào duy nhất cho thấy mọi kì cùng lúc"],"e":"Mỗi tế bào đóng băng ở một kì; ghép nhiều tế bào mới thấy toàn bộ diễn biến nguyên phân."},{"f":"K3","p":"Tế bào sinh dưỡng của một loài có 2n = 46. Giao tử của loài đó có bao nhiêu NST?","a":"23","w":["46","92","12"],"e":"Giảm phân giảm số NST đi một nửa: n = 46/2 = 23."},{"f":"K3","p":"Một tế bào nguyên phân liên tiếp 3 lần (mọi tế bào con đều phân chia). Số tế bào con tạo thành là bao nhiêu?","a":"8","w":["6","3","9"],"e":"Sau k lần nguyên phân có 2ᵏ tế bào: 2³ = 8 tế bào con."},{"f":"K3","p":"Bộ NST của một người được ghi 47, XXY thay vì 46, XY. Kết luận đúng là gì?","a":"Có đột biến số lượng NST: thừa một NST giới tính X","w":["Đây là bộ NST hoàn toàn bình thường như mọi người","Người này thiếu một NST thường trong bộ NST","Số 47 cho thấy thừa một cặp NST thường"],"e":"46 → 47 chiếc, chiếc thừa là X trong cặp giới tính: đột biến lệch bội ở NST giới tính."},{"f":"K3","p":"Trong giảm phân, tế bào mẹ 2n = 8 tạo ra bao nhiêu tế bào con, mỗi tế bào có bao nhiêu NST?","a":"4 tế bào con, mỗi tế bào 4 NST","w":["2 tế bào con, mỗi tế bào 8 NST","4 tế bào con, mỗi tế bào 8 NST","8 tế bào con, mỗi tế bào 4 NST"],"e":"Một tế bào mẹ giảm phân cho 4 giao tử, mỗi giao tử đơn bội n = 8/2 = 4 NST."},{"f":"K3","p":"Hai gene A và B cùng nằm trên một NST, khoảng cách rất gần nhau. Nhận xét đúng về di truyền của chúng là gì?","a":"Chúng thường di truyền cùng nhau (liên kết gene)","w":["Chúng luôn phân li độc lập như ở hai NST khác nhau","Một gene sẽ tự biến mất khi di truyền cùng nhau","Liên kết gene làm tăng số giao tử lên vô hạn"],"e":"Gene cùng NST và gần nhau ít hoán đổi nên có xu hướng đi cùng nhau vào giao tử."}],"kh9-s3":[{"f":"K2","p":"Muốn tìm hiểu một bệnh di truyền trong một gia đình, cách thu thập thông tin đúng và có đạo đức là gì?","a":"Lập phả hệ có đồng ý, ghi ai mắc bệnh qua các thế hệ","w":["Đoán bệnh của từng người qua ngoại hình rồi ghi vào phả hệ","Công bố thông tin bệnh của gia đình lên mạng xã hội","Chỉ hỏi một người và suy ra cho cả gia đình nhiều đời"],"e":"Phả hệ nhiều thế hệ, thu thập có đồng ý và bảo mật, mới giúp phân tích cách di truyền của bệnh."},{"f":"K2","p":"Để đánh giá nguy cơ bệnh di truyền cho một cặp vợ chồng, thông tin nào cần được chuyên gia xem xét?","a":"Tiền sử bệnh hai bên gia đình và xét nghiệm khi cần","w":["Chỉ cần xem ngoại hình khoẻ mạnh của hai vợ chồng","Chỉ cần biết nhóm máu của hai vợ chồng là đủ","Không cần thông tin gì, nguy cơ của mọi cặp đều bằng nhau"],"e":"Nhiều bệnh lặn không biểu hiện ở người mang gene; phải dựa vào phả hệ và xét nghiệm tư vấn di truyền."},{"f":"K2","p":"Muốn khảo sát hiệu quả truyền thông kế hoạch hoá gia đình ở một khu dân cư, cách làm đáng tin là gì?","a":"Khảo sát mẫu đại diện, ẩn danh, so trước–sau truyền thông","w":["Chỉ hỏi vài người quen và suy ra cho toàn khu dân cư","Hỏi trực tiếp tên tuổi người trả lời để công khai kết quả","Kết luận hiệu quả ngay khi chưa truyền thông xong"],"e":"Mẫu đại diện, ẩn danh và so sánh trước–sau mới cho kết luận khách quan và tôn trọng người được hỏi."},{"f":"K2","p":"Kiểm tra dự đoán 'hôn nhân cận huyết làm tăng nguy cơ bệnh lặn ở con', bằng chứng cần xét là gì?","a":"So tỉ lệ bệnh lặn ở gia đình cận huyết và không, mẫu lớn","w":["Chỉ xét một gia đình cận huyết có con mắc bệnh là đủ","Hỏi ý kiến cảm tính của người dân về vấn đề này","Đếm số cặp kết hôn cận huyết mà không xem bệnh ở con"],"e":"Một trường hợp riêng không chứng minh được xu hướng; phải so tỉ lệ trên mẫu lớn ở hai nhóm."},{"f":"K2","p":"Khi ứng dụng chọn giống bằng lai tạo trong chăn nuôi, bước kiểm tra nào không thể bỏ qua?","a":"Theo dõi con lai nhiều thế hệ trước khi nhân rộng","w":["Nhân rộng ngay sau lứa lai đầu tiên trông khoẻ mạnh","Chỉ chọn con lai to nhất, bỏ qua sức đề kháng bệnh","Bỏ qua theo dõi vì lai tạo luôn cho kết quả tốt"],"e":"Con lai cần được kiểm chứng ổn định qua các thế hệ mới tránh rủi ro khi nhân rộng đàn giống."},{"f":"K3","p":"Phả hệ: bố mẹ đều bình thường nhưng sinh con mắc bệnh lặn do gene trên NST thường. Kiểu gene của bố mẹ là gì (A bình thường, a gây bệnh)?","a":"Cả hai đều dị hợp Aa","w":["Cả hai đều đồng hợp AA","Một người AA, một người aa","Cả hai đều đồng hợp aa"],"e":"Con mắc bệnh aa nhận a từ cả bố và mẹ; bố mẹ bình thường mà sinh con aa nên cả hai phải là Aa."},{"f":"K3","p":"Hai vợ chồng đều mang gene lặn gây bệnh (Aa × Aa). Xác suất mỗi đứa con mắc bệnh (aa) là bao nhiêu?","a":"25%","w":["50%","75%","0%"],"e":"Sơ đồ lai Aa × Aa cho tỉ lệ 1 AA : 2 Aa : 1 aa → con aa chiếm 1/4 = 25%."},{"f":"K3","p":"Khảo sát trẻ mắc một bệnh di truyền lặn: nhóm có bố mẹ kết hôn cận huyết có 12/200 trẻ mắc bệnh; nhóm bố mẹ không cận huyết có 2/200 trẻ mắc bệnh. Kết luận nào đúng?","a":"Trẻ nhóm cận huyết mắc bệnh lặn gấp 6 lần nhóm kia","w":["Kết hôn cận huyết không ảnh hưởng tỉ lệ bệnh lặn","Nhóm không cận huyết mắc bệnh lặn nhiều hơn hẳn","Mọi trẻ ở nhóm cận huyết đều mắc bệnh lặn"],"e":"Tỉ lệ mắc: cận huyết 12/200 = 6%, không cận huyết 2/200 = 1%, gấp 6 lần — hôn nhân cận huyết làm tăng nguy cơ con mắc bệnh lặn."},{"f":"K3","p":"Một bệnh di truyền do gene lặn liên kết NST X: bố bình thường, mẹ mang gene bệnh. Con trai có nguy cơ mắc bệnh khoảng bao nhiêu?","a":"50%","w":["0%","100%","25%"],"e":"Con trai nhận X từ mẹ; mẹ mang gene bệnh cho X bệnh với xác suất 1/2 nên con trai có khoảng 50% nguy cơ."},{"f":"K3","p":"Ứng dụng di truyền: giống lúa mới năng suất 7 tấn/ha so với giống cũ 5 tấn/ha trên cùng điều kiện. Mức tăng năng suất là bao nhiêu?","a":"40%","w":["2%","20%","140%"],"e":"Tăng 2 tấn trên gốc 5 tấn: 2/5 × 100% = 40%."}],"kh9-s4":[{"f":"K2","p":"Muốn kiểm tra chọn lọc nhân tạo làm thay đổi một tính trạng ở cây trồng, thí nghiệm đúng là gì?","a":"Mỗi thế hệ chỉ gieo hạt cây mong muốn, ghi số đo từng đời","w":["Gieo hạt tuỳ ý các cây rồi hy vọng tính trạng tự thay đổi","Chỉ trồng một thế hệ và kết luận chọn lọc có hiệu quả","Trộn hạt mọi cây với nhau để giữ nguyên tính trạng cũ"],"e":"Chọn lọc nhân tạo là chọn cá thể mong muốn làm giống qua nhiều thế hệ và ghi lại sự thay đổi."},{"f":"K2","p":"Để kiểm tra dự đoán về chọn lọc tự nhiên ở bướm trong môi trường thay đổi, dữ liệu cần thu là gì?","a":"Tỉ lệ bướm sáng/tối nhiều năm, kèm thay đổi môi trường","w":["Chỉ đếm bướm trong một ngày duy nhất rồi kết luận tiến hoá","Đếm số bướm sáng trong phòng thí nghiệm nuôi nhân tạo","Hỏi cảm nhận của người dân về màu bướm thay đổi"],"e":"Tiến hoá là thay đổi qua các thế hệ ngoài tự nhiên: cần số liệu nhiều năm gắn với biến đổi môi trường."},{"f":"K2","p":"Muốn dùng hoá thạch để suy ra thứ tự xuất hiện của các nhóm sinh vật, nguyên tắc ghi chép đúng là gì?","a":"Ghi rõ lớp đất đá chứa hoá thạch: lớp sâu hơn thường cổ hơn","w":["Chỉ cần hình dạng hoá thạch, không cần vị trí lớp đá","Hoá thạch ở lớp trên luôn cổ hơn lớp dưới sâu","Trộn hoá thạch các lớp lại để nghiên cứu chung"],"e":"Địa tầng: lớp dưới hình thành trước nên hoá thạch trong đó cổ hơn, đó là cơ sở sắp xếp thời gian."},{"f":"K2","p":"Kiểm tra khả năng kháng thuốc của vi khuẩn, thí nghiệm an toàn và có đối chứng cần gì?","a":"Nuôi ở phòng chuyên môn, so đĩa có/không có kháng sinh","w":["Tự nuôi vi khuẩn gây bệnh tại nhà để thử thuốc","Thử thuốc trực tiếp trên người khi chưa kiểm chứng","Chỉ dùng đĩa có kháng sinh, không cần đĩa đối chứng"],"e":"Nghiên cứu vi khuẩn phải ở cơ sở chuyên môn; đĩa không kháng sinh làm đối chứng cho thấy vi khuẩn vẫn mọc bình thường."},{"f":"K2","p":"Khi so sánh cấu tạo của hai loài để tìm bằng chứng tiến hoá, cách tiếp cận đúng là gì?","a":"So cấu trúc tương đồng, không chỉ giống chức năng ngoài","w":["Chỉ nhìn kích thước cơ thể to nhỏ để kết luận họ hàng","Hai loài sống cùng nơi thì chắc chắn cùng nguồn gốc gần","Bỏ qua giải phẫu, chỉ dựa vào màu sắc cơ thể"],"e":"Cơ quan tương đồng cùng kế hoạch cấu tạo cho thấy nguồn gốc chung, mạnh hơn giống nhau bề ngoài do thích nghi."},{"f":"K3","p":"Bảng tỉ lệ bướm: năm 1850 (rừng sáng): bướm sáng 95%, tối 5%; năm 1950 (khói công nghiệp, thân cây sẫm): sáng 10%, tối 90%. Kết luận đúng là gì?","a":"Môi trường sẫm đi làm bướm tối được chọn lọc ưu thế hơn","w":["Bướm sáng tự biến thành bướm tối khi cây sẫm màu","Tỉ lệ hai dạng bướm không hề thay đổi theo thời gian","Chọn lọc tự nhiên không liên quan đến màu thân cây"],"e":"Bướm tối khó bị chim phát hiện trên thân cây sẫm nên sống sót và sinh sản nhiều hơn: chọn lọc tự nhiên."},{"f":"K3","p":"Người chăn nuôi chỉ cho những con gà đẻ nhiều trứng nhất làm giống qua 6 thế hệ, năng suất tăng từ 180 lên 260 trứng/năm. Đây là ví dụ của quá trình nào?","a":"Chọn lọc nhân tạo","w":["Chọn lọc tự nhiên","Đột biến số lượng NST","Di truyền liên kết gene"],"e":"Con người chủ động chọn cá thể có tính trạng mong muốn làm giống: đó là chọn lọc nhân tạo."},{"f":"K3","p":"Hoá thạch lớp đá A (sâu nhất): chỉ có sinh vật biển đơn giản; lớp B: cá và lưỡng cư; lớp C (trên cùng): thú. Thứ tự xuất hiện đúng là gì?","a":"Sinh vật biển đơn giản trước, cá sau, thú sau cùng","w":["Thú xuất hiện đầu tiên rồi mới đến cá và sinh vật biển","Cả ba nhóm xuất hiện cùng một thời điểm trong lịch sử","Lớp sâu nhất chứa sinh vật xuất hiện muộn nhất"],"e":"Lớp đá sâu cổ hơn: trình tự địa tầng cho thấy sinh vật phức tạp dần theo thời gian địa chất."},{"f":"K3","p":"Một quần thể côn trùng sau nhiều lần phun thuốc: lần 1 chết 95%, các lần sau tỉ lệ chết giảm còn 40% dù dùng thuốc như cũ. Giải thích đúng là gì?","a":"Cá thể kháng thuốc sống sót, truyền tính kháng cho đời sau","w":["Thuốc tự yếu đi vì côn trùng làm thuốc biến chất","Mọi côn trùng đều tự miễn dịch ngay trong đời mình","Phun thuốc càng nhiều côn trùng càng yếu đi mãi"],"e":"Chọn lọc: số ít cá thể vốn kháng thuốc sống sót và di truyền tính kháng, quần thể dần kháng hơn."},{"f":"K3","p":"Darwin quan sát chim sẻ ở các đảo có mỏ khác nhau phù hợp thức ăn từng đảo. Kết luận phù hợp nhất là gì?","a":"Sẻ phân hoá từ tổ tiên chung, thích nghi từng đảo","w":["Mỗi loài sẻ được tạo ra riêng lẻ không liên quan nhau","Mỏ chim thay đổi ngay khi chim muốn ăn loại hạt khác","Môi trường đảo không ảnh hưởng gì tới hình dạng mỏ"],"e":"Cùng tổ tiên, khác điều kiện sống nên chọn lọc giữ lại dạng mỏ phù hợp: bằng chứng tiến hoá thích nghi."}],"ls9-h1":[{"f":"X1","p":"Một nước sau chiến tranh kinh tế kiệt quệ, lạm phát cao, dân chúng bất mãn. Điều kiện này dễ tạo cơ hội cho lực lượng nào lên nắm quyền bằng hứa hẹn cực đoan?","a":"Lực lượng phát xít hứa khôi phục sức mạnh bằng bạo lực","w":["Phong trào hoà bình quốc tế trung lập","Các nghiệp đoàn thương mại tự do","Phong trào bảo vệ môi trường sinh thái"],"e":"Khủng hoảng kinh tế - xã hội là mảnh đất cho chủ nghĩa phát xít trỗi dậy giữa hai cuộc chiến tranh."},{"f":"X1","p":"Nhà máy đóng cửa hàng loạt, ngân hàng phá sản, hàng triệu người thất nghiệp ở nhiều nước cùng lúc. Hiện tượng được mô tả là gì?","a":"Khủng hoảng kinh tế thế giới lan rộng","w":["Một nước tự nguyện giảm sản xuất hàng hoá","Thị trường chứng khoán tăng trưởng mạnh","Các nước cùng nhau xoá nợ cho nhau"],"e":"Khủng hoảng 1929-1933 bắt đầu từ Mỹ rồi lan ra toàn thế giới tư bản."},{"f":"X1","p":"Hai cách thoát khủng hoảng: một nước cải cách kinh tế - xã hội trong khuôn khổ dân chủ, nước khác lập chế độ độc tài phát xít và chạy đua vũ trang. Bài học so sánh đúng là gì?","a":"Cùng khủng hoảng nhưng lựa chọn chính trị rất khác nhau","w":["Mọi nước đều chọn con đường phát xít như nhau","Cải cách dân chủ không thể giúp thoát khủng hoảng","Khủng hoảng không ảnh hưởng gì tới chính trị"],"e":"Mỹ với Chính sách mới và Đức, Nhật đi theo phát xít là hai hướng giải quyết trái ngược."},{"f":"X1","p":"Một nước phát xít tăng chi quân sự, tuyên truyền chủ nghĩa dân tộc cực đoan, đòi chia lại thế giới. Nguy cơ trực tiếp nhất là gì?","a":"Gây chiến tranh xâm lược để chia lại thế giới","w":["Hoà bình thế giới được củng cố lâu dài","Các nước thuộc địa được trao độc lập ngay","Chạy đua vũ trang biến mất trên thế giới"],"e":"Chủ nghĩa phát xít là nguồn gốc trực tiếp dẫn tới Chiến tranh thế giới thứ hai."},{"f":"X2","p":"Ảnh tư liệu: hàng người thất nghiệp dài trước cửa một nhà phát cháo ở Mỹ đầu thập niên 1930. Bức ảnh phản ánh điều gì?","a":"Hậu quả xã hội nặng nề của khủng hoảng kinh tế","w":["Đời sống nhân dân Mỹ sung túc nhất thời kì này","Thất nghiệp không tồn tại trong khủng hoảng","Chính phủ không cần can thiệp vào kinh tế"],"e":"Ảnh thất nghiệp, đói nghèo là tư liệu điển hình về khủng hoảng 1929-1933."},{"f":"X2","p":"Mô tả sử liệu: một đạo luật/hiệp ước sau WWI buộc nước thua trận bồi thường nặng và mất đất, gây bất mãn kéo dài. Sử liệu giúp giải thích điều gì?","a":"Hệ thống hoà ước bất công gieo mầm xung đột mới","w":["Chiến tranh đã chấm dứt mọi mâu thuẫn quốc tế","Nước thua trận hài lòng hoàn toàn với hoà ước","Bồi thường chiến tranh giúp kinh tế phát triển"],"e":"Hệ thống Vec-xai - Oa-sinh-tơn chứa đựng mâu thuẫn, không tạo hoà bình bền vững."},{"f":"X2","p":"Một bài diễn văn của lãnh đạo phát xít hứa xoá bỏ hiệp ước bất công, khôi phục quân đội mạnh, đổ lỗi cho các nhóm dân cư khác. Bài diễn văn cho thấy thủ đoạn nào?","a":"Kích động dân tộc cực đoan để giành quyền lực","w":["Kêu gọi đoàn kết quốc tế chống chiến tranh","Chủ trương cắt giảm quân đội để hoà bình","Bảo vệ quyền của mọi nhóm dân cư như nhau"],"e":"Phát xít lợi dụng bất mãn và tuyên truyền cực đoan để lên nắm quyền ở Đức, Italia, Nhật."},{"f":"X3","p":"Bảng sản xuất công nghiệp thời khủng hoảng (minh hoạ theo hướng SGK): chỉ số từ 100 xuống khoảng 60 ở nhiều nước tư bản. Nhận xét đúng là gì?","a":"Sản xuất suy giảm nghiêm trọng trong khủng hoảng","w":["Sản xuất tăng mạnh nhờ khủng hoảng","Chỉ số không thay đổi trong suốt thập niên","Khủng hoảng chỉ ảnh hưởng ngành nông nghiệp"],"e":"Sụt giảm sản xuất là biểu hiện cốt lõi của khủng hoảng kinh tế 1929-1933."},{"f":"X3","p":"Số người thất nghiệp ở một nước (minh hoạ): 1929: 1 triệu; 1932: 6 triệu. Hệ quả xã hội suy ra đúng nhất là gì?","a":"Đời sống lao động sa sút, bất ổn xã hội tăng cao","w":["Thất nghiệp tăng làm xã hội ổn định hơn","Người lao động giàu lên nhờ trợ cấp cao","Sáu triệu người đều chuyển sang làm chủ"],"e":"Thất nghiệp tăng 6 lần kéo theo đói nghèo và bất mãn, tạo điều kiện cho cực đoan."},{"f":"X3","p":"Dãy năm: WWI kết thúc 1918; khủng hoảng bắt đầu 1929; WWII bùng nổ 1939. Nhận xét đúng về khoảng giữa hai cuộc chiến là gì?","a":"Chỉ khoảng hai thập kỉ hoà bình đầy bất ổn","w":["Hoà bình kéo dài gần một thế kỉ ổn định","WWII nổ ra ngay năm sau khi WWI kết thúc","Khủng hoảng diễn ra sau khi WWII kết thúc"],"e":"1918-1939 là 21 năm: trật tự sau WWI mong manh, khủng hoảng và phát xít dẫn tới chiến tranh mới."}],"ls9-h2":[{"f":"X1","p":"Một thanh niên yêu nước đầu thế kỉ XX nhận thấy con đường vua quan phong kiến và con đường dựa vào nước ngoài đều bế tắc. Hướng đi mới đúng đắn là gì?","a":"Tìm con đường cứu nước gắn với cách mạng vô sản","w":["Quay lại xin vua ban chiếu Cần Vương mới","Chờ một nước tư bản trao trả độc lập","Bỏ hoạt động yêu nước để làm kinh tế riêng"],"e":"Nguyễn Ái Quốc tìm ra con đường cứu nước theo khuynh hướng vô sản sau khi tiếp cận chủ nghĩa Mác - Lê-nin."},{"f":"X1","p":"Công nhân đồn điền, nhà máy bị bóc lột nặng, nhiều cuộc bãi công nổ ra nhưng tự phát, nhanh chóng bị đàn áp. Điều phong trào còn thiếu nhất là gì?","a":"Tổ chức lãnh đạo thống nhất và đường lối rõ ràng","w":["Sự tham gia của đông đảo quần chúng lao động","Lí do chính đáng để đấu tranh đòi quyền lợi","Sự chú ý của chính quyền thực dân cai trị"],"e":"Phong trào trước 1930 còn tự phát; sự ra đời của Đảng năm 1930 khắc phục hạn chế đó."},{"f":"X1","p":"Ở một vùng nông thôn, nông dân chiếm chính quyền xã trong cao trào cách mạng, chia lại ruộng công, xoá nợ. Hình thức chính quyền mới đó gợi nhớ cao trào nào?","a":"Xô viết Nghệ - Tĩnh","w":["Phong trào Cần Vương","Khởi nghĩa Yên Bái","Phong trào Đông du"],"e":"Xô viết Nghệ - Tĩnh 1930-1931 là đỉnh cao của cao trào cách mạng 1930-1931."},{"f":"X1","p":"Tháng 8/1945, thời cơ tổng khởi nghĩa xuất hiện khi phát xít Nhật đầu hàng Đồng minh. Yếu tố quyết định để chớp thời cơ thành công là gì?","a":"Lực lượng cách mạng đã được chuẩn bị lâu dài","w":["Chỉ cần một tuyên bố mà không cần lực lượng","Chờ quân Đồng minh đến trao chính quyền","Dựa hoàn toàn vào quân đội nước ngoài"],"e":"Thắng lợi Cách mạng tháng Tám nhờ chuẩn bị lực lượng, đường lối và chớp đúng thời cơ."},{"f":"X2","p":"Mô tả sử liệu: một bản yêu sách của người đại diện nhân dân An Nam gửi tới hội nghị quốc tế năm 1919 đòi các quyền tự do, bình đẳng. Sử liệu cho thấy điều gì?","a":"Yêu nước Việt Nam đã vươn ra đấu tranh trên trường quốc tế","w":["Nhân dân Việt Nam chấp nhận mãi ách thuộc địa","Yêu sách đòi khôi phục chế độ phong kiến cũ","Hội nghị đã trao độc lập ngay cho Việt Nam"],"e":"Bản Yêu sách của nhân dân An Nam là hoạt động nổi tiếng của Nguyễn Ái Quốc tại Pháp."},{"f":"X2","p":"Một văn kiện chính trị đầu năm 1930 nêu nhiệm vụ đánh đổ đế quốc và phong kiến, thành lập chính quyền của nhân dân. Văn kiện gắn với sự kiện nào?","a":"Thành lập Đảng Cộng sản Việt Nam","w":["Thành lập nước Việt Nam Dân chủ Cộng hoà","Kí Hiệp định Giơ-ne-vơ về Đông Dương","Phát động kháng chiến toàn quốc chống Pháp"],"e":"Hội nghị hợp nhất đầu 1930 thành lập Đảng, thông qua cương lĩnh chính trị đầu tiên."},{"f":"X2","p":"Ảnh tư liệu: đoàn biểu tình đông đảo có cờ đỏ búa liềm ở vùng Nghệ - Hà đầu thập niên 1930. Ảnh phản ánh cao trào nào?","a":"Cao trào cách mạng 1930-1931","w":["Cao trào kháng chiến chống Mỹ cứu nước","Phong trào Duy tân đầu thế kỉ XX","Cao trào cải cách ruộng đất sau 1954"],"e":"Hình ảnh biểu tình, mít tinh là tư liệu tiêu biểu của Xô viết Nghệ - Tĩnh."},{"f":"X3","p":"Bảng thời gian (SGK): Đảng thành lập 1930; cao trào 1930-1931; Mặt trận Việt Minh thành lập 1941; Tổng khởi nghĩa 1945. Nhận xét đúng là gì?","a":"Quá trình chuẩn bị cách mạng kéo dài, có bước phát triển","w":["Cách mạng tháng Tám thắng lợi không cần chuẩn bị","Đảng thành lập sau khi cách mạng đã thắng lợi","Việt Minh thành lập trước khi có Đảng lãnh đạo"],"e":"15 năm từ 1930 đến 1945 là quá trình rèn luyện, chuẩn bị lực lượng cho tổng khởi nghĩa."},{"f":"X3","p":"Số tỉnh/thành giành chính quyền trong Tổng khởi nghĩa (theo bài học): khởi nghĩa thắng lợi trên cả nước trong thời gian ngắn cuối tháng 8. Kết luận đúng là gì?","a":"Khởi nghĩa có tính toàn dân, toàn quốc và kịp thời","w":["Chỉ một thành phố duy nhất giành chính quyền","Khởi nghĩa kéo dài nhiều năm mới thắng lợi","Chính quyền cách mạng chỉ lập ở nông thôn"],"e":"Tính toàn quốc, toàn dân và chớp thời cơ là đặc điểm nổi bật của Cách mạng tháng Tám."},{"f":"X3","p":"Bảng lực lượng (minh hoạ tổng hợp): từ đội tuyên truyền nhỏ năm 1944, đến 1945 đã có lực lượng vũ trang và căn cứ địa rộng. Xu hướng đúng là gì?","a":"Lực lượng cách mạng lớn mạnh nhanh trước tổng khởi nghĩa","w":["Lực lượng cách mạng yếu dần theo thời gian","Không cần xây dựng lực lượng vũ trang nào","Căn cứ địa thu hẹp dần đến khi biến mất"],"e":"Việt Minh xây dựng lực lượng chính trị và vũ trang làm tiền đề cho tổng khởi nghĩa."}],"ls9-h3":[{"f":"X1","p":"Sau 1945, hai nước lớn có chế độ xã hội khác nhau cùng thắng phát xít rồi nhanh chóng đối đầu. Tình trạng đối đầu kéo dài nhưng không chiến tranh trực tiếp được gọi là gì?","a":"Chiến tranh lạnh giữa hai cực","w":["Chiến tranh thế giới thứ ba nóng","Hoà bình hợp tác toàn diện tuyệt đối","Chung sống không có mâu thuẫn nào"],"e":"Trật tự hai cực Ianta dẫn tới Chiến tranh lạnh giữa Liên Xô và Mỹ cùng các đồng minh."},{"f":"X1","p":"Một nước thuộc địa sau 1945 tuyên bố độc lập, phong trào lan ra nhiều nước Á, Phi. Xu thế chung đó là gì?","a":"Phong trào giải phóng dân tộc phát triển mạnh","w":["Các đế quốc tự nguyện tăng thêm thuộc địa","Thuộc địa chấp nhận cai trị lâu dài hơn","Chỉ châu Âu mới có biến động chính trị"],"e":"Sau 1945, phong trào giải phóng dân tộc làm hệ thống thuộc địa của chủ nghĩa đế quốc tan rã."},{"f":"X1","p":"Một quốc gia Tây Âu sau chiến tranh nhận viện trợ kinh tế của Mỹ để phục hồi. Hệ quả chính trị đi kèm thường là gì?","a":"Gắn kết hơn vào khối tư bản do Mỹ đứng đầu","w":["Trở thành đồng minh của Liên Xô ngay","Rút khỏi mọi liên minh quốc tế lớn","Không chịu ảnh hưởng nào từ bên ngoài"],"e":"Kế hoạch phục hồi châu Âu gắn Tây Âu vào quỹ đạo ảnh hưởng của Mỹ thời Chiến tranh lạnh."},{"f":"X1","p":"Cuối thập niên 1980, một loạt nước Đông Âu thay đổi chế độ, tiếp đó Liên Xô tan rã. Hệ quả lớn nhất đối với trật tự thế giới là gì?","a":"Trật tự hai cực chấm dứt, thế giới chuyển biến mới","w":["Chiến tranh lạnh trở nên gay gắt hơn trước","Hai cực được củng cố vững chắc hơn nữa","Mỹ và Liên Xô cùng tăng cường đối đầu"],"e":"Năm 1991, Liên Xô tan rã, trật tự hai cực Ianta sụp đổ."},{"f":"X2","p":"Mô tả bản đồ: châu Âu bị chia bởi một 'bức màn' tượng trưng, phía đông và phía tây thuộc hai khối đối lập. Bản đồ phản ánh tình trạng nào?","a":"Châu Âu chia thành hai khối trong Chiến tranh lạnh","w":["Châu Âu thống nhất thành một nhà nước chung","Không còn biên giới quốc gia ở châu Âu","Hai khối hợp tác quân sự chặt chẽ với nhau"],"e":"Sự phân chia Đông - Tây Âu là biểu hiện rõ của trật tự hai cực và Chiến tranh lạnh."},{"f":"X2","p":"Sử liệu: một hội nghị cuối WWII của ba cường quốc thắng trận thoả thuận phân chia phạm vi ảnh hưởng và lập Liên hợp quốc. Hội nghị đó đặt nền cho điều gì?","a":"Trật tự thế giới hai cực sau chiến tranh","w":["Chiến tranh lạnh kết thúc ngay năm 1945","Các nước thuộc địa được độc lập tất cả","Một chính phủ thế giới duy nhất ra đời"],"e":"Hội nghị Ianta (1945) phân chia phạm vi ảnh hưởng, hình thành trật tự hai cực."},{"f":"X2","p":"Một bài phát biểu của lãnh đạo một nước thuộc địa tại hội nghị Á - Phi tuyên bố không đứng về khối nào. Bài phát biểu thể hiện xu hướng nào?","a":"Phong trào không liên kết của các nước mới độc lập","w":["Gia nhập khối quân sự của một siêu cường","Chấp nhận quay lại chế độ thuộc địa cũ","Cô lập hoàn toàn với thế giới bên ngoài"],"e":"Nhiều nước Á, Phi, Mỹ Latinh chọn đường lối không liên kết trong thời Chiến tranh lạnh."},{"f":"X3","p":"Bảng số nước độc lập (minh hoạ xu hướng SGK): sau 1945 hàng chục nước Á, Phi giành độc lập trong vài thập kỉ. Nhận xét đúng là gì?","a":"Hệ thống thuộc địa cũ tan rã trên phạm vi rộng","w":["Số nước thuộc địa tăng lên sau năm 1945","Độc lập chỉ diễn ra ở một châu lục duy nhất","Phong trào giải phóng dân tộc thất bại chung"],"e":"Làn sóng độc lập dân tộc làm bản đồ chính trị thế giới thay đổi căn bản sau 1945."},{"f":"X3","p":"Dãy năm: Ianta 1945; Chiến tranh lạnh kéo dài tới 1991. Độ dài khoảng 46 năm. Nhận định đúng là gì?","a":"Đối đầu hai cực chi phối quan hệ quốc tế gần nửa thế kỉ","w":["Chiến tranh lạnh chỉ kéo dài vài năm ngắn ngủi","Trật tự hai cực kết thúc ngay sau năm 1945","Năm 1991 hai cực mới bắt đầu hình thành"],"e":"1991-1945=46 năm, cho thấy sức chi phối lâu dài của trật tự hai cực Ianta."},{"f":"X3","p":"Chi tiêu quân sự của hai siêu cường (minh hoạ): tăng cao kéo dài, kèm các cuộc chiến tranh cục bộ ở nhiều khu vực. Kết luận phù hợp là gì?","a":"Chạy đua vũ trang gây tốn kém và bất ổn thế giới","w":["Chiến tranh lạnh không tốn kém nguồn lực nào","Chi tiêu quân sự giảm đều suốt thời kì này","Chiến tranh cục bộ không liên quan hai cực"],"e":"Chiến tranh lạnh biểu hiện ở chạy đua vũ trang và xung đột cục bộ, dù hai cực không đánh nhau trực tiếp."}],"ls9-h4":[{"f":"X1","p":"Sau Cách mạng tháng Tám, đất nước cùng lúc đối mặt giặc đói, giặc dốt và thù trong giặc ngoài. Cách ứng phó thể hiện bản lĩnh của chính quyền mới là gì?","a":"Vừa củng cố chính quyền, vừa lo đời sống, học tập của dân","w":["Chỉ tập trung quân sự, bỏ qua đói và dốt","Xin nước ngoài cai quản giúp một thời gian","Hoãn mọi việc đến khi hết khó khăn mới làm"],"e":"Những năm đầu, chính quyền cách mạng giải quyết nạn đói, nạn dốt và bảo vệ chính quyền non trẻ."},{"f":"X1","p":"Một chiến dịch quân sự mùa đông - xuân đánh vào tập đoàn cứ điểm mạnh nhất của địch ở vùng núi phía Bắc, buộc địch phải đàm phán. Chiến dịch đó là minh chứng cho điều gì?","a":"Kháng chiến chống Pháp đi đến thắng lợi quyết định","w":["Kháng chiến mới bắt đầu những trận đánh nhỏ","Địch tự nguyện rút vì hết lí do chiến tranh","Thắng lợi chỉ nhờ viện trợ mà không cần chiến đấu"],"e":"Chiến thắng Điện Biên Phủ 1954 buộc Pháp kí Hiệp định Giơ-ne-vơ."},{"f":"X1","p":"Trong kháng chiến chống Mỹ, miền Bắc vừa sản xuất vừa chi viện cho miền Nam. Vai trò của miền Bắc được đánh giá đúng nhất là gì?","a":"Hậu phương lớn chi viện cho tiền tuyến lớn miền Nam","w":["Miền Bắc không liên quan cuộc kháng chiến ở Nam","Miền Bắc chỉ nhận chi viện từ miền Nam vào","Hai miền không có liên hệ trong kháng chiến"],"e":"Quan hệ hậu phương - tiền tuyến là nét đặc sắc của kháng chiến chống Mỹ, cứu nước."},{"f":"X1","p":"Một học sinh đọc về đường mòn vận tải xuyên rừng, qua nhiều nước, luôn bị đánh phá ác liệt mà vẫn thông suốt. Tuyến đường cho thấy yếu tố nào quyết định chi viện?","a":"Ý chí, tổ chức và sự hi sinh của nhiều thế hệ","w":["Đường vận tải không hề bị địch đánh phá","Chi viện chỉ thực hiện bằng đường biển lớn","Tuyến đường tự hình thành không cần con người"],"e":"Đường Hồ Chí Minh là biểu tượng của tổ chức chi viện chiến lược trong kháng chiến chống Mỹ."},{"f":"X2","p":"Văn kiện đọc ngày 2/9/1945 mở đầu bằng ý 'Tất cả mọi người đều sinh ra có quyền bình đẳng' (theo SGK). Văn kiện đó khẳng định điều gì?","a":"Quyền độc lập, tự do của dân tộc Việt Nam","w":["Quyền của thực dân tiếp tục cai trị Việt Nam","Việt Nam trở thành một tỉnh của nước ngoài","Chỉ một nhóm người mới có quyền bình đẳng"],"e":"Tuyên ngôn Độc lập khai sinh nước Việt Nam Dân chủ Cộng hoà."},{"f":"X2","p":"Mô tả sử liệu: một hiệp định năm 1954 công nhận độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ của Việt Nam, lấy vĩ tuyến 17 làm giới tuyến quân sự tạm thời. Nhận định đúng là gì?","a":"Giới tuyến chỉ tạm thời, đất nước sẽ thống nhất","w":["Đất nước bị chia cắt vĩnh viễn theo hiệp định","Hiệp định chia Việt Nam thành hai quốc gia riêng","Tổng tuyển cử thống nhất không được nhắc tới"],"e":"Hiệp định Giơ-ne-vơ quy định giới tuyến tạm thời và tổng tuyển cử thống nhất đất nước."},{"f":"X2","p":"Ảnh tư liệu: lá cờ tung bay trên nóc hầm chỉ huy địch chiều 7/5/1954. Bức ảnh gắn với chiến thắng nào và cho thấy điều gì?","a":"Điện Biên Phủ - kháng chiến chống Pháp thắng lợi","w":["Chiến dịch Hồ Chí Minh - giải phóng Sài Gòn","Chiến thắng biên giới - mở rộng căn cứ địa","Điện Biên Phủ trên không - thắng không quân Mỹ"],"e":"Hình ảnh cờ trên hầm Đờ Cát là biểu tượng chiến thắng Điện Biên Phủ."},{"f":"X3","p":"Bảng thời gian: kháng chiến chống Pháp 1945-1954 (9 năm); chống Mỹ 1954-1975 (21 năm). Nhận xét đúng là gì?","a":"Cuộc kháng chiến giành độc lập kéo dài nhiều thập kỉ","w":["Độc lập giành được ngay sau năm 1945 không cần kháng chiến","Hai cuộc kháng chiến diễn ra trong cùng một năm","Kháng chiến chống Mỹ ngắn hơn chống Pháp"],"e":"Ba mươi năm kháng chiến liên tục là đặc điểm lớn của lịch sử Việt Nam 1945-1975."},{"f":"X3","p":"Số liệu một chiến dịch (theo SGK): quân và dân ta tiêu diệt, bắt sống toàn bộ tập đoàn cứ điểm với hơn 16 nghìn quân địch. Quy mô đó cho thấy điều gì?","a":"Thắng lợi có ý nghĩa chiến lược quyết định cuộc kháng chiến","w":["Chỉ là một trận đánh nhỏ lẻ ở biên giới","Địch tự đầu hàng không qua chiến đấu ác liệt","Chiến dịch không ảnh hưởng đàm phán quốc tế"],"e":"Quy mô tiêu diệt tập đoàn cứ điểm Điện Biên Phủ làm thay đổi cục diện chiến tranh Đông Dương."},{"f":"X3","p":"Dãy sự kiện: Hiệp định Paris 1973; đại thắng mùa Xuân 1975. Khoảng cách hai sự kiện là 2 năm. Nhận định đúng là gì?","a":"Sau hiệp định, cách mạng tiếp tục tiến tới thống nhất","w":["Hiệp định đã hoàn thành thống nhất đất nước ngay","Năm 1975 đất nước vẫn chia cắt như trước","Đại thắng diễn ra trước khi hiệp định được kí"],"e":"1973-1975: Mỹ rút quân theo hiệp định, nhân dân ta tiến lên giải phóng hoàn toàn miền Nam."}],"ls9-h5":[{"f":"X1","p":"Sau 1991, một nước lớn không còn đối thủ ngang tầm về quân sự - kinh tế trong thời gian đầu. Trật tự thế giới khi đó được mô tả đúng nhất là gì?","a":"Xu hướng đơn cực rồi dần đa cực hoá","w":["Trật tự hai cực được củng cố mạnh hơn","Thế giới không còn cường quốc nào lớn","Mọi nước có sức mạnh hoàn toàn ngang nhau"],"e":"Sau Chiến tranh lạnh, Mỹ có ưu thế tương đối, song xu thế đa cực ngày càng rõ."},{"f":"X1","p":"Một khu vực châu Á tăng trưởng kinh tế nhanh, nhiều trung tâm tài chính, công nghệ lớn xuất hiện. Điều này tác động thế nào tới trật tự thế giới?","a":"Châu Á - Thái Bình Dương thành trung tâm cạnh tranh mới","w":["Châu Á ngày càng ít vai trò trong thế giới","Chỉ châu Âu mới quyết định kinh tế toàn cầu","Tăng trưởng khu vực không ảnh hưởng trật tự quốc tế"],"e":"Sự trỗi dậy của châu Á là nét lớn của thế giới từ 1991 đến nay."},{"f":"X1","p":"Một vấn đề như biến đổi khí hậu, dịch bệnh không nước nào tự giải quyết được hiệu quả. Bài học về quan hệ quốc tế hiện nay là gì?","a":"Cần hợp tác đa phương và tổ chức quốc tế","w":["Mỗi nước đóng cửa tự giải quyết riêng lẻ","Vấn đề toàn cầu không cần ai quan tâm","Chỉ cường quốc lớn nhất mới phải hành động"],"e":"Các thách thức toàn cầu đòi hỏi hợp tác quốc tế, là đặc điểm của thế giới sau Chiến tranh lạnh."},{"f":"X1","p":"Nước Nga sau 1991 trải qua biến động lớn rồi tìm cách khôi phục vị thế cường quốc. Quá trình này cho thấy điều gì?","a":"Các nước lớn điều chỉnh chiến lược để khẳng định vị thế","w":["Nga biến mất khỏi quan hệ quốc tế sau 1991","Vị thế các nước không bao giờ thay đổi","Nga trở thành thuộc địa của một nước khác"],"e":"Nga, Mỹ, Trung Quốc, EU... đều điều chỉnh chiến lược trong trật tự thế giới mới."},{"f":"X2","p":"Mô tả bản đồ thế giới sau 1991: một liên bang lớn ở Đông Âu - Bắc Á tách thành nhiều quốc gia độc lập. Bản đồ phản ánh sự kiện nào?","a":"Liên Xô tan rã, nhiều nước độc lập ra đời","w":["Châu Âu hợp nhất thành một quốc gia duy nhất","Các nước Đông Âu gia nhập một liên bang mới lớn hơn","Bản đồ thế giới không đổi so với năm 1945"],"e":"Năm 1991 Liên Xô tan rã thành 15 nước độc lập, làm thay đổi bản đồ chính trị thế giới."},{"f":"X2","p":"Một văn kiện/tuyên bố của nhiều nước nhấn mạnh thế giới đa cực, tôn trọng luật pháp quốc tế. Văn kiện phản ánh xu thế nào?","a":"Đa cực hoá và hợp tác đa phương","w":["Đơn cực tuyệt đối do một nước chi phối mãi","Quay lại trật tự hai cực như thời Chiến tranh lạnh","Xoá bỏ hoàn toàn các tổ chức quốc tế"],"e":"Xu thế đa cực, đa phương là nét chính của quan hệ quốc tế sau 1991."},{"f":"X2","p":"Sử liệu: ảnh một bức tường ngăn đôi một thành phố châu Âu bị người dân phá bỏ năm 1989. Bức ảnh là biểu tượng của điều gì?","a":"Chiến tranh lạnh ở châu Âu đi đến kết thúc","w":["Một cuộc chiến tranh mới bắt đầu ở châu Âu","Thành phố quyết định xây tường cao hơn nữa","Châu Âu chia cắt sâu sắc hơn sau sự kiện"],"e":"Bức tường Béc-lin sụp đổ là biểu tượng kết thúc chia cắt Đông - Tây ở châu Âu."},{"f":"X3","p":"Bảng số trung tâm kinh tế lớn (minh hoạ xu hướng): năm 1991 Mỹ chiếm ưu thế nổi trội; đến nay EU, Trung Quốc, Nhật Bản cùng giữ vai trò lớn. Nhận xét đúng là gì?","a":"Sức mạnh kinh tế thế giới phân tán hơn trước","w":["Chỉ một trung tâm kinh tế duy nhất tồn tại","Kinh tế thế giới không có trung tâm nào lớn","Trung Quốc, EU không có vai trò kinh tế gì"],"e":"Đa cực hoá thể hiện trước hết ở sự phân tán sức mạnh kinh tế - tài chính."},{"f":"X3","p":"Dãy năm: Chiến tranh lạnh kết thúc 1991; đến nay đã hơn ba thập kỉ. Nhận định đúng về thời kì này là gì?","a":"Thế giới vừa hợp tác vừa cạnh tranh, nhiều biến động","w":["Thế giới yên ổn tuyệt đối không xung đột nào","Mọi xung đột cục bộ đã chấm dứt hoàn toàn","Quan hệ quốc tế đóng băng không thay đổi"],"e":"Sau 1991, thế giới có hoà bình, hợp tác là chủ đạo nhưng vẫn còn cạnh tranh, xung đột cục bộ."},{"f":"X3","p":"Tỉ trọng GDP của châu Á trong kinh tế thế giới (minh hoạ xu hướng tăng): 1990 khoảng 25%, gần đây khoảng 40%. Kết luận phù hợp là gì?","a":"Trọng tâm kinh tế thế giới dịch chuyển về châu Á","w":["Châu Á tụt hậu dần trong kinh tế thế giới","Tỉ trọng châu Á giảm một nửa sau ba thập kỉ","Kinh tế thế giới chỉ tập trung ở châu Mỹ"],"e":"Tỉ trọng tăng từ 25% lên khoảng 40% cho thấy sự trỗi dậy của châu Á - Thái Bình Dương."}],"ls9-h6":[{"f":"X1","p":"Sau thống nhất, đất nước gặp nhiều khó khăn kinh tế, cơ chế quản lí cũ không còn phù hợp. Yêu cầu cấp thiết đặt ra là gì?","a":"Đổi mới cơ chế quản lí, phát triển kinh tế - xã hội","w":["Giữ nguyên mọi cơ chế cũ không thay đổi","Đóng cửa hoàn toàn với kinh tế bên ngoài","Chỉ tập trung vào một ngành kinh tế duy nhất"],"e":"Bối cảnh khó khăn sau 1975 và khủng hoảng đầu thập niên 1980 dẫn tới đường lối Đổi mới 1986."},{"f":"X1","p":"Một hợp tác xã trước đây làm theo kế hoạch cứng, nay được khoán sản phẩm, người lao động hưởng theo kết quả làm ra. Thay đổi này phản ánh tinh thần nào của Đổi mới?","a":"Phát huy động lực của người lao động, xoá bao cấp","w":["Quay lại cơ chế phân phối bình quân tuyệt đối","Cấm mọi hoạt động kinh tế ngoài quốc doanh","Nhà nước không quản lí kinh tế bằng chính sách nữa"],"e":"Đổi mới chuyển sang kinh tế hàng hoá nhiều thành phần, vận hành theo cơ chế thị trường có quản lí."},{"f":"X1","p":"Việt Nam gia nhập một tổ chức khu vực rồi Tổ chức Thương mại thế giới. Việc hội nhập đó mang lại cơ hội chính nào?","a":"Mở rộng thị trường, thu hút đầu tư và công nghệ","w":["Tự cô lập kinh tế để tránh mọi cạnh tranh","Chỉ nhận viện trợ mà không cần cải cách trong nước","Mất hoàn toàn quyền tự chủ về kinh tế đối ngoại"],"e":"Hội nhập quốc tế là nội dung lớn của thời kì Đổi mới, từ ASEAN 1995 đến WTO 2007."},{"f":"X1","p":"Một địa phương ven biển trước đây chỉ đánh bắt nhỏ, nay có cảng, khu công nghiệp và du lịch phát triển nhờ mở cửa. Sự thay đổi này thuộc thành tựu của lĩnh vực nào?","a":"Kinh tế đối ngoại và phát triển vùng trong Đổi mới","w":["Chính sách bao cấp thời kì trước Đổi mới","Kinh tế tự cung tự cấp khép kín ở địa phương","Hoạt động buôn bán nhỏ lẻ không có đầu tư"],"e":"Đổi mới và hội nhập làm thay đổi diện mạo nhiều vùng, nhất là ven biển, đô thị lớn."},{"f":"X2","p":"Mô tả sử liệu: một văn kiện đại hội đảng cuối năm 1986 thừa nhận sai lầm, khuyết điểm và đề ra đường lối đổi mới toàn diện. Giá trị của văn kiện là gì?","a":"Đánh dấu bước ngoặt đổi mới đất nước","w":["Là văn kiện kết thúc thời kì đổi mới","Chủ trương giữ nguyên cơ chế bao cấp cũ","Chỉ đổi mới trong lĩnh vực văn hoá đơn lẻ"],"e":"Đại hội VI (1986) mở đầu công cuộc Đổi mới do Đảng khởi xướng và lãnh đạo."},{"f":"X2","p":"Ảnh tư liệu hai thời kì cùng một cửa hàng ở thành phố: trước Đổi mới hàng hoá khan hiếm, xếp hàng tem phiếu; sau Đổi mới hàng hoá phong phú. Ảnh cho thấy thay đổi nào?","a":"Đời sống và thị trường hàng hoá được cải thiện rõ","w":["Hàng hoá sau Đổi mới khan hiếm hơn trước","Tem phiếu vẫn là hình thức phân phối chính hiện nay","Ảnh không phản ánh biến đổi kinh tế nào"],"e":"Đối chiếu ảnh là cách trực quan thấy tác động của Đổi mới tới đời sống nhân dân."},{"f":"X2","p":"Một hiệp định/bản ghi nhớ ghi Việt Nam trở thành thành viên chính thức của một tổ chức khu vực năm 1995. Sự kiện đó thuộc tiến trình nào?","a":"Hội nhập quốc tế của Việt Nam thời Đổi mới","w":["Việt Nam rút khỏi mọi tổ chức quốc tế","Quan hệ đối ngoại chỉ giới hạn một nước duy nhất","Hội nhập diễn ra trước khi đất nước thống nhất"],"e":"Gia nhập ASEAN năm 1995 là mốc hội nhập quan trọng sau khi bình thường hoá quan hệ quốc tế."},{"f":"X3","p":"Bảng thu nhập bình quân (minh hoạ xu hướng SGK): từ mức rất thấp cuối thập niên 1980, đến nay tăng nhiều lần, Việt Nam vào nhóm thu nhập trung bình. Nhận xét đúng là gì?","a":"Đổi mới mang lại tăng trưởng và cải thiện đời sống","w":["Thu nhập giảm liên tục trong thời kì Đổi mới","Việt Nam vẫn ở nhóm nước nghèo nhất như trước","Tăng trưởng không ảnh hưởng gì tới đời sống dân"],"e":"Thành tựu Đổi mới thể hiện ở tăng trưởng kinh tế và giảm nghèo, nâng cao đời sống."},{"f":"X3","p":"Tỉ lệ hộ nghèo (minh hoạ xu hướng giảm mạnh): từ trên 50% đầu thập niên 1990 xuống còn vài phần trăm gần đây. Kết luận phù hợp nhất là gì?","a":"Công tác giảm nghèo đạt kết quả rất lớn","w":["Nghèo đói tăng lên trong thời kì Đổi mới","Giảm nghèo không liên quan phát triển kinh tế","Tỉ lệ nghèo giữ nguyên suốt ba thập kỉ"],"e":"Giảm nghèo là thành tựu xã hội nổi bật, được quốc tế ghi nhận của Việt Nam."},{"f":"X3","p":"Cơ cấu kinh tế (minh hoạ xu hướng): nông nghiệp giảm tỉ trọng, công nghiệp - dịch vụ tăng dần qua các thập kỉ Đổi mới. Xu hướng đó gọi là gì?","a":"Chuyển dịch cơ cấu kinh tế theo hướng hiện đại","w":["Kinh tế quay lại thuần nông như trước đây","Công nghiệp và dịch vụ biến mất dần","Cơ cấu kinh tế không thay đổi chút nào"],"e":"Chuyển dịch cơ cấu là chỉ dấu của công nghiệp hoá, hiện đại hoá trong Đổi mới."}],"ls9-h7":[{"f":"X1","p":"Một nhà máy dùng rô-bốt và hệ thống tự động, công nhân chuyển sang giám sát, bảo trì máy. Thay đổi này là biểu hiện của xu hướng nào?","a":"Tự động hoá trong cách mạng công nghiệp hiện đại","w":["Quay lại sản xuất thủ công hoàn toàn","Máy móc bị loại bỏ khỏi nhà máy hiện đại","Công nhân không cần học kĩ năng mới nữa"],"e":"Cách mạng khoa học - kĩ thuật và Công nghiệp 4.0 gắn với tự động hoá, rô-bốt, dữ liệu."},{"f":"X1","p":"Một học sinh ở Việt Nam học trực tuyến với giáo viên nước ngoài, mua hàng từ sàn thương mại điện tử quốc tế. Trải nghiệm đó phản ánh xu thế nào?","a":"Toàn cầu hoá gắn với công nghệ thông tin","w":["Mỗi nước khép kín hoàn toàn về thông tin","Thương mại chỉ diễn ra trong phạm vi làng xã","Công nghệ thông tin không ảnh hưởng đời sống"],"e":"Toàn cầu hoá thể hiện trong thương mại, giáo dục, thông tin xuyên biên giới nhờ công nghệ."},{"f":"X1","p":"Một công ti đa quốc gia đặt nhà máy ở nhiều nước, dùng linh kiện từ nhiều châu lục cho một sản phẩm. Mô hình đó cho thấy đặc điểm nào của kinh tế toàn cầu hoá?","a":"Sản xuất được tổ chức theo chuỗi giá trị toàn cầu","w":["Mỗi nước tự sản xuất khép kín mọi linh kiện","Thương mại quốc tế đang biến mất dần","Sản phẩm hiện đại chỉ làm tại một nước duy nhất"],"e":"Chuỗi cung ứng toàn cầu là biểu hiện điển hình của toàn cầu hoá kinh tế."},{"f":"X1","p":"Công nghệ mới tạo việc làm mới nhưng cũng làm một số nghề cũ mất đi. Thái độ học tập phù hợp của học sinh là gì?","a":"Học tập suốt đời, rèn kĩ năng công nghệ và thích ứng","w":["Từ chối mọi công nghệ mới trong học tập","Chỉ học một nghề cố định cho cả đời người","Công nghệ không liên quan lựa chọn nghề nghiệp"],"e":"Cách mạng 4.0 đòi hỏi lao động có kĩ năng số, khả năng học lại và thích ứng liên tục."},{"f":"X2","p":"Mô tả sử liệu: một mạng lưới máy tính toàn cầu ra đời từ cuối thế kỉ XX giúp thông tin lan truyền tức thì khắp thế giới. Sử liệu nói về thành tựu nào?","a":"Internet và cách mạng thông tin liên lạc","w":["Động cơ hơi nước trong giao thông vận tải","Kĩ thuật in chữ rời thời trung đại","Điện thoại cố định đầu thế kỉ XX"],"e":"Internet là thành tựu tiêu biểu của cách mạng khoa học - kĩ thuật hiện đại."},{"f":"X2","p":"Một bức ảnh chụp Trái Đất từ vệ tinh nhân tạo, kèm dữ liệu dự báo thời tiết toàn cầu. Bức ảnh cho thấy ứng dụng nào của khoa học hiện đại?","a":"Công nghệ vũ trụ phục vụ đời sống trên Trái Đất","w":["Vũ trụ học chỉ phục vụ mục đích quân sự thuần tuý","Vệ tinh không truyền được dữ liệu về mặt đất","Dự báo thời tiết không cần dữ liệu quan trắc"],"e":"Từ vệ tinh nhân tạo đầu tiên 1957, công nghệ vũ trụ ứng dụng rộng trong thông tin, thời tiết."},{"f":"X2","p":"Sử liệu: một tuyên bố quốc tế về biến đổi khí hậu có chữ kí của hầu hết các nước. Sự tồn tại của tuyên bố cho thấy điều gì?","a":"Vấn đề toàn cầu cần hợp tác toàn cầu giải quyết","w":["Biến đổi khí hậu chỉ là việc của một nước","Khoa học không có vai trò trong vấn đề khí hậu","Các nước không còn hợp tác với nhau nữa"],"e":"Toàn cầu hoá vừa tạo cơ hội hợp tác vừa đặt ra thách thức chung cho nhân loại."},{"f":"X3","p":"Số người dùng internet thế giới (minh hoạ xu hướng): 2000 khoảng 0,4 tỉ; 2020 khoảng 4,5 tỉ. Nhận xét đúng là gì?","a":"Kết nối số tăng hơn mười lần trong hai thập kỉ","w":["Internet ngày càng ít người sử dụng trên thế giới","Số người dùng không đổi trong suốt 20 năm","Internet chỉ phổ biến ở một châu lục duy nhất"],"e":"Tăng từ 0,4 lên 4,5 tỉ cho thấy tốc độ lan rộng của cách mạng thông tin."},{"f":"X3","p":"Bảng tốc độ xử lí/tự động hoá một dây chuyền (minh hoạ): thủ công 100 sản phẩm/ngày; tự động 5.000 sản phẩm/ngày. Kết luận đúng là gì?","a":"Năng suất tăng khoảng 50 lần nhờ tự động hoá","w":["Tự động hoá làm năng suất giảm mạnh","Hai cách sản xuất cho năng suất như nhau","Thủ công nhanh hơn tự động năm mươi lần"],"e":"5.000/100=50 lần, minh hoạ tác động năng suất của khoa học - kĩ thuật hiện đại."},{"f":"X3","p":"Thương mại thế giới (minh hoạ xu hướng tăng): giá trị xuất nhập khẩu toàn cầu tăng nhiều lần từ cuối thế kỉ XX đến nay. Xu hướng đó phản ánh điều gì?","a":"Kinh tế các nước ngày càng phụ thuộc, liên kết lẫn nhau","w":["Các nước ngày càng tự cô lập về kinh tế","Thương mại quốc tế đang thu hẹp dần đều","Toàn cầu hoá không thể hiện trong kinh tế"],"e":"Tăng trưởng thương mại và đầu tư xuyên quốc gia là thước đo của toàn cầu hoá."}],"dl9-g1":[{"f":"X1","p":"Một tỉnh đồng bằng đông dân, đất chật, nhiều lao động trẻ thiếu việc làm, trong khi khu công nghiệp tỉnh bạn thiếu công nhân. Giải pháp lao động hợp lí là gì?","a":"Đào tạo nghề và dịch chuyển lao động có tổ chức","w":["Bắt mọi lao động ở lại quê không được di chuyển","Giảm đào tạo để lao động tự tìm việc lấy","Đóng cửa khu công nghiệp thiếu công nhân"],"e":"Phân bố dân cư và lao động không đều đòi hỏi đào tạo, chuyển dịch lao động hợp lí."},{"f":"X1","p":"Một bản làng miền núi dân cư thưa, sống phân tán theo sườn núi gần nguồn nước. Kiểu phân bố đó chịu ảnh hưởng chủ yếu của yếu tố nào?","a":"Điều kiện tự nhiên và tập quán sản xuất","w":["Chính sách đô thị hoá ở thành phố lớn","Hoạt động thương mại quốc tế qua cảng biển","Mạng lưới khu công nghiệp tập trung"],"e":"Dân cư miền núi thưa, phân tán gắn với địa hình, đất, nước và sản xuất nương rẫy, lâm nghiệp."},{"f":"X1","p":"Thành phố lớn thu hút dân nhập cư nhanh, gây áp lực nhà ở, giao thông, việc làm. Biện pháp cân bằng lâu dài là gì?","a":"Phát triển các đô thị vệ tinh và kinh tế địa phương","w":["Cấm hoàn toàn người dân di chuyển đến thành phố","Tập trung mọi đầu tư vào một đô thị duy nhất","Giảm xây trường học, bệnh viện ở đô thị lớn"],"e":"Phân bố dân cư hợp lí cần giảm chênh lệch cơ hội giữa các vùng, đô thị."},{"f":"X1","p":"Một địa phương có nhiều lao động nữ dệt may, nay ngành tự động hoá mạnh. Hướng giải quyết việc làm bền vững là gì?","a":"Đào tạo lại kĩ năng, mở ngành dịch vụ, nghề mới","w":["Để lao động tự thất nghiệp không hỗ trợ gì","Giữ nguyên kĩ thuật cũ để khỏi đào tạo lại","Giảm tuổi lao động xuống mức thấp nhất"],"e":"Lao động và việc làm gắn chặt với cơ cấu kinh tế và đào tạo nghề theo nhu cầu thị trường."},{"f":"X2","p":"Mô tả bản đồ mật độ dân số: màu đậm tập trung ở hai đồng bằng lớn và đô thị, màu nhạt ở miền núi phía Bắc, Tây Nguyên. Bản đồ cho thấy đặc điểm nào?","a":"Dân cư phân bố rất không đều giữa các vùng","w":["Dân cư phân bố đều khắp cả nước như nhau","Miền núi đông dân hơn đồng bằng rõ rệt","Đô thị có mật độ thấp nhất cả nước"],"e":"Hai đồng bằng sông Hồng, sông Cửu Long và các đô thị là nơi tập trung dân cư cao nhất."},{"f":"X2","p":"Một bảng/sơ đồ tháp dân số có đáy rộng, thân thu hẹp dần ở nhóm tuổi cao. Tháp đó cho thấy cơ cấu dân số thuộc loại nào?","a":"Dân số trẻ, tỉ lệ người trong tuổi lao động sẽ tăng","w":["Dân số già, phần lớn là người cao tuổi","Dân số không có trẻ em sinh ra nữa","Cơ cấu tuổi không ảnh hưởng lao động"],"e":"Việt Nam trải qua thời kì cơ cấu dân số vàng với lực lượng lao động dồi dào."},{"f":"X2","p":"Sử liệu thống kê: nước ta có 54 dân tộc, dân tộc Kinh chiếm đa số, các dân tộc khác phân bố chủ yếu ở miền núi, biên giới. Nhận định đúng là gì?","a":"Cộng đồng dân tộc đa dạng, phân bố xen kẽ theo vùng","w":["Chỉ một dân tộc duy nhất sinh sống ở Việt Nam","Mọi dân tộc đều tập trung ở đồng bằng ven biển","Dân tộc thiểu số chiếm đa số dân cả nước"],"e":"54 dân tộc là đặc điểm cơ bản của dân cư Việt Nam trong SGK."},{"f":"X3","p":"Bảng mật độ dân số (làm tròn, người/km2): đồng bằng sông Hồng khoảng 1.000; miền núi phía Bắc khoảng 130. Nhận xét đúng là gì?","a":"Mật độ đồng bằng cao gấp nhiều lần miền núi","w":["Miền núi đông đúc hơn đồng bằng sông Hồng","Mật độ hai vùng hoàn toàn bằng nhau","Mật độ không liên quan điều kiện sống"],"e":"Khoảng 1.000 so với 130, gấp gần 8 lần, thể hiện phân bố dân cư không đều."},{"f":"X3","p":"Cơ cấu lao động theo ngành (minh hoạ xu hướng): nông nghiệp giảm từ khoảng 60% xuống 30%, dịch vụ tăng lên gần 40%. Xu hướng đúng là gì?","a":"Lao động chuyển dịch theo cơ cấu kinh tế hiện đại","w":["Lao động nông nghiệp tăng mạnh trở lại đa số tuyệt đối","Dịch vụ biến mất khỏi cơ cấu lao động","Cơ cấu lao động không đổi qua thời gian"],"e":"Chuyển dịch lao động gắn với công nghiệp hoá: giảm nông nghiệp, tăng công nghiệp - dịch vụ."},{"f":"X3","p":"Tỉ lệ thất nghiệp/thiếu việc (minh hoạ): thành thị 2%, nông thôn thiếu việc theo thời vụ cao hơn. Vấn đề việc làm nổi bật ở nông thôn là gì?","a":"Thiếu việc làm theo mùa vụ nông nghiệp","w":["Nông thôn không còn lao động nào sinh sống","Việc làm nông thôn đã đầy đủ quanh năm hết","Thất nghiệp thành thị cao hơn mọi nơi khác nhiều"],"e":"Lao động nông thôn đông, nông nghiệp thời vụ nên thiếu việc làm là vấn đề cần giải quyết."}],"dl9-g2":[{"f":"X1","p":"Một tỉnh ven biển có ngư trường lớn, cảng cá và cơ sở chế biến. Ngành kinh tế nên ưu tiên phát triển theo lợi thế là gì?","a":"Thuỷ sản gắn khai thác, nuôi trồng và chế biến","w":["Trồng cây ôn đới trên đất mặn ven biển","Khai thác than đá dưới đáy biển gần bờ","Chỉ phát triển trồng lúa trên đất bãi triều"],"e":"Điều kiện tự nhiên ven biển quyết định thế mạnh thuỷ sản của nhiều địa phương."},{"f":"X1","p":"Vùng đất đỏ badan rộng, khí hậu cận xích đạo hai mùa mưa khô. Cây công nghiệp phù hợp nhất để phát triển lâu năm là gì?","a":"Cà phê, cao su, hồ tiêu","w":["Lúa nước ở ruộng ngập sâu","Cây ôn đới cần mùa đông lạnh dài","Rong biển và cây ngập mặn ven triều"],"e":"Tây Nguyên với đất badan là vùng cây công nghiệp lâu năm trọng điểm của cả nước."},{"f":"X1","p":"Một địa phương có di tích lịch sử, bãi biển đẹp, lễ hội đặc sắc nhưng giao thông chưa thuận lợi. Để du lịch phát triển, yếu tố cần cải thiện trước là gì?","a":"Hạ tầng giao thông và dịch vụ du lịch","w":["Bỏ qua quảng bá vì tài nguyên đã đủ mạnh","Hạn chế khách để giữ nguyên hạ tầng cũ","Chỉ xây thêm nhà máy công nghiệp nặng"],"e":"Du lịch cần tài nguyên du lịch cộng với hạ tầng, dịch vụ và nguồn nhân lực."},{"f":"X1","p":"Nông dân muốn tăng thu nhập thay vì chỉ bán nông sản thô giá thấp. Hướng đi phù hợp với xu hướng ngành nông nghiệp hiện nay là gì?","a":"Chế biến sâu, xây thương hiệu, liên kết tiêu thụ","w":["Bán toàn bộ sản phẩm thô ngay sau thu hoạch","Giảm chất lượng để tăng số lượng bán ra","Bỏ trồng trọt, không sản xuất gì nữa"],"e":"Nông nghiệp hiện đại gắn sản xuất với chế biến, thị trường và ứng dụng công nghệ."},{"f":"X2","p":"Mô tả bản đồ công nghiệp: các trung tâm công nghiệp lớn tập trung ở Đông Nam Bộ, đồng bằng sông Hồng và ven biển miền Trung. Bản đồ cho thấy quy luật phân bố nào?","a":"Công nghiệp gắn với đô thị, cảng, nguồn lao động, thị trường","w":["Công nghiệp phân bố đều ở mọi vùng núi cao","Trung tâm công nghiệp xa hẳn các đầu mối giao thông","Công nghiệp chỉ có ở vùng trồng lúa lớn nhất"],"e":"Công nghiệp tập trung nơi có hạ tầng, lao động, thị trường và nguyên liệu thuận lợi."},{"f":"X2","p":"Một biểu đồ cơ cấu giá trị sản xuất nông nghiệp có trồng trọt chiếm tỉ trọng lớn nhất, chăn nuôi tăng dần. Biểu đồ cho thấy điều gì?","a":"Trồng trọt vẫn chủ đạo, chăn nuôi ngày càng quan trọng","w":["Chăn nuôi đã chiếm toàn bộ giá trị nông nghiệp","Trồng trọt biến mất khỏi nông nghiệp nước ta","Thuỷ sản thuộc lĩnh vực công nghiệp chế tạo"],"e":"Cơ cấu nông nghiệp chuyển dịch theo hướng tăng chăn nuôi, thuỷ sản, giảm thuần trồng trọt."},{"f":"X2","p":"Bản đồ thương mại chấm các cửa khẩu, cảng biển và trung tâm thương mại lớn ở biên giới phía Bắc, phía Tây và ven biển. Nhận định đúng là gì?","a":"Hoạt động thương mại gắn với vị trí giao thông, cửa khẩu","w":["Thương mại chỉ diễn ra trong nội bộ một tỉnh","Cảng biển không liên quan xuất nhập khẩu hàng hoá","Cửa khẩu biên giới không có trao đổi hàng hoá"],"e":"Dịch vụ thương mại phát triển theo mạng lưới giao thông, đô thị và cửa khẩu quốc tế."},{"f":"X3","p":"Bảng sản lượng lúa (minh hoạ): vùng A năng suất 6 tấn/ha trên 1 triệu ha; vùng B năng suất 4 tấn/ha trên 1 triệu ha. Kết luận đúng là gì?","a":"Cùng diện tích, vùng A cho sản lượng cao hơn 2 triệu tấn","w":["Hai vùng cho sản lượng hoàn toàn bằng nhau","Vùng B cho sản lượng cao hơn vùng A","Năng suất không ảnh hưởng sản lượng lúa"],"e":"6 triệu tấn so với 4 triệu tấn: chênh 2 triệu tấn do năng suất khác nhau."},{"f":"X3","p":"Cơ cấu GDP (minh hoạ xu hướng): nông - lâm - thuỷ sản 15%, công nghiệp - xây dựng 38%, dịch vụ 47%. Nhận xét đúng là gì?","a":"Dịch vụ chiếm tỉ trọng lớn nhất trong cơ cấu","w":["Nông nghiệp chiếm hơn một nửa GDP hiện nay","Công nghiệp có tỉ trọng nhỏ nhất ba khu vực","Ba khu vực có tỉ trọng hoàn toàn bằng nhau"],"e":"Cơ cấu hiện đại: dịch vụ lớn nhất, nông nghiệp giảm xuống tỉ trọng thấp nhất."},{"f":"X3","p":"Kim ngạch xuất khẩu một mặt hàng (tỉ USD, minh hoạ): năm 1: 2; năm 5: 5; năm 10: 9. Xu hướng và ý nghĩa phù hợp là gì?","a":"Xuất khẩu tăng, thị trường và sức cạnh tranh mở rộng","w":["Xuất khẩu giảm dần qua các năm quan sát","Mặt hàng mất hoàn toàn thị trường nước ngoài","Kim ngạch không thay đổi trong mười năm"],"e":"Từ 2 lên 9 tỉ USD cho thấy tăng trưởng xuất khẩu gắn với hội nhập, chế biến."}],"dl9-g3":[{"f":"X1","p":"Một vùng có đất badan, khí hậu cao nguyên và diện tích rừng còn khá, dân tộc thiểu số đông. Vùng đó phù hợp nhất với hướng phát triển nào?","a":"Cây công nghiệp lâu năm, thuỷ điện, du lịch cao nguyên","w":["Nuôi trồng thuỷ sản biển quy mô lớn nhất nước","Khai thác dầu khí ở thềm lục địa xa bờ","Trồng lúa ngập sâu ở châu thổ rộng lớn"],"e":"Các đặc điểm nêu là thế mạnh điển hình của Tây Nguyên."},{"f":"X1","p":"Vùng đồng bằng thấp nhất nước, sông kênh chằng chịt, thường có mùa nước nổi. Để phát triển bền vững, vùng cần ưu tiên thích ứng với vấn đề nào?","a":"Biến đổi khí hậu, xâm nhập mặn và sụt lún đất","w":["Tuyết rơi dày kéo dài trong mùa đông","Hoang mạc hoá do hoàn toàn không có sông ngòi","Động đất mạnh xảy ra thường xuyên hàng năm"],"e":"Đồng bằng sông Cửu Long chịu tác động mạnh của nước biển dâng và xâm nhập mặn."},{"f":"X1","p":"Một vùng có thủ đô, nhiều trường đại học, viện nghiên cứu và công nghiệp công nghệ cao. Lợi thế lớn nhất của vùng là gì?","a":"Nguồn nhân lực chất lượng cao và hạ tầng phát triển","w":["Tài nguyên dầu khí lớn nhất cả nước ngoài khơi","Diện tích rừng tự nhiên lớn nhất cả nước","Mật độ dân số thấp nhất trong các vùng"],"e":"Đồng bằng sông Hồng, nhất là Hà Nội, có thế mạnh về nhân lực, khoa học - công nghệ."},{"f":"X1","p":"Vùng ven biển miền Trung hẹp, nhiều bão, nhưng có cảng biển, bãi tắm và di sản văn hoá. Hướng phát triển tổng hợp phù hợp là gì?","a":"Kinh tế biển, du lịch và dịch vụ cảng biển","w":["Chỉ trồng lúa trên đồng bằng rộng lớn nhất nước","Phát triển thuỷ điện lớn trên sông dài nhất","Khai thác bô-xít quy mô lớn như Tây Nguyên"],"e":"Bắc Trung Bộ và duyên hải miền Trung có thế mạnh kinh tế biển và du lịch di sản."},{"f":"X2","p":"Mô tả bản đồ sáu vùng: vùng ở cực Bắc nhiều núi cao, biên giới dài; vùng ở cực Nam là đồng bằng châu thổ rộng. Bản đồ giúp nhận xét gì?","a":"Mỗi vùng có điều kiện tự nhiên, thế mạnh rất khác nhau","w":["Sáu vùng có điều kiện hoàn toàn giống hệt nhau","Vùng phía Bắc là đồng bằng rộng nhất nước","Vùng phía Nam chủ yếu là núi cao hiểm trở"],"e":"Phân hoá lãnh thổ là cơ sở để mỗi vùng phát huy thế mạnh riêng trong phát triển."},{"f":"X2","p":"Một sơ đồ vùng kinh tế trọng điểm phía Nam gồm đô thị lớn nhất nước, cảng và khu công nghiệp dày đặc. Sơ đồ phản ánh vai trò nào của Đông Nam Bộ?","a":"Vùng kinh tế năng động, đóng góp lớn nhất cả nước","w":["Vùng kinh tế chậm phát triển nhất cả nước","Vùng chuyên thuần nông nghiệp trồng lúa nước","Vùng không có đô thị lớn nào đáng kể"],"e":"Đông Nam Bộ là vùng dẫn đầu về công nghiệp, dịch vụ và thu hút đầu tư."},{"f":"X2","p":"Bản đồ liên kết vùng cho thấy cao tốc, cảng biển nối Tây Nguyên và miền Trung với các cảng xuất khẩu. Liên kết đó nhằm giải quyết hạn chế nào của Tây Nguyên?","a":"Vùng không giáp biển, cần lối ra biển cho hàng hoá","w":["Tây Nguyên thiếu đất đỏ badan để trồng cây","Tây Nguyên có quá nhiều cảng biển lớn rồi","Liên kết làm Tây Nguyên mất hết thế mạnh riêng"],"e":"Tây Nguyên là vùng duy nhất không giáp biển nên liên kết vùng có ý nghĩa đặc biệt."},{"f":"X3","p":"Bảng đóng góp GDP (minh hoạ tỉ trọng): Đông Nam Bộ khoảng 30%, đồng bằng sông Hồng khoảng 30%, các vùng còn lại khoảng 40%. Nhận xét đúng là gì?","a":"Hai vùng đầu tàu chiếm khoảng ba phần năm GDP","w":["Mỗi vùng đóng góp GDP hoàn toàn bằng nhau","Vùng núi phía Bắc đóng góp lớn nhất cả nước","Đồng bằng sông Cửu Long chiếm hơn nửa GDP"],"e":"30+30=60%, cho thấy vai trò đầu tàu của Đông Nam Bộ và đồng bằng sông Hồng."},{"f":"X3","p":"Thu nhập bình quân một vùng (minh hoạ): vùng biển đảo xa đất liền thấp hơn trung bình cả nước dù giàu tiềm năng biển. Vấn đề phát triển cần quan tâm là gì?","a":"Đầu tư hạ tầng, dịch vụ để khai thác tiềm năng biển","w":["Vùng không có tiềm năng nào cần đầu tư thêm","Thu nhập thấp chứng tỏ biển không có giá trị","Giảm kết nối giữa đảo và đất liền là tốt nhất"],"e":"Tiềm năng lớn nhưng hạ tầng hạn chế là bài toán chung của nhiều vùng biển đảo, miền núi."},{"f":"X3","p":"Diện tích và dân số (làm tròn, minh hoạ theo SGK): vùng đồng bằng sông Cửu Long diện tích lớn, dân đông; vùng Tây Nguyên diện tích lớn nhưng dân thưa hơn. Nhận xét đúng là gì?","a":"Mật độ dân cư Tây Nguyên thấp hơn đồng bằng phía Nam","w":["Tây Nguyên đông dân hơn châu thổ sông Cửu Long","Hai vùng có mật độ dân hoàn toàn bằng nhau","Dân số không liên quan diện tích của vùng"],"e":"Cùng diện tích lớn nhưng điều kiện cư trú khác nhau làm mật độ dân cư chênh lệch rõ."}],"dl9-c1":[{"f":"X1","p":"Một đô thị cổ có phố nghề, thương cảng và kiến trúc nhiều thời kì chồng lấp. Khi quy hoạch hiện đại, cách làm đúng nhất để giữ bản sắc là gì?","a":"Bảo tồn khu phố cổ gắn với phát triển dịch vụ, du lịch","w":["Phá bỏ toàn bộ dấu tích cổ để xây mới đồng loạt","Cấm mọi hoạt động kinh tế trong khu đô thị cổ","Di chuyển toàn bộ dân khỏi đô thị cổ vĩnh viễn"],"e":"Đô thị lịch sử cần bảo tồn di sản trong quá trình phát triển, như Thăng Long - Hà Nội, Hội An."},{"f":"X1","p":"Thành phố nơi học sinh sống kẹt xe giờ cao điểm, ngập khi mưa lớn, thiếu cây xanh. Những vấn đề này là mặt trái của quá trình nào nếu không quy hoạch tốt?","a":"Đô thị hoá nhanh thiếu đồng bộ hạ tầng","w":["Dân số đô thị giảm mạnh trong thời gian dài","Đô thị ngừng mở rộng diện tích xây dựng","Nông thôn hoá các khu vực trung tâm thành phố"],"e":"Đô thị hoá nhanh gây áp lực hạ tầng, môi trường, nhà ở nếu quy hoạch không theo kịp."},{"f":"X1","p":"Một đô thị thông minh dùng cảm biến đo mực nước mưa, điều tiết giao thông qua dữ liệu thời gian thực. Yếu tố cốt lõi của mô hình này là gì?","a":"Ứng dụng công nghệ và dữ liệu vào quản lí đô thị","w":["Quản lí hoàn toàn bằng giấy tờ thủ công cũ","Không cần thu thập thông tin về thành phố","Chỉ lắp thiết bị trang trí cho đẹp đường phố"],"e":"Đô thị thông minh dùng công nghệ thông tin để quản lí hiệu quả, phục vụ cư dân tốt hơn."},{"f":"X1","p":"Làng nghề ven đô bị lấn bởi khu đô thị mới, nhiều hộ chuyển sang dịch vụ. Quá trình chuyển đổi đó phản ánh xu hướng nào?","a":"Đô thị hoá lan toả ra vùng ven và ngoại ô","w":["Đô thị thu hẹp dần về trung tâm hành chính","Vùng ven đô tách rời hoàn toàn khỏi thành phố","Dịch vụ biến mất ở các khu đô thị mới"],"e":"Đô thị hoá mở rộng không gian đô thị, chuyển đổi nghề nghiệp ở vùng ven."},{"f":"X2","p":"Mô tả sử liệu: một tấm bản đồ cổ của Thăng Long có hoàng thành, phố phường buôn bán và sông Hồng chảy qua phía đông. Bản đồ cho thấy đô thị xưa gắn với yếu tố nào?","a":"Vị trí bên sông lớn, trung tâm chính trị - thương mại","w":["Đô thị xưa nằm giữa sa mạc khô cằn lớn","Thành phố không có hoạt động buôn bán nào","Sông ngòi không liên quan sự hình thành đô thị"],"e":"Nhiều đô thị Việt Nam cổ hình thành bên sông lớn, là trung tâm hành chính và thương mại."},{"f":"X2","p":"Ảnh tư liệu hai thời kì của cùng một thương cảng cổ: xưa thuyền buồm san sát, nay là phố đi bộ du lịch nổi tiếng. Ảnh cho thấy sự thay đổi chức năng nào?","a":"Từ thương cảng quốc tế thành đô thị di sản - du lịch","w":["Từ đô thị thành vùng núi hoang vu không người","Chức năng của đô thị không thay đổi chút nào","Thương cảng cổ trở thành khu công nghiệp nặng"],"e":"Hội An là ví dụ đô thị cổ chuyển chức năng theo thời gian, giữ giá trị di sản."},{"f":"X2","p":"Một đoạn mô tả trong SGK về các đô thị thời phong kiến thường gắn với thành trì, lỵ sở và chợ. Mô tả đó cho thấy đặc điểm nào của đô thị xưa?","a":"Đô thị gắn với hành chính, quân sự và thương mại","w":["Đô thị xưa chủ yếu là khu công nghiệp máy móc","Mọi đô thị xưa đều có sân bay quốc tế lớn","Đô thị xưa không có chợ hay hoạt động buôn bán"],"e":"Đô thị Việt Nam truyền thống là trung tâm hành chính - thương mại, quy mô nhỏ hơn đô thị hiện đại."},{"f":"X3","p":"Tỉ lệ dân đô thị (minh hoạ xu hướng): 1990 khoảng 20%, gần đây khoảng 40%. Nhận xét đúng là gì?","a":"Quá trình đô thị hoá diễn ra ngày càng nhanh","w":["Tỉ lệ dân đô thị giảm một nửa sau ba thập kỉ","Đô thị hoá đã hoàn thành từ năm 1990 rồi","Dân số đô thị không tăng trong thời kì Đổi mới"],"e":"Tỉ trọng dân đô thị tăng gấp đôi phản ánh đô thị hoá gắn với công nghiệp hoá, Đổi mới."},{"f":"X3","p":"Số đô thị (minh hoạ): từ vài trăm đô thị cuối thế kỉ XX lên hơn 800 đô thị gần đây, gồm nhiều loại khác nhau. Kết luận phù hợp là gì?","a":"Mạng lưới đô thị mở rộng và phân cấp đa dạng","w":["Số đô thị giảm dần theo thời gian quan sát","Chỉ có một đô thị duy nhất trên cả nước","Đô thị mới chỉ xuất hiện ở vùng đồng bằng"],"e":"Mạng lưới đô thị phát triển cả về số lượng, quy mô và phân bố trên các vùng."},{"f":"X3","p":"Bảng so sánh hai đô thị (minh hoạ): đô thị đặc biệt dân số trên 5 triệu; đô thị nhỏ dân số dưới 100 nghìn. Cách phân loại này dựa chủ yếu vào tiêu chí nào?","a":"Quy mô dân số và vai trò, chức năng đô thị","w":["Màu sắc kiến trúc của các toà nhà trong đô thị","Số lượng lễ hội diễn ra trong một năm","Khoảng cách từ đô thị tới đường biên giới"],"e":"Phân loại đô thị ở Việt Nam dựa vào quy mô dân số, mật độ, vai trò và trình độ phát triển."}],"dl9-c2":[{"f":"X1","p":"Học sinh ở châu thổ sông Hồng thăm một làng có luỹ tre, cổng làng, đình và ruộng lúa bao quanh. Cấu trúc làng đó thể hiện đặc trưng nào của văn minh châu thổ?","a":"Làng xã gắn kết, tự quản trên nền lúa nước","w":["Cư trú phân tán du mục không có làng xã","Làng chỉ là nơi ở tạm theo mùa vụ ngắn","Không có sinh hoạt cộng đồng trong làng xưa"],"e":"Làng xã là tế bào của văn minh châu thổ sông Hồng, gắn với trồng lúa nước."},{"f":"X1","p":"Người dân châu thổ sông Cửu Long đắp nhà ven kênh, đi lại bằng ghe, họp chợ nổi trên sông. Lối sống đó là kết quả của quá trình nào?","a":"Thích ứng và khai phá môi trường sông nước phía Nam","w":["Sao chép nguyên xi lối sống miền núi phía Bắc","Từ chối sử dụng sông ngòi trong đời sống","Sống tách biệt hoàn toàn với thiên nhiên xung quanh"],"e":"Văn minh châu thổ phía Nam hình thành qua khai phá, thích ứng với sông nước của nhiều cộng đồng."},{"f":"X1","p":"Một lễ hội ở hai châu thổ đều cầu mưa thuận gió hoà, mùa màng tốt. Điểm chung đó bắt nguồn từ nền sản xuất nào?","a":"Nông nghiệp trồng lúa nước phụ thuộc thiên nhiên","w":["Công nghiệp khai thác mỏ ở vùng đồi núi","Thương mại đường biển quốc tế quy mô lớn","Nghề chăn nuôi gia súc trên thảo nguyên"],"e":"Tín ngưỡng, lễ hội nông nghiệp là nét chung của văn minh lúa nước hai châu thổ."},{"f":"X1","p":"Biến đổi khí hậu làm xâm nhập mặn ở châu thổ phía Nam sâu hơn, lúa bị ảnh hưởng. Giải pháp thích ứng thuộc truyền thống 'sống chung với lũ, với mặn' là gì?","a":"Chuyển đổi cây trồng, vật nuôi chịu mặn ở vùng ven","w":["Cố trồng lúa ngọt ở mọi diện tích như trước","Bỏ toàn bộ sản xuất nông nghiệp ở châu thổ","Ngăn mọi nguồn nước sông chảy vào đồng ruộng"],"e":"Thích ứng linh hoạt là truyền thống của cư dân châu thổ, nay áp dụng trước biến đổi khí hậu."},{"f":"X2","p":"Mô tả hiện vật và di tích ở châu thổ phía Nam: tượng, đồ trang sức và dấu tích cảng thị cổ ven biển. Nhóm di tích gắn với văn hoá nào?","a":"Văn hoá Óc Eo của cư dân cổ ở Nam Bộ","w":["Văn hoá Đông Sơn ở châu thổ sông Hồng","Văn hoá Sa Huỳnh ở duyên hải miền Trung","Di tích của cư dân du mục thảo nguyên Bắc Á"],"e":"Óc Eo là văn hoá cổ tiêu biểu ở châu thổ sông Cửu Long, gắn với Phù Nam."},{"f":"X2","p":"Sử liệu: hệ thống kênh đào lớn ở Nam Bộ thời phong kiến và đầu thế kỉ XX giúp thoát lũ, rửa phèn và giao thông. Hệ thống kênh cho thấy điều gì?","a":"Con người cải tạo châu thổ để mở rộng sản xuất lúa","w":["Châu thổ tự màu mỡ mà không cần cải tạo gì","Kênh đào chỉ dùng cho mục đích quân sự thuần tuý","Sản xuất lúa không cần nguồn nước tưới tiêu"],"e":"Kênh Vĩnh Tế, kênh Chợ Gạo... là công trình cải tạo châu thổ, mở rộng vùng lúa Nam Bộ."},{"f":"X2","p":"Một đoạn mô tả chợ nổi: ghe thuyền tụ họp từ sớm, hàng hoá treo trên cây sào trước mũi ghe để người mua dễ nhận biết. Chi tiết 'cây bẹo' treo hàng cho thấy nét văn hoá nào?","a":"Sáng tạo thích ứng với buôn bán trên sông nước","w":["Phong tục của cư dân vùng núi cao khô hạn","Quy định bắt buộc của thương nhân nước ngoài","Cách trang trí ghe thuyền cho lễ hội lớn"],"e":"Chợ nổi và cây bẹo là nét văn hoá sông nước đặc trưng của châu thổ sông Cửu Long."},{"f":"X3","p":"Bảng so sánh (theo SGK): tuổi hình thành - châu thổ sông Hồng bồi đắp lâu đời hơn, có đê; châu thổ sông Cửu Long trẻ hơn, mở rộng ra biển hàng chục mét mỗi năm ở mũi Cà Mau (trước đây). Nhận xét đúng là gì?","a":"Châu thổ phía Nam vẫn đang mở rộng tự nhiên ra biển","w":["Hai châu thổ ngừng bồi đắp hoàn toàn từ lâu","Châu thổ sông Hồng mở rộng nhanh hơn phía Nam","Bồi đắp không liên quan lượng phù sa sông"],"e":"Phù sa sông Mê Công từng bồi đắp mũi Cà Mau lấn biển rõ rệt, nay chịu tác động sạt lở, nước biển dâng."},{"f":"X3","p":"Tỉ trọng sản lượng (minh hoạ): châu thổ sông Cửu Long khoảng 50% sản lượng lúa, khoảng 65% sản lượng thuỷ sản nuôi trồng cả nước. Kết luận đúng là gì?","a":"Vùng là trung tâm lúa gạo và thuỷ sản lớn nhất nước","w":["Vùng chỉ mạnh về lúa, không có thế mạnh thuỷ sản","Cả nước hầu như không dựa vào vùng châu thổ này","Thuỷ sản nuôi trồng tập trung chủ yếu ở miền núi"],"e":"Số liệu tỉ trọng cho thấy vai trò trọng điểm quốc gia của châu thổ sông Cửu Long."},{"f":"X3","p":"Mật độ kênh rạch và dân cư (minh hoạ nhận xét): dân cư châu thổ phía Nam phân bố dọc sông, kênh; châu thổ phía Bắc tập trung trong các làng có đê bao. Khác biệt này do yếu tố nào chi phối?","a":"Chế độ nước và cách trị thuỷ của từng châu thổ","w":["Ngôn ngữ giao tiếp khác nhau giữa hai miền","Số lượng lễ hội khác nhau trong một năm","Khoảng cách tới thủ đô của từng châu thổ"],"e":"Sống trong đê và sống ven sông kênh là hai kiểu cư trú thích ứng với lũ khác nhau."}],"dl9-c3":[{"f":"X1","p":"Một bạn học sinh muốn góp phần bảo vệ chủ quyền biển đảo bằng hành động thiết thực, đúng lứa tuổi. Việc làm phù hợp nhất là gì?","a":"Học tập, tuyên truyền đúng về biển đảo trong nhà trường","w":["Tự ý ra đảo xa sinh sống không qua tổ chức nào","Chia sẻ thông tin chưa kiểm chứng gây hoang mang","Viết bài bịa thêm sự kiện về lịch sử quần đảo"],"e":"Trách nhiệm công dân với biển đảo bắt đầu từ nhận thức đúng và hành động hợp pháp, phù hợp lứa tuổi."},{"f":"X1","p":"Địa phương ven biển tổ chức triển lãm bản đồ, tư liệu về hai quần đảo ngoài khơi miền Trung. Mục đích giáo dục chính của triển lãm là gì?","a":"Cung cấp bằng chứng lịch sử, pháp lí về chủ quyền","w":["Trưng bày tranh phong cảnh biển cho vui mắt","Quảng cáo tour du lịch ra đảo cho mọi người","Giới thiệu các loài hải sản quý của vùng biển"],"e":"Triển lãm 'Hoàng Sa, Trường Sa của Việt Nam' là hình thức tuyên truyền bằng chứng chủ quyền phổ biến."},{"f":"X1","p":"Khi đọc tin quốc tế liên quan Biển Đông, cách tiếp cận đúng của công dân là gì?","a":"Đối chiếu nguồn chính thống và luật quốc tế","w":["Chỉ tin tiêu đề giật gân trên mạng xã hội lạ","Chia sẻ tin nóng dù chưa rõ nguồn gốc xuất xứ","Từ chối tìm hiểu mọi thông tin về biển đảo"],"e":"Lập trường của Việt Nam về Biển Đông dựa trên UNCLOS 1982 và bằng chứng lịch sử - pháp lí."},{"f":"X1","p":"Một doanh nghiệp muốn đầu tư nuôi trồng hải sản trong vùng đặc quyền kinh tế của Việt Nam. Điều kiện pháp lí cơ bản là gì?","a":"Tuân thủ pháp luật Việt Nam và quy định về vùng biển","w":["Không cần xin phép vì vùng biển là của chung thế giới","Chỉ cần thoả thuận riêng với tàu nước ngoài gần đó","Khai thác mọi loài kể cả loài cấm, quý hiếm"],"e":"Trong vùng đặc quyền kinh tế, Việt Nam có quyền chủ quyền về thăm dò, khai thác, quản lí tài nguyên."},{"f":"X2","p":"Mô tả nhóm sử liệu: bản đồ cổ của Việt Nam và phương Tây vẽ hai quần đảo ngoài khơi miền Trung thuộc lãnh thổ Việt Nam, cùng châu bản triều Nguyễn về quản lí. Nhóm sử liệu có giá trị gì?","a":"Bằng chứng lịch sử - pháp lí khẳng định chủ quyền","w":["Chỉ có giá trị nghệ thuật, không liên quan chủ quyền","Là tư liệu của nước ngoài nên không dùng được","Bản đồ cổ luôn sai nên không có giá trị gì"],"e":"Theo SGK, hệ thống tư liệu lịch sử và pháp lí là cơ sở khẳng định chủ quyền với Hoàng Sa, Trường Sa."},{"f":"X2","p":"Một điều khoản của UNCLOS 1982 quy định quốc gia quần đảo/ven biển được hưởng vùng đặc quyền kinh tế 200 hải lí. Điều khoản này giúp Việt Nam xác định điều gì?","a":"Các quyền và lợi ích hợp pháp của mình ở Biển Đông","w":["Quyền sở hữu toàn bộ Biển Đông cho một nước","Quyền tự do khai thác của mọi nước trong lãnh hải ta","Việc bãi bỏ mọi ranh giới biển giữa các nước"],"e":"UNCLOS là cơ sở pháp lí quốc tế cho các quyền hợp pháp của Việt Nam ở Biển Đông."},{"f":"X2","p":"Sử liệu: các đội tàu của nhà nước phong kiến Việt Nam hằng năm ra quần đảo đo đạc, khai thác sản vật, dựng bia, trồng cây. Hoạt động liên tục đó thể hiện điều gì?","a":"Thực thi chủ quyền thường xuyên, liên tục trong lịch sử","w":["Chỉ là hoạt động buôn bán tư nhân của ngư dân","Quần đảo được quản lí bởi một nhà nước khác","Hoạt động diễn ra một lần duy nhất rồi chấm dứt"],"e":"Đội Hoàng Sa, Bắc Hải là bằng chứng thực thi chủ quyền liên tục của nhà nước Việt Nam."},{"f":"X3","p":"Bảng các vùng biển theo UNCLOS (hải lí từ đường cơ sở): lãnh hải 12; tiếp giáp lãnh hải 24; đặc quyền kinh tế 200. Nhận xét đúng về thứ tự độ rộng là gì?","a":"Vùng đặc quyền kinh tế rộng nhất trong ba vùng nêu","w":["Lãnh hải rộng hơn vùng đặc quyền kinh tế","Vùng tiếp giáp rộng nhất trong ba vùng biển","Ba vùng có độ rộng hoàn toàn bằng nhau"],"e":"12 < 24 < 200 hải lí: các vùng biển mở rộng dần với quyền của quốc gia ven biển khác nhau."},{"f":"X3","p":"Số đảo, quần đảo (theo SGK): Việt Nam có hai quần đảo lớn ngoài khơi là Hoàng Sa và Trường Sa cùng nhiều đảo ven bờ. Nhận định đúng là gì?","a":"Hệ thống đảo là bộ phận lãnh thổ không tách rời của Việt Nam","w":["Chỉ các đảo ven bờ mới thuộc lãnh thổ Việt Nam","Quần đảo xa bờ không thuộc chủ quyền nước nào","Đảo và quần đảo không được tính là lãnh thổ"],"e":"Theo SGK, Hoàng Sa và Trường Sa là bộ phận không thể tách rời của lãnh thổ Việt Nam."},{"f":"X3","p":"Một thống kê học tập (minh hoạ): 90% học sinh sau chủ đề nêu đúng tên hai quần đảo và văn bản luật biển quốc tế liên quan. Kết luận phù hợp là gì?","a":"Giáo dục chủ quyền đạt mục tiêu nhận thức cơ bản","w":["Học sinh chưa cần học thêm gì về biển đảo nữa","Thống kê chứng minh chủ quyền không cần bằng chứng","Tỉ lệ này cho thấy dạy về biển đảo là thừa"],"e":"Nhận thức đúng là nền tảng của trách nhiệm bảo vệ chủ quyền biển, đảo trong thế hệ trẻ."}],"nv9-b1":[{"f":"V1","p":"Đọc đoạn văn: 'Nàng dâu trẻ bị oan, không một lời kêu van được tới tai người chồng đang ở xa. Đêm cuối, nàng ôm con đứng bên bờ sông, dặn con nhớ mặt cha rồi gieo mình xuống nước. Dân làng dựng một nấm mồ nhỏ ven sông. Nhiều năm sau, người chồng trở về, nghe hết đầu đuôi thì đã muộn. Oan khuất của nàng chỉ được trời đất chứng giám.' Đoạn văn khiến người đọc thương xót nàng dâu chủ yếu vì điều gì?","a":"Nàng bị oan mà không có cơ hội tự minh oan","w":["Nàng không được chồng gửi thư về thăm","Dân làng không ai quan tâm tới nàng","Người chồng trở về quá sớm sau chiến tranh"],"e":"Nàng 'không một lời kêu van được tới tai chồng', chết oan và sự thật chỉ rõ khi 'đã muộn' — như bi kịch Vũ Nương: thương xót vì oan khuất không đường minh oan."},{"f":"V1","p":"Đọc đoạn văn: 'Ông lão nghèo nuôi được con dế nhỏ, đem đấu với dế của quan huyện. Ai cũng cười vì dế nhỏ như hạt đỗ. Vậy mà dế nhỏ thắng cả gà trống, khiến quan phải nể. Ông lão thoát được tội, nhưng nhìn con dế mệt lả, ông bỗng thấy xót. Thắng lợi của kẻ yếu đôi khi cũng phải trả giá không nhỏ.' Yếu tố kì ảo trong đoạn có vai trò gì?","a":"Giúp kẻ yếu thắng kẻ mạnh, bộc lộ khát vọng công lí","w":["Chứng minh dế nhỏ luôn thắng dế to thật","Làm cho câu chuyện thêm dài và phức tạp","Cho thấy ông lão rất giỏi nuôi dế chọi"],"e":"Con dế nhỏ thắng gà trống là yếu tố kì ảo kiểu Dế chọi: nó đảo ngược mạnh — yếu, thể hiện khát vọng công lí của người dân nhỏ bé trước quyền thế."},{"f":"V1","p":"Đọc đoạn phân tích: 'Truyện kì ảo xưa không dùng phép lạ để khoe phép lạ. Mỗi chi tiết lạ đều có một món nợ với đời thực phải trả. Người chết hiện về là để nói điều lúc sống không nói được. Vật nhỏ thắng lớn là để an ủi kẻ yếu thế ngoài đời. Bóc đi lớp vỏ thần kì, bên trong là tiếng nói rất người.' Theo đoạn, chi tiết kì ảo trong truyện xưa thực chất để làm gì?","a":"Nói thay những điều đời thực khó nói trực tiếp","w":["Trang trí cho truyện thêm phần hấp dẫn","Chứng minh phép lạ là có thật ngoài đời","Làm người đọc quên đi cuộc sống thực"],"e":"Đoạn nêu người chết hiện về 'để nói điều lúc sống không nói được' (như Vũ Nương trở về) — kì ảo là phương tiện gửi tiếng nói nhân văn, không phải để khoe phép lạ."},{"f":"V1","p":"Đọc đoạn văn: 'Hai vị thần tranh nhau một nàng công chúa. Một bên dâng nước ngập đồng, một bên đắp núi cao dần. Năm nào nước cũng dâng, núi cũng cao thêm như lời hẹn chưa dứt. Người dân xem câu chuyện ấy để giải thích mùa lũ quê mình. Nhưng sâu hơn, họ gửi vào đó niềm tin rằng đất này luôn có người giữ.' Ngoài giải thích hiện tượng lũ, đoạn cho thấy truyện thần thoại còn gửi gắm điều gì?","a":"Niềm tin vào sức chống chọi, giữ đất của con người","w":["Nỗi sợ hãi tuyệt đối trước thần linh","Mong muốn hai vị thần hoà giải với nhau","Khát vọng được sống trên núi cao mát mẻ"],"e":"Gợi Sơn Tinh – Thuỷ Tinh: ngoài lí giải lũ lụt, đoạn nhấn mạnh niềm tin 'đất này luôn có người giữ' — tức sức chống chọi bền bỉ của con người trước thiên nhiên."},{"f":"V1","p":"Đọc đoạn văn: 'Sau khi mất, nàng được thuỷ thần rước về cung nước. Nàng sống trong nhung lụa mà lòng vẫn hướng về cõi trần. Khi có dịp, nàng hiện về trên sông trong thoáng chốc, nói lời từ biệt cuối cùng rồi tan vào sóng. Người chồng đứng trên bờ, gọi mãi không được một lời đáp trọn vẹn. Âm dương cách biệt là nỗi đau không gì bù nổi.' Chi tiết nàng hiện về 'trong thoáng chốc' có ý nghĩa gì?","a":"Gợi công lí muộn màng, âm dương vẫn cách biệt","w":["Chứng minh thuỷ cung là nơi hạnh phúc nhất","Cho thấy nàng đã quên hết chuyện cõi trần","Khẳng định nàng sẽ sống lại như người thường"],"e":"Hiện về thoáng chốc rồi 'tan vào sóng', chồng gọi không đáp trọn — như kết thúc Chuyện người con gái Nam Xương: oan được giải nhưng người không trở lại, công lí đến muộn và đầy đau xót."},{"f":"V1","p":"Đọc đoạn phân tích: 'Cùng một mô-típ người phụ nữ bị oan, truyện truyền kì khác truyện cổ tích ở chỗ nó không cho cái kết đoàn viên trọn vẹn. Nàng được minh oan nhưng không trở lại làm vợ, làm mẹ như xưa. Cái thiếu trọn vẹn ấy làm người đọc day dứt. Day dứt chính là cách truyện buộc ta suy nghĩ về xã hội đã sinh ra nỗi oan. Đó là dụng ý nghệ thuật sâu xa của người viết truyện truyền kì.' Theo đoạn, vì sao truyền kì không cho kết thúc đoàn viên trọn vẹn?","a":"Để người đọc day dứt và suy ngẫm về xã hội","w":["Vì tác giả không nghĩ ra được kết đoàn viên","Vì truyện truyền kì cấm viết kết có hậu","Vì nhân vật chính không muốn trở về nhà"],"e":"Đoạn lí giải kết thúc thiếu trọn vẹn tạo 'day dứt' buộc suy ngẫm về xã hội sinh ra nỗi oan — nét bi kịch đặc trưng của truyền kì, khác cổ tích đoàn viên."},{"f":"V2","p":"Câu văn: 'Chiếc bóng trên vách trong đêm vắng đã hoá thành một bản án oan treo lơ lửng trên đời nàng.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Ẩn dụ — chiếc bóng thành bản án oan nghiệt","w":["Nhân hoá — chiếc bóng biết kết tội nàng","So sánh — chiếc bóng giống như bản án thật","Nói quá — bản án treo được trên vách nhà"],"e":"'Bóng hoá thành bản án oan' là ẩn dụ, gợi chi tiết chiếc bóng trong Chuyện người con gái Nam Xương: một hình ảnh vô tình trở thành chứng cứ kết tội oan cho Vũ Nương."},{"f":"V2","p":"Câu văn: 'Con dế nhỏ, nhỏ như hạt đỗ, mà mang theo cả vận mệnh của một gia đình nghèo.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Điệp và đối lập — sinh vật nhỏ gánh số phận lớn","w":["Nói quá — con dế quyết định được vận mệnh","Ẩn dụ — hạt đỗ là vận mệnh gia đình nghèo","Hoán dụ — lấy con dế thay cho gia đình"],"e":"Từ 'nhỏ' lặp lại và đặt đối lập 'nhỏ — vận mệnh cả gia đình' làm nổi bật nghịch lí của Dế chọi: sinh vật bé nhỏ gánh trên mình sinh mệnh kẻ yếu thế."},{"f":"V2","p":"Câu văn: 'Núi cứ cao lên, nước cứ dâng lên, và lòng kiên trì của con người cũng cứ lớn lên theo năm tháng.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Điệp ngữ — nhấn mạnh cuộc chống chọi bền bỉ","w":["Ẩn dụ — núi và nước là lòng kiên trì","Nhân hoá — núi và nước biết ganh đua nhau","Liệt kê — kể các hiện tượng của thiên nhiên"],"e":"Cụm 'cứ... lên' lặp ba lần tạo điệp ngữ, song hành núi — nước — lòng người, nhấn mạnh cuộc chống chọi với lũ bền bỉ qua năm tháng trong Sơn Tinh – Thuỷ Tinh."},{"f":"V2","p":"Câu văn: 'Lời thề của nàng trong như nước sông quê, mà số phận nàng lại đục như dòng nước sau cơn lũ oan.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"So sánh đối lập — trong sáng đối lập oan khuất","w":["Ẩn dụ — nước sông quê là lời thề của nàng","Nói giảm — làm nhẹ nỗi oan của nàng dâu","Điệp ngữ — lặp lại hình ảnh dòng nước sông"],"e":"Hai vế so sánh 'trong như nước sông' và 'đục như nước sau lũ' đặt đối lập: phẩm chất trong sáng của người phụ nữ đối lập với số phận oan khuất — gây xót thương, như số phận Vũ Nương."},{"f":"V2","p":"Câu văn: 'Thuỷ cung mở cửa đón nàng về, nhưng cõi trần đóng lại sau lưng nàng một cánh cửa không bao giờ mở nữa.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Ẩn dụ — cánh cửa chỉ ranh giới âm dương","w":["Nhân hoá — thuỷ cung biết mở cửa đón khách","Điệp ngữ — lặp lại hình ảnh cánh cửa đóng","Nói quá — cánh cửa không bao giờ mở được"],"e":"'Cánh cửa không bao giờ mở nữa' là ẩn dụ cho ranh giới âm — dương không thể vượt qua, nhấn mạnh tính vĩnh viễn của chia lìa trong kết thúc truyện truyền kì."}],"nv9-b2":[{"f":"V1","p":"Đọc đoạn văn: 'Người vợ trẻ tiễn chồng ra trận, đứng tựa cửa nhìn theo cho đến khi bóng người khuất sau rặng tre. Ngày qua ngày, nàng thắp hương, ngóng tin mà tin không về. Tóc nàng điểm sương khi tuổi còn xanh. Nỗi chờ đợi gặm nhấm tuổi xuân của nàng chậm rãi mà tàn nhẫn. Chiến tranh lấy của nàng không chỉ người chồng, mà cả những năm tháng đẹp nhất.' Đoạn văn lên án chiến tranh chủ yếu ở điểm nào?","a":"Chiến tranh tàn phá tuổi xuân người ở nhà","w":["Chiến tranh làm đường đi lại khó khăn","Người vợ không nhận được thư của chồng","Chồng ra trận không mang theo đủ hành lí"],"e":"Chiến tranh 'lấy cả những năm tháng đẹp nhất', tóc điểm sương khi tuổi còn xanh — như Chinh phụ ngâm: lên án chiến tranh phi nghĩa huỷ hoại tuổi xuân người chinh phụ."},{"f":"V1","p":"Đọc đoạn văn: 'Nàng cung nữ ngồi trong cung sâu, nghe tiếng đàn của người khác vọng qua tường. Xưa kia, tiếng đàn ấy từng dành riêng cho nàng. Giờ nàng đếm ngày bằng những tiếng đàn xa dần. Thanh xuân của nàng bị giam trong bốn bức tường son. Nỗi oán của nàng không thành tiếng khóc, nó lắng thành một thứ im lặng rất dài.' Tâm trạng chủ đạo của nàng cung nữ trong đoạn là gì?","a":"Oán sầu, cô đơn vì tuổi xuân bị giam cầm","w":["Vui mừng vì được sống trong cung điện","Ganh tị với người cung nữ được sủng ái","Bình thản chờ đợi một ngày được ra cung"],"e":"Tiếng đàn 'xa dần', thanh xuân 'bị giam trong bốn bức tường son', im lặng rất dài — như Cung oán ngâm khúc: oán sầu và cô đơn là chủ đạo."},{"f":"V1","p":"Đọc đoạn phân tích: 'Thơ trữ tình trung đại viết về phụ nữ thường không cho nhân vật gào khóc. Nỗi buồn được nén vào một tiếng thở dài, một cái nhìn ra cửa, một đêm không ngủ. Sự nén ấy làm cảm xúc nặng hơn. Người đọc không bị ép phải thương. Họ tự thương lấy, và vì thế thương rất lâu.' Theo đoạn, vì sao cách viết nén cảm xúc lại hiệu quả?","a":"Cảm xúc nén chặt khiến người đọc tự rung cảm lâu","w":["Vì nhân vật phụ nữ xưa không biết khóc","Vì thơ trung đại cấm diễn tả cảm xúc mạnh","Vì người đọc không thích nhân vật yếu đuối"],"e":"Nỗi buồn 'nén vào tiếng thở dài, cái nhìn ra cửa' khiến người đọc 'tự thương lấy, thương rất lâu' — hiệu quả của trữ tình trung đại nằm ở sự kìm nén, gợi mà không tả hết."},{"f":"V1","p":"Đọc đoạn văn: 'Đêm mưa, tiếng đàn của người nghệ sĩ mù vang lên trong xóm nghèo. Người nghe ngồi quanh, không ai nói một lời. Tiếng đàn kể thay họ những nỗi niềm không gọi được thành tên: nhớ người xa, thương thân phận, tiếc tuổi trẻ. Khi tiếng đàn dứt, mưa vẫn rơi. Nhiều người ra về mà mắt còn ướt.' Theo đoạn, tiếng đàn trong đoạn có sức mạnh gì?","a":"Nói thay nỗi niềm không nói thành lời của người nghe","w":["Giúp người nghe quên hẳn mọi buồn phiền","Làm cho cơn mưa đêm nhanh chóng tạnh","Chứng tỏ tài năng của người nghệ sĩ mù"],"e":"Tiếng đàn 'kể thay những nỗi niềm không gọi được thành tên' — gợi Tiếng đàn mưa: âm nhạc trở thành tiếng nói của tâm trạng con người, không đơn thuần khoe tài nghệ."},{"f":"V1","p":"Đọc đoạn văn: 'Nàng ngồi đếm những mùa hoa nở rồi tàn sau song cửa. Mỗi mùa hoa là một năm chờ đợi nữa trôi qua. Người đi không hẹn ngày về, người ở không biết chờ đến bao giờ. Cái đáng sợ nhất không phải là xa cách. Đó là sự chờ đợi không có điểm hẹn cuối cùng.' Câu cuối đoạn giúp hiểu sâu hơn điều gì về nỗi khổ của người chờ đợi?","a":"Chờ đợi vô vọng đáng sợ hơn cả xa cách","w":["Xa cách lâu ngày làm tình cảm phai nhạt","Người chờ đợi thường quên mất thời gian","Mùa hoa nở tàn là quy luật của tự nhiên"],"e":"Đoạn kết luận 'đáng sợ nhất là chờ đợi không có điểm hẹn' — đào sâu tâm trạng chinh phụ/cung nữ: nỗi khổ nằm ở sự vô vọng, không chỉ ở khoảng cách."},{"f":"V1","p":"Đọc đoạn phân tích: 'Hai người phụ nữ, một là vợ lính, một là cung nữ — địa vị khác nhau mà nỗi niềm giống nhau đến lạ. Cả hai đều có tuổi xuân, đều bị hoàn cảnh giam giữ tuổi xuân ấy. Văn học trung đại đặt họ cạnh nhau để nói một điều lớn hơn số phận cá nhân. Đó là tiếng nói đòi quyền được sống, được hạnh phúc cho người phụ nữ. Đó cũng là tiếng nói chung mà văn học trung đại gửi tới hôm nay.' Theo đoạn, điểm gặp nhau của hai nhân vật cho thấy điều gì?","a":"Tiếng nói nhân đạo đòi hạnh phúc cho phụ nữ","w":["Phụ nữ xưa ai cũng có số phận buồn thảm","Địa vị xã hội không quan trọng với phụ nữ","Hai tác phẩm được viết bởi cùng một người"],"e":"Chinh phụ và cung nữ khác địa vị nhưng cùng bị giam tuổi xuân; đoạn rút ra 'tiếng nói đòi quyền sống, hạnh phúc cho phụ nữ' — giá trị nhân đạo chung của hai tác phẩm."},{"f":"V2","p":"Câu thơ tự viết: 'Đợi chàng, đợi đến hoa tàn mấy độ, đợi đến tóc xanh đã ngả màu sương.' Biện pháp tu từ và tác dụng của câu thơ là gì?","a":"Điệp ngữ — nhấn mạnh chờ đợi dài dằng dặc","w":["Nói quá — tóc xanh ngả sương là không thật","Ẩn dụ — hoa tàn là tuổi xuân của nàng","Hoán dụ — lấy tóc thay cho người chinh phụ"],"e":"Từ 'đợi' lặp ba lần tạo điệp ngữ, kéo dài cảm giác chờ đợi từ mùa hoa này sang mùa hoa khác đến bạc tóc — đúng tâm trạng chinh phụ chờ chồng."},{"f":"V2","p":"Câu thơ tự viết: 'Cung sâu như biển sâu, người vào thì dễ, đường ra thì không ai chỉ lối.' Biện pháp tu từ và tác dụng của câu thơ là gì?","a":"So sánh — cung cấm mênh mông, bít lối như biển","w":["Ẩn dụ — biển sâu là chốn cung cấm lạnh lẽo","Nói quá — cung điện rộng bằng cả biển lớn","Điệp ngữ — lặp lại từ sâu để nhấn mạnh"],"e":"'Cung sâu như biển sâu' có từ so sánh 'như' — so sánh, gợi chốn cung cấm mênh mông và bế tắc của người cung nữ trong Cung oán ngâm khúc."},{"f":"V2","p":"Câu văn: 'Tiếng đàn mưa đêm ấy không gảy trên dây đàn, nó gảy trên những sợi thần kinh mỏng manh nhất của người nghe.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Ẩn dụ — tiếng đàn chạm sâu vào cảm xúc","w":["Nhân hoá — tiếng đàn biết gảy đàn thay người","Nói giảm — làm nhẹ tác động của tiếng đàn","Điệp ngữ — lặp lại hình ảnh tiếng đàn mưa"],"e":"Đàn 'gảy trên sợi thần kinh' là ẩn dụ chuyển đổi cảm giác, diễn tả tiếng đàn (như Tiếng đàn mưa) tác động sâu xa, tê buốt vào tâm hồn người nghe."},{"f":"V2","p":"Câu thơ tự viết: 'Xuân đi, xuân đến, xuân lại đi — chỉ có người ngồi đợi là ở lại với tháng năm.' Biện pháp tu từ và tác dụng của câu thơ là gì?","a":"Điệp ngữ — thời gian trôi, người đợi đứng lại","w":["Đối lập — mùa xuân vui, người đợi buồn","Ẩn dụ — mùa xuân là tuổi xuân của nàng","Câu hỏi tu từ — hỏi về sự trở lại của xuân"],"e":"Từ 'xuân' và cấu trúc đi — đến — đi lặp lại tạo điệp ngữ, làm nổi bật vòng tuần hoàn thời gian đối nghịch với sự đứng yên chờ đợi của con người."},{"f":"V2","p":"Câu thơ tự viết: 'Nỗi buồn của nàng không thành tiếng, nó thành khói hương mỏng, quẩn quanh mãi trên bàn thờ lạnh.' Biện pháp tu từ và tác dụng của câu thơ là gì?","a":"Ẩn dụ — nỗi buồn thành khói hương quẩn quanh","w":["Nhân hoá — nỗi buồn biết hoá thành khói","So sánh — nỗi buồn mỏng giống khói hương","Nói quá — khói hương quẩn quanh mãi không tan"],"e":"Nỗi buồn trừu tượng 'thành khói hương mỏng quẩn quanh' là ẩn dụ hữu hình hoá cảm xúc, gợi nỗi buồn âm ỉ, dai dẳng của người phụ nữ chờ đợi trong thơ trữ tình trung đại."}],"nv9-b3":[{"f":"V1","p":"Đọc đoạn văn: 'Nàng ngồi một mình bên lầu nhỏ, nhìn ra sông nước mênh mang. Người bận tâm sự nhìn cảnh nào cũng thấy lòng mình trong đó. Sóng vỗ thì lòng nàng cũng không yên. Chim kêu chiều thì nàng lại nhớ người xa. Cảnh ngoài kia rộng lớn bao nhiêu, nỗi cô đơn trong nàng càng lớn bấy nhiêu. Nàng bị giam giữa lầu son mà tâm hồn thì trôi dạt khắp chân trời.' Đoạn văn thể hiện quan hệ cảnh — tình như thế nào?","a":"Cảnh càng rộng, nỗi cô đơn càng sâu sắc","w":["Cảnh đẹp giúp nàng quên đi nỗi buồn","Nàng không quan tâm đến cảnh vật xung quanh","Cảnh vật quyết định hoàn toàn số phận nàng"],"e":"Như Kiều ở lầu Ngưng Bích, cảnh sông nước càng mênh mang, nỗi cô đơn càng lớn — cảnh không làm vơi buồn mà làm sâu thêm tâm trạng nhân vật."},{"f":"V1","p":"Đọc đoạn văn: 'Chàng trai trẻ gặp bọn cướp đang uy hiếp đoàn xe của một tiểu thư. Không đợi ai nhờ, chàng xông vào đánh tan bọn cướp. Cứu người xong, chàng không nhận quà tạ ơn, chỉ xin được ra về. Tiểu thư nhìn theo bóng chàng khuất dần mà lòng xao xuyến. Người quân tử làm việc nghĩa như làm việc tự nhiên phải làm.' Hành động không nhận quà tạ ơn cho thấy phẩm chất gì của chàng trai?","a":"Làm việc nghĩa vô tư, không vụ lợi","w":["Không thích món quà của tiểu thư tặng","Sợ bọn cướp quay lại trả thù mình","Muốn tỏ ra lạnh lùng trước tiểu thư"],"e":"Như Lục Vân Tiên cứu Kiều Nguyệt Nga: đánh cướp vì nghĩa, không nhận tạ ơn — phẩm chất quân tử vô tư, làm điều phải làm một cách tự nhiên."},{"f":"V1","p":"Đọc đoạn văn: 'Nàng ngồi đếm canh khuya, tiếng mõ xa vọng lại từng hồi. Người ta bảo nàng dại vì cứ tự hành hạ mình bằng nỗi buồn. Nhưng chỉ nàng mới biết, nỗi buồn ấy là thứ duy nhất còn thuộc về riêng nàng. Trong một đời bị sắp đặt, được buồn theo ý mình cũng là một cách giữ lấy bản thân. Câu thơ của nàng vì thế vừa đau vừa kiêu hãnh.' Theo đoạn, nỗi buồn của nhân vật có ý nghĩa gì khác thường?","a":"Là cách nàng giữ lấy bản ngã của riêng mình","w":["Là dấu hiệu nàng đã hoàn toàn tuyệt vọng","Là thói quen không có ý nghĩa gì sâu xa","Là cách nàng làm cho người khác thương hại"],"e":"Gợi Tự tình của Hồ Xuân Hương: nỗi buồn là 'thứ duy nhất thuộc về riêng nàng', 'được buồn theo ý mình là giữ lấy bản thân' — buồn mà kiêu hãnh, khẳng định bản ngã phụ nữ."},{"f":"V1","p":"Đọc đoạn phân tích: 'Ngôn ngữ trong truyện thơ xưa có một sức mạnh lạ: nó vừa kể chuyện vừa hát. Người đọc thuộc lòng những câu thơ không phải vì bị bắt học. Họ thuộc vì câu thơ nói hộ lòng mình trong nhiều hoàn cảnh khác nhau. Một câu thơ hay sống được trong miệng người đời nhiều thế hệ. Đó là lúc văn chương hoá thành tiếng nói của cả dân tộc.' Theo đoạn, dấu hiệu cho thấy câu thơ đã hoá thành tiếng nói dân tộc là gì?","a":"Được truyền miệng, nói hộ lòng nhiều thế hệ","w":["Được in trong nhiều sách giáo khoa nhất","Được tác giả sáng tác trong thời gian ngắn","Chỉ người có học mới hiểu và thuộc được"],"e":"Câu thơ 'sống trong miệng người đời nhiều thế hệ', 'nói hộ lòng mình' — như Truyện Kiều đi vào ca dao, đời sống: đó là khi văn chương thành tiếng nói chung của dân tộc."},{"f":"V1","p":"Đọc đoạn văn: 'Lần đầu gặp nhau trong vườn xuân, chàng và nàng chưa nói với nhau một lời trọn vẹn. Chỉ một ánh mắt, một câu thơ trao đi đã đủ làm cả hai thao thức. Tình yêu trong văn chương xưa bắt đầu lặng lẽ như thế. Nó không ồn ào mà sâu, không vội vã mà bền. Người đọc sau này vẫn rung động vì sự khởi đầu trong trẻo ấy.' Theo đoạn, tình yêu trong văn chương xưa có đặc điểm gì?","a":"Kín đáo, trong trẻo mà sâu sắc, bền lâu","w":["Ồn ào, công khai ngay từ lần gặp đầu","Chóng tàn như những cuộc tình thoáng qua","Chỉ dựa vào vẻ đẹp bên ngoài của nhau"],"e":"Gợi Kim – Kiều gặp gỡ: chỉ 'một ánh mắt, một câu thơ' đã thao thức; đoạn khái quát tình yêu xưa kín đáo, trong trẻo mà sâu bền."},{"f":"V1","p":"Đọc đoạn phân tích: 'Có ý kiến cho rằng ca dao chỉ là lời hát của người ít học nên đơn sơ. Ý kiến ấy chưa hiểu hết ca dao. Trong mấy câu ngắn, người xưa gửi được cả một triết lí sống: thương người, trọng nghĩa, giữ lời. Ngôn ngữ dân tộc trong ca dao mộc mạc mà tinh. Nó là gốc rễ nuôi dưỡng mọi dòng văn chương viết sau này.' Theo đoạn, giá trị của ca dao nằm ở đâu?","a":"Chứa triết lí sống và ngôn ngữ dân tộc tinh hoa","w":["Đơn sơ nên ai cũng có thể sáng tác được","Chỉ có giá trị giải trí trong lúc lao động","Quan trọng vì có lịch sử lâu đời nhất"],"e":"Đoạn phản bác 'đơn sơ = ít giá trị': ca dao chứa 'triết lí sống' và ngôn ngữ 'mộc mạc mà tinh', là 'gốc rễ' của văn chương — đúng chủ điểm hồn nước trong tiếng mẹ cha."},{"f":"V2","p":"Câu thơ tự viết: 'Buồn trông con nhện chăng tơ, buồn trông nỗi nhớ cứ quấn lấy người.' Biện pháp tu từ và tác dụng của câu thơ là gì?","a":"Điệp ngữ — nỗi buồn chồng chất, quấn quýt","w":["Ẩn dụ — con nhện chăng tơ là nỗi nhớ","So sánh — nỗi nhớ giống như mạng nhện","Nhân hoá — con nhện biết buồn thay người"],"e":"'Buồn trông' lặp lại gợi điệp ngữ kiểu Kiều ở lầu Ngưng Bích, diễn tả nỗi buồn nối tiếp, chồng chất trong lòng người cô đơn."},{"f":"V2","p":"Câu thơ tự viết: 'Tiếng đàn là tiếng lòng nàng, dây đàn đứt thì lòng nàng cũng đứt theo từng khúc.' Biện pháp tu từ và tác dụng của câu thơ là gì?","a":"Ẩn dụ — tiếng đàn đồng nhất với tiếng lòng","w":["Hoán dụ — lấy dây đàn thay cho nàng Kiều","Nói quá — dây đàn đứt làm lòng đứt thật","Điệp ngữ — lặp lại hình ảnh tiếng đàn hay"],"e":"'Tiếng đàn là tiếng lòng' là ẩn dụ đồng nhất âm nhạc với nội tâm, gợi hình ảnh Kiều đánh đàn bộc lộ tâm trạng — nghệ thuật và tâm hồn hoà làm một."},{"f":"V2","p":"Câu thơ tự viết: 'Trăng khuya một mảnh, lòng người một mảnh, hai mảnh lẻ loi soi nhau qua cửa sổ.' Biện pháp tu từ và tác dụng của câu thơ là gì?","a":"Điệp ngữ và đối — trăng lẻ loi như lòng người","w":["Ẩn dụ — mặt trăng là mảnh lòng của nàng","Nhân hoá — trăng biết soi cửa sổ ngóng người","Nói giảm — làm nhẹ nỗi cô đơn ban đêm"],"e":"'Một mảnh' lặp lại cùng cấu trúc đối trăng — lòng tạo điệp và đối, gợi nỗi cô đơn của nhân vật trữ tình kiểu Tự tình: cảnh lẻ loi soi chiếu lòng lẻ loi."},{"f":"V2","p":"Câu văn: 'Câu thơ lục bát là dòng sông nhỏ của tiếng Việt, chảy êm mà chở được cả buồn vui của một dân tộc.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Ẩn dụ — thơ lục bát như dòng sông chở cảm xúc","w":["So sánh — câu thơ giống hệt dòng sông nhỏ","Nhân hoá — dòng sông biết chở buồn vui","Nói quá — câu thơ chở được cả một dân tộc"],"e":"Thể lục bát (của Truyện Kiều, Lục Vân Tiên) được ví ngầm là 'dòng sông' không qua từ so sánh — ẩn dụ, ca ngợi sức chứa cảm xúc dân tộc của thể thơ dân tộc."},{"f":"V2","p":"Câu thơ tự viết: 'Nàng nói bằng mắt, chàng đáp bằng thơ — một cuộc trò chuyện không tiếng mà ồn ào trong tim cả hai.' Biện pháp tu từ và tác dụng của câu thơ là gì?","a":"Đối lập và ẩn dụ — tình ý kín đáo mà mãnh liệt","w":["Điệp ngữ — lặp lại cấu trúc nói và đáp","Nói quá — cuộc trò chuyện ồn ào trong tim","Hoán dụ — lấy mắt và thơ thay cho hai người"],"e":"Đối lập 'không tiếng/ồn ào trong tim' cùng ẩn dụ tiếng ồn trong tim — diễn tả tình ý buổi gặp gỡ kiểu Kim – Kiều: bề ngoài lặng lẽ, bên trong xao động mạnh."}],"nv9-b4":[{"f":"V1","p":"Đọc đoạn văn: 'Người bạn sắp lên đường đi xa, chàng thi sĩ đứng trên lầu cao nhìn theo cánh buồm. Buồm càng xa, người càng nhỏ lại giữa sông nước mênh mông. Ông không khóc, chỉ đứng lặng rất lâu. Cái lặng ấy nói nhiều hơn mọi lời tiễn biệt ồn ào. Tình bạn trong thơ xưa thường sâu ở chỗ không nói hết.' Theo đoạn, cái lặng của người tiễn bạn nói lên điều gì?","a":"Tình bạn sâu nặng, khó nói thành lời","w":["Người tiễn bạn không có tình cảm gì sâu sắc","Thi sĩ không biết nói lời tiễn biệt hay","Cánh buồm đi xa quá nhanh, không kịp chào"],"e":"'Cái lặng nói nhiều hơn lời tiễn biệt ồn ào' — gợi Hoàng Hạc lâu tống Mạnh Hạo Nhiên chi Quảng Lăng của Lí Bạch: tình bạn sâu nặng thể hiện bằng lặng nhìn theo buồm xa."},{"f":"V1","p":"Đọc đoạn phân tích: 'Một bài nghị luận văn học thuyết phục không nằm ở chỗ khen tác phẩm thật nhiều. Nó nằm ở chỗ người viết chỉ ra được chi tiết nào làm nên giá trị của tác phẩm và vì sao. Mỗi nhận xét đều có câu thơ, câu văn làm chứng. Đọc xong, người đọc quay lại tác phẩm gốc với con mắt sáng hơn trước. Nghị luận văn học, hoá ra, cũng là một cách đọc văn có trách nhiệm.' Theo đoạn, bài nghị luận văn học tốt phải có yếu tố nào?","a":"Nhận xét gắn với dẫn chứng từ tác phẩm","w":["Lời khen càng nhiều càng chứng tỏ hay","Chỉ cần tóm tắt lại nội dung tác phẩm","Dùng nhiều thuật ngữ khó để gây ấn tượng"],"e":"Đoạn nhấn mạnh 'mỗi nhận xét đều có câu thơ, câu văn làm chứng' và giúp người đọc 'quay lại tác phẩm với con mắt sáng hơn' — nghị luận phải có luận điểm gắn dẫn chứng."},{"f":"V1","p":"Đọc đoạn văn: 'Bài thơ tiễn bạn chỉ có vài câu mà người đọc thấy cả một hành trình. Câu đầu là nơi chia tay, câu giữa là dòng sông mở rộng, câu cuối chỉ còn cánh buồm và ánh mắt người ở lại. Không gian cứ mở rộng dần ra. Tình cảm theo không gian ấy mà lan xa, không dứt. Đọc xong, người đọc như cũng đứng trên lầu ngắm sông.' Theo đoạn, nghệ thuật mở rộng không gian trong bài thơ có tác dụng gì?","a":"Làm tình cảm tiễn biệt lan xa, ngân dài","w":["Làm bài thơ dài hơn về số câu chữ","Giúp người đọc biết rõ địa lí dòng sông","Che giấu việc bài thơ quá ít chi tiết"],"e":"Không gian mở dần lầu — sông — buồm xa và 'tình cảm theo đó lan xa, không dứt' — nghệ thuật không gian mở (điển hình thơ tiễn biệt Lí Bạch) kéo dài dư âm tình bạn."},{"f":"V1","p":"Đọc đoạn phân tích: 'Đọc thơ Đường, đừng vội hỏi bài thơ 'nói gì' theo kiểu tóm tắt. Hãy hỏi bài thơ 'làm ta cảm thấy gì' ở từng hình ảnh. Một cánh buồm, một dòng sông, một ánh mắt nhìn theo — ý nghĩa nằm trong cách các hình ảnh ấy đứng cạnh nhau. Tóm tắt được nội dung mà không cảm được hình ảnh thì mới hiểu nửa bài thơ. Đó cũng là cách đọc mà các bài nghị luận thơ mẫu mực luôn hướng tới.' Theo đoạn, cách đọc thơ Đường đúng là gì?","a":"Cảm nhận hình ảnh và quan hệ giữa chúng","w":["Tóm tắt nội dung càng ngắn gọn càng tốt","Chỉ cần dịch đúng nghĩa từng chữ Hán","Học thuộc lòng mà không cần cảm nhận"],"e":"Đoạn khuyên hỏi 'làm ta cảm thấy gì ở từng hình ảnh' và xem 'cách hình ảnh đứng cạnh nhau' — đọc thơ Đường phải cảm nhận ngôn ngữ hình ảnh, không dừng ở tóm tắt."},{"f":"V1","p":"Đọc đoạn văn: 'Người viết trẻ gửi bài phân tích thơ của mình cho thầy. Thầy không sửa một chữ, chỉ gạch dưới những câu nhận xét không có dẫn chứng đi kèm. Bài viết từ chỗ đầy những lời khen chung chung buộc phải làm lại từ đầu. Sau lần ấy, người viết trẻ hiểu rằng cảm xúc về thơ là cần, nhưng chưa đủ. Nghị luận cần cả trái tim lẫn bằng chứng.' Bài học người viết trẻ rút ra là gì?","a":"Nghị luận cần cảm xúc đi cùng dẫn chứng","w":["Chỉ cần viết hay là bài nghị luận tốt","Lời khen chung chung được thầy đánh giá cao","Không nên bày tỏ cảm xúc khi viết nghị luận"],"e":"Thầy gạch những câu 'không có dẫn chứng'; kết luận 'cần cả trái tim lẫn bằng chứng' — bài học cốt lõi khi viết văn bản nghị luận văn học."},{"f":"V1","p":"Đọc đoạn văn: 'Có bài thơ tiễn biệt viết rất nhiều lời chúc, lời dặn. Có bài thơ chỉ viết một cánh buồm xa dần và người đứng nhìn. Bài thơ thứ hai thường ở lại lâu hơn trong lòng người đọc. Có lẽ vì nó tin vào người đọc: không nói hết, để người đọc tự lấp đầy bằng nỗi niềm chia xa của chính mình. Sự tin cậy ấy là một thứ nghệ thuật.' Theo đoạn, vì sao bài thơ ít lời lại ở lâu trong lòng người đọc?","a":"Vì để khoảng trống cho người đọc đồng cảm","w":["Vì bài thơ ngắn nên dễ học thuộc lòng","Vì lời chúc trong thơ thường không thật","Vì cánh buồm là hình ảnh hiếm gặp trong thơ"],"e":"Bài thơ 'không nói hết, để người đọc tự lấp đầy bằng nỗi niềm của mình' — nghệ thuật hàm súc của thơ Đường tiễn biệt: khoảng trống tạo đồng sáng tạo, dư âm dài."},{"f":"V2","p":"Câu thơ tự viết: 'Buồm bạn xa dần, xa dần, đến khi chỉ còn một chấm trắng giữa trời nước mênh mông.' Biện pháp tu từ và tác dụng của câu thơ là gì?","a":"Điệp ngữ — kéo dài ánh mắt tiễn bạn đi xa","w":["Nói quá — cánh buồm nhỏ bằng một chấm","Ẩn dụ — chấm trắng là tình bạn của hai người","Nhân hoá — cánh buồm biết đi xa dần dần"],"e":"'Xa dần' lặp lại tạo điệp ngữ, kéo dài thời gian và ánh mắt người ở lại dõi theo bạn — như hình ảnh buồm xa trong thơ tiễn biệt của Lí Bạch."},{"f":"V2","p":"Câu văn: 'Một bài thơ hay là một hạt giống: người viết gieo xuống trang giấy, bao thế hệ người đọc làm nó nảy mầm theo cách riêng.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Ẩn dụ — thơ sống tiếp qua mỗi thế hệ đọc","w":["So sánh — bài thơ giống như hạt giống thật","Điệp ngữ — lặp lại hình ảnh hạt giống thơ","Nói quá — một bài thơ sống được bao thế hệ"],"e":"Thơ là 'hạt giống', người đọc làm 'nảy mầm' — ẩn dụ liên hoàn về sự sống của tác phẩm qua tiếp nhận, đúng tinh thần khám phá vẻ đẹp văn chương."},{"f":"V2","p":"Câu thơ tự viết: 'Sông cứ chảy về đông như không biết có người đang đứng lặng trên lầu mà tiễn bạn.' Biện pháp tu từ và tác dụng của câu thơ là gì?","a":"Nhân hoá và đối lập — sông vô tình, người hữu tình","w":["Ẩn dụ — dòng sông là thời gian trôi nhanh","Nói giảm — làm nhẹ nỗi buồn chia tay bạn","Điệp ngữ — lặp lại hình ảnh dòng sông chảy"],"e":"Sông 'không biết' là nhân hoá theo lối phủ định, đặt đối lập dòng chảy vô tình với người đứng lặng hữu tình — làm nổi bật nỗi buồn tiễn biệt nơi lầu Hoàng Hạc."},{"f":"V2","p":"Câu văn: 'Luận điểm là xương sống của bài nghị luận, dẫn chứng là máu thịt — thiếu một trong hai, bài văn đều không đứng vững.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Ẩn dụ — bài văn như cơ thể sống cần đủ phần","w":["So sánh — bài nghị luận giống cơ thể người","Hoán dụ — lấy xương sống thay cho luận điểm","Nói quá — bài văn không đứng vững được thật"],"e":"Luận điểm là 'xương sống', dẫn chứng là 'máu thịt' — ẩn dụ hữu cơ, giúp học sinh nhớ quan hệ không thể tách rời giữa luận điểm và dẫn chứng trong văn nghị luận."},{"f":"V2","p":"Câu thơ tự viết: 'Bạn đi một bước, lòng tôi theo một bước; bạn khuất sau sông, lòng tôi vẫn chưa chịu quay về.' Biện pháp tu từ và tác dụng của câu thơ là gì?","a":"Điệp ngữ và nhân hoá — lòng quyến luyến không rời","w":["Ẩn dụ — lòng tôi là người bạn đồng hành","Nói quá — lòng theo bạn ra tận bờ sông","Đối lập — bạn đi xa, lòng tôi ở lại gần"],"e":"Cấu trúc 'bạn... lòng tôi...' lặp lại và 'lòng chưa chịu quay về' (nhân hoá) diễn tả sự quyến luyến trong tiễn biệt: thân ở lại mà lòng đi theo bạn."}],"nv9-b5":[{"f":"V1","p":"Đọc đoạn văn: 'Hai gia đình có mối thù truyền kiếp, con cái hai nhà lại yêu nhau. Đôi trẻ biết rõ tình yêu của mình bị cả hai họ cấm đoán. Họ vẫn chọn nhau, dù cái giá phải trả có thể là mạng sống. Khi cả hai cùng chết, người lớn hai nhà mới ôm nhau khóc và chôn cất mối thù. Cái chết của người trẻ trở thành lời buộc tội đanh thép nhất dành cho thù hận.' Theo đoạn, cái chết của đôi trẻ có ý nghĩa gì lớn nhất?","a":"Buộc tội thù hận và thức tỉnh hai gia đình","w":["Chứng minh tình yêu luôn dẫn tới bi kịch","Làm cho hai gia đình càng thù nhau hơn","Cho thấy đôi trẻ hành động thiếu suy nghĩ"],"e":"Như Rô-mê-ô và Giu-li-ét: đôi trẻ chết, hai họ 'mới ôm nhau khóc và chôn cất mối thù' — cái chết là lời buộc tội thù hận, mang ý nghĩa thức tỉnh nhân văn."},{"f":"V1","p":"Đọc đoạn văn: 'Chàng trai đứng giữa hai bổn phận. Một bên là danh dự gia đình bị xúc phạm, đòi chàng phải rửa nhục bằng gươm. Một bên là tình yêu với con gái của đối thủ. Thắng được kẻ thù thì mất người yêu, giữ được người yêu thì mang tiếng hèn. Chàng không tìm được đường ra nào không phải trả giá. Đó chính là lúc bi kịch bắt đầu.' Theo đoạn, bi kịch của chàng trai nằm ở đâu?","a":"Xung đột không lối thoát giữa danh dự và tình yêu","w":["Chàng trai không đủ dũng cảm để chiến đấu","Kẻ thù của gia đình chàng quá mạnh mẽ","Người yêu không thật lòng yêu chàng trai"],"e":"Như Rô-đri-gơ trong Lơ Xít: danh dự đòi rửa nhục, tình yêu đòi giữ người yêu — 'không đường ra nào không trả giá': xung đột không lối thoát là hạt nhân bi kịch cổ điển."},{"f":"V1","p":"Đọc đoạn văn: 'Dòng nước trong truyện của ông hiền hoà mà giấu một bí mật đau lòng. Người làng sống bên dòng nước bao đời, vừa ơn nó vừa sợ nó. Một đứa trẻ mất đi trong làn nước ấy khiến cả làng lặng xuống. Truyện không kết tội ai cụ thể. Nó buộc người đọc nghĩ về cách con người đối xử với nhau và với thiên nhiên khi nỗi đau đến.' Theo đoạn, truyện về làn nước gợi suy ngẫm chủ yếu về điều gì?","a":"Quan hệ giữa con người với nhau và thiên nhiên","w":["Sự nguy hiểm của sông nước với trẻ em","Kĩ thuật bơi lội an toàn cho người làng","Phong tục sinh sống ven sông của người dân"],"e":"Gợi Bí ẩn của làn nước của Bảo Ninh: truyện 'không kết tội ai', buộc suy ngẫm về cách con người đối xử với nhau và với thiên nhiên trước nỗi đau — chiều sâu nhân văn là chính."},{"f":"V1","p":"Đọc đoạn phân tích: 'Bi kịch khác truyện buồn ở chỗ nhân vật bi kịch không chỉ gặp rủi ro. Họ bị đặt vào thế phải chọn giữa hai điều đều đúng, đều thiêng liêng. Chọn bên nào cũng mất bên kia. Người xem thương họ không phải vì họ yếu. Người xem thương vì họ dám chọn và dám trả giá đến cùng.' Theo đoạn, điều làm nên chất bi kịch là gì?","a":"Phải chọn giữa hai giá trị đều thiêng liêng","w":["Nhân vật gặp nhiều rủi ro, bất hạnh dồn dập","Nhân vật chính quá yếu đuối, bất lực","Kết thúc truyện buồn và có người chết"],"e":"Đoạn phân biệt bi kịch với truyện buồn: hạt nhân là xung đột 'chọn giữa hai điều đều đúng, đều thiêng liêng' và dám trả giá — như xung đột trong Lơ Xít và Rô-mê-ô và Giu-li-ét."},{"f":"V1","p":"Đọc đoạn văn: 'Nàng uống liều thuốc giả chết để thoát khỏi cuộc hôn nhân bị ép buộc. Người yêu không biết kế hoạch ấy, tưởng nàng chết thật nên tự vẫn bên nàng. Nàng tỉnh dậy, thấy người yêu đã mất, bèn đi theo chàng. Chỉ một tin tức đến chậm một bước mà hai mạng người ra đi. Bi kịch ở đây sinh ra từ thù hận và cả từ sự chậm trễ oan nghiệt của số phận.' Theo đoạn, nguyên nhân trực tiếp dẫn tới kết cục của đôi trẻ là gì?","a":"Tin tức đến chậm khiến đôi trẻ hiểu lầm nhau","w":["Đôi trẻ không thật lòng yêu thương nhau","Gia đình hai bên đã đồng ý cho họ cưới","Nàng giả chết chỉ để thử lòng người yêu"],"e":"Kế hoạch giả chết thất bại vì 'một tin tức đến chậm một bước' — hiểu lầm chồng lên thù hận gia đình tạo kết cục bi thảm trong Rô-mê-ô và Giu-li-ét."},{"f":"V1","p":"Đọc đoạn phân tích: 'Xem xong một vở bi kịch hay, khán giả ra về trong im lặng. Họ không chỉ buồn cho nhân vật. Họ giật mình nghĩ về chính mình: về những mối thù nhỏ mình đang giữ, những lời chưa kịp nói với người thân. Bi kịch vì thế không làm con người tuyệt vọng. Nó thanh lọc cảm xúc và nhắc ta sống nhân ái hơn khi còn kịp.' Theo đoạn, tác dụng sâu xa của bi kịch với khán giả là gì?","a":"Thanh lọc cảm xúc, nhắc sống nhân ái hơn","w":["Làm khán giả tuyệt vọng về cuộc đời","Chỉ mang lại nỗi buồn thuần tuý giải trí","Dạy khán giả cách trả thù cho nhân vật"],"e":"Khán giả 'giật mình nghĩ về chính mình' và được 'thanh lọc cảm xúc' — đúng chức năng thanh lọc (catharsis) của bi kịch cổ điển: buồn mà hướng thiện."},{"f":"V2","p":"Câu văn: 'Thù hận là bức tường cao hai gia đình tự xây, và tình yêu của đôi trẻ là bông hoa mọc ở chân tường ấy.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Ẩn dụ — thù hận ngăn cách, tình yêu mong manh đẹp","w":["So sánh — tình yêu giống như bông hoa thật","Nhân hoá — bức tường biết ngăn hai gia đình","Điệp ngữ — lặp lại hình ảnh bức tường cao"],"e":"'Thù hận là bức tường', 'tình yêu là bông hoa' là ẩn dụ đối sánh, làm nổi bật bi kịch Rô-mê-ô và Giu-li-ét: cái đẹp mong manh nảy nở ngay bên ngăn cách thù hận."},{"f":"V2","p":"Câu văn: 'Danh dự gọi chàng ra trận, tình yêu gọi chàng ở lại — hai tiếng gọi cùng vang lên trong một trái tim.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Nhân hoá và đối lập — xung đột nội tâm giằng xé","w":["Điệp ngữ — lặp lại tiếng gọi của danh dự","Ẩn dụ — trái tim là chiến trường của chàng","Nói quá — hai tiếng gọi nghe thấy thật sự"],"e":"Danh dự và tình yêu 'gọi' như con người (nhân hoá) đặt đối lập ra trận — ở lại, diễn tả xung đột giằng xé trong lòng nhân vật kiểu Lơ Xít."},{"f":"V2","p":"Câu văn: 'Làn nước ấy im lặng, im lặng như đang giữ một bí mật mà cả làng không ai dám hỏi tới.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Điệp ngữ và nhân hoá — nước giấu bí mật đau lòng","w":["Ẩn dụ — làn nước là bí mật của cả làng","Nói giảm — làm nhẹ bí mật trong làn nước","So sánh — làn nước im lặng như người làng"],"e":"'Im lặng' lặp lại (điệp ngữ) và nước 'giữ bí mật' (nhân hoá) tạo không khí ám ảnh, gợi Bí ẩn của làn nước: thiên nhiên như chứng nhân câm lặng của nỗi đau."},{"f":"V2","p":"Câu văn: 'Họ yêu nhau bằng cả tuổi trẻ, và trả giá bằng cả tuổi trẻ — cái giá đắt nhất một con người có thể trả.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Điệp ngữ và nói quá — nhấn mạnh sự hy sinh trọn vẹn","w":["Ẩn dụ — tuổi trẻ là cái giá phải trả","Đối lập — yêu nhau nhiều, trả giá ít","Hoán dụ — lấy tuổi trẻ thay cho mạng sống"],"e":"Cụm 'bằng cả tuổi trẻ' lặp lại tạo điệp ngữ, kết hợp khẳng định tuyệt đối 'cái giá đắt nhất' (nói quá có chủ ý) để nhấn mạnh đôi trẻ đã dâng trọn tuổi trẻ cho tình yêu."},{"f":"V2","p":"Câu văn: 'Cái chết của đôi trẻ không khép lại câu chuyện, nó mở ra một bài học mà hai gia đình phải học bằng nước mắt.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Ẩn dụ và đối lập — cái chết thành bài học thức tỉnh","w":["Nhân hoá — cái chết biết mở ra bài học","Điệp ngữ — lặp lại hình ảnh cái chết trẻ","Nói giảm — làm nhẹ nỗi đau của hai nhà"],"e":"'Cái chết mở ra bài học' là ẩn dụ kết hợp đối lập khép lại — mở ra, khẳng định ý nghĩa thức tỉnh của kết thúc bi kịch: thù hận bị chôn cất sau cái chết của đôi trẻ."}],"nv9-b6":[{"f":"V1","p":"Đọc vụ án giả định: 'Phòng làm việc khoá từ bên trong, cửa sổ chốt chặt. Nạn nhân mất một chiếc đồng hồ vàng. Thám tử không vội kết luận ma thuật. Anh chú ý tới vệt nước nhỏ dưới cửa sổ và mẩu thuốc lá còn ấm trên bậu cửa. Từ hai chi tiết ấy, anh suy ra hung thủ đã vào bằng đường ống nước ngoài tường trước khi khoá trái cửa từ bên ngoài bằng một sợi dây.' Suy luận của thám tử dựa trên nguyên tắc nào?","a":"Mọi bí mật đều có dấu vết vật chất giải thích được","w":["Hung thủ trong phòng kín luôn dùng ma thuật","Chỉ cần hỏi nhân chứng là phá được án ngay","Chi tiết nhỏ trong phòng kín không đáng chú ý"],"e":"Vệt nước và mẩu thuốc ấm là dấu vết vật chất; thám tử kiểu Sherlock Holmes phá án bằng quan sát và suy luận logic, không cần ma thuật hay nhân chứng tình cờ."},{"f":"V1","p":"Đọc đoạn văn: 'Mọi người đều tin thủ phạm là anh hầu phòng vì chỉ anh có chìa khoá. Thám tử lại hỏi: nếu anh ta là thủ phạm, vì sao anh ta để lại dấu giày của chính mình rõ ràng ngay cửa? Hung thủ thật thường không tự tố cáo mình lộ liễu như vậy. Câu hỏi ấy làm cả phòng im lặng. Hướng điều tra từ đó rẽ sang một người chưa ai nghi ngờ.' Theo đoạn, thám tử nghi ngờ kết luận ban đầu vì lí do gì?","a":"Dấu vết quá lộ liễu, giống như bị gài sẵn","w":["Anh hầu phòng là người hiền lành, tốt bụng","Thám tử không tin vào bằng chứng dấu giày","Mọi người trong vụ án đều ghét anh hầu phòng"],"e":"Thám tử lập luận dấu giày 'quá lộ liễu, giống bị gài' — thủ pháp đánh lạc hướng kinh điển của truyện trinh thám: bằng chứng hiển nhiên nhất có thể là bẫy."},{"f":"V1","p":"Đọc đoạn văn: 'Bài hát đồng sáu xu được hát trong bữa tiệc gia đình giàu có. Ngay sau đó, một người trong nhà bị sát hại. Thám tử nhận thấy sáu người hát bài hát ấy đều có mặt trong một vụ việc cũ nhiều năm trước. Bà không hỏi ai ghét nạn nhân nhất. Bà hỏi ai là người sợ bài hát ấy được hát lại nhất.' Cách hỏi của thám tử cho thấy nguyên tắc phá án nào?","a":"Tìm động cơ ẩn sau chi tiết tưởng như vô tình","w":["Hỏi trực tiếp ai là hung thủ của vụ án","Chỉ cần đếm số người có mặt trong bữa tiệc","Bài hát nào cũng là manh mối chính của án"],"e":"Gợi truyện của A-ga-thơ Crít-xti: thám tử không hỏi bề mặt ('ai ghét nhất') mà tìm người 'sợ bài hát được hát lại' — động cơ ẩn gắn với quá khứ là chìa khoá vụ án."},{"f":"V1","p":"Đọc đoạn phân tích: 'Truyện trinh thám hay giống một ván cờ công bằng. Mọi quân cờ đều bày ra trước mắt người đọc ngay từ đầu. Chỉ có điều, người đọc nhìn mà không thấy, vì tác giả khéo che mắt bằng những chi tiết gây nhiễu. Đến hồi kết, đáp án hiện ra và người đọc thốt lên: hoá ra nó ở ngay đây từ đầu. Cảm giác ấy là phần thưởng lớn nhất của thể loại này.' Theo đoạn, điều làm truyện trinh thám công bằng và hấp dẫn là gì?","a":"Manh mối bày sẵn, đáp án bất ngờ mà hợp lí","w":["Đáp án được giấu kĩ đến mức không ai đoán được","Tác giả không đưa ra bất kì manh mối nào","Người đọc phải đọc lại nhiều lần mới hiểu"],"e":"Đoạn nhấn mạnh manh mối 'bày ra từ đầu' nhưng bị chi tiết gây nhiễu che mắt; kết thúc 'bất ngờ mà ở ngay đây' — tính công bằng logic là linh hồn truyện trinh thám."},{"f":"V1","p":"Đọc đoạn văn: 'Ba sinh viên cùng ở một dãy phòng, một bài thi bị đánh cắp trước giờ thi. Thám tử xem xét ba căn phòng. Phòng thứ nhất ngăn nắp quá mức, phòng thứ hai bừa bộn tự nhiên, phòng thứ ba có ấm trà mới pha dù chủ phòng nói mình vừa đi xa về. Thám tử mỉm cười chỉ vào ấm trà. Chi tiết nhỏ không biết nói dối như con người.' Theo đoạn, vì sao thám tử chú ý tới ấm trà?","a":"Ấm trà mới pha mâu thuẫn với lời khai đi xa","w":["Ấm trà là tang vật của vụ trộm bài thi","Chủ phòng thứ ba nổi tiếng thích uống trà","Phòng thứ ba ngăn nắp hơn hai phòng còn lại"],"e":"Gợi truyện Ba chàng sinh viên: lời khai 'vừa đi xa về' mâu thuẫn với 'ấm trà mới pha' — suy luận trinh thám dựa trên mâu thuẫn giữa lời nói và vật chứng."},{"f":"V1","p":"Đọc đoạn phân tích: 'Thám tử Việt Nam đời đầu phá án giữa một xã hội đang đổi thay. Hung thủ không chỉ là kẻ ác, đôi khi là sản phẩm của lòng tham và thời thế loạn lạc. Người viết vì thế vừa dựng vụ án gay cấn, vừa ghi lại bộ mặt xã hội đương thời. Đọc truyện của ông, ta vừa hồi hộp theo dấu hung thủ, vừa hiểu thêm một thời đã qua. Giá trị ấy khiến truyện trinh thám vượt ra ngoài khuôn khổ giải trí thuần tuý.' Theo đoạn, truyện trinh thám Việt Nam đời đầu còn có giá trị gì ngoài gây hồi hộp?","a":"Phản ánh bộ mặt xã hội của một thời kì","w":["Dạy người đọc cách trở thành thám tử thật","Chứng minh xã hội xưa không có tội phạm","Chỉ tập trung miêu tả kĩ thuật phá án mới"],"e":"Đoạn nêu tác giả (như Phạm Cao Củng) 'vừa dựng vụ án, vừa ghi lại bộ mặt xã hội đương thời' — giá trị phản ánh xã hội là điểm cộng ngoài yếu tố hồi hộp."},{"f":"V2","p":"Câu văn: 'Hiện trường không biết nói dối, hiện trường chỉ im lặng chờ một đôi mắt biết đọc nó mà thôi.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Nhân hoá — hiện trường như nhân chứng trung thực","w":["Ẩn dụ — đôi mắt biết đọc là thám tử giỏi","Điệp ngữ — lặp lại từ hiện trường hai lần","Nói quá — hiện trường nói được như con người"],"e":"Hiện trường 'không biết nói dối', 'im lặng chờ' là nhân hoá, biến hiện trường thành nhân chứng trung thực — đề cao quan sát trong phá án trinh thám."},{"f":"V2","p":"Câu văn: 'Một mẩu thuốc lá nhỏ, nhỏ đến mức trăm người đi qua không ai thấy, lại là chiếc chìa khoá mở cả vụ án.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Ẩn dụ và điệp — chi tiết nhỏ chứa giá trị lớn","w":["Nói quá — mẩu thuốc lá mở được khoá thật","Hoán dụ — lấy mẩu thuốc thay cho hung thủ","So sánh — mẩu thuốc lá giống chiếc chìa khoá"],"e":"Từ 'nhỏ' lặp lại (điệp) và mẩu thuốc 'là chiếc chìa khoá' (ẩn dụ) nhấn mạnh nguyên tắc trinh thám: chi tiết nhỏ nhất có thể là manh mối quyết định."},{"f":"V2","p":"Câu văn: 'Hung thủ xoá dấu chân, xoá dấu tay, xoá mọi thứ — trừ một thứ không xoá được: sự mâu thuẫn trong lời khai của chính mình.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Điệp ngữ — nhấn mạnh nỗ lực xoá dấu vết vô ích","w":["Ẩn dụ — lời khai là dấu vết của hung thủ","Nhân hoá — sự mâu thuẫn biết tự tố cáo mình","Nói giảm — làm nhẹ tội lỗi của hung thủ"],"e":"Động từ 'xoá' lặp ba lần tạo điệp ngữ, dồn dập cho thấy hung thủ xoá hết vật chứng mà vẫn thua ở mâu thuẫn lời khai — ca ngợi suy luận logic của thám tử."},{"f":"V2","p":"Câu văn: 'Bộ óc của thám tử là một chiếc máy ảnh lạnh lùng: nó chụp lại mọi chi tiết và không bỏ qua một góc tối nào.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Ẩn dụ — trí tuệ thám tử ghi nhận khách quan, tỉ mỉ","w":["So sánh — bộ óc giống hệt chiếc máy ảnh","Nhân hoá — máy ảnh biết chụp mọi góc tối","Điệp ngữ — lặp lại hình ảnh chiếc máy ảnh"],"e":"'Bộ óc là chiếc máy ảnh' không có từ so sánh — ẩn dụ, diễn tả khả năng quan sát khách quan, ghi nhớ chi tiết của thám tử kiểu Hôm (Holmes)."},{"f":"V2","p":"Câu văn: 'Đêm xảy ra vụ án, cả ngôi nhà ngủ say, chỉ có sự thật là thức — thức và chờ người đến gọi tên nó.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Nhân hoá — sự thật như người thức chờ được gọi","w":["Ẩn dụ — ngôi nhà ngủ say là đêm yên tĩnh","Nói quá — sự thật thức được suốt cả đêm","Điệp ngữ — lặp lại từ thức để nhấn mạnh"],"e":"'Sự thật thức, chờ người gọi tên' gán hành động con người cho khái niệm trừu tượng — nhân hoá, gợi niềm tin của truyện trinh thám: sự thật luôn tồn tại, chờ suy luận khám phá."}],"nv9-b7":[{"f":"V1","p":"Đọc đoạn văn: 'Người mẹ ru con bằng những câu hát cũ của làng. Đứa trẻ chưa hiểu hết lời ru mà đã thuộc giai điệu của tiếng mẹ đẻ. Lớn lên, đi xa đến đâu, nghe một câu hát quê nhà là lòng lại chùng xuống. Tiếng nói của một dân tộc sống trong những lời ru như thế. Nó bền hơn mọi công trình, vì nó nằm trong lòng người.' Theo đoạn, vì sao tiếng mẹ đẻ có sức sống bền lâu?","a":"Vì nó sống trong lời ru và lòng người","w":["Vì được ghi chép trong nhiều cuốn sách","Vì công trình ngôn ngữ được xây dựng lớn","Vì trẻ em bắt buộc phải học thuộc lòng"],"e":"Tiếng Việt 'sống trong lời ru', 'nằm trong lòng người' nên 'bền hơn mọi công trình' — gợi bài thơ Tiếng Việt của Lưu Quang Vũ: sức sống của ngôn ngữ nằm trong đời sống và tình cảm nhân dân."},{"f":"V1","p":"Đọc đoạn văn: 'Mưa xuân rơi nhẹ như bụi phấn trên những cành cây vừa nhú lộc. Cô gái ngồi bên khung cửa, nghe mưa mà lòng xao xuyến không rõ vì sao. Có lẽ vì mùa xuân nào cũng gợi một lời hẹn chưa nói. Mưa không buồn mà người ngắm mưa lại bâng khuâng. Cảnh xuân và lòng xuân cứ thế quấn vào nhau.' Tâm trạng của cô gái trong đoạn là gì?","a":"Bâng khuâng, xao xuyến trước mùa xuân","w":["Buồn bã, tuyệt vọng vì mưa kéo dài","Vui mừng rộn ràng như đi hội xuân","Lo lắng vì mùa xuân đến quá muộn"],"e":"Mưa xuân 'nhẹ như bụi phấn', lòng 'xao xuyến', 'bâng khuâng' vì 'lời hẹn chưa nói' — đúng không khí Mưa xuân của Nguyễn Bính: trữ tình, phấp phỏng tình xuân."},{"f":"V1","p":"Đọc đoạn văn: 'Người con xa quê nhiều năm trở về, đứng ở đầu làng mà ngỡ ngàng. Con đường đất xưa nay đã rải nhựa, mái ngói thay mái rạ. Nhưng khi nghe tiếng chào bằng giọng quê cũ, mắt anh bỗng cay. Miền quê thay đổi nhiều thứ. Chỉ có tình quê là ở lại nguyên vẹn trong giọng nói và ánh mắt người làng.' Theo đoạn, điều gì ở quê hương không thay đổi theo thời gian?","a":"Tình quê trong giọng nói và tình người","w":["Con đường đất và những mái nhà tranh","Cuộc sống của người dân làng quê xưa","Phong cảnh làng quê không hề biến đổi"],"e":"Đường, mái nhà đều đổi thay nhưng 'tình quê ở lại nguyên vẹn' — gợi Miền quê của Nguyễn Khoa Điềm: quê hương bền lâu ở tình cảm con người, không chỉ ở cảnh vật."},{"f":"V1","p":"Đọc đoạn phân tích: 'Thơ hiện đại không còn bị buộc vào niêm luật chặt như thơ xưa. Câu dài, câu ngắn theo nhịp cảm xúc mà đi. Nhưng tự do không có nghĩa là tuỳ tiện. Mỗi chỗ ngắt dòng đều là một lựa chọn của nhà thơ. Đọc thơ hiện đại, ta phải nghe bằng tai và cảm bằng nhịp, không chỉ đếm chữ.' Theo đoạn, đọc thơ hiện đại cần chú ý điều gì?","a":"Nhịp điệu cảm xúc và cách ngắt dòng của nhà thơ","w":["Chỉ cần đếm đủ số chữ trong mỗi dòng","Niêm luật chặt chẽ như thơ Đường luật","Đọc càng nhanh càng hiểu đúng ý thơ"],"e":"Đoạn nêu thơ hiện đại theo 'nhịp cảm xúc', 'mỗi chỗ ngắt dòng là một lựa chọn' — đọc phải chú ý nhịp và ngắt dòng, khác cách đọc thơ luật xưa."},{"f":"V1","p":"Đọc đoạn văn: 'Có người hỏi nhà thơ vì sao ông viết nhiều về tiếng nói quê mình đến thế. Ông đáp rằng mỗi dân tộc có một thứ không thể vay mượn: tiếng nói của tổ tiên để lại. Đất có thể mất rồi lấy lại, tiếng nói mà mất thì hồn dân tộc cũng mờ đi. Viết về tiếng Việt, với ông, là viết về điều thiêng liêng nhất. Giữ gìn tiếng nói, theo ông, là giữ gìn chính mình trước hết.' Theo đoạn, vì sao tiếng nói được coi là thiêng liêng nhất?","a":"Tiếng nói mất đi thì hồn dân tộc cũng mờ đi","w":["Tiếng nói là thứ dễ vay mượn của dân tộc khác","Mọi dân tộc đều có tiếng nói giống hệt nhau","Nhà thơ chỉ viết được về tiếng nói quê mình"],"e":"Lập luận 'đất mất có thể lấy lại, tiếng mất thì hồn mờ' — tiếng nói gắn với hồn dân tộc, nối Bài 7 với tư tưởng 'hồn nước nằm trong tiếng mẹ cha'."},{"f":"V1","p":"Đọc đoạn phân tích: 'Cùng viết về quê hương, mỗi nhà thơ chọn một lối vào khác nhau. Người vào bằng cơn mưa xuân và mối tình thôn dã. Người vào bằng giọng nói, lời ru và con đường làng. Lối vào khác nhau mà điểm đến giống nhau: lòng biết ơn với mảnh đất đã nuôi mình lớn. Quê hương trong thơ vì thế vừa riêng vừa chung.' Theo đoạn, điểm đến chung của các nhà thơ viết về quê là gì?","a":"Lòng biết ơn với đất đã nuôi mình trưởng thành","w":["Sự so sánh xem quê ai đẹp hơn trong thơ","Nỗi buồn vì quê hương thay đổi quá nhiều","Mong muốn rời quê đi tìm cuộc sống mới"],"e":"Hai lối vào mưa xuân/tình thôn dã (Nguyễn Bính) và lời ru/đường làng (Nguyễn Khoa Điềm) cùng đến 'lòng biết ơn' — điểm chung của hồn thơ về miền quê."},{"f":"V2","p":"Câu thơ tự viết: 'Tiếng Việt là tiếng mẹ ru, là tiếng cha dặn, là tiếng đất này gọi ta về mỗi lúc đi xa.' Biện pháp tu từ và tác dụng của câu thơ là gì?","a":"Điệp ngữ và ẩn dụ — tiếng Việt gắn với cội nguồn","w":["Nhân hoá — tiếng Việt biết gọi người đi xa","Liệt kê — kể các âm thanh của tiếng Việt","Nói quá — tiếng Việt gọi được người ở xa"],"e":"Cấu trúc 'là tiếng...' lặp ba lần tạo điệp ngữ kết hợp ẩn dụ, gắn tiếng Việt với mẹ, cha và đất — ca ngợi tiếng mẹ đẻ như cội nguồn thiêng liêng, như thơ Lưu Quang Vũ."},{"f":"V2","p":"Câu thơ tự viết: 'Mưa xuân mỏng như một lời thì thầm, rơi lên tóc người con gái đang chờ ai ở đầu thôn.' Biện pháp tu từ và tác dụng của câu thơ là gì?","a":"So sánh — mưa xuân nhẹ, kín đáo như lời thì thầm","w":["Ẩn dụ — mưa xuân là lời thì thầm của trời","Nhân hoá — mưa biết thì thầm với con gái","Điệp ngữ — lặp lại hình ảnh mưa xuân rơi"],"e":"'Mưa mỏng như lời thì thầm' có từ 'như' — so sánh, gợi mưa xuân Nguyễn Bính: nhẹ nhàng, kín đáo, gắn với tâm trạng chờ đợi của người con gái."},{"f":"V2","p":"Câu thơ tự viết: 'Miền quê không ở trên bản đồ, miền quê ở trong giọng nói chưa hề đổi của người mẹ già.' Biện pháp tu từ và tác dụng của câu thơ là gì?","a":"Ẩn dụ — quê hương sống trong giọng nói người mẹ","w":["Nói quá — quê hương không có trên bản đồ","Điệp ngữ — lặp lại từ miền quê hai lần","Hoán dụ — lấy giọng nói thay cho quê hương"],"e":"Khẳng định quê 'ở trong giọng nói của mẹ' là ẩn dụ về nơi cư trú của quê hương trong tâm hồn: quê hương bền lâu nhất là tiếng nói và tình mẹ, như tinh thần Miền quê."},{"f":"V2","p":"Câu thơ tự viết: 'Xuân đến không gõ cửa, xuân đến bằng một cành lộc non, một tiếng chim sớm và một lòng người chợt trẻ lại.' Biện pháp tu từ và tác dụng của câu thơ là gì?","a":"Điệp ngữ và nhân hoá — xuân đến nhẹ nhàng, hồi sinh","w":["Ẩn dụ — mùa xuân là vị khách đến thăm nhà","Liệt kê — kể các dấu hiệu của mùa xuân","Nói giảm — mùa xuân đến rất ít người biết"],"e":"'Xuân đến' lặp lại cùng xuân 'không gõ cửa' (nhân hoá) diễn tả mùa xuân đến tự nhiên, nhẹ nhàng và làm 'lòng người trẻ lại' — sức hồi sinh của xuân."},{"f":"V2","p":"Câu văn: 'Một câu ca dao cũ trong miệng bà là một dòng sông nhỏ, chảy từ đời bà sang đời cháu mà không hề cạn.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Ẩn dụ — ca dao như dòng sông truyền qua thế hệ","w":["So sánh — câu ca dao giống hệt dòng sông","Nhân hoá — dòng sông chảy từ đời này sang đời","Điệp ngữ — lặp lại hình ảnh dòng sông nhỏ"],"e":"Ca dao 'là dòng sông chảy từ đời bà sang đời cháu' là ẩn dụ dòng chảy truyền đời, ca ngợi sức sống bền bỉ của văn hoá dân gian và tiếng Việt trong gia đình."}],"nv9-b8":[{"f":"V1","p":"Đọc đoạn văn: 'Người viết đặt trước mắt độc giả một phép tính lạnh lùng: số tiền thế giới chi cho vũ khí trong một thời gian ngắn đủ để cứu sống, học hành cho hàng triệu trẻ em. Ông không kết tội một nước nào cụ thể. Ông kết tội cái thói quen coi chạy đua vũ trang là chuyện bình thường. Khi điều vô lí được coi là bình thường, đó mới là điều đáng sợ nhất. Phép tính của ông vì thế không lạnh lùng như vẻ ngoài của nó.' Theo đoạn, đối tượng bị phê phán sâu nhất là gì?","a":"Thói quen coi chạy đua vũ trang là bình thường","w":["Một quốc gia cụ thể chạy đua vũ trang","Trẻ em không được đến trường đầy đủ","Cách tính toán chi phí của người viết bài"],"e":"Như Đấu tranh cho một thế giới hoà bình của Mác-két: không kết tội riêng nước nào, mà phê phán việc nhân loại quen coi điều vô lí (chạy đua vũ trang) là bình thường."},{"f":"V1","p":"Đọc đoạn văn: 'Băng tan, biển dâng, bão mạnh lên — những tin tức ấy ngày nào cũng có trên báo. Nhưng với người dân vùng ven biển, đó không phải tin tức. Đó là mái nhà bị sóng cuốn năm ngoái, là ruộng muối mất trắng mùa này. Biến đổi khí hậu với họ là chuyện cơm áo hằng ngày. Vì thế, lời kêu gọi hành động không thể chờ đến khi mọi người đều đồng ý.' Đoạn văn muốn nhấn mạnh điều gì về biến đổi khí hậu?","a":"Nó đã là hiện thực đời sống, cần hành động ngay","w":["Nó chỉ là tin tức trên báo chí quốc tế","Chỉ người dân ven biển mới bị ảnh hưởng","Cần chờ tất cả đồng ý rồi mới hành động"],"e":"Đối lập 'tin tức' với 'mái nhà bị cuốn, ruộng mất trắng' cho thấy biến đổi khí hậu là hiện thực cấp bách — hành động không thể chờ đợi, đúng tinh thần văn bản nghị luận xã hội Bài 8."},{"f":"V1","p":"Đọc đoạn văn: 'Trong bài ca chúc Tết gửi thanh niên, nhà yêu nước già không chúc giàu sang. Ông chúc lớp trẻ có chí lớn, biết học, biết làm, biết gánh việc nước nhà. Ông coi thanh niên là rường cột của tương lai dân tộc. Lời chúc vì thế không mềm mỏng như lời chúc thường. Nó là một lời giao việc đầy tin cậy cho thế hệ sau.' Theo đoạn, lời chúc Tết dành cho thanh niên thực chất là gì?","a":"Lời giao nhiệm vụ đầy tin cậy cho thế hệ trẻ","w":["Lời chúc giàu sang, may mắn như thường lệ","Lời nhắc thanh niên chỉ nên lo học hành","Lời tâm sự riêng của một người già cô đơn"],"e":"Như Bài ca chúc Tết thanh niên của Phan Bội Châu: chúc 'chí lớn, biết gánh việc nước' — lời chúc là sự giao phó sứ mệnh cứu nước cho thanh niên, không phải chúc tụng thông thường."},{"f":"V1","p":"Đọc đoạn phân tích: 'Văn nghị luận xã hội mạnh không phải vì giọng văn đanh thép nhất. Nó mạnh vì người viết đứng về phía sự sống và lẽ phải, nói điều mà lương tri ai cũng nhận ra nhưng ít người nói thành lời. Đọc một bài như thế, người đọc có cảm giác được nói hộ. Cảm giác ấy biến bài báo thành tiếng nói chung của cả cộng đồng. Đó là lí do bài viết sống lâu hơn những bài chỉ ồn ào nhất thời.' Theo đoạn, sức mạnh của nghị luận xã hội nằm ở đâu?","a":"Nói lên tiếng nói của lương tri cộng đồng","w":["Giọng văn đanh thép, hùng hồn nhất","Người viết nổi tiếng hơn mọi nhà báo khác","Bài viết dài và có nhiều số liệu nhất"],"e":"Đoạn kết luận nghị luận mạnh vì 'đứng về phía sự sống, lẽ phải', nói hộ lương tri — đúng chủ điểm 'Tiếng nói của lương tri' của Bài 8."},{"f":"V1","p":"Đọc đoạn văn: 'Một em học sinh viết trong bài nghị luận của mình: 'Em không làm được việc lớn cho hoà bình thế giới, nhưng em có thể không bắt nạt bạn yếu hơn trong lớp.' Thầy giáo đánh dấu câu ấy và ghi bên cạnh: 'Đây mới là luận điểm sống.' Hoà bình, hoá ra, bắt đầu từ những việc rất gần. Nó bắt đầu ngay trong cách ta đối xử với người bên cạnh mỗi ngày. Bài học về hoà bình vì thế không nằm đâu xa ngoài trang vở của em.' Ý chính của đoạn là gì?","a":"Hoà bình bắt đầu từ ứng xử hằng ngày gần gũi","w":["Học sinh không thể làm gì cho hoà bình","Luận điểm trong bài văn phải thật to lớn","Bắt nạt bạn là chuyện nhỏ không đáng kể"],"e":"Từ 'không bắt nạt bạn yếu' được coi là 'luận điểm sống' — hoà bình bắt đầu từ hành vi hằng ngày, thu hẹp vấn đề lớn về hành động thiết thực của mỗi người."},{"f":"V1","p":"Đọc đoạn phân tích: 'Khi viết về hiểm hoạ chiến tranh hạt nhân, người viết không miêu tả cảnh nổ bom ghê rợn. Ông chỉ hỏi một câu giản dị: nếu mọi thứ bị huỷ diệt, ai sẽ là người đọc sử, ai sẽ ngắm tranh, ai sẽ nghe nhạc? Câu hỏi ấy làm người đọc lạnh người hơn mọi miêu tả. Vì nó chạm vào điều quý nhất: sự tiếp nối của văn hoá và con người. Cách viết ấy cho thấy nghị luận xã hội chạm vào người đọc bằng tư tưởng, không bằng la hét.' Theo đoạn, vì sao câu hỏi giản dị lại gây ấn tượng mạnh?","a":"Vì nó chạm tới sự tiếp nối văn hoá nhân loại","w":["Vì miêu tả cảnh nổ bom không đáng sợ","Vì người đọc thích trả lời câu hỏi khó","Vì câu hỏi ngắn nên dễ ghi nhớ hơn cả"],"e":"Như cách lập luận của Mác-két: câu hỏi 'ai sẽ đọc sử, ngắm tranh, nghe nhạc' chạm vào sự tiếp nối văn hoá — giá trị bị huỷ diệt nếu chiến tranh hạt nhân xảy ra, nên gây lạnh người hơn miêu tả trực tiếp."},{"f":"V2","p":"Câu văn: 'Chạy đua vũ trang là cuộc chạy mà đích đến là vực thẳm, kẻ về nhất cũng là kẻ rơi xuống trước.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Ẩn dụ nghịch lí — chạy đua vũ trang tự huỷ diệt","w":["So sánh — cuộc chạy đua giống vực thẳm sâu","Nói quá — kẻ về nhất rơi xuống vực thật","Điệp ngữ — lặp lại hình ảnh cuộc chạy đua"],"e":"'Cuộc chạy đích là vực thẳm' là ẩn dụ nghịch lí: thắng trong chạy đua vũ trang cũng là tự huỷ diệt — lập luận hình tượng chống chiến tranh, như tinh thần Mác-két."},{"f":"V2","p":"Câu văn: 'Hoà bình không phải là món quà trời cho, hoà bình là cái cây con người phải trồng và giữ mỗi ngày.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Điệp ngữ và ẩn dụ — hoà bình cần vun trồng hằng ngày","w":["Nhân hoá — hoà bình là cái cây biết lớn lên","Nói giảm — làm nhẹ trách nhiệm giữ hoà bình","Câu hỏi tu từ — hỏi về nguồn gốc hoà bình"],"e":"'Hoà bình' lặp lại (điệp ngữ) và được ví ngầm là 'cái cây phải trồng và giữ' (ẩn dụ) — nhấn mạnh hoà bình là thành quả phải chủ động vun đắp, không tự nhiên mà có."},{"f":"V2","p":"Câu văn: 'Trái Đất nóng lên một độ, biển dâng lên một gang, và tương lai của những đứa trẻ ven biển lùi lại một bước dài.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Điệp cấu trúc tăng tiến — hệ quả khí hậu dồn dập","w":["Ẩn dụ — tương lai của trẻ em biết lùi bước","Nhân hoá — Trái Đất biết nóng lên từng độ","Nói quá — biển dâng một gang là quá lớn"],"e":"Ba vế cùng cấu trúc với mức độ tăng dần (một độ — một gang — một bước dài) tạo điệp cấu trúc tăng tiến, nhấn mạnh hệ quả dây chuyền của biến đổi khí hậu lên thế hệ trẻ."},{"f":"V2","p":"Câu văn: 'Thanh niên là tờ giấy trắng của một thời đại ư? Không, thanh niên là ngòi bút viết nên thời đại của chính mình.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Ẩn dụ và phủ định — thanh niên chủ động viết lịch sử","w":["So sánh — thanh niên giống như ngòi bút thật","Điệp ngữ — lặp lại từ thanh niên hai lần","Nói quá — thanh niên viết được cả thời đại"],"e":"Phủ định ẩn dụ 'tờ giấy trắng' (bị động) để thay bằng 'ngòi bút' (chủ động) — khẳng định vai trò chủ thể của thanh niên, như kì vọng của Phan Bội Châu."},{"f":"V2","p":"Câu văn: 'Một quả bom có thể xoá một thành phố trong phút chốc, nhưng không một quả bom nào xoá được khát vọng sống của con người.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Đối lập và nói quá — khát vọng sống bất diệt","w":["Ẩn dụ — quả bom là sức mạnh huỷ diệt lớn","Điệp ngữ — lặp lại hình ảnh quả bom nổ","Nhân hoá — khát vọng sống biết chống bom đạn"],"e":"Đối lập 'xoá thành phố' với 'không xoá được khát vọng sống' cùng khẳng định tuyệt đối (nói quá có chủ ý) tôn vinh sức sống và khát vọng hoà bình của nhân loại."}],"nv9-b9":[{"f":"V1","p":"Đọc đoạn văn: 'Đường lên núi thiêng dài và dốc, người đi lễ phải dừng nghỉ nhiều lần. Nhưng không ai than mệt thành lời. Càng lên cao, tiếng nói chuyện càng nhỏ lại, bước chân càng chậm lại. Có lẽ khung cảnh trầm mặc của núi rừng tự nó dạy con người sự lặng im. Xuống núi, nhiều người nói họ mang về một thứ không nhìn thấy được: sự yên tĩnh trong lòng.' Theo đoạn, điều quý nhất người đi lễ mang về là gì?","a":"Sự yên tĩnh, thanh thản trong tâm hồn","w":["Những bức ảnh đẹp chụp trên đỉnh núi","Sức khoẻ tốt hơn nhờ leo núi vận động","Đặc sản mua được ở chân núi thiêng"],"e":"Đoạn kết: mang về 'thứ không nhìn thấy được: sự yên tĩnh trong lòng' — như Yên Tử, núi thiêng: giá trị chuyến đi là trải nghiệm tâm linh, thanh thản, không phải vật chất."},{"f":"V1","p":"Đọc đoạn văn: 'Người chơi cây cảnh bảo rằng chăm một cây bonsai là học cách kiên nhẫn. Cây không lớn theo ý muốn của người, người phải học theo nhịp của cây. Một dáng cây đẹp hôm nay là kết quả của mười năm uốn nắn từng chút. Ai vội vàng đều làm hỏng cây. Cây cảnh vì thế dạy người ta bài học sống chậm giữa một thời đại vội vàng.' Theo đoạn, văn hoá cây cảnh dạy con người điều gì?","a":"Kiên nhẫn, sống chậm và thuận theo tự nhiên","w":["Cách uốn cây nhanh nhất để bán được giá","Kĩ thuật trồng cây hiện đại, năng suất cao","Sự giàu sang của người sở hữu cây quý"],"e":"'Cây không lớn theo ý người, người học theo nhịp cây', 'mười năm uốn nắn' — như Văn hoá hoa – cây cảnh: cây cảnh là bài học kiên nhẫn và sống chậm, không chỉ là thú chơi hay kinh tế."},{"f":"V1","p":"Đọc đoạn văn: 'Chuyến đi của lớp em tới một di tích xưa không bắt đầu bằng việc chụp ảnh. Thầy dặn cả lớp đứng lặng một phút trước cổng di tích. Một phút ấy làm thay đổi cả chuyến đi. Mọi người bước vào với tâm thế khác: chậm hơn, kính cẩn hơn. Suy ngẫm hoá ra bắt đầu trước cả khi ta đọc dòng chữ giới thiệu đầu tiên.' Theo đoạn, một phút đứng lặng có tác dụng gì?","a":"Tạo tâm thế trân trọng trước khi tham quan","w":["Giúp học sinh nghỉ mệt sau quãng đường xa","Là nghi thức bắt buộc của mọi di tích","Làm chuyến đi thêm phần trang trọng hình thức"],"e":"Một phút lặng làm mọi người 'chậm hơn, kính cẩn hơn' — đúng tinh thần 'Đi và suy ngẫm': du lịch văn hoá bắt đầu bằng thái độ trân trọng, suy ngẫm chứ không phải chụp ảnh vội vàng."},{"f":"V1","p":"Đọc đoạn phân tích: 'Văn bản du kí hay không đo bằng số địa danh người viết đã đi qua. Nó đo bằng độ sâu của cái nhìn. Cùng một ngọn núi, người đi vội chỉ thấy đá và cây. Người đi chậm thấy cả lịch sử, tín ngưỡng và số phận con người gắn với ngọn núi ấy. Du kí vì thế là hành trình của đôi chân và cũng là hành trình của suy nghĩ.' Theo đoạn, giá trị của du kí nằm ở đâu?","a":"Độ sâu cái nhìn, suy ngẫm về nơi đã đến","w":["Số địa danh được nhắc đến trong bài viết","Tốc độ di chuyển của người viết du kí","Độ dài của hành trình qua nhiều vùng đất"],"e":"Đoạn đối lập 'đi vội chỉ thấy đá cây' với 'đi chậm thấy lịch sử, tín ngưỡng, số phận con người' — du kí giá trị ở suy ngẫm, đúng tên Bài 9: Đi và suy ngẫm."},{"f":"V1","p":"Đọc đoạn văn: 'Hoa đào nở ở miền Bắc báo hiệu Tết, hoa mai vàng rực ở miền Nam cũng báo hiệu Tết. Hai loài hoa, hai miền đất, cùng một niềm mong đợi đoàn viên. Người Việt ngắm hoa ngày Tết không chỉ ngắm vẻ đẹp. Họ ngắm cả một năm đã qua và một năm sắp đến trong đó. Hoa vì thế là một phần của đời sống tinh thần, không phải vật trang trí đơn thuần.' Theo đoạn, hoa ngày Tết với người Việt có ý nghĩa gì?","a":"Gắn với đoàn viên và suy ngẫm về thời gian","w":["Chỉ để trang trí nhà cửa cho đẹp mắt","Chỉ nở ở một miền nhất định của đất nước","Là dấu hiệu báo mùa xuân về theo tự nhiên"],"e":"Đào — mai hai miền cùng gợi 'đoàn viên' và nhìn lại một năm — như Văn hoá hoa – cây cảnh: hoa là đời sống tinh thần và văn hoá, vượt qua chức năng trang trí."},{"f":"V1","p":"Đọc đoạn văn: 'Đứng trước dòng sông quê hương, nhà thơ chợt lặng người. Sông vẫn chảy như thời ông còn là cậu bé tắm sông mỗi chiều. Bao người thân đã đi xa, bao biến đổi đã qua, chỉ dòng sông là chứng nhân còn ở lại. Tình sông núi trong thơ ông vì thế không ồn ào. Nó là nỗi niềm của người biết ơn dòng nước đã nuôi lớn cả một đời người.' Theo đoạn, dòng sông trong đoạn là chứng nhân của điều gì?","a":"Thời gian, biến đổi và đời người gắn với quê hương","w":["Những trận lũ lớn trong lịch sử vùng quê","Hoạt động tắm sông của trẻ em nông thôn","Sự thay đổi dòng chảy qua các mùa trong năm"],"e":"Sông 'vẫn chảy' trong khi người thân đi xa, biến đổi đã qua — sông là chứng nhân thời gian và đời người, gợi Tình sông núi: tình quê lặng lẽ, biết ơn."},{"f":"V2","p":"Câu văn: 'Núi không nói một lời, mà ai lên núi cũng nghe được một bài học về sự tĩnh lặng.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Nhân hoá và đối lập — núi dạy bài học không lời","w":["Ẩn dụ — bài học về tĩnh lặng là núi thiêng","Nói quá — núi dạy được bài học cho mọi người","Điệp ngữ — lặp lại từ núi để nhấn mạnh"],"e":"Núi 'không nói' mà 'dạy bài học' là nhân hoá kết hợp đối lập, gợi Yên Tử: thiên nhiên trầm mặc tự nó giáo dục tâm hồn con người."},{"f":"V2","p":"Câu văn: 'Một cây cảnh nhỏ trên bàn là một khu rừng thu gọn, một đời người thu gọn, một bài học kiên nhẫn thu gọn.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Điệp ngữ — cây nhỏ chứa nhiều giá trị lớn","w":["Ẩn dụ — cây cảnh là khu rừng và đời người","Liệt kê — kể các thứ thu gọn trong cây cảnh","Nói giảm — thu hẹp giá trị của cây cảnh nhỏ"],"e":"Cụm 'một... thu gọn' lặp ba lần tạo điệp ngữ, nhấn mạnh nghịch lí cây nhỏ chứa giá trị lớn về thiên nhiên, đời người và kiên nhẫn — đúng tinh thần văn hoá cây cảnh."},{"f":"V2","p":"Câu thơ tự viết: 'Sông ôm làng vào lòng như mẹ ôm con, núi che làng khỏi gió như cha đứng ở đầu sân.' Biện pháp tu từ và tác dụng của câu thơ là gì?","a":"So sánh và nhân hoá — sông núi như cha mẹ nuôi làng","w":["Ẩn dụ — sông núi là cha mẹ của dân làng","Điệp ngữ — lặp lại cấu trúc sông núi ôm che","Nói quá — sông núi bảo vệ được cả làng quê"],"e":"'Sông ôm như mẹ, núi che như cha' có từ so sánh 'như' kết hợp nhân hoá, biến sông núi thành cha mẹ — diễn tả tình sông núi gắn bó, nuôi dưỡng con người."},{"f":"V2","p":"Câu văn: 'Đi một chuyến đi, về mang theo một đôi mắt mới — đó là chuyến đi đáng giá nhất của người ham học hỏi.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Ẩn dụ — đôi mắt mới chỉ cái nhìn trưởng thành","w":["Nói quá — đi một chuyến thay được đôi mắt","Nhân hoá — đôi mắt mới biết ham học hỏi","Hoán dụ — lấy đôi mắt thay cho người đi"],"e":"'Đôi mắt mới' là ẩn dụ cho cái nhìn và nhận thức trưởng thành sau chuyến đi — kết tinh tinh thần 'Đi và suy ngẫm': đi để đổi thay cách nhìn đời."},{"f":"V2","p":"Câu văn: 'Hoa nở rồi hoa tàn, hoa tàn rồi hoa lại nở — vòng hoa ấy nhắc người ta rằng mọi buồn vui đều có mùa của nó.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Điệp ngữ — vòng tuần hoàn của hoa và đời người","w":["Ẩn dụ — hoa là buồn vui của đời người","Nhân hoá — hoa biết nhắc nhở con người","Câu hỏi tu từ — hỏi về vòng đời của hoa"],"e":"Chuỗi 'hoa nở — hoa tàn — hoa lại nở' lặp cấu trúc tạo điệp ngữ, gợi vòng tuần hoàn tự nhiên và triết lí đời người trong văn hoá hoa: buồn vui đều theo mùa mà qua đi, lại đến."}],"nv9-b10":[{"f":"V1","p":"Đọc đoạn văn: 'Cuối năm học, em mở lại cuốn sổ tay đọc sách của mình. Những trang đầu ghi chép vụng về, chỉ chép lại cốt truyện. Càng về sau, em càng ghi nhiều câu hỏi và cảm xúc của riêng mình. Cuốn sổ vì thế không chỉ ghi lại sách. Nó ghi lại chính em — một người đọc đã lớn lên qua từng cuốn sách trong suốt một năm.' Theo đoạn, cuốn sổ tay đọc sách có giá trị gì lớn nhất?","a":"Ghi lại hành trình trưởng thành của người đọc","w":["Ghi lại đầy đủ cốt truyện các cuốn sách","Giúp em nhớ mọi chi tiết để làm bài kiểm tra","Chứng minh em đã đọc được nhiều sách nhất lớp"],"e":"Sổ từ 'chép cốt truyện' tiến tới 'ghi câu hỏi và cảm xúc riêng' — như Sổ tay đọc sách ở Bài 10: giá trị lớn nhất là ghi lại sự trưởng thành của người đọc."},{"f":"V1","p":"Đọc đoạn phân tích: 'Nói văn học là lịch sử tâm hồn không có nghĩa là văn học thay được sách sử. Sách sử ghi việc đã xảy ra, văn học ghi con người đã cảm thấy thế nào khi việc ấy xảy ra. Thiếu sách sử, ta không biết quá khứ. Thiếu văn học, ta biết quá khứ mà không hiểu con người của quá khứ. Hai thứ bổ sung cho nhau để quá khứ trở nên trọn vẹn.' Theo đoạn, văn học bổ sung cho sách sử điều gì?","a":"Cho hiểu cảm xúc, tâm hồn con người quá khứ","w":["Thay thế hoàn toàn sách sử trong học tập","Ghi lại chính xác mọi sự kiện đã xảy ra","Làm cho việc học lịch sử trở nên dễ dàng hơn"],"e":"Đoạn phân biệt sử 'ghi việc xảy ra' với văn học 'ghi con người cảm thấy thế nào' — văn học bổ sung chiều sâu tâm hồn, đúng quan niệm 'văn học là lịch sử tâm hồn'."},{"f":"V1","p":"Đọc đoạn văn: 'Một bạn học sinh chia sẻ cuốn sách yêu thích trước lớp. Ban đầu bạn nói run, chỉ kể lại nội dung. Nhưng khi kể tới đoạn nhân vật làm bạn khóc, giọng bạn chợt chắc lại. Cả lớp lặng nghe. Hoá ra, giới thiệu một cuốn sách hay nhất là lúc người nói dám chia sẻ cảm xúc thật của mình về sách. Cảm xúc thật có sức lây lan hơn mọi lời quảng cáo.' Theo đoạn, yếu tố giúp phần giới thiệu sách thành công là gì?","a":"Chia sẻ cảm xúc thật của người đọc về sách","w":["Kể lại nội dung sách thật đầy đủ, chi tiết","Nói nhanh và trôi chảy không vấp một chữ","Quảng cáo cuốn sách bằng nhiều lời hay nhất"],"e":"Giọng 'chắc lại' khi kể đoạn làm mình khóc và cả lớp lặng nghe — giới thiệu sách (hoạt động Về đích Bài 10) thành công nhờ cảm xúc thật, không phải tóm tắt đầy đủ."},{"f":"V1","p":"Đọc đoạn văn: 'Hành trình ba năm học văn của em khép lại bằng một nhận xét giản dị của thầy: 'Các em đã đi từ chỗ hỏi truyện này nói gì, tới chỗ hỏi truyện này làm em nghĩ gì về cuộc sống.' Hai câu hỏi chỉ khác nhau vài chữ. Nhưng khoảng cách giữa chúng là cả một sự trưởng thành trong cách đọc. Đó là món quà lớn nhất mà môn Văn để lại cho mỗi người. Em ghi lại câu nói của thầy vào trang cuối cuốn sổ tay đọc sách của mình.' Theo đoạn, sự trưởng thành trong cách đọc thể hiện ở đâu?","a":"Từ hiểu nội dung sang liên hệ, suy ngẫm về cuộc sống","w":["Từ đọc ít sách sang đọc được nhiều sách hơn","Từ đọc truyện sang chỉ đọc thơ trữ tình","Từ hỏi nhiều câu sang không cần hỏi câu nào"],"e":"Chuyển từ 'truyện nói gì' sang 'truyện làm em nghĩ gì về cuộc sống' — trưởng thành đọc văn là biết liên hệ tác phẩm với đời sống, đúng mục tiêu tổng kết của Bài 10."},{"f":"V1","p":"Đọc đoạn phân tích: 'Nhiều người rời trường phổ thông là rời luôn sách văn học. Nhưng cũng có người mang theo một vài câu thơ suốt đời, lúc vui thì nhớ, lúc buồn thì dựa vào. Khác biệt không nằm ở trí nhớ. Nó nằm ở việc thời đi học, họ có từng được một tác phẩm chạm vào thật sự hay không. Một lần chạm thật đáng giá hơn trăm lần đọc đối phó.' Theo đoạn, điều quyết định việc một người gắn bó lâu dài với văn học là gì?","a":"Từng có tác phẩm thật sự chạm tới cảm xúc mình","w":["Có trí nhớ tốt để thuộc nhiều câu thơ hay","Đọc được đủ trăm cuốn sách khi còn đi học","Học giỏi môn Văn nhất trong suốt thời đi học"],"e":"Đoạn khẳng định khác biệt 'không nằm ở trí nhớ' mà ở 'một lần được tác phẩm chạm vào thật sự' — gắn bó với văn học nhờ trải nghiệm cảm xúc thật, hợp chủ điểm văn học — lịch sử tâm hồn."},{"f":"V1","p":"Đọc đoạn văn: 'Nhìn lại các tác phẩm đã học, em thấy mỗi thời kì để lại một giọng điệu riêng. Văn học trung đại trầm và trang trọng, văn học hiện đại gần gũi và đa thanh hơn. Nhưng xuyên qua các thời kì là một sợi dây không đứt: nỗi niềm của con người Việt trước cuộc đời. Hiểu sợi dây ấy là hiểu vì sao văn học được gọi là lịch sử tâm hồn của dân tộc.' Theo đoạn, 'sợi dây không đứt' xuyên qua văn học các thời kì là gì?","a":"Nỗi niềm của con người Việt trước cuộc đời","w":["Giọng điệu trang trọng của văn học cổ","Số lượng tác phẩm được sáng tác mỗi thời kì","Ngôn ngữ viết giống nhau qua mọi thời kì"],"e":"Các thời kì khác giọng điệu nhưng cùng chung 'nỗi niềm con người Việt trước cuộc đời' — sợi dây ấy làm văn học thành lịch sử tâm hồn dân tộc qua thời gian."},{"f":"V2","p":"Câu văn: 'Văn học là tấm gương soi không phải khuôn mặt, mà là tâm hồn của cả một dân tộc qua nhiều thế kỉ.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Ẩn dụ — văn học phản chiếu tâm hồn dân tộc","w":["So sánh — văn học giống như tấm gương soi","Nhân hoá — văn học biết soi tâm hồn người","Nói quá — văn học soi được nhiều thế kỉ"],"e":"'Văn học là tấm gương soi tâm hồn' là ẩn dụ cốt lõi của Bài 10, khẳng định văn học phản chiếu đời sống tinh thần dân tộc qua thời gian."},{"f":"V2","p":"Câu văn: 'Một cuốn sổ tay đọc sách nhỏ là một khu vườn, mỗi trang ghi chép là một hạt giống suy nghĩ chờ nảy mầm.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Ẩn dụ — ghi chép đọc sách như gieo hạt tư duy","w":["Điệp ngữ — lặp lại hình ảnh khu vườn nhỏ","Nói giảm — làm nhẹ giá trị của việc ghi chép","Hoán dụ — lấy hạt giống thay cho cuốn sách"],"e":"Sổ tay là 'khu vườn', ghi chép là 'hạt giống chờ nảy mầm' — ẩn dụ liên hoàn, đề cao việc ghi chép khi đọc: suy nghĩ được gieo và sẽ lớn lên theo thời gian."},{"f":"V2","p":"Câu văn: 'Câu thơ cũ đọc lại sau mười năm không còn là câu thơ cũ, vì người đọc đã không còn là người đọc của mười năm trước.' Biện pháp tu từ và tác dụng của câu văn là ý gì?","a":"Điệp ngữ và đối lập — ý nghĩa thơ đổi theo người đọc","w":["Ẩn dụ — câu thơ cũ là người đọc năm xưa","Nói quá — câu thơ thay đổi sau mười năm thật","Nhân hoá — câu thơ biết thay đổi theo năm tháng"],"e":"Cấu trúc lặp 'không còn là... của mười năm trước' cùng đối lập thơ — người đọc diễn tả chân lí tiếp nhận văn học: tác phẩm bất biến nhưng ý nghĩa đổi theo trải nghiệm người đọc."},{"f":"V2","p":"Câu văn: 'Sách đóng lại, bài học mở ra; trang cuối khép, hành trình của người đọc lại bắt đầu.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"Đối lập và điệp cấu trúc — đọc kết thúc mà mở đầu","w":["Ẩn dụ — trang cuối là cánh cửa hành trình","Nói quá — hành trình bắt đầu từ trang cuối sách","Câu đặc biệt — gây bất ngờ ở cuối câu văn"],"e":"Hai cặp đối lập đóng/mở, khép/bắt đầu trong cấu trúc song song tạo điệp và đối, khẳng định đọc sách không kết thúc ở trang cuối mà mở ra hành trình suy ngẫm mới."},{"f":"V2","p":"Câu văn: 'Tiếng Việt trong câu đơn thì gọn gàng như một nhịp trống, sang câu ghép thì ngân vang như một dàn nhạc nhiều bè.' Biện pháp tu từ và tác dụng của câu văn là gì?","a":"So sánh — câu đơn gọn, câu ghép phong phú nhiều bè","w":["Ẩn dụ — câu đơn là nhịp trống của tiếng Việt","Điệp ngữ — lặp lại hình ảnh tiếng Việt ngân vang","Nhân hoá — tiếng Việt biết ngân vang như nhạc"],"e":"Hai vế đều có từ 'như' (gọn như nhịp trống, ngân như dàn nhạc) — so sánh, giúp phân biệt trực quan câu đơn và câu ghép: gọn gàng đơn tuyến với phong phú đa tuyến, đúng mạch ôn tập câu của Bài 10."}]});
/* ĐỢT 3 V24 — bank nâng cao thật viết tay theo cụm chương, dữ kiện mới,
   đã duyệt tay theo chương (luật Q5) trước khi nạp — biên bản: kiem-chung-v24/sau-dot3/DUYET-*. */
window.__ADV3BANKS24 = Object.assign(window.__ADV3BANKS24 || {}, {"g9-u1":[{"f":"A1","p":"In Van Lam village, old Mrs Huong has made embroidery for forty years. Young people in the neighbourhood used to leave for city jobs, so few learners stayed in her workshop. Last year, she opened a free Saturday class, and twelve teenagers joined. Now their silk scarves are sold at the craft fair. Why did Mrs Huong open the free class?","a":"To keep the craft alive with young learners.","w":["To sell her house in the village.","To learn how to make pottery.","To close her workshop on Saturdays."],"e":"Ít người trẻ ở lại học nghề, lớp miễn phí giúp truyền nghề cho thanh thiếu niên."},{"f":"A1","p":"Mr Tuan runs a small pottery workshop near the river. Visitors often ask why his vases feel heavier than factory vases. He explains that each vase is made by hand and dried slowly in the sun. Nothing is rushed, so the clay becomes strong. In the passage, 'by hand' means ___.","a":"made manually, not by machines","w":["made very quickly in a factory","made only in the morning sun","made from river water only"],"e":"Bình làm thủ công, phơi chậm nên khác đồ nhà máy — by hand là làm bằng tay."},{"f":"A1","p":"Every Sunday morning, volunteers in Hoa's neighbourhood look after the small park. They collect litter, water the flowers and repair the broken bench. Elderly people can then sit safely and children have a clean place to play. The head of the group says a clean park brings neighbours closer together. What is the main idea of the passage?","a":"Neighbours work together to care for their park.","w":["Elderly people repair benches alone.","Children play in the park on Sundays.","Volunteers sell flowers in the park."],"e":"Ý chính: hàng xóm cùng chăm sóc công viên của khu dân cư."},{"f":"A1","p":"Lan has visited a conical hat workshop in Hue twice. She has watched artisans shape palm leaves over a wooden frame. The hats look simple, but one hat takes almost a whole day to finish. Lan now understands why her grandmother told her to preserve the craft carefully. What can we infer about conical hat making?","a":"It is slow work that needs great patience.","w":["It can be finished in a few minutes.","It is done only by machines today.","It uses silk instead of palm leaves."],"e":"Một chiếc nón mất gần một ngày — công việc chậm, cần kiên nhẫn."},{"f":"A1","p":"When the lantern festival was cancelled because of rain, Linh felt disappointed at first. She had spent two weeks painting a lantern with her classmates. Later, their teacher displayed all the lanterns inside the community hall instead. Linh smiled when visitors praised her work. How did Linh's feelings change?","a":"From disappointed to pleased and proud.","w":["From proud to angry with visitors.","From excited to too tired to smile.","From nervous to afraid of the rain."],"e":"Ban đầu thất vọng vì hủy lễ hội, sau vui và tự hào khi đèn được trưng bày."},{"f":"A1","p":"A new community library has just been built in Nam's neighbourhood. It was funded by local families and former students who now work in the city. Students can borrow books for free, and retired teachers help them with homework there. If more books are donated, the library will open on Sundays too. Why was the library built with local support?","a":"Local people wanted a free place to learn.","w":["City workers needed a new office.","Retired teachers wanted to sell books.","Students refused to do homework at home."],"e":"Thư viện do người dân góp xây để có nơi học miễn phí cho học sinh."},{"f":"A2","p":"Visitor: Excuse me, where can I buy silk scarves here? Lan: At Mrs Huong's workshop, over there. Visitor: Thank you. Could you show me the way? — What does Lan answer?","a":"Of course. Follow me, it's just two minutes away.","w":["Scarves are made of silk.","I bought mine last year.","The workshop opens at eight."],"e":"Hỏi nhờ chỉ đường nên đáp đồng ý dẫn đường."},{"f":"A2","p":"Tourist: How long does it take to make this lantern? Artisan: About three days. Tourist: That's a long time! Why does it take so long? — What does the artisan answer?","a":"Because every step is done carefully by hand.","w":["It costs two hundred thousand dong.","I learnt it from my mother.","Visitors love colourful lanterns."],"e":"Hỏi vì sao lâu phải đáp lý do: làm thủ công cẩn thận từng bước."},{"f":"A2","p":"Mai: I don't know what to give my teacher as a souvenir. Hung: What about a small pottery vase from our village? Mai: Good idea. Where is it sold? — What does Hung answer?","a":"At the handicraft shop near the gate.","w":["It was made by Mr Tuan.","She likes flowers very much.","Last Sunday at the fair."],"e":"Hỏi nơi bán phải đáp địa điểm bán."},{"f":"A2","p":"Student: Excuse me, who should I contact to join the clean-up? Teacher: Mr Binh, the neighbourhood head. Student: Thank you. How can I contact him? — What does the teacher answer?","a":"You can meet him at the community hall tonight.","w":["He has worked here for years.","The clean-up starts on Sunday.","Volunteers wear green shirts."],"e":"Hỏi cách liên hệ phải đáp cách/nơi gặp người phụ trách."}],"g9-u2":[{"f":"A1","p":"Since a new metro line opened, fewer residents in Linh's district drive downtown. Trains run every eight minutes, so people no longer wait long at the station. The streets near her school, which used to be crowded all day, are now quieter in the morning. Linh says city life has become more convenient. Why are the streets quieter now?","a":"More people travel by metro instead of cars.","w":["The school has moved to the suburb.","Trains stop running in the morning.","Residents leave the city centre early."],"e":"Nhiều người đi metro thay ô tô nên đường bớt đông."},{"f":"A1","p":"Mr Khoa lives in a suburb but works downtown. Every morning, he leaves home early to avoid traffic jams on the main road. If he leaves after seven, his bus is stuck for nearly an hour. He therefore reads the news on his phone while waiting at home. In the passage, 'stuck' means ___.","a":"unable to move in traffic","w":["driving very fast downtown","waiting at home for news","reading on a mobile phone"],"e":"Xe kẹt gần một giờ khi tắc đường — stuck là không di chuyển được."},{"f":"A1","p":"Big cities offer modern facilities such as hospitals, libraries and entertainment centres. However, the air is often polluted because there are too many private vehicles. Many residents say they love the convenience but miss the peaceful life of their hometowns. City councils are trying to plant more trees and improve public transport. What is the main idea of the passage?","a":"City life is convenient but has problems too.","w":["All residents want to leave big cities.","Public transport is always polluted.","Modern facilities exist only downtown."],"e":"Ý chính: sống ở thành phố tiện lợi nhưng cũng có vấn đề như ô nhiễm."},{"f":"A1","p":"The taller the buildings in the centre get, the narrower the old streets below feel. Small shops have been replaced by shopping malls, and rents have risen quickly. An old resident told a reporter that she feels like a stranger in her own neighbourhood. She has lived there for over thirty years and knows every corner well. What can we infer about the old resident?","a":"She feels the area has changed too much.","w":["She owns a shop in the new mall.","She wants to build taller buildings.","She has just moved into the centre."],"e":"Cảm giác như người lạ nơi mình ở cho thấy khu phố thay đổi quá nhiều."},{"f":"A1","p":"If the city builds more parks, residents will have cleaner air and places to exercise. A plan has been announced to turn an empty downtown lot into a green park. Children who live in nearby skyscrapers are especially excited, because they have nowhere to play outside now. The mayor says the project will be finished next spring. Why are the children excited about the plan?","a":"They will finally have a place to play outside.","w":["Their skyscraper will become taller.","The empty lot will become a mall.","They can exercise inside their flats."],"e":"Trẻ em chung cư cao tầng chưa có chỗ chơi ngoài trời nên háo hức có công viên."},{"f":"A1","p":"Traffic in the city is becoming worse and worse during rush hour. A survey found that the average resident spends fifty minutes travelling only six kilometres. Experts suggest that companies should let staff start work at different times. If working hours are spread out, fewer vehicles will be on the road at once. What solution do the experts suggest?","a":"Letting staff start work at different times.","w":["Building more roads in the centre.","Asking residents to travel six kilometres.","Closing all companies during rush hour."],"e":"Chuyên gia đề xuất lệch giờ làm để giảm xe cùng lúc trên đường."},{"f":"A2","p":"Visitor: Excuse me, how can I get around the city centre? Receptionist: By metro or bus. It's very convenient. Visitor: Which is faster during rush hour? — What does the receptionist answer?","a":"The metro is faster. It avoids traffic jams.","w":["The centre has many skyscrapers.","Buses stop near the hotel.","Rush hour ends at eight."],"e":"Hỏi phương tiện nào nhanh hơn phải so sánh và nêu lý do tránh tắc đường."},{"f":"A2","p":"Lan: Why do you prefer living in the suburb? Minh: Because it's peaceful and the air is cleaner. Lan: Isn't it far from your office downtown? — What does Minh answer?","a":"Yes, but the train takes only twenty minutes.","w":["My office has modern facilities.","Suburbs have many residents.","I bought the house last year."],"e":"Thừa nhận xa nhưng nêu cách khắc phục: tàu chỉ mất 20 phút."},{"f":"A2","p":"Mother: You'll be late if you leave now. The road is jammed. Son: Then I'll take the metro instead. Mother: Good idea. Where is the nearest station? — What does Son answer?","a":"Just behind the supermarket, Mum.","w":["It runs every eight minutes.","I have a monthly ticket.","The metro is very modern."],"e":"Hỏi ga gần nhất ở đâu phải đáp vị trí."},{"f":"A2","p":"Tourist: Is this city always so crowded? Guide: Yes, especially downtown at weekends. Tourist: When is it quieter, then? — What does the guide answer?","a":"Early on weekday mornings, before eight.","w":["There are many entertainment centres.","Visitors love the old streets.","It has over a million residents."],"e":"Hỏi khi nào vắng hơn phải đáp thời điểm."}],"g9-u3":[{"f":"A1","p":"Hoa used to stay up late to finish homework and felt stressed every morning. Her teacher advised her to manage her time and make a priority list each evening. Now she does difficult tasks first and takes short breaks to relax. She has slept better for two months and can concentrate in class. How has Hoa changed?","a":"She manages time better and feels less stressed.","w":["She does homework only in the morning.","She has stopped taking any breaks.","She finds all her tasks difficult now."],"e":"Hoa lập danh sách ưu tiên, ngủ tốt hơn, tập trung hơn — quản lí thời gian tốt, bớt căng thẳng."},{"f":"A1","p":"Many teens skip breakfast when they have an early deadline at school. Doctors warn that without a balanced diet in the morning, students cannot concentrate for long. A small meal with bread, eggs and fruit gives the brain energy for hours. Students who eat breakfast often get better marks. Why should teens not skip breakfast?","a":"It gives them energy to concentrate at school.","w":["It helps them finish deadlines earlier.","It is the biggest meal of the day.","It makes them sleep longer at night."],"e":"Bữa sáng cân bằng cung cấp năng lượng giúp tập trung học."},{"f":"A1","p":"Tuan feels anxious before every maths test, even when he has revised carefully. His hands shake, and he forgets things he knew the night before. His counsellor told him that anxiety in small amounts is normal and taught him to breathe slowly. His teacher noticed this and talked with him after class. In the passage, 'anxious' means ___.","a":"worried and nervous","w":["tired and very sleepy","angry with the teacher","proud of good results"],"e":"Tay run, quên bài trước kì thi — anxious là lo âu, hồi hộp."},{"f":"A1","p":"Experts say teenagers should limit screen time before bed. The light from phones makes the brain stay awake, so teens fall asleep later and wake up tired. Reading a book or listening to soft music helps the body relax instead. Good sleep protects both physical and mental health. What is the main idea of the passage?","a":"Less screen time at night helps teens sleep well.","w":["Teenagers should read books all night.","Phones should be banned at school.","Mental health is more important than sleep."],"e":"Ý chính: giảm thời gian màn hình buổi tối giúp ngủ ngon."},{"f":"A1","p":"If Minh exercises regularly, he will feel stronger and less tired after school. He has joined the school running club and trains three times a week. His friends noticed that he smiles more and worries less about deadlines. His parents are pleased with the change they see in him. What can we infer about exercise for Minh?","a":"It has improved his mood and well-being.","w":["It has made his deadlines disappear.","It takes all his free time daily.","It is the only subject he likes."],"e":"Tập thể dục giúp Minh vui hơn, ít lo hơn — cải thiện tâm trạng và sức khỏe tinh thần."},{"f":"A1","p":"Lan set a small goal last month: to revise English for twenty minutes a day. At first, she often delayed the task and watched videos instead. She then put her phone in another room while studying. After three weeks, the habit became easier and her vocabulary improved. Why did putting the phone away help Lan?","a":"It removed a distraction from her study time.","w":["It gave her more videos to watch.","It made her goal much smaller.","It improved her phone battery life."],"e":"Để điện thoại phòng khác loại bỏ yếu tố gây xao nhãng khi học."},{"f":"A2","p":"Friend: You look really stressed these days. Mai: I have three deadlines this week. Friend: If you feel stressed, what should you do first? — What does Mai answer?","a":"I should make a priority list and start now.","w":["I had a test yesterday morning.","My favourite food is salad.","Deadlines are very important."],"e":"Bị căng thẳng vì hạn chót nên cần lập danh sách ưu tiên và bắt đầu làm."},{"f":"A2","p":"Doctor: How many hours do you sleep each night? Teen: Only about five hours, Doctor. Doctor: That's too little. What keeps you awake? — What does the teen answer?","a":"I use my phone in bed until midnight.","w":["I exercise every morning.","Breakfast is at six thirty.","My school starts at seven."],"e":"Hỏi điều gì làm thức khuya phải đáp thói quen dùng điện thoại trên giường."},{"f":"A2","p":"Lan: I can't concentrate in class these days. Teacher: You should sleep earlier and eat breakfast. Lan: Thank you. What if I still feel tired? — What does the teacher answer?","a":"Then you ought to see the school doctor.","w":["Breakfast is a balanced meal.","Class starts at seven fifteen.","You did well in the last test."],"e":"Hỏi nếu vẫn mệt thì sao, đáp lời khuyên đi gặp bác sĩ."},{"f":"A2","p":"Minh: Shall we play games until late tonight? Hoa: I don't think we should. We have a test tomorrow. Minh: You're right. What should we do instead? — What does Hoa answer?","a":"Let's revise together, then relax and sleep early.","w":["Games are my favourite hobby.","The test has fifty questions.","I bought a new phone case."],"e":"Trước ngày thi nên ôn bài cùng nhau rồi thư giãn, ngủ sớm."}],"g9-u4":[{"f":"A1","p":"Grandpa was telling stories about the old village while Grandma was cooking dinner. In his youth, there was no electricity, so families gathered around an oil lamp in the evening. Children listened to storytellers and helped their parents during the harvest. Grandpa says those hard days taught his generation to value simple things. What did families do in the evenings in the past?","a":"They gathered around an oil lamp together.","w":["They watched stories on television.","They cooked dinner in restaurants.","They travelled to the city at night."],"e":"Ngày xưa không có điện, gia đình quây quần quanh đèn dầu buổi tối."},{"f":"A1","p":"The ancient monument in Hoa's village has been preserved for over two hundred years. It was built by local people to worship their ancestors and remember a village hero. Every spring, a festival is held there, and young people clean the yard before it. Visitors are asked not to touch the old stone walls. Why is the monument important to villagers?","a":"It connects them to their ancestors and history.","w":["It is the tallest building in the village.","It was built only two years ago.","It is used as a school every spring."],"e":"Đền thờ tổ tiên và anh hùng làng — gắn kết dân làng với tổ tiên, lịch sử."},{"f":"A1","p":"When Mai found old photos of her mother as a schoolgirl, she kept asking questions. Her mother explained that students used to walk barefoot to school and share one textbook. Mai listened quietly and then hugged her mother. She understood how much life had improved for her generation. How did Mai probably feel after listening?","a":"Grateful for her easier life today.","w":["Bored by the old black photos.","Angry that textbooks were shared.","Afraid to walk to school barefoot."],"e":"Hiểu đời xưa khó khăn, Mai biết ơn cuộc sống dễ dàng hơn hôm nay."},{"f":"A1","p":"In the past, buffaloes were a farmer's most valuable helper in the rice fields. A strong buffalo could plough land that ten people could not finish in a day. Farmers fed their buffaloes carefully and gave them days to rest after the harvest. Children often took the buffaloes to the river in the afternoon. In the passage, 'valuable' means ___.","a":"very useful and important","w":["very old and very slow","very big and very heavy","very cheap to buy locally"],"e":"Trâu cày thay mười người, được chăm sóc kĩ — valuable là quý giá, quan trọng."},{"f":"A1","p":"Many old customs are disappearing as villages change. Young people who work far away cannot return for every traditional festival. Village elders worry that children will forget how to worship ancestors properly. They have started teaching the customs at the community house on Sundays. Why are the elders worried?","a":"Young people may forget the old customs.","w":["The community house is too small.","Festivals are held only on Sundays.","Children dislike visiting the village."],"e":"Người trẻ đi làm xa, ít dự lễ — người cao tuổi lo phong tục bị lãng quên."},{"f":"A1","p":"While people were working in the fields one summer, a sudden storm broke an old tree near the village gate. The tree had stood there for generations and appeared in many family memories. Villagers planted a new tree in the same place the next spring. They said the village gate must always have a tree, old or new. What does the new tree show about the villagers?","a":"They want to keep their tradition alive.","w":["They are afraid of summer storms.","They need shade for the rice fields.","They cut down trees every spring."],"e":"Trồng cây mới ở cổng làng cho thấy dân làng muốn giữ truyền thống."},{"f":"A2","p":"Grandson: Grandpa, what was school like in your time? Grandpa: We walked to school and shared textbooks. Grandson: Did you have electricity in class? — What does Grandpa answer?","a":"No, we studied by oil lamps on dark days.","w":["Schools had fifty students.","I was a good student then.","Textbooks were printed in Hanoi."],"e":"Hỏi có điện ở lớp không, đáp không và nêu đèn dầu thay thế."},{"f":"A2","p":"Visitor: What is this monument built for? Guide: To worship a village hero. Visitor: When was it built? — What does the guide answer?","a":"Over two hundred years ago.","w":["By the local people here.","During the spring festival.","Next to the village gate."],"e":"Hỏi when phải đáp thời gian xây dựng."},{"f":"A2","p":"Mai: I wish I had lived in Grandma's peaceful village. Hung: Why do you wish that? Mai: Because life there was simple and quiet. — What does Hung answer?","a":"I understand. City life is much noisier.","w":["The village has a festival.","Grandma tells many stories.","You were born in the city."],"e":"Đáp đồng cảm với lý do yêu làng quê yên bình, đối chiếu phố ồn ào."},{"f":"A2","p":"Teacher: Why should we preserve our heritage? Student: To remember our past and teach the young. Teacher: Can you give an example? — What does the student answer?","a":"We should protect old monuments and festivals.","w":["Heritage is very ancient.","My village is very beautiful.","Festivals are held in spring."],"e":"Hỏi ví dụ bảo tồn di sản phải nêu việc cụ thể: bảo vệ di tích, lễ hội."}],"g9-u5":[{"f":"A1","p":"Lan has just returned from a camping trip in the mountains, and she calls it unforgettable. On the first night, her group got lost for an hour because their map was wet. A local guide found them and led them back safely. Lan says the scary moment made the warm campfire afterwards feel even more special. Why does Lan call the trip unforgettable?","a":"Both the danger and the rescue were memorable.","w":["The map was bought in the mountains.","Her group camped for many weeks.","The campfire was the biggest ever."],"e":"Chuyến đi đáng nhớ vì cả lúc lạc đường nguy hiểm lẫn lúc được cứu."},{"f":"A1","p":"Have you ever tried snorkelling? Minh had never tried it before his trip to Phu Quoc last summer. Under the clear water, he saw colourful fish swimming around the coral. He was so amazed that he forgot to feel nervous. It is the most exciting experience he has ever had. How did Minh feel under the water?","a":"Amazed by the fish and coral he saw.","w":["Embarrassed in front of his friends.","Terrible because the water was cold.","Bored after a few minutes swimming."],"e":"Minh kinh ngạc trước cá và san hô đầy màu sắc dưới nước."},{"f":"A1","p":"During our school trip, I had an embarrassing moment at lunch. I called the tour guide 'Dad' in front of the whole class because I was sleepy. Everyone laughed, and my face turned red. The guide smiled kindly and said it happened to him once too. In the passage, 'embarrassing' means ___.","a":"making you feel shy and uncomfortable","w":["making you feel very excited","making you feel tired and hungry","making you feel proud and happy"],"e":"Gọi nhầm hướng dẫn viên là bố, mặt đỏ bừng — embarrassing là ngượng ngùng, xấu hổ."},{"f":"A1","p":"Our class has explored three caves this year, but Son Doong is still a dream for everyone. We have watched films about its huge chambers and underground river. Our teacher says a real visit needs months of training and special permission. We hope we will be ready to apply when we are older. What is the main idea of the passage?","a":"The class dreams of visiting Son Doong one day.","w":["The class has already visited Son Doong.","Caves have underground rivers in films.","Teachers need special permission to teach."],"e":"Ý chính: cả lớp mơ ước một ngày được đến Sơn Đoòng."},{"f":"A1","p":"Mai has kept a travel diary since she was ten. She has written about local food in Hue, boat trips in Ha Long and a brilliant sunrise in Da Lat. When she feels sad, she reads the diary and remembers the people who travelled with her. The diary, she says, is worth more than any souvenir. Why does Mai value her diary so much?","a":"It holds her memories of trips and people.","w":["It was the most expensive souvenir.","It was written by a famous traveller.","It contains maps of many places."],"e":"Nhật ký chứa kỉ niệm về chuyến đi và con người nên Mai quý hơn quà lưu niệm."},{"f":"A1","p":"Tom had never eaten Vietnamese local food before he came to Hanoi. On his first evening, his host took him to a small street stall for pho. He found the taste strange at first, but by the third bowl that week, he loved it. He told his friends it was a brilliant discovery. What can we infer about Tom?","a":"He gradually came to love pho.","w":["He only ate food from his country.","He cooked pho for his host family.","He disliked street food in Hanoi."],"e":"Ban đầu lạ miệng, đến bát thứ ba trong tuần thì thích — Tom dần yêu phở."},{"f":"A2","p":"Lan: Have you ever been camping by a lake? Minh: Yes, I have. Lan: When did you go? — What does Minh answer?","a":"Last summer, with my classmates.","w":["Yes, it was unforgettable.","I have packed my tent.","Camping is very exciting."],"e":"Hỏi when trong quá khứ phải đáp thời gian cụ thể đã đi."},{"f":"A2","p":"Tourist: Excuse me, is this your first time snorkelling? Hoa: Yes, it is. Tourist: How do you feel about it? — What does Hoa answer?","a":"A little nervous, but very excited.","w":["The coral is very colourful.","I bought a new camera.","We arrived here yesterday."],"e":"Hỏi cảm giác lần đầu lặn phải đáp cảm xúc."},{"f":"A2","p":"Mai: What was the most memorable part of your trip? Hung: Climbing the mountain at sunrise. Mai: Why was it so special? — What does Hung answer?","a":"Because the scenery above the clouds was amazing.","w":["We climbed for three hours.","I took many photos there.","The mountain is very high."],"e":"Hỏi vì sao đặc biệt phải đáp lý do: phong cảnh trên mây tuyệt vời."},{"f":"A2","p":"Friend: You've just come back from Ha Long. How was it? Lan: Brilliant! We explored a cave yesterday. Friend: What did you buy as a souvenir? — What does Lan answer?","a":"A small stone boat for my mother.","w":["The cave was very dark.","We travelled by boat.","Ha Long is a famous bay."],"e":"Hỏi mua quà lưu niệm gì phải nêu món quà cụ thể."}],"g9-u6":[{"f":"A1","p":"Grandma enjoys telling us how communication has changed. In her youth, a letter took a week to reach her brother who worked in another province. Today, she video-calls him every Sunday on a smartphone her grandson gave her. She still writes letters sometimes, because she says handwriting carries feelings that screens cannot. Why does Grandma still write letters sometimes?","a":"She believes handwriting shows feelings better.","w":["Her smartphone is often broken.","Her brother cannot use a phone.","Letters arrive faster than calls."],"e":"Bà vẫn viết thư vì chữ viết tay truyền cảm xúc mà màn hình không làm được."},{"f":"A1","p":"In the past, few village homes had electricity, so appliances were almost unknown. Families cooked on wood fires and kept food cool in clay pots. Now almost every home has a fridge, a washing machine and an electric cooker. Life is more convenient, but electricity bills have become a new worry. What is one disadvantage of modern appliances mentioned?","a":"Families must pay higher electricity bills.","w":["Food cannot be kept cool anymore.","Cooking takes longer than before.","Village homes have no electricity now."],"e":"Tiện lợi hơn nhưng hóa đơn điện trở thành nỗi lo mới."},{"f":"A1","p":"My parents and I often disagree about entertainment, which shows the generation gap in our family. They prefer traditional folk songs, while I enjoy online videos and pop music. However, we have learnt to respect each other's choices and watch some programmes together. On Sundays, we sometimes sing folk songs together after dinner. In the passage, 'generation gap' means ___.","a":"different views between young and old people","w":["a long holiday between school terms","a modern device used by families","a traditional song sung together"],"e":"Bất đồng giữa cha mẹ và con về giải trí — generation gap là khoảng cách thế hệ."},{"f":"A1","p":"Transport in Viet Nam has improved greatly in one generation. Grandpa used to cycle twenty kilometres to the nearest town on a dirt road. Father rode a motorbike on a paved road, and today I travel by electric bus on a highway. Each generation has reached the town faster and more comfortably than the one before. What is the main idea of the passage?","a":"Travel has become faster over the generations.","w":["Highways are longer than dirt roads.","Electric buses are used only by students.","Grandpa cycled farther than Father."],"e":"Ý chính: việc đi lại nhanh và thoải mái hơn qua các thế hệ."},{"f":"A1","p":"Children in the past used to play traditional games in the village yard after school. They made toys from bamboo and leaves because shops were far away. Today's children tend to play on tablets at home, so they spend less time outdoors. Teachers worry that some traditional games will be forgotten if schools do not teach them. Why are teachers worried?","a":"Traditional games may disappear in the future.","w":["Tablets are too expensive for children.","Shops are still far from villages.","Children play outdoors too much now."],"e":"Trẻ em chơi máy tính bảng ở nhà, ít ra ngoài — trò chơi truyền thống có thể bị quên."},{"f":"A1","p":"Aunt Lien decided to learn how to use online shopping, although she had avoided it for years. Her daughter showed her how to compare prices and check reviews carefully. After her first order arrived safely, Aunt Lien smiled and said technology was not as scary as she thought. She has since taught two of her friends how to order online too. What can we infer about Aunt Lien?","a":"She overcame her fear of new technology.","w":["She opened her own online shop.","She bought the most expensive item.","She stopped shopping at local markets."],"e":"Từng tránh né nhiều năm, nay mua thành công — dì đã vượt qua nỗi sợ công nghệ."},{"f":"A2","p":"Grandson: Grandpa, how did you travel to school as a boy? Grandpa: I used to walk five kilometres every day. Grandson: That sounds hard. How do children go now? — What does Grandpa answer?","a":"Most of them ride bicycles or take the bus.","w":["Schools were very far away.","I liked walking with friends.","Your father has a motorbike."],"e":"Hỏi trẻ em nay đi học thế nào phải đáp phương tiện hiện nay."},{"f":"A2","p":"Mother: Why are you watching videos again, Son? Son: Just for ten minutes, Mum. Mother: You spend too much time on screens. What did children do for fun in my time? — What does Son answer?","a":"They played traditional games outdoors, didn't they?","w":["Videos are very interesting.","I will finish my homework soon.","My tablet has many games."],"e":"Đáp lại câu hỏi về giải trí xưa: chơi trò dân gian ngoài trời — hợp mạch hội thoại."},{"f":"A2","p":"Lan: My grandparents don't understand my messages with emojis. Minh: That's the generation gap. Lan: How can I help them understand? — What does Minh answer?","a":"Explain the meanings patiently, one by one.","w":["Emojis are used worldwide.","Your grandparents are very kind.","Messages should be very short."],"e":"Hỏi cách giúp ông bà hiểu phải đáp cách giải thích kiên nhẫn."},{"f":"A2","p":"Teacher: How has schooling changed since your parents' time? Student: We learn with computers and the Internet now. Teacher: What did your parents use instead? — What does the student answer?","a":"They used printed books and wrote by hand.","w":["Schooling is very important.","My parents studied very hard.","Computers are used in class."],"e":"Hỏi xưa cha mẹ dùng gì thay máy tính phải đáp sách in và viết tay."}],"g9-u7":[{"f":"A1","p":"A visitor asked a guide if Son Doong was the largest cave in the world. The guide said it was, and added that the cave is so big that a whole city street could fit inside. He also explained that only a limited number of tourists can enter each year to protect its formations. Visitors must book many months in advance. Why must visitors book so early?","a":"Only a limited number can enter each year.","w":["The cave is the deepest in the world.","Guides work only a few months a year.","The city street inside is very busy."],"e":"Số khách vào hang mỗi năm bị giới hạn để bảo vệ hang nên phải đặt sớm."},{"f":"A1","p":"Fansipan, which is located in northern Viet Nam, is called the roof of Indochina. Climbers who reach its majestic peak are rewarded with a sea of clouds below them. Many say the view at sunrise is breathtaking and worth every difficult step. Those who are not fit can take a cable car instead. In the passage, 'breathtaking' means ___.","a":"extremely beautiful and impressive","w":["very cold and very windy","difficult and very tiring","high and very dangerous"],"e":"Cảnh bình minh trên biển mây gây choáng ngợp — breathtaking là ngoạn mục."},{"f":"A1","p":"Ha Long Bay has been recognised as a natural wonder because of its thousands of limestone islands. Each island has its own shape, and local people have given them names like Fighting Cocks and Incense Burner. Tourists who explore the bay by boat discover a new view at every turn. The bay changes colour from morning to evening. What is the main idea of the passage?","a":"Ha Long Bay's islands make it a true wonder.","w":["Local people named every island recently.","Tourists must travel by boat all day.","The bay is most beautiful in the morning."],"e":"Ý chính: hàng nghìn đảo đá vôi tạo nên kì quan Hạ Long."},{"f":"A1","p":"A student asked whether tourists were allowed to camp on the valley floor. The ranger said they were not, because camping fires could damage the grassland and disturb wild animals. Designated campsites have been built on a nearby hill instead. From there, campers still enjoy a spectacular view of the whole valley. Why is camping on the valley floor banned?","a":"It could harm nature and wild animals.","w":["The valley floor is too far from the hill.","Campers prefer the view from the river.","The grassland is used for farming only."],"e":"Cấm cắm trại dưới thung lũng vì lửa trại hại cỏ và động vật hoang dã."},{"f":"A1","p":"When Linh first saw the waterfall hidden deep in the forest, she stood silently for a minute. Water fell from a high cliff into a clear pool, and a rainbow appeared in the fine spray. She later wrote in her diary that no photo could show how majestic it really was. Her friends quietly took photos beside her. How did Linh feel at the waterfall?","a":"Deeply impressed by its natural beauty.","w":["Disappointed that photos were banned.","Worried about the deep clear pool.","Tired after the long forest walk."],"e":"Linh đứng lặng, viết nhật ký không ảnh nào tả hết — cô ấn tượng sâu sắc trước vẻ hùng vĩ."},{"f":"A1","p":"Phong Nha Cave was discovered by a local man in 1890, but its full beauty was not known until much later. Explorers have since found long underground rivers and strange rock formations inside. Today, boats take visitors through the first part of the cave only. The deeper parts are kept for scientists to study. Why can visitors see only the first part?","a":"The deeper parts are reserved for research.","w":["The boats are too big for the river.","The cave was discovered too recently.","Scientists visit only in the summer."],"e":"Phần sâu của hang dành cho nhà khoa học nghiên cứu nên khách chỉ xem phần đầu."},{"f":"A2","p":"Tourist: Excuse me, is this the largest cave in the region? Guide: Yes, it is. Tourist: Can we enter it today? — What does the guide answer?","a":"I'm afraid not. You need a permit first.","w":["It was discovered in 1890.","Many tourists visit it yearly.","The cave has a long river."],"e":"Hỏi hôm nay vào được không, đáp chưa được vì cần giấy phép — hợp ngữ cảnh."},{"f":"A2","p":"Lan: The guide said the peak is 3,143 metres high. Minh: Wow! Did he say how long the climb takes? Lan: Yes, he did. — What does Lan answer next?","a":"He said it took two days to reach the top.","w":["The peak is in the north.","Climbers must be very fit.","We took the cable car down."],"e":"Câu hỏi tường thuật: hướng dẫn viên nói leo lên đỉnh mất hai ngày."},{"f":"A2","p":"Visitor: Why do people call this place a paradise? Local: Because of its beaches and clear water. Visitor: What else makes it special? — What does the local answer?","a":"Its quiet islands and spectacular sunsets.","w":["Paradise is a beautiful word.","Tourists come here in summer.","I was born on this island."],"e":"Hỏi điều gì nữa làm nơi này đặc biệt phải nêu thêm cảnh đẹp cụ thể."},{"f":"A2","p":"Student: Can we visit the bay tomorrow, Miss? Teacher: That depends on the weather. Student: What did the forecast say? — What does the teacher answer?","a":"It said it would be sunny and calm.","w":["The bay is a natural wonder.","We will travel there by boat.","Tomorrow is a school holiday."],"e":"Hỏi dự báo nói gì phải tường thuật nội dung dự báo."}],"g9-u8":[{"f":"A1","p":"The homestay owner who welcomed us in Da Lat treated us like family. She cooked local dishes, showed us her flower garden and told stories about the town. Our package tour hotel last year was comfortable, but nobody there knew our names. Mai said she would choose a homestay again for her next holiday. Why does Mai prefer the homestay?","a":"She was treated personally, like family.","w":["The hotel rooms were too small.","The flower garden was very big.","Da Lat is colder than her town."],"e":"Chủ homestay đối đãi như người nhà, nhớ tên khách — Mai thích sự gần gũi cá nhân."},{"f":"A1","p":"Before booking a package tour, wise tourists check the itinerary carefully. Some cheap tours include long hours in souvenir shops, which leaves little time for sightseeing. A good itinerary balances famous destinations with free time to rest. Reading reviews from other holidaymakers also helps you choose well. What should tourists check before booking?","a":"The itinerary and other tourists' reviews.","w":["The price of souvenirs in shops.","The size of the tour guide's bag.","The colour of the tour brochure."],"e":"Du khách khôn ngoan kiểm tra lịch trình và đọc đánh giá trước khi đặt tour."},{"f":"A1","p":"Our tour guide, whose knowledge of history amazed everyone, took us to an ancient temple. He explained each carving and answered questions patiently for an hour. A tourist from France said it was the best guided visit she had ever joined. Without him, we would have understood very little. What can we infer about the guide?","a":"His explanations made the visit meaningful.","w":["He spoke French better than anyone.","He had visited France many times.","He carved the temple statues himself."],"e":"Nhờ giải thích của hướng dẫn viên, chuyến tham quan trở nên ý nghĩa."},{"f":"A1","p":"Domestic tourism has grown quickly since travel became cheaper. Families who used to holiday only in their home province now explore beaches and mountains across the country. Local resorts and homestays have been built to welcome them. This growth has created jobs for tour guides and drivers in many regions. What is the main idea of the passage?","a":"More people now travel within their country.","w":["Resorts are more popular than homestays.","Travel abroad has become cheaper.","Tour guides earn more than drivers."],"e":"Ý chính: ngày càng nhiều người du lịch trong nước."},{"f":"A1","p":"If you book your accommodation early, you will have more choices and lower prices. Lan learnt this the hard way when her family arrived in Nha Trang without a booking during a festival. They visited six hotels before finding one expensive room far from the beach. She now books at least a month before every trip. Why did Lan's family have a difficult evening?","a":"They had not booked a room in advance.","w":["The festival was held far from the beach.","Six hotels were closed for repairs.","Their room had no view of the beach."],"e":"Không đặt phòng trước vào dịp lễ hội nên gia đình vất vả tìm phòng."},{"f":"A1","p":"A travel brochure described a resort as 'a quiet paradise by the sea'. When Nam arrived, he found loud music by the pool and a crowded beach. He felt the brochure had promised more than the resort could offer. He wrote an honest review so other tourists would know the truth. How did Nam feel about the resort?","a":"Disappointed because it differed from the brochure.","w":["Excited by the loud poolside music.","Proud of his honest travel review.","Surprised that the beach was quiet."],"e":"Thực tế ồn ào, đông đúc khác xa tờ rơi — Nam thất vọng."},{"f":"A2","p":"Tourist: I'd like a package tour to Hue for three days. Agent: We have one leaving on Friday. Tourist: Does it include accommodation and meals? — What does the agent answer?","a":"Yes, hotels and breakfast are included.","w":["Hue is a historic city.","The tour guide speaks English.","You can pay by card here."],"e":"Hỏi tour có gồm chỗ ở, bữa ăn không phải xác nhận nội dung bao gồm."},{"f":"A2","p":"Receptionist: Welcome! Do you have a booking, sir? Guest: Yes, under the name David Brown. Receptionist: Let me check. — What does the receptionist say next?","a":"Yes, a double room for two nights, sir.","w":["The hotel is near the beach.","Breakfast is served at seven.","Our hotel has a swimming pool."],"e":"Sau khi kiểm tra đặt phòng, lễ tân xác nhận loại phòng và số đêm."},{"f":"A2","p":"Mai: Our itinerary tomorrow looks very busy. Guide: We start sightseeing at eight and visit three places. Mai: When will we have free time? — What does the guide answer?","a":"After four o'clock, before dinner.","w":["The old town is very famous.","Lunch is at a local restaurant.","You should bring a camera."],"e":"Hỏi khi nào có thời gian rảnh phải đáp khung giờ cụ thể."},{"f":"A2","p":"Tourist: Excuse me, where can I buy souvenirs near here? Local: There's a market two streets away. Tourist: Thank you. Is it open now? — What does the local answer?","a":"Yes, it stays open until nine tonight.","w":["Souvenirs there are beautiful.","I bought a hat there yesterday.","The market is very crowded."],"e":"Hỏi chợ còn mở không phải xác nhận giờ mở cửa."}],"g9-u9":[{"f":"A1","p":"English is spoken as an official language in more than fifty countries. A student who can communicate in English can study abroad, work for foreign companies and read books that have not been translated. That is the reason why many Vietnamese parents encourage their children to learn it early. However, teachers remind learners that their mother tongue should never be forgotten. Why do parents encourage early English learning?","a":"It opens chances to study and work globally.","w":["English is easy for young children.","All foreign books are written in English.","Their mother tongue is less important."],"e":"Tiếng Anh mở cơ hội học tập, làm việc toàn cầu nên cha mẹ khuyến khích học sớm."},{"f":"A1","p":"A bilingual person is someone who speaks two languages fluently. Mai grew up speaking Vietnamese at home and English at her international school. She can translate songs for her mother and help foreign visitors in her town. She says each language helps her see the world in a different way. In the passage, 'fluent' most likely means ___.","a":"able to speak smoothly and easily","w":["able to write with a dictionary","able to remember many words","able to speak very loudly"],"e":"Song ngữ trôi chảy cả hai thứ tiếng — fluent là nói trôi chảy, dễ dàng."},{"f":"A1","p":"Learners often worry about their accent when they speak English. Teachers explain that a clear pronunciation matters more than sounding exactly like a native speaker. People around the world speak English with many different accents, and they still understand each other well. What matters most is being understood. What is the main idea of the passage?","a":"Being clear matters more than a perfect accent.","w":["Learners should copy native speakers exactly.","Accents make English impossible to learn.","Pronunciation is not important at all."],"e":"Ý chính: nói rõ ràng quan trọng hơn giọng hoàn hảo như người bản xứ."},{"f":"A1","p":"The word whose meaning Linh kept forgetting was 'habitat'. She wrote it on a card with a picture of a forest and reviewed it every morning. After a week, she could use it in sentences without looking at the dictionary. Her teacher said learning vocabulary in context is more effective than memorising long lists. What helped Linh remember the word?","a":"Learning it with a picture and in context.","w":["Memorising a very long word list.","Looking it up in the dictionary daily.","Forgetting it for a whole week."],"e":"Linh nhớ từ nhờ thẻ hình và ôn trong ngữ cảnh."},{"f":"A1","p":"At an English-speaking contest, Hung spoke slowly and made two grammar mistakes. However, the judges praised him because his ideas were clear and he never stopped to search for words. He communicated his message successfully, which is the real goal of learning a language. The audience understood every idea without difficulty. Why did the judges praise Hung?","a":"He communicated his ideas clearly throughout.","w":["He made no grammar mistakes at all.","He spoke the fastest in the contest.","He used the longest words on stage."],"e":"Ban giám khảo khen vì Hung truyền đạt ý rõ ràng, không dừng lại tìm từ."},{"f":"A1","p":"Many English words have been borrowed from other languages over the centuries. 'Kindergarten' came from German, and 'karaoke' came from Japanese. As people travel and trade, languages exchange words and grow richer. Dictionaries must be updated regularly to include new words like these. What can we infer about English vocabulary?","a":"It keeps growing through contact with other languages.","w":["It was completed many centuries ago.","It borrows words only from German.","It changes only when dictionaries change."],"e":"Từ vựng tiếng Anh vay mượn và giàu lên nhờ tiếp xúc ngôn ngữ khác."},{"f":"A2","p":"Lan: Why do you learn English so seriously? Minh: Because I want to study abroad one day. Lan: Which skill do you practise most? — What does Minh answer?","a":"Speaking. I practise with friends every day.","w":["English is an official language.","My dictionary has many words.","I started learning at seven."],"e":"Hỏi luyện kĩ năng nào nhất phải nêu kĩ năng và cách luyện."},{"f":"A2","p":"Teacher: What does 'bilingual' mean, Mai? Mai: It describes someone who speaks two languages. Teacher: Can you give an example? — What does Mai answer?","a":"My aunt speaks Vietnamese and French fluently.","w":["A dictionary explains many words.","Two languages are difficult.","Speaking is an important skill."],"e":"Hỏi ví dụ về song ngữ phải nêu người nói hai thứ tiếng cụ thể."},{"f":"A2","p":"Tourist: Excuse me, can you speak English? Student: Yes, a little. Tourist: Could you help me translate this sign? — What does the student answer?","a":"Of course. It says 'No entry', sir.","w":["The sign is near the gate.","English is spoken worldwide.","I learn English at school."],"e":"Được nhờ dịch biển báo nên đáp nhận lời và dịch nội dung biển."},{"f":"A2","p":"Friend: Your English pronunciation has improved a lot! Hoa: Thank you. I listen and repeat every morning. Friend: How long do you practise each day? — What does Hoa answer?","a":"About twenty minutes before breakfast.","w":["By listening to English songs.","With my teacher at school.","Yes, pronunciation is important."],"e":"Hỏi luyện bao lâu mỗi ngày phải đáp khoảng thời gian."}],"g9-u10":[{"f":"A1","p":"The Amazon rainforest, which is often called the lungs of the Earth, produces a large amount of the world's oxygen. It is also the habitat of thousands of species of flora and fauna found nowhere else. Sadly, large areas of the forest are being cut down every year. If this continues, many species will disappear forever. Why is the Amazon so important?","a":"It provides oxygen and homes for unique species.","w":["It is the oldest forest in the world.","It produces rain for the whole Earth.","It is visited by thousands of tourists."],"e":"Amazon tạo oxi và là nơi sống của nhiều loài độc nhất nên rất quan trọng."},{"f":"A1","p":"Polar bears live in the Arctic, where sea ice is their main hunting ground. Because of global warming, the ice now melts earlier each spring. Bears therefore have less time to hunt and must wait hungry on land for longer. Scientists warn that their numbers have fallen in some areas. Why are polar bears in danger?","a":"Melting ice leaves them less time to hunt.","w":["Hunters visit the Arctic every spring.","Bears cannot swim in cold water.","Land provides no food in summer."],"e":"Băng tan sớm vì nóng lên toàn cầu khiến gấu ít thời gian săn mồi."},{"f":"A1","p":"A nature reserve is an area where endangered species are protected by law. In Cuc Phuong, rangers patrol the forest to stop illegal hunting and tree cutting. Animals that are hurt are treated and returned to the wild when they are healthy. Visitors may enter only certain parts of the reserve. In the passage, 'endangered' means ___.","a":"at risk of disappearing completely","w":["very large and very strong","found only in zoos today","protected by many visitors"],"e":"Loài được luật bảo vệ vì có nguy cơ biến mất — endangered là có nguy cơ tuyệt chủng."},{"f":"A1","p":"Earth's ecosystems depend on balance. If one species disappears, the animals that feed on it may also decline, and plants it used to eat may grow out of control. This is why protecting a single habitat helps protect the whole food web within it. Small changes can have wide effects on nature. What is the main idea of the passage?","a":"All species in an ecosystem are connected.","w":["Plants grow faster without animals.","Food webs exist only in rainforests.","Protecting habitats is very expensive."],"e":"Ý chính: mọi loài trong hệ sinh thái liên kết với nhau."},{"f":"A1","p":"My uncle, who works at a nature reserve, once helped rescue an injured elephant calf. The calf had lost its mother and could not find food alone. After months of care, it was strong enough to join a herd again. My uncle says that day was the proudest moment of his career. How did the uncle feel when the calf rejoined the herd?","a":"Proud that his care had saved the calf.","w":["Worried that the herd would reject it.","Sad that his career was ending.","Angry at the people who hurt it."],"e":"Chú tự hào vì công chăm sóc đã cứu được voi con."},{"f":"A1","p":"Grasslands cover large parts of the Earth and support many grazing animals. Unlike rainforests, they receive little rain, so their plants have deep roots to reach water underground. When the climate becomes drier, grasslands can turn into deserts. Farmers are therefore advised not to let animals eat all the grass in one area. Why do grassland plants have deep roots?","a":"To reach water deep under the ground.","w":["To support many grazing animals.","To stop grasslands becoming deserts.","To grow taller than rainforest trees."],"e":"Đồng cỏ ít mưa nên cây có rễ sâu để lấy nước dưới đất."},{"f":"A2","p":"Student: Miss, why are rainforests disappearing? Teacher: Because people cut trees for land and wood. Student: What will happen if this continues? — What does the teacher answer?","a":"Many species will lose their habitats.","w":["Rainforests are very large.","Trees grow very slowly there.","People need land for farming."],"e":"Hỏi hậu quả nếu phá rừng tiếp diễn phải đáp loài mất môi trường sống."},{"f":"A2","p":"Lan: Have you heard about the new nature reserve? Minh: Yes, it was established last year. Lan: What animals does it protect? — What does Minh answer?","a":"Endangered monkeys and rare birds.","w":["It is near a famous rainforest.","Rangers patrol it every day.","Visitors can camp there."],"e":"Hỏi khu bảo tồn bảo vệ loài nào phải nêu loài cụ thể."},{"f":"A2","p":"Visitor: The Earth is getting warmer, isn't it? Scientist: Yes, that is global warming. Visitor: What is one of its effects? — What does the scientist answer?","a":"Sea levels rise as polar ice melts.","w":["The Earth orbits around the Sun.","Oxygen is needed by all species.","Habitats are homes for animals."],"e":"Hỏi một hệ quả của nóng lên toàn cầu phải nêu mực nước biển dâng do băng tan."},{"f":"A2","p":"Teacher: What can students do to protect the planet? Hoa: We can plant trees and save water. Teacher: Why does planting trees help? — What does Hoa answer?","a":"Trees produce oxygen and give animals homes.","w":["Trees grow in every habitat.","Planting is a school activity.","Water is important for trees."],"e":"Hỏi vì sao trồng cây giúp ích phải nêu cây tạo oxi, cho động vật nơi ở."}],"g9-u11":[{"f":"A1","p":"The teacher suggested using a new language app that gives students short daily exercises. Lan, who used to forget vocabulary quickly, has practised on the app for a month. Her tablet reminds her at seven each morning, and the exercises feel like games. She has remembered twice as many words as before. Why has the app helped Lan?","a":"It makes her practise regularly in a fun way.","w":["It is the newest device in her class.","It works only on tablets, not phones.","It gives her a reminder at weekends."],"e":"Ứng dụng nhắc hằng ngày, bài tập như trò chơi giúp Lan luyện đều và nhớ từ hơn."},{"f":"A1","p":"Experts recommend that users should not charge their smartphones overnight every night. Leaving a battery at one hundred per cent for many hours can shorten its life. It is better to charge the device in the evening and unplug it before bed. A healthy battery will last longer during the day too. What do experts advise users to do?","a":"Unplug the phone before going to bed.","w":["Charge the phone only in the morning.","Buy a new battery every year.","Use the phone until midnight daily."],"e":"Chuyên gia khuyên rút sạc trước khi ngủ để bảo vệ pin."},{"f":"A1","p":"A smartwatch is a portable device that you wear on your wrist. Besides telling the time, it can count your steps, measure your heart rate and show messages from your phone. Many runners find it useful because it is light and wireless. It can also remind the wearer to stand up and move. In the passage, 'portable' means ___.","a":"easy to carry or move around","w":["easy to charge very quickly","able to connect to the Internet","able to show many messages"],"e":"Đeo trên tay, nhẹ, không dây — portable là mang theo được."},{"f":"A1","p":"Electronic devices have changed how students learn. With a laptop, they can join online classes, search for information in seconds and share homework with teachers instantly. However, devices should be used for limited hours, because long screen time can hurt their eyes. Balance is the key to using technology well. What is the main idea of the passage?","a":"Devices help learning if used in balance.","w":["Students should search information faster.","Online classes have replaced all schools.","Laptops are better than tablets for study."],"e":"Ý chính: thiết bị hỗ trợ học tập nếu dùng cân bằng, điều độ."},{"f":"A1","p":"Minh was advised to choose a laptop with a larger screen for his design work. His old device was slow, and its battery lasted only one hour. After saving for six months, he bought a new one that can work all day. He now finishes his projects faster and with less eye strain. Why did Minh need a new laptop?","a":"His old one was slow with a weak battery.","w":["His design work had already finished.","He wanted the largest screen in class.","He had saved money for a tablet."],"e":"Laptop cũ chậm, pin chỉ một giờ nên Minh cần máy mới."},{"f":"A1","p":"The technician suggested checking the printer before blaming the computer. Sure enough, the printer's paper tray was empty, and its ink was almost finished. After adding paper and ink, the document was printed perfectly. The office manager laughed and said simple causes are often forgotten. What was wrong with the printer?","a":"It had run out of paper and ink.","w":["Its screen was too small to read.","Its battery needed charging overnight.","It was not connected to any laptop."],"e":"Máy in hết giấy và gần hết mực — đó là nguyên nhân thật."},{"f":"A2","p":"Student: My tablet battery runs out very fast. Technician: You should close apps you are not using. Student: Thank you. What else should I do? — What does the technician answer?","a":"Turn down the screen brightness as well.","w":["Tablets are portable devices.","You bought it last month.","The charger is on the desk."],"e":"Hỏi nên làm thêm gì để tiết kiệm pin phải đáp giảm độ sáng màn hình."},{"f":"A2","p":"Mai: I want to buy headphones for online classes. Shop assistant: These wireless ones are very popular. Mai: How long does their battery last? — What does the shop assistant answer?","a":"About ten hours on one charge.","w":["They cost five hundred thousand dong.","They come in black and white.","Students like them very much."],"e":"Hỏi pin dùng được bao lâu phải đáp thời lượng pin."},{"f":"A2","p":"Teacher: I recommend that you should back up your files. Student: Why is that important, Miss? Teacher: In case your laptop breaks down. — What does the student answer?","a":"I see. I'll save them on a USB drive tonight.","w":["Laptops are expensive devices.","My files are very interesting.","School starts again on Monday."],"e":"Hiểu lời khuyên sao lưu nên đáp sẽ lưu vào USB tối nay."},{"f":"A2","p":"Lan: My smartphone screen is cracked. What should I do? Hung: You should take it to a repair shop. Lan: Do you know a good one near here? — What does Hung answer?","a":"Yes, there's one next to the post office.","w":["Screens are made of glass.","It happened last week.","Repairing is quite cheap."],"e":"Hỏi tiệm sửa chữa tốt gần đây phải đáp địa điểm cụ thể."}],"g9-u12":[{"f":"A1","p":"Although the salary is not high, Mrs Phuong loves her job as a tailor. She has made clothes for families in her town for thirty years and knows many customers by name. She says a well-made shirt that fits perfectly makes people confident. That feeling, for her, is more rewarding than money. Why does Mrs Phuong love her job?","a":"Making people confident makes it rewarding.","w":["She earns more than other tailors.","She has worked for only a few years.","Customers buy the cheapest shirts."],"e":"May đồ vừa vặn giúp khách tự tin — đó là phần thưởng ý nghĩa hơn tiền với bà Phương."},{"f":"A1","p":"Becoming a surgeon is one of the most demanding career paths. Students must study medicine for many years and pass difficult exams. During training, they work long hours in hospitals and must stay calm in emergencies. Only those with both skill and patience can succeed. In the passage, 'demanding' means ___.","a":"requiring a lot of effort and skill","w":["offering a very high salary","lasting only a short time","popular with many students"],"e":"Học nhiều năm, giờ dài, cần kĩ năng và kiên nhẫn — demanding là đòi hỏi cao."},{"f":"A1","p":"Minh trained hard for two years, so he became a skilled mechanic at a young age. Older workers respect him because he can find engine problems that others miss. He told a school visitor that passion matters, but daily training matters even more. Young people, he said, should never stop learning new skills. What is the main idea of the passage?","a":"Training and learning lead to career success.","w":["Mechanics earn respect from visitors.","Engine work is easier for young people.","Passion alone guarantees a good job."],"e":"Ý chính: đào tạo và học hỏi liên tục dẫn tới thành công nghề nghiệp."},{"f":"A1","p":"A software engineer who designs learning apps visited our school last week. She explained that her job combines technology with creativity, because an app must be both useful and enjoyable. If students find an app boring, she redesigns it based on their feedback. Her talk inspired many of us to consider this career. Why does she redesign her apps?","a":"To make them enjoyable for student users.","w":["To sell them at a higher price.","To finish her work more quickly.","To learn new computer languages."],"e":"Cô thiết kế lại ứng dụng dựa trên phản hồi để học sinh thấy thú vị."},{"f":"A1","p":"Lan loves children, so she decided to apply for a teaching course after graduation. She knows the training will take four years and that a teacher's work is demanding. However, she believes watching children grow and learn will make every effort worthwhile. If she passes the entrance exam, she will start this September. How does Lan feel about her chosen career?","a":"Determined and hopeful about becoming a teacher.","w":["Worried that the course is too short.","Uncertain which career to choose.","Disappointed about the entrance exam."],"e":"Lan biết đào tạo vất vả nhưng vẫn quyết tâm, hi vọng — quyết tâm và lạc quan."},{"f":"A1","p":"Because she had strong qualifications and good interview skills, Hoa was chosen for the accountant position over twenty other applicants. The manager said her careful way of working with numbers impressed the whole team. She will start next month and hopes to earn a promotion within two years. Her former teacher was not surprised by the news at all. Why was Hoa chosen for the job?","a":"Her qualifications and careful work impressed them.","w":["She was the only applicant with a degree.","She hoped to earn a quick promotion.","She had worked there for two years."],"e":"Hoa được chọn nhờ bằng cấp tốt và cách làm việc cẩn thận gây ấn tượng."},{"f":"A2","p":"Student: I love fixing machines. What job suits me? Teacher: You could become a mechanic or an engineer. Student: What training do I need for that? — What does the teacher answer?","a":"A technical course and lots of practice.","w":["Mechanics earn quite well now.","The garage is near your school.","You fixed my bike last week."],"e":"Hỏi cần đào tạo gì phải đáp khóa học kĩ thuật và thực hành nhiều."},{"f":"A2","p":"Lan: Why do you want to become a designer? Mai: Because I love drawing and creating new things. Lan: Is the job demanding? — What does Mai answer?","a":"Yes, but it's rewarding when people love my work.","w":["Designers use computers daily.","I applied for a course yesterday.","My drawings are on the wall."],"e":"Hỏi nghề có vất vả không, đáp có nhưng bổ ích khi được yêu thích — hợp ngữ cảnh nhượng bộ."},{"f":"A2","p":"Interviewer: Why should we choose you for this job? Applicant: I'm careful, hard-working and good with numbers. Interviewer: When can you start? — What does the applicant answer?","a":"I can start next Monday, sir.","w":["Accountants work in offices.","The job was posted last week.","My qualification is from Hanoi."],"e":"Hỏi khi nào bắt đầu được phải đáp thời điểm bắt đầu."},{"f":"A2","p":"Son: Dad, although surgeons earn well, their job looks stressful. Father: That's true. Son: So why do many students choose it? — What does the father answer?","a":"Because saving lives is deeply rewarding.","w":["Hospitals are modern buildings.","Training takes many years.","Your uncle is a surgeon."],"e":"Hỏi vì sao nhiều người chọn nghề phẫu thuật phải đáp cứu người là việc rất ý nghĩa."}],"g9-review":[{"f":"A1","p":"Nga has lived in her neighbourhood for ten years and has seen it change greatly. A community centre was built where an empty lot used to be, and teenagers now learn embroidery there at weekends. The streets are busier, yet Nga says neighbours still look after each other as before. She hopes the friendly spirit will never change. What does Nga hope will stay the same?","a":"The neighbours' friendly, caring spirit.","w":["The empty lot in her neighbourhood.","The weekend embroidery classes.","The busy streets near her house."],"e":"Nga hi vọng tinh thần thân thiện, chăm sóc lẫn nhau của hàng xóm không đổi."},{"f":"A1","p":"If students manage their time well, they will feel less stressed before exams. Tuan, who used to revise all night, now follows a weekly plan and sleeps early. His marks have improved, and he still has time to play football with friends. His teacher told the class that balance, not longer hours, brings real progress. What lesson does Tuan's story teach?","a":"Balanced study brings better results.","w":["Football should be played every day.","Exams are easier than before.","Revising all night is necessary."],"e":"Câu chuyện Tuấn cho thấy học cân bằng hiệu quả hơn học thâu đêm."},{"f":"A1","p":"The old theatre, which was built in 1950, has been restored by the city council. Local people who watched plays there as children now bring their grandchildren to the same seats. A famous director said the building is part of the city's memory and must be preserved for future generations. Children learn the building's history on school visits there. In the passage, 'restored' means ___.","a":"repaired and returned to good condition","w":["built again in a new place","closed for future generations","painted in a modern style"],"e":"Nhà hát cũ được thành phố sửa chữa — restored là tu sửa, khôi phục."},{"f":"A1","p":"A young engineer returned to her hometown after studying in the city. She suggested that farmers should use a weather app to plan their harvest. At first, some farmers doubted the app, but its forecasts proved correct three times. Now most families check it every morning before going to the fields. Why did the farmers begin to trust the app?","a":"Its forecasts turned out to be correct.","w":["The engineer was born in their town.","The app was completely free forever.","Harvests had failed three times."],"e":"Nông dân tin ứng dụng vì dự báo đúng ba lần liên tiếp."},{"f":"A1","p":"Have you ever visited a place that changed how you think? On a trip to a nature reserve, Binh saw an endangered bird for the first time. A ranger explained that if its habitat disappeared, the bird would disappear too. Since that day, Binh has joined every school tree-planting activity. What changed Binh after the trip?","a":"He became active in protecting nature.","w":["He decided to become a ranger.","He stopped travelling to reserves.","He started keeping birds at home."],"e":"Sau chuyến đi, Bình tham gia mọi hoạt động trồng cây — tích cực bảo vệ thiên nhiên."},{"f":"A1","p":"Although English has many different accents around the world, speakers usually understand each other. Problems happen when people speak too fast or use local words that others do not know. Teachers therefore advise learners to speak clearly and check meaning politely. Good communication depends more on clarity than on copying one accent. What is the main idea of the passage?","a":"Clear speaking helps English users understand each other.","w":["Local words should never be used.","Learners must copy one single accent.","Accents cause most travel problems."],"e":"Ý chính: nói rõ ràng giúp người dùng tiếng Anh hiểu nhau."},{"f":"A2","p":"Mai: I don't know where to buy a conical hat for my guest. Lan: At the handicraft shop in the old town. Mai: How can I get there from here? — What does Lan answer?","a":"Take bus number 5 and get off at the market.","w":["The hat is made of palm leaves.","Guests usually love souvenirs.","The old town is very famous."],"e":"Hỏi đường đi phải đáp phương tiện và điểm xuống cụ thể."},{"f":"A2","p":"Doctor: You should exercise more and sleep earlier. Teen: What if I have too much homework? Doctor: Then manage your time better. — What does the teen answer?","a":"I'll make a priority list every evening.","w":["Homework is very difficult now.","I joined the running club.","Sleeping is good for health."],"e":"Nhận lời khuyên quản lí thời gian nên hứa lập danh sách ưu tiên mỗi tối."},{"f":"A2","p":"Tourist: Excuse me, who built this monument? Guide: Local people built it two centuries ago. Tourist: Why was it built? — What does the guide answer?","a":"To worship the village's ancestors.","w":["It is visited every spring.","The stone walls are very old.","A festival is held here yearly."],"e":"Hỏi vì sao xây di tích phải đáp mục đích thờ cúng tổ tiên."},{"f":"A2","p":"Student: I want a career that helps people directly. Teacher: Then teaching or medicine may suit you. Student: Which qualification do I need for medicine? — What does the teacher answer?","a":"A medical degree after years of training.","w":["Doctors work in hospitals.","Medicine is a demanding career.","Many students apply every year."],"e":"Hỏi bằng cấp cho ngành y phải đáp bằng y khoa sau nhiều năm đào tạo."}]});
  if (typeof window.__phaseCompleteGrade === "function") window.__phaseCompleteGrade(9);

/* ================= MỤC 9 (v18) — SVG KHOA HỌC: gắn hình K4/K5 cho KHTN 9 =================
   Kỷ luật K4: KHÔNG vẽ ảnh, KHÔNG vẽ tia phản xạ/khúc xạ, cung góc không số. */
(function () {
  function findT(id) { return findTopic127(9, id); }
  function k4LensGen() {
    var zone = rand(0, 2);
    var answers = ["Ảnh thật, ngược chiều, nhỏ hơn vật", "Ảnh thật, ngược chiều, lớn hơn vật", "Ảnh ảo, cùng chiều, lớn hơn vật"];
    var q = mcqQ("Một vật đặt trước thấu kính hội tụ như hình vẽ (F, 2F là dữ kiện cho sẵn). Ảnh của vật qua thấu kính có tính chất nào sau đây?",
      answers.filter(function (x) { return x !== answers[zone]; }),
      answers[zone],
      "Vật ở ngoài 2F: ảnh thật, ngược chiều, nhỏ hơn vật. Vật ở giữa F và 2F: ảnh thật, ngược chiều, lớn hơn vật. Vật ở trong F: ảnh ảo, cùng chiều, lớn hơn vật.");
    q.figure = figK4LensSVG(zone, pick([30, 38, 44]));
    return q;
  }
  function k4MirrorGen() {
    var ang = pick([30, 40, 50, 60]);
    var q = mcqQ("Một tia sáng chiếu tới gương phẳng như hình vẽ (cung góc không ghi số đo). Theo định luật phản xạ ánh sáng, góc phản xạ so với góc tới thế nào?",
      ["Nhỏ hơn góc tới", "Lớn hơn góc tới"], "Bằng góc tới",
      "Định luật phản xạ ánh sáng: tia phản xạ nằm trong mặt phẳng tới và góc phản xạ bằng góc tới.");
    q.figure = figK4MirrorSVG(ang);
    return q;
  }
  function k5ThermGen() {
    var value = 5 * rand(-2, 12);
    var wrongs = [value - 10, value - 5, value + 5, value + 10].filter(function (x) { return x >= -10 && x <= 60 && x !== value; });
    var q = mcqQ("Quan sát nhiệt kế trong hình. Nhiệt kế chỉ bao nhiêu độ C?",
      shuffle(wrongs).slice(0, 2).map(function (x) { return x + "°C"; }),
      value + "°C", "Đọc mức thuỷ ngân trên thang chia độ: mỗi vạch nhỏ là 5°C.");
    q.figure = figK5ThermSVG(value, -10, 60, 5);
    q.figureOnly = true;
    return q;
  }
  function k5RulerGen() {
    var len = rand(3, 13);
    var q = mcqQ("Quan sát hình: một vật đặt khít vạch 0 của thước. Vật dài bao nhiêu xăng-ti-mét?",
      [len - 1, len + 1, len + 2].map(function (x) { return x + " cm"; }),
      len + " cm", "Đọc vạch cuối của vật trên thước: vật dài " + len + " cm.");
    q.figure = figK5RulerSVG(len);
    q.figureOnly = true;
    return q;
  }
  var t;
  t = findT("kh9-p2"); if (t) { t.pools.choose.push(k4LensGen, k4LensGen, k4MirrorGen); }
  t = findT("kh9-mo"); if (t) { t.pools.choose.push(k5ThermGen, k5RulerGen); }
})();
